insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.v.grande_apostasie', 'eg', 'vocabulary', 'vocabulary', 'grande apostasie', 4, '{}'::text[], 7, '{"translation": "idée de plusieurs groupes récents : l''Église des apôtres aurait disparu, il faut la restaurer", "partOfSpeech": "concept", "lessonId": "eg.l60", "dictionaryItemId": "eg.d.grande_apostasie"}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l01', 'eg', 1, 'Pourquoi étudier l''histoire de l''Église ?', 'Comprendre à quoi sert l''histoire de l''Église, comment elle éclaire les dogmes, et dans quel décor elle commence.', 1, 1, 'eg.g01.pourquoi_histoire', array['eg.g01.pourquoi_histoire','eg.v.histoire_ecclesiastique','eg.v.dogme','eg.v.heresie','eg.v.schisme','eg.v.empire_romain','eg.v.ere_chretienne','eg.v.jesus_christ']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l02', 'eg', 1, 'La Pentecôte et la première communauté', 'De la croix à la Pentecôte : comment une poignée de disciples apeurés devient l''Église, et comment elle vit à Jérusalem.', 1, 2, 'eg.g02.pentecote_communaute', array['eg.g02.pentecote_communaute','eg.v.jerusalem','eg.v.ponce_pilate','eg.v.apotre','eg.v.ascension','eg.v.chambre_haute','eg.v.pentecote','eg.v.saint_pierre','eg.v.premiere_communaute','eg.v.fraction_du_pain']::text[], array['eg.g01.pourquoi_histoire']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l03', 'eg', 1, 'Étienne, Paul et les premières missions', 'Les premiers conflits, le martyre d''Étienne, la conversion de Paul et ses voyages vers les païens.', 2, 3, 'eg.g03.etienne_paul_missions', array['eg.g03.etienne_paul_missions','eg.v.helleniste','eg.v.saint_etienne','eg.v.martyr','eg.v.saint_paul','eg.v.barnabe','eg.v.synagogue','eg.v.paiens','eg.v.antioche','eg.v.chretiens']::text[], array['eg.g01.pourquoi_histoire','eg.g02.pentecote_communaute']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l04', 'eg', 1, 'Le concile de Jérusalem (vers 49)', 'Faut-il être circoncis pour être chrétien ? Le premier concile tranche, et fonde la méthode de tous les conciles.', 2, 4, 'eg.g04.concile_jerusalem', array['eg.g04.concile_jerusalem','eg.v.concile','eg.v.circoncision','eg.v.judaisants','eg.v.loi_de_moise','eg.v.salut','eg.v.concile_de_jerusalem','eg.v.jacques_de_jerusalem']::text[], array['eg.g02.pentecote_communaute','eg.g03.etienne_paul_missions']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l05', 'eg', 1, 'Les persécutions du premier siècle', 'De Jacques à Domitien : qui persécute les premiers chrétiens, pourquoi, et comment la chute de Jérusalem change tout.', 2, 5, 'eg.g05.persecutions_premier_siecle', array['eg.g05.persecutions_premier_siecle','eg.v.herode_agrippa','eg.v.jacques_de_zebedee','eg.v.neron','eg.v.incendie_de_rome','eg.v.revolte_juive','eg.v.chute_de_jerusalem','eg.v.temple_de_jerusalem','eg.v.domitien']::text[], array['eg.g03.etienne_paul_missions','eg.g04.concile_jerusalem']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l06', 'eg', 1, 'Les évangiles, les épîtres et les premières hérésies', 'Pourquoi l''enseignement de Jésus est mis par écrit, quels sont les écrits du premier siècle, et face à quelles erreurs : judaïsants et gnostiques.', 3, 6, 'eg.g06.ecrits_heresies', array['eg.g06.ecrits_heresies','eg.v.tradition_orale','eg.v.epitre','eg.v.evangile','eg.v.nouveau_testament','eg.v.saint_jean','eg.v.gnosticisme','eg.v.docetisme','eg.v.simon_le_magicien']::text[], array['eg.g04.concile_jerusalem','eg.g05.persecutions_premier_siecle']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l07', 'eg', 1, 'Les apôtres et les sièges apostoliques', 'Où sont allés les apôtres après la Pentecôte, et ce qu''est un siège apostolique : Jérusalem, Antioche, Rome, Éphèse, Alexandrie.', 3, 7, 'eg.g07.apotres_sieges', array['eg.g07.apotres_sieges','eg.v.saint_andre','eg.v.saint_thomas','eg.v.saint_matthieu','eg.v.saint_barthelemy','eg.v.siege_apostolique','eg.v.succession_apostolique']::text[], array['eg.g05.persecutions_premier_siecle','eg.g06.ecrits_heresies']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l08', 'eg', 1, 'Saint Marc et la fondation de l''Église d''Alexandrie', 'Qui est saint Marc, comment il apporte l''Évangile en Égypte, comment il meurt, et pourquoi l''Église copte est apostolique.', 3, 8, 'eg.g08.marc_alexandrie', array['eg.g08.marc_alexandrie','eg.v.alexandrie','eg.v.septante','eg.v.saint_marc','eg.v.anianus','eg.v.eglise_d_alexandrie','eg.v.copte','eg.v.reliques_de_saint_marc','eg.v.cathedrale_saint_marc']::text[], array['eg.g06.ecrits_heresies','eg.g07.apotres_sieges']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l09', 'eg', 2, 'Les apôtres ne sont plus là', 'Comprendre pourquoi, au IIe siècle, l''Église doit défendre sa foi, et sur quoi elle s''appuie : Écritures, tradition, succession apostolique.', 2, 9, 'eg.g09.releve_des_apotres', array['eg.g09.releve_des_apotres','eg.v.sainte_tradition','eg.v.depot_de_la_foi','eg.v.eveque','eg.v.ecritures','eg.v.doctrine']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l10', 'eg', 2, 'Les quatre sièges apostoliques', 'Rome, Alexandrie, Antioche, Jérusalem : pourquoi ces Églises ont une autorité particulière, et qui les a fondées.', 2, 10, 'eg.g10.sieges_apostoliques', array['eg.g10.sieges_apostoliques','eg.v.siege_de_rome','eg.v.siege_d_alexandrie','eg.v.siege_d_antioche','eg.v.siege_de_jerusalem','eg.v.pape_d_alexandrie']::text[], array['eg.g09.releve_des_apotres']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l11', 'eg', 2, 'Clément, Ignace, Polycarpe : les Pères apostoliques', 'Trois évêques proches des apôtres qui transmettent la foi par leurs lettres.', 2, 11, 'eg.g11.peres_apostoliques', array['eg.g11.peres_apostoliques','eg.v.peres_apostoliques','eg.v.clement_de_rome','eg.v.ignace_d_antioche','eg.v.polycarpe_de_smyrne','eg.v.lettre_aux_corinthiens','eg.v.sept_lettres_d_ignace','eg.v.lettre_aux_philippiens','eg.v.catholique_sens','eg.v.smyrne']::text[], array['eg.g10.sieges_apostoliques','eg.g09.releve_des_apotres']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l12', 'eg', 2, 'Persécutions, martyrs et poisson secret', 'Pourquoi Rome persécute, qui sont les martyrs de ce siècle, et pourquoi le poisson ICHTHYS est le signe des chrétiens.', 2, 12, 'eg.g12.persecutions_ichthus', array['eg.g12.persecutions_ichthus','eg.v.persecution_romaine','eg.v.trajan','eg.v.marc_aurele','eg.v.septime_severe','eg.v.ichthys','eg.v.culte_de_l_empereur','eg.v.martyrs_de_lyon','eg.v.pline_le_jeune']::text[], array['eg.g11.peres_apostoliques','eg.g10.sieges_apostoliques']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l13', 'eg', 2, 'Les apologistes : défendre la foi', 'Justin Martyr et Tertullien répondent aux accusations des païens et montrent que la foi chrétienne est raisonnable.', 2, 13, 'eg.g13.apologistes', array['eg.g13.apologistes','eg.v.apologiste','eg.v.paganisme','eg.v.justin_martyr','eg.v.tertullien','eg.v.apologetique','eg.v.dialogue_avec_tryphon','eg.v.semences_du_verbe','eg.v.sang_des_martyrs']::text[], array['eg.g12.persecutions_ichthus','eg.g11.peres_apostoliques']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l14', 'eg', 2, 'Gnosticisme et docétisme', 'Deux hérésies liées : le salut par une connaissance secrète, et le Christ au corps fantôme. Comment l''Église répond.', 3, 14, 'eg.g14.gnosticisme_docetisme', array['eg.g14.gnosticisme_docetisme','eg.v.gnose','eg.v.demiurge','eg.v.valentin','eg.v.basilide','eg.v.irenee_de_lyon','eg.v.contre_les_heresies','eg.v.nag_hammadi']::text[], array['eg.g13.apologistes','eg.g12.persecutions_ichthus']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l15', 'eg', 2, 'Marcion et Montan : deux dieux, une fausse prophétie', 'Marcion rejette l''Ancien Testament, Montanus annonce une « nouvelle prophétie » : ce qu''ils enseignent, et comment l''Église répond.', 3, 15, 'eg.g15.marcion_montan', array['eg.g15.marcion_montan','eg.v.marcion','eg.v.marcionisme','eg.v.montanus','eg.v.montanisme','eg.v.paraclet','eg.v.priscilla_et_maximilla','eg.v.millenarisme','eg.v.rigorisme']::text[], array['eg.g14.gnosticisme_docetisme','eg.g13.apologistes']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l16', 'eg', 2, 'Le canon, la règle de foi et Démétrios', 'Comment l''Église répond aux hérésies : le canon, la règle de foi, et le rôle d''Alexandrie sous saint Démétrios.', 3, 16, 'eg.g16.canon_regle_de_foi', array['eg.g16.canon_regle_de_foi','eg.v.canon_des_ecritures','eg.v.regle_de_foi','eg.v.fragment_de_muratori','eg.v.saint_demetrios','eg.v.date_de_paques','eg.v.quatorze_nisan','eg.v.epacte']::text[], array['eg.g15.marcion_montan','eg.g14.gnosticisme_docetisme','eg.g13.apologistes']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l17', 'eg', 3, 'Pourquoi persécute-t-on les chrétiens ?', 'Comprendre les causes de l''hostilité : le culte impérial, le secret, les rumeurs et les accusations des philosophes.', 1, 17, 'eg.g17.chretiens_mal_vus', array['eg.g17.chretiens_mal_vus','eg.v.edit_imperial','eg.v.anthropophagie','eg.v.accusation_atheisme','eg.v.meurtre_rituel','eg.v.mauvais_citoyens','eg.v.sacrifice_public']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l18', 'eg', 3, 'Maximin, Dèce, Valérien : trois vagues', 'Suivre les persécutions du IIIe siècle : qui, quand, avec quels édits, et pourquoi elles font grandir l''Église.', 2, 18, 'eg.g18.edits_de_maximin_a_valerien', array['eg.g18.edits_de_maximin_a_valerien','eg.v.maximin','eg.v.dece','eg.v.valerien','eg.v.edit_de_dece','eg.v.libellus','eg.v.semence_de_chretiens']::text[], array['eg.g17.chretiens_mal_vus']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l19', 'eg', 3, 'Dioclétien et l''ère des martyrs', 'Comprendre la dixième persécution, pourquoi l''année 284 est l''an 1 du calendrier copte et ce qu''est le Nayrouz.', 2, 19, 'eg.g19.diocletien_ere_des_martyrs', array['eg.g19.diocletien_ere_des_martyrs','eg.v.diocletien','eg.v.grande_persecution_303','eg.v.dixieme_persecution','eg.v.calendrier_copte','eg.v.ere_des_martyrs','eg.v.nayrouz']::text[], array['eg.g17.chretiens_mal_vus','eg.g18.edits_de_maximin_a_valerien']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l20', 'eg', 3, 'Du martyre au désert : Paul et Antoine', 'Découvrir les tout premiers ermites d''Égypte : Paul de Thèbes (vers 250) et Antoine (vers 270).', 2, 20, 'eg.g20.premiers_ermites', array['eg.g20.premiers_ermites','eg.v.paul_de_thebes','eg.v.antoine','eg.v.ermite','eg.v.anachorete','eg.v.desert_d_egypte','eg.v.fuite_au_desert']::text[], array['eg.g18.edits_de_maximin_a_valerien','eg.g19.diocletien_ere_des_martyrs']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l21', 'eg', 3, 'Paul de Samosate et Sabellius : les deux pièges', 'Comprendre deux erreurs du IIIe siècle sur la Trinité, qui les a combattues et comment l''Église a répondu.', 3, 21, 'eg.g21.erreurs_sur_la_trinite', array['eg.g21.erreurs_sur_la_trinite','eg.v.paul_de_samosate','eg.v.zenobie','eg.v.denys_d_alexandrie','eg.v.concile_d_antioche_269','eg.v.sabellius','eg.v.modalisme','eg.v.trinite','eg.v.excommunication']::text[], array['eg.g19.diocletien_ere_des_martyrs','eg.g20.premiers_ermites']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l22', 'eg', 3, 'Les tombés, Novatien et Mani', 'Comprendre le débat sur le pardon après les persécutions (Novatien) et découvrir le manichéisme (Mani).', 3, 22, 'eg.g22.novatien_et_mani', array['eg.g22.novatien_et_mani','eg.v.novatien','eg.v.cyprien','eg.v.tombes','eg.v.penitence','eg.v.novatianisme','eg.v.mani','eg.v.manicheisme','eg.v.augustin']::text[], array['eg.g19.diocletien_ere_des_martyrs','eg.g21.erreurs_sur_la_trinite']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l23', 'eg', 3, 'La Sainte Tradition et le canon du Nouveau Testament', 'Comprendre comment l''Église a transmis la foi par écrit et choisi les livres du Nouveau Testament selon quatre critères.', 3, 23, 'eg.g23.tradition_et_canon', array['eg.g23.tradition_et_canon','eg.v.tradition_ecrite','eg.v.canon_du_nouveau_testament','eg.v.approbation_apostolique','eg.v.apocryphes','eg.v.didache','eg.v.tradition_apostolique_d_hippolyte','eg.v.didascalie','eg.v.pasteur_d_hermas']::text[], array['eg.g21.erreurs_sur_la_trinite','eg.g22.novatien_et_mani']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l24', 'eg', 3, 'Comment l''Église s''organise : évêques, prêtres, diacres', 'Comprendre la naissance de la hiérarchie à trois degrés, le rôle des confesseurs et l''origine du titre de pape d''Alexandrie.', 3, 24, 'eg.g24.structure_de_l_eglise', array['eg.g24.structure_de_l_eglise','eg.v.diacre','eg.v.pretre','eg.v.clerge','eg.v.hierarchie_a_trois_degres','eg.v.confesseur','eg.v.prophetes_des_premiers_temps','eg.v.heraclas','eg.v.patriarche_a_partir_de_451']::text[], array['eg.g22.novatien_et_mani','eg.g23.tradition_et_canon']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l25', 'eg', 4, 'Le feu avant la paix', 'Dioclétien, Galère et la grande persécution de 303 à 311 : pourquoi l''Église copte compte ses années depuis les martyrs.', 2, 25, 'eg.g25.grande_persecution', array['eg.g25.grande_persecution','eg.v.galere','eg.v.quatre_edits','eg.v.edit_de_tolerance_311','eg.v.pierre_sceau_des_martyrs','eg.v.saint_georges','eg.v.saint_mina']::text[], array['eg.g17.chretiens_mal_vus','eg.g18.edits_de_maximin_a_valerien','eg.g19.diocletien_ere_des_martyrs']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l26', 'eg', 4, 'Constantin : la croix et la paix', 'De la vision de 312 à l''édit de Milan, puis Constantinople : comment l''Église passe de la persécution à la faveur de l''empereur.', 2, 26, 'eg.g26.constantin', array['eg.g26.constantin','eg.v.constantin','eg.v.helene','eg.v.maxence','eg.v.edit_de_milan','eg.v.licinius','eg.v.constantinople','eg.v.eveque_du_dehors','eg.v.armenie']::text[], array['eg.g25.grande_persecution']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l27', 'eg', 4, 'Arius : le Fils est-il Dieu ?', 'Qui est Arius, que dit-il du Christ, pourquoi l''Église ne peut pas l''accepter, et les trois positions du IVe siècle.', 3, 27, 'eg.g27.arius', array['eg.g27.arius','eg.v.arius','eg.v.arianisme','eg.v.alexandre_d_alexandrie','eg.v.eusebe_de_nicomedie','eg.v.semi_arianisme','eg.v.homoousios','eg.v.divinite_du_christ']::text[], array['eg.g25.grande_persecution','eg.g26.constantin']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l28', 'eg', 4, 'Nicée 325 : le premier concile', 'Qui convoque, où, quand, contre qui, ce qui est décidé : le premier concile œcuménique et son credo.', 3, 28, 'eg.g28.concile_de_nicee', array['eg.g28.concile_de_nicee','eg.v.concile_de_nicee','eg.v.concile_oecumenique','eg.v.nicee','eg.v.credo_de_nicee','eg.v.anathemes','eg.v.eusebe_de_cesaree','eg.v.les_318_eveques']::text[], array['eg.g25.grande_persecution','eg.g26.constantin','eg.g27.arius']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l29', 'eg', 4, 'Athanase : le défenseur de la foi', 'De son livre de jeunesse à ses exils, de la Vie d''Antoine à la liste des 27 livres : le patriarche qui tient seul contre le monde.', 3, 29, 'eg.g29.athanase', array['eg.g29.athanase','eg.v.athanase','eg.v.defenseur_de_la_foi','eg.v.sur_l_incarnation_du_verbe','eg.v.vie_d_antoine','eg.v.exils_d_athanase','eg.v.frumentius']::text[], array['eg.g26.constantin','eg.g27.arius','eg.g28.concile_de_nicee']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l30', 'eg', 4, 'Les Pères du désert', 'Antoine, Paul, Pacôme, Macaire : comment l''Égypte devient la mère du monachisme, de la solitude à la vie en communauté.', 3, 30, 'eg.g30.peres_du_desert', array['eg.g30.peres_du_desert','eg.v.monachisme','eg.v.saint_antoine','eg.v.saint_paul_l_ermite','eg.v.saint_pacome','eg.v.vie_cenobitique','eg.v.saint_macaire_le_grand','eg.v.scete','eg.v.jean_cassien','eg.v.chenoute']::text[], array['eg.g26.constantin','eg.g28.concile_de_nicee','eg.g29.athanase']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l31', 'eg', 4, 'Constantinople 381 : l''Esprit Saint', 'Le deuxième concile : Théodose Ier, les 150 évêques, Apollinaire, Macédonius et le credo complété.', 3, 31, 'eg.g31.concile_de_constantinople', array['eg.g31.concile_de_constantinople','eg.v.concile_de_constantinople','eg.v.theodose_ier','eg.v.apollinaire','eg.v.macedonius','eg.v.credo_de_nicee_constantinople','eg.v.saint_gregoire_le_theologien','eg.v.saint_cyrille_de_jerusalem','eg.v.pape_timothee','eg.v.religion_d_etat_380']::text[], array['eg.g27.arius','eg.g28.concile_de_nicee','eg.g29.athanase','eg.g30.peres_du_desert']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l32', 'eg', 4, 'Le siècle en un tableau', 'Les deux conciles côte à côte, les quatre erreurs, les grands saints et les trois liturgies : le bilan du IVe siècle.', 3, 32, 'eg.g32.bilan_du_siecle', array['eg.g32.bilan_du_siecle','eg.v.saint_basile_le_grand','eg.v.saint_ephrem_le_syrien','eg.v.saint_ambroise_de_milan','eg.v.saint_jean_chrysostome','eg.v.saint_augustin_d_hippone','eg.v.saint_nicolas_de_myre']::text[], array['eg.g25.grande_persecution','eg.g26.constantin','eg.g27.arius','eg.g28.concile_de_nicee','eg.g29.athanase','eg.g30.peres_du_desert','eg.g31.concile_de_constantinople']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l33', 'eg', 5, 'Cinq sièges, une seule Église', 'Au début du Ve siècle : les cinq sièges apostoliques, les trois premiers conciles et la jalousie qui couve autour d''Alexandrie.', 1, 33, 'eg.g33.cinq_sieges', array['eg.g33.cinq_sieges','eg.v.patriarche','eg.v.canon_ecclesiastique','eg.v.nouvelle_rome','eg.v.canon_3_de_381','eg.v.trois_premiers_conciles']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l34', 'eg', 5, 'Nestorius et le titre qui fâche', 'Nestorius devient patriarche de Constantinople en 428, refuse le titre Théotokos et sépare le Verbe de l''homme Jésus.', 2, 34, 'eg.g34.nestorius', array['eg.g34.nestorius','eg.v.nestorius','eg.v.nestorianisme','eg.v.theotokos','eg.v.christotokos','eg.v.le_verbe','eg.v.incarnation','eg.v.ecole_d_antioche']::text[], array['eg.g33.cinq_sieges']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l35', 'eg', 5, 'Saint Cyrille, le Pilier de la foi', 'Le 24e pape d''Alexandrie défend le titre Théotokos et formule la foi en « une seule nature du Verbe incarné ».', 2, 35, 'eg.g35.cyrille', array['eg.g35.cyrille','eg.v.cyrille_d_alexandrie','eg.v.pilier_de_la_foi','eg.v.formule_de_cyrille','eg.v.douze_anathemes','eg.v.celestin_ier','eg.v.unite_du_christ']::text[], array['eg.g34.nestorius','eg.g33.cinq_sieges']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l36', 'eg', 5, 'Éphèse 431 : Nestorius condamné', 'Le troisième concile œcuménique : qui l''a convoqué, qui l''a présidé et ce qu''il a décidé.', 3, 36, 'eg.g36.ephese_431', array['eg.g36.ephese_431','eg.v.concile_ephese_431','eg.v.theodose_ii','eg.v.ephese','eg.v.pelagianisme','eg.v.jean_d_antioche']::text[], array['eg.g35.cyrille','eg.g34.nestorius']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l37', 'eg', 5, 'Après Éphèse : la paix fragile', 'La formule d''union de 433, l''Église de l''Orient, la mort de Cyrille en 444 et l''arrivée de Dioscore et de Flavien.', 3, 37, 'eg.g37.apres_ephese', array['eg.g37.apres_ephese','eg.v.formule_d_union','eg.v.eglise_de_l_orient','eg.v.perse','eg.v.flavien','eg.v.dioscore']::text[], array['eg.g36.ephese_431','eg.g35.cyrille']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l38', 'eg', 5, 'Eutychès : quand l''humanité disparaît', 'Le moine Eutychès prétend que l''humanité du Christ est absorbée par sa divinité ; Flavien le condamne en 448.', 3, 38, 'eg.g38.eutyches', array['eg.g38.eutyches','eg.v.eutyches','eg.v.monophysisme','eg.v.archimandrite','eg.v.synode_de_constantinople_448','eg.v.humanite_absorbee']::text[], array['eg.g37.apres_ephese','eg.g36.ephese_431']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l39', 'eg', 5, 'Éphèse II (449) : le concile de la discorde', 'Dioscore préside le second concile d''Éphèse : Eutychès est réhabilité, Flavien déposé et le Tome de Léon n''est pas lu.', 4, 39, 'eg.g39.ephese_449', array['eg.g39.ephese_449','eg.v.concile_ephese_449','eg.v.leon_ier','eg.v.tome_de_leon','eg.v.brigandage_d_ephese','eg.v.marcien','eg.v.pulcherie']::text[], array['eg.g38.eutyches','eg.g37.apres_ephese']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l40', 'eg', 5, 'Chalcédoine 451 : le premier schisme', 'Le concile de Chalcédoine : qui le convoque, ce qu''il décide, pourquoi l''Église copte le refuse et la rupture qui suit.', 4, 40, 'eg.g40.chalcedoine', array['eg.g40.chalcedoine','eg.v.concile_chalcedoine','eg.v.chalcedoine','eg.v.definition_de_chalcedoine','eg.v.deux_natures','eg.v.canon_28','eg.v.premier_schisme']::text[], array['eg.g39.ephese_449','eg.g38.eutyches']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l41', 'eg', 5, 'Saint Dioscore, confesseur de la foi', 'Qui était Dioscore, ce dont on l''accuse, ce que répond la tradition copte, son exil à Gangra et pourquoi l''Église copte le vénère.', 4, 41, 'eg.g41.dioscore', array['eg.g41.dioscore','eg.v.archidiacre','eg.v.accusations_contre_dioscore','eg.v.gangra']::text[], array['eg.g40.chalcedoine','eg.g39.ephese_449']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l42', 'eg', 5, 'Miaphysisme : la foi de l''Église copte', 'Mono, dyo, mia : trois mots grecs pour comprendre ce que l''Église copte croit sur la nature du Christ, et pourquoi elle n''est pas monophysite.', 4, 42, 'eg.g42.miaphysisme', array['eg.g42.miaphysisme','eg.v.miaphysisme','eg.v.dyophysisme','eg.v.physis','eg.v.sans_melange_ni_division']::text[], array['eg.g41.dioscore','eg.g40.chalcedoine']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l43', 'eg', 5, 'Le schisme et ses suites : deux papes à Alexandrie', 'Hénotikon, persécutions, Justinien, melkites : comment la rupture de 451 s''installe et pourquoi l''Égypte a deux patriarches d''Alexandrie.', 4, 43, 'eg.g43.schisme_et_suites', array['eg.g43.schisme_et_suites','eg.v.henotikon','eg.v.zenon','eg.v.justinien','eg.v.melkites','eg.v.non_chalcedoniens','eg.v.chalcedoniens','eg.v.macaire_d_edkou']::text[], array['eg.g42.miaphysisme','eg.g40.chalcedoine']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l44', 'eg', 5, 'Deux familles orthodoxes, un dialogue', 'Trois ou sept conciles, les six Églises sœurs, le dialogue du XXe siècle et la frise du Ve siècle pour tout réviser.', 4, 44, 'eg.g44.deux_familles', array['eg.g44.deux_familles','eg.v.eglises_soeurs','eg.v.intercommunion','eg.v.accord_de_1989','eg.v.christologie']::text[], array['eg.g43.schisme_et_suites','eg.g42.miaphysisme','eg.g40.chalcedoine']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l45', 'eg', 6, 'La logique des conciles', 'Pourquoi un concile, qui le convoque, ce qu''il produit, et pourquoi l''Église copte en reconnaît trois.', 2, 45, 'eg.g45.logique_des_conciles', array['eg.g45.logique_des_conciles','eg.v.synode','eg.v.orthodoxie','eg.v.symbole_de_foi','eg.v.reception_d_un_concile']::text[], array['eg.g33.cinq_sieges','eg.v.concile_de_jerusalem','eg.v.concile_oecumenique','eg.v.canon_ecclesiastique','eg.v.anathemes']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l53', 'eg', 7, 'Les quatre grandes familles de chrétiens', 'Situer les Églises orthodoxes orientales, les orthodoxes chalcédoniens, les catholiques et les protestants, et savoir ce qui les distingue.', 1, 53, 'eg.g53.familles_eglises', array['eg.g53.familles_eglises','eg.v.eglises_orthodoxes_orientales','eg.v.eglise_orthodoxe_chalcedonienne','eg.v.eglise_catholique','eg.v.protestantisme','eg.v.eglise_syriaque_orthodoxe','eg.v.eglise_armenienne_apostolique','eg.v.eglise_tewahedo','eg.v.eglise_malankare']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l54', 'eg', 7, 'Les orthodoxes chalcédoniens : deux natures ou une ?', 'Comprendre ce qui nous sépare des orthodoxes grecs, russes ou serbes : le concile de Chalcédoine, la formule de saint Cyrille et les rapprochements récents.', 2, 54, 'eg.g54.chalcedoine_orthodoxes', array['eg.g54.chalcedoine_orthodoxes','eg.v.sept_conciles','eg.v.trois_conciles','eg.v.patriarcat_grec_d_alexandrie','eg.v.dialogue_chambesy']::text[], array['eg.g53.familles_eglises']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l55', 'eg', 7, 'Avec les catholiques (1) : le pape, le Filioque et 1054', 'Comprendre la primauté et l''infaillibilité du pape, l''ajout du Filioque au Credo et la rupture de 1054 entre Rome et Constantinople.', 2, 55, 'eg.g55.papaute_filioque', array['eg.g55.papaute_filioque','eg.v.pape','eg.v.primaute_du_pape','eg.v.infaillibilite_pontificale','eg.v.vatican_i','eg.v.filioque','eg.v.schisme_de_1054','eg.v.ex_cathedra']::text[], array['eg.g54.chalcedoine_orthodoxes','eg.g53.familles_eglises']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l56', 'eg', 7, 'Avec les catholiques (2) : purgatoire, Marie, pain et célibat', 'Comprendre quatre différences avec l''Église catholique : le purgatoire, l''Immaculée Conception, le pain sans levain et le célibat des prêtres, et ce que croit l''Église copte.', 2, 56, 'eg.g56.dogmes_usages_catholiques', array['eg.g56.dogmes_usages_catholiques','eg.v.purgatoire','eg.v.immaculee_conception','eg.v.peche_originel','eg.v.azymes','eg.v.pain_leve','eg.v.celibat_des_pretres','eg.v.prieres_pour_les_defunts']::text[], array['eg.g55.papaute_filioque','eg.g54.chalcedoine_orthodoxes']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l57', 'eg', 7, 'Avec les protestants (1) : la Réforme, l''Écriture seule, la foi seule', 'Comprendre la Réforme de 1517 et deux principes protestants, sola scriptura et sola fide, et ce que l''Église copte répond avec respect.', 3, 57, 'eg.g57.reforme_protestante', array['eg.g57.reforme_protestante','eg.v.martin_luther','eg.v.theses_de_wittenberg','eg.v.reforme','eg.v.sola_scriptura','eg.v.sola_fide','eg.v.jean_calvin','eg.v.deuterocanoniques']::text[], array['eg.g56.dogmes_usages_catholiques','eg.g55.papaute_filioque']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l58', 'eg', 7, 'Avec les protestants (2) : sacrements, saints, icônes, succession', 'Comprendre pourquoi nous avons sept sacrements, honorons les saints et les icônes et gardons la succession apostolique, là où la plupart des protestants font autrement.', 3, 58, 'eg.g58.protestants_sacrements_saints', array['eg.g58.protestants_sacrements_saints','eg.v.sept_sacrements','eg.v.deux_sacrements','eg.v.intercession_des_saints','eg.v.veneration','eg.v.icone','eg.v.pasteur','eg.v.eglise_evangelique_d_egypte']::text[], array['eg.g57.reforme_protestante','eg.g56.dogmes_usages_catholiques']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l59', 'eg', 7, 'Groupes récents (1) : mormons et adventistes', 'Découvrir l''histoire et les croyances des mormons et des adventistes, et comprendre ce qui les distingue de la foi chrétienne historique de l''Église copte.', 3, 59, 'eg.g59.mormons_adventistes', array['eg.g59.mormons_adventistes','eg.v.mormons','eg.v.joseph_smith','eg.v.livre_de_mormon','eg.v.moroni','eg.v.adventistes','eg.v.william_miller','eg.v.grande_deception','eg.v.ellen_white','eg.v.sabbat_du_samedi']::text[], array['eg.g58.protestants_sacrements_saints','eg.g57.reforme_protestante']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l60', 'eg', 7, 'Groupes récents (2) : témoins de Jéhovah, Science chrétienne et bilan', 'Découvrir les témoins de Jéhovah et la Science chrétienne, voir ce que les groupes récents ont en commun, et savoir répondre avec douceur et respect.', 4, 60, 'eg.g60.temoins_science_chretienne', array['eg.g60.temoins_science_chretienne','eg.v.temoins_de_jehovah','eg.v.charles_taze_russell','eg.v.traduction_du_monde_nouveau','eg.v.cent_quarante_quatre_mille','eg.v.refus_des_transfusions','eg.v.science_chretienne','eg.v.mary_baker_eddy','eg.v.science_et_sante','eg.v.grande_apostasie']::text[], array['eg.g59.mormons_adventistes','eg.g58.protestants_sacrements_saints','eg.g57.reforme_protestante']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l01.e01', 'eg', 'eg.l01', 'eg.g01.pourquoi_histoire', array['eg.g01.pourquoi_histoire','eg.v.histoire_ecclesiastique']::text[], 'mcq', 'lesson', 'L''étude de l''histoire de l''Église sert d''abord à…', array['comprendre le présent']::text[], 'L''histoire éclaire le passé pour comprendre le présent et préparer l''avenir : elle donne du sens à ce que nous vivons dans l''Église.', 1, '{"unitIds": ["eg.g01.pourquoi_histoire", "eg.v.histoire_ecclesiastique"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "L''étude de l''histoire de l''Église sert d''abord à…", "promptLanguage": "fr", "answer": "comprendre le présent", "acceptedAnswers": ["comprendre le présent"], "explanation": "L''histoire éclaire le passé pour comprendre le présent et préparer l''avenir : elle donne du sens à ce que nous vivons dans l''Église.", "tip": "Comprendre avant de réciter.", "extraExample": {"text": "La messe que tu connais a elle-même une histoire.", "translation": "Chaque pratique a été formée au fil des siècles."}, "options": ["apprendre des dates par cœur", "remplacer la lecture de la Bible", "comprendre le présent"], "errorPatterns": [{"equals": "apprendre des dates par cœur", "category": "word_confusion", "feedback": "Les dates sont des repères, mais le but est de comprendre les causes."}], "id": "eg.l01.e01", "pool": "lesson", "lessonId": "eg.l01", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l01.e02', 'eg', 'eg.l01', 'eg.g01.pourquoi_histoire', array['eg.g01.pourquoi_histoire','eg.v.ere_chretienne']::text[], 'mcq', 'lesson', 'Quel événement sert de repère pour compter les années de l''ère chrétienne ?', array['la naissance de Jésus-Christ']::text[], 'Le calendrier est coupé en deux époques : avant et après la naissance de Jésus-Christ. C''est l''ère chrétienne.', 1, '{"unitIds": ["eg.g01.pourquoi_histoire", "eg.v.ere_chretienne"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel événement sert de repère pour compter les années de l''ère chrétienne ?", "promptLanguage": "fr", "answer": "la naissance de Jésus-Christ", "acceptedAnswers": ["la naissance de Jésus-Christ"], "explanation": "Le calendrier est coupé en deux époques : avant et après la naissance de Jésus-Christ. C''est l''ère chrétienne.", "tip": "Avant J.-C. / après J.-C. : le Christ est le point de coupure.", "extraExample": {"text": "On écrit « 49 après J.-C. » pour le concile de Jérusalem.", "translation": "Le même repère sert pour toutes les dates du cours."}, "options": ["la chute de Jérusalem", "la naissance de Jésus-Christ", "la fondation de Rome"], "id": "eg.l01.e02", "pool": "lesson", "lessonId": "eg.l01", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l01.e03', 'eg', 'eg.l01', 'eg.g01.pourquoi_histoire', array['eg.g01.pourquoi_histoire','eg.v.ere_chretienne']::text[], 'mcq', 'lesson', 'Comment appelle-t-on le calendrier qui compte les années depuis la naissance du Christ ?', array['l''ère chrétienne']::text[], 'L''ère chrétienne part de la naissance du Christ. L''ère des martyrs, utilisée par l''Église copte, part de 284.', 2, '{"unitIds": ["eg.g01.pourquoi_histoire", "eg.v.ere_chretienne"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Comment appelle-t-on le calendrier qui compte les années depuis la naissance du Christ ?", "promptLanguage": "fr", "answer": "l''ère chrétienne", "acceptedAnswers": ["l''ère chrétienne"], "explanation": "L''ère chrétienne part de la naissance du Christ. L''ère des martyrs, utilisée par l''Église copte, part de 284.", "tip": "Deux repères différents : le Christ pour l''ère chrétienne, les martyrs pour l''ère copte.", "extraExample": {"text": "Nous sommes en 2026 de l''ère chrétienne.", "translation": "En année copte, ce serait autre chose : on y reviendra."}, "options": ["l''ère romaine", "l''ère chrétienne", "l''ère des martyrs"], "errorPatterns": [{"equals": "l''ère des martyrs", "category": "word_confusion", "feedback": "C''est l''ère copte, qui part de 284, pas l''ère chrétienne."}], "id": "eg.l01.e03", "pool": "lesson", "lessonId": "eg.l01", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l01.e04', 'eg', 'eg.l01', 'eg.g01.pourquoi_histoire', array['eg.g01.pourquoi_histoire','eg.v.empire_romain']::text[], 'mcq', 'lesson', 'Qu''est-ce qui aide l''Évangile à voyager dans le monde du Ier siècle ?', array['la langue grecque']::text[], 'Routes, ports et langue grecque : un voyageur peut se faire comprendre d''un bout à l''autre de la Méditerranée orientale, ce qui aide les apôtres.', 2, '{"unitIds": ["eg.g01.pourquoi_histoire", "eg.v.empire_romain"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qu''est-ce qui aide l''Évangile à voyager dans le monde du Ier siècle ?", "promptLanguage": "fr", "answer": "la langue grecque", "acceptedAnswers": ["la langue grecque"], "explanation": "Routes, ports et langue grecque : un voyageur peut se faire comprendre d''un bout à l''autre de la Méditerranée orientale, ce qui aide les apôtres.", "tip": "Un empire, des routes, une langue commune : le décor de la mission.", "extraExample": {"text": "Le Nouveau Testament est écrit en grec.", "translation": "La langue commune sert à diffuser les écrits."}, "options": ["le latin seul", "l''araméen seul", "la langue grecque"], "id": "eg.l01.e04", "pool": "lesson", "lessonId": "eg.l01", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l01.e05', 'eg', 'eg.l01', 'eg.g01.pourquoi_histoire', array['eg.g01.pourquoi_histoire','eg.v.schisme']::text[], 'mcq', 'lesson', 'Une rupture de communion entre des Églises s''appelle…', array['un schisme']::text[], 'Un schisme brise l''unité entre des Églises. Une hérésie, elle, touche à la doctrine ; un dogme est une vérité de foi.', 1, '{"unitIds": ["eg.g01.pourquoi_histoire", "eg.v.schisme"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Une rupture de communion entre des Églises s''appelle…", "promptLanguage": "fr", "answer": "un schisme", "acceptedAnswers": ["un schisme"], "explanation": "Un schisme brise l''unité entre des Églises. Une hérésie, elle, touche à la doctrine ; un dogme est une vérité de foi.", "tip": "Schisme = séparation. Pense à « scission ».", "extraExample": {"text": "En 1054, Rome et Constantinople se séparent.", "translation": "C''est un schisme, même si la foi était proche."}, "options": ["un schisme", "une hérésie", "un dogme"], "errorPatterns": [{"equals": "une hérésie", "category": "word_confusion", "feedback": "L''hérésie touche la doctrine ; ici on parle de communion rompue, donc d''un schisme."}], "id": "eg.l01.e05", "pool": "lesson", "lessonId": "eg.l01", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l01.e06', 'eg', 'eg.l01', 'eg.g01.pourquoi_histoire', array['eg.g01.pourquoi_histoire','eg.v.heresie']::text[], 'mcq', 'lesson', 'Une hérésie est d''abord une question de…', array['doctrine']::text[], 'Une hérésie est un enseignement qui s''écarte de la foi reçue des apôtres : elle touche à la doctrine. Le schisme, lui, touche à l''unité.', 2, '{"unitIds": ["eg.g01.pourquoi_histoire", "eg.v.heresie"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Une hérésie est d''abord une question de…", "promptLanguage": "fr", "answer": "doctrine", "acceptedAnswers": ["doctrine"], "explanation": "Une hérésie est un enseignement qui s''écarte de la foi reçue des apôtres : elle touche à la doctrine. Le schisme, lui, touche à l''unité.", "tip": "Hérésie = doctrine, schisme = unité.", "extraExample": {"text": "Dire que Jésus n''a eu que l''apparence d''un homme est une erreur de doctrine.", "translation": "Nous verrons que c''est le gnosticisme."}, "options": ["calendrier", "politique", "doctrine"], "id": "eg.l01.e06", "pool": "lesson", "lessonId": "eg.l01", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l01.e07', 'eg', 'eg.l01', 'eg.g01.pourquoi_histoire', array['eg.g01.pourquoi_histoire','eg.v.dogme']::text[], 'mcq', 'lesson', 'Pourquoi beaucoup de dogmes ont-ils été formulés ?', array['pour répondre à une hérésie']::text[], 'Quand une erreur menace la foi, l''Église dit clairement ce qu''elle croit : c''est ainsi que naissent beaucoup de dogmes, souvent lors d''un concile.', 3, '{"unitIds": ["eg.g01.pourquoi_histoire", "eg.v.dogme"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi beaucoup de dogmes ont-ils été formulés ?", "promptLanguage": "fr", "answer": "pour répondre à une hérésie", "acceptedAnswers": ["pour répondre à une hérésie"], "explanation": "Quand une erreur menace la foi, l''Église dit clairement ce qu''elle croit : c''est ainsi que naissent beaucoup de dogmes, souvent lors d''un concile.", "tip": "Pas d''erreur, pas besoin de définition : le dogme répond à une crise.", "extraExample": {"text": "Nicée (325) répond à Arius.", "translation": "Chaque concile répond à un problème précis."}, "options": ["pour fêter une victoire de l''empereur", "pour changer la foi des apôtres", "pour répondre à une hérésie"], "errorPatterns": [{"equals": "pour changer la foi des apôtres", "category": "word_confusion", "feedback": "Un dogme n''invente rien : il précise la foi reçue des apôtres."}], "id": "eg.l01.e07", "pool": "lesson", "lessonId": "eg.l01", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l01.e08', 'eg', 'eg.l01', 'eg.g01.pourquoi_histoire', array['eg.g01.pourquoi_histoire','eg.v.histoire_ecclesiastique']::text[], 'mcq', 'lesson', 'La première phase de l''histoire de l''Église couvre…', array['les trois premiers siècles']::text[], 'La phase I va du premier au troisième siècle : naissance de l''Église, expansion et persécutions. Ce module en couvre le début.', 2, '{"unitIds": ["eg.g01.pourquoi_histoire", "eg.v.histoire_ecclesiastique"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "La première phase de l''histoire de l''Église couvre…", "promptLanguage": "fr", "answer": "les trois premiers siècles", "acceptedAnswers": ["les trois premiers siècles"], "explanation": "La phase I va du premier au troisième siècle : naissance de l''Église, expansion et persécutions. Ce module en couvre le début.", "tip": "Phase I = siècles 1 à 3.", "extraExample": {"text": "Le premier siècle est le premier chapitre de la phase I.", "translation": "Les deuxième et troisième viendront ensuite."}, "options": ["le premier siècle seulement", "les dix premiers siècles", "les trois premiers siècles"], "id": "eg.l01.e08", "pool": "lesson", "lessonId": "eg.l01", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l01.e09', 'eg', 'eg.l01', 'eg.g01.pourquoi_histoire', array['eg.g01.pourquoi_histoire','eg.v.empire_romain']::text[], 'mcq', 'lesson', 'Pourquoi regarder le décor politique, social et économique ?', array['le contexte explique les événements']::text[], 'L''Église vit dans une société précise : l''Empire romain. Connaître ce décor aide à comprendre pourquoi les chrétiens voyagent, sont persécutés ou se séparent.', 2, '{"unitIds": ["eg.g01.pourquoi_histoire", "eg.v.empire_romain"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi regarder le décor politique, social et économique ?", "promptLanguage": "fr", "answer": "le contexte explique les événements", "acceptedAnswers": ["le contexte explique les événements"], "explanation": "L''Église vit dans une société précise : l''Empire romain. Connaître ce décor aide à comprendre pourquoi les chrétiens voyagent, sont persécutés ou se séparent.", "tip": "Pas d''événement sans contexte.", "extraExample": {"text": "Les routes romaines facilitent la mission de saint Paul.", "translation": "Le même empire peut aider ou persécuter."}, "options": ["pour juger les empereurs", "le contexte explique les événements", "pour oublier la foi"], "id": "eg.l01.e09", "pool": "lesson", "lessonId": "eg.l01", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l01.e10', 'eg', 'eg.l01', 'eg.g01.pourquoi_histoire', array['eg.g01.pourquoi_histoire','eg.v.jesus_christ','eg.v.ere_chretienne']::text[], 'fill_blank', 'lesson', 'Le calendrier prouve que la naissance du Christ a partagé le temps en deux : avant et après ___.', array['Jésus-Christ','Jésus Christ','Jesus-Christ']::text[], 'C''est la venue de Jésus-Christ qui sert de repère au calendrier de l''ère chrétienne.', 1, '{"unitIds": ["eg.g01.pourquoi_histoire", "eg.v.jesus_christ", "eg.v.ere_chretienne"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Le calendrier prouve que la naissance du Christ a partagé le temps en deux : avant et après ___.", "promptLanguage": "fr", "answer": "Jésus-Christ", "acceptedAnswers": ["Jésus-Christ", "Jésus Christ", "Jesus-Christ"], "explanation": "C''est la venue de Jésus-Christ qui sert de repère au calendrier de l''ère chrétienne.", "tip": "Le temps compte à partir de lui.", "extraExample": {"text": "Il est né vers l''an 4 avant J.-C.", "translation": "Le calendrier n''a pas été parfaitement calculé au départ."}, "options": ["Abraham", "Jésus-Christ", "Constantin"], "id": "eg.l01.e10", "pool": "lesson", "lessonId": "eg.l01", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l01.e11', 'eg', 'eg.l01', 'eg.g01.pourquoi_histoire', array['eg.g01.pourquoi_histoire','eg.v.dogme']::text[], 'fill_blank', 'lesson', 'Un ___ est une vérité de foi définie et enseignée par l''Église.', array['dogme']::text[], 'Le dogme formule clairement une vérité essentielle de la foi.', 1, '{"unitIds": ["eg.g01.pourquoi_histoire", "eg.v.dogme"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Un ___ est une vérité de foi définie et enseignée par l''Église.", "promptLanguage": "fr", "answer": "dogme", "acceptedAnswers": ["dogme"], "explanation": "Le dogme formule clairement une vérité essentielle de la foi.", "tip": "Dogme = vérité de foi. Schisme = rupture.", "extraExample": {"text": "Le dogme de la Trinité date des premiers siècles.", "translation": "Il a été précisé à Nicée."}, "options": ["dogme", "schisme", "calendrier"], "id": "eg.l01.e11", "pool": "lesson", "lessonId": "eg.l01", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l01.e12', 'eg', 'eg.l01', 'eg.g01.pourquoi_histoire', array['eg.g01.pourquoi_histoire','eg.v.empire_romain']::text[], 'fill_blank', 'lesson', 'Au temps de Jésus, Jérusalem est occupée par les ___.', array['Romains','les Romains']::text[], 'L''Empire romain contrôle la Judée : Jérusalem est occupée par les Romains, et Ponce Pilate représente l''empereur.', 1, '{"unitIds": ["eg.g01.pourquoi_histoire", "eg.v.empire_romain"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Au temps de Jésus, Jérusalem est occupée par les ___.", "promptLanguage": "fr", "answer": "Romains", "acceptedAnswers": ["Romains", "les Romains"], "explanation": "L''Empire romain contrôle la Judée : Jérusalem est occupée par les Romains, et Ponce Pilate représente l''empereur.", "tip": "Rome tient la ville.", "extraExample": {"text": "Jésus est jugé par un gouverneur romain.", "translation": "Il s''appelle Ponce Pilate."}, "options": ["Perses", "Grecs", "Romains"], "id": "eg.l01.e12", "pool": "lesson", "lessonId": "eg.l01", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l01.e13', 'eg', 'eg.l01', 'eg.g01.pourquoi_histoire', array['eg.g01.pourquoi_histoire','eg.v.histoire_ecclesiastique']::text[], 'fill_blank', 'lesson', 'Notre voyage commence par le ___ siècle.', array['premier']::text[], 'L''histoire de l''Église commence au premier siècle, avec Jésus-Christ, la Pentecôte et les apôtres.', 1, '{"unitIds": ["eg.g01.pourquoi_histoire", "eg.v.histoire_ecclesiastique"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Notre voyage commence par le ___ siècle.", "promptLanguage": "fr", "answer": "premier", "acceptedAnswers": ["premier"], "explanation": "L''histoire de l''Église commence au premier siècle, avec Jésus-Christ, la Pentecôte et les apôtres.", "tip": "Un siècle après l''autre.", "extraExample": {"text": "Le dernier apôtre meurt vers l''an 100.", "translation": "C''est la fin du premier siècle."}, "options": ["troisième", "vingtième", "premier"], "id": "eg.l01.e13", "pool": "lesson", "lessonId": "eg.l01", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l01.e14', 'eg', 'eg.l01', 'eg.g01.pourquoi_histoire', array['eg.g01.pourquoi_histoire','eg.v.dogme','eg.v.heresie','eg.v.schisme','eg.v.ere_chretienne']::text[], 'match', 'lesson', 'Les mots clés du cours', '{}'::text[], 'Dogme, hérésie, schisme et ère chrétienne sont les quatre mots de base pour parler de l''histoire de l''Église.', 1, '{"unitIds": ["eg.g01.pourquoi_histoire", "eg.v.dogme", "eg.v.heresie", "eg.v.schisme", "eg.v.ere_chretienne"], "type": "match", "difficulty": 1, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Les mots clés du cours", "promptLanguage": "fr", "answer": "Le dogme = vérité de foi définie par l''Église ; L''hérésie = enseignement qui s''écarte de la foi des apôtres ; Le schisme = rupture de communion entre Églises ; L''ère chrétienne = années comptées depuis la naissance du Christ", "acceptedAnswers": [], "explanation": "Dogme, hérésie, schisme et ère chrétienne sont les quatre mots de base pour parler de l''histoire de l''Église.", "tip": "Doctrine ou unité ? Dogme/hérésie d''un côté, schisme de l''autre.", "pairs": [{"left": "Le dogme", "right": "vérité de foi définie par l''Église"}, {"left": "L''hérésie", "right": "enseignement qui s''écarte de la foi des apôtres"}, {"left": "Le schisme", "right": "rupture de communion entre Églises"}, {"left": "L''ère chrétienne", "right": "années comptées depuis la naissance du Christ"}], "id": "eg.l01.e14", "pool": "lesson", "lessonId": "eg.l01", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l01.e15', 'eg', 'eg.l01', 'eg.g01.pourquoi_histoire', array['eg.g01.pourquoi_histoire','eg.v.empire_romain','eg.v.jesus_christ','eg.v.histoire_ecclesiastique']::text[], 'match', 'lesson', 'Le décor et le plan', '{}'::text[], 'Le premier siècle se passe dans l''Empire romain, et l''histoire ecclésiastique raconte l''Église depuis Jésus-Christ.', 2, '{"unitIds": ["eg.g01.pourquoi_histoire", "eg.v.empire_romain", "eg.v.jesus_christ", "eg.v.histoire_ecclesiastique"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Le décor et le plan", "promptLanguage": "fr", "answer": "L''Empire romain = domine presque tout le monde connu ; Jérusalem = occupée par les Romains ; Jésus-Christ = partage le temps en deux époques ; L''histoire ecclésiastique = histoire de l''Église et du christianisme", "acceptedAnswers": [], "explanation": "Le premier siècle se passe dans l''Empire romain, et l''histoire ecclésiastique raconte l''Église depuis Jésus-Christ.", "tip": "Rome, Jérusalem, le Christ : le décor et le point de départ.", "pairs": [{"left": "L''Empire romain", "right": "domine presque tout le monde connu"}, {"left": "Jérusalem", "right": "occupée par les Romains"}, {"left": "Jésus-Christ", "right": "partage le temps en deux époques"}, {"left": "L''histoire ecclésiastique", "right": "histoire de l''Église et du christianisme"}], "id": "eg.l01.e15", "pool": "lesson", "lessonId": "eg.l01", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l01.e16', 'eg', 'eg.l01', 'eg.g01.pourquoi_histoire', array['eg.g01.pourquoi_histoire']::text[], 'reorder', 'lesson', 'Phrase-repère : l''utilité de l''histoire.', array['Comprendre le passé aide à comprendre le présent']::text[], 'L''histoire éclaire le passé pour que nous comprenions le présent.', 2, '{"unitIds": ["eg.g01.pourquoi_histoire"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "prompt": "Phrase-repère : l''utilité de l''histoire.", "promptLanguage": "fr", "answer": "Comprendre le passé aide à comprendre le présent", "acceptedAnswers": ["Comprendre le passé aide à comprendre le présent"], "explanation": "L''histoire éclaire le passé pour que nous comprenions le présent.", "tip": "Passé → présent → avenir.", "extraExample": {"text": "Connaître l''histoire de l''Église aide à comprendre la messe.", "translation": "Rien n''est apparu sans raison."}, "tokens": ["aide", "à", "comprendre", "le", "présent", "Comprendre", "le", "passé"], "id": "eg.l01.e16", "pool": "lesson", "lessonId": "eg.l01", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l01.e17', 'eg', 'eg.l01', 'eg.g01.pourquoi_histoire', array['eg.g01.pourquoi_histoire','eg.v.heresie']::text[], 'free_answer', 'lesson', 'Quel mot désigne un enseignement qui s''écarte de la foi reçue des apôtres ?', array['hérésie','une hérésie','l''hérésie','heresie']::text[], 'C''est l''hérésie : une erreur de doctrine, à laquelle l''Église répond souvent par un dogme.', 2, '{"unitIds": ["eg.g01.pourquoi_histoire", "eg.v.heresie"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Quel mot désigne un enseignement qui s''écarte de la foi reçue des apôtres ?", "promptLanguage": "fr", "answer": "hérésie", "acceptedAnswers": ["hérésie", "une hérésie", "l''hérésie", "heresie"], "explanation": "C''est l''hérésie : une erreur de doctrine, à laquelle l''Église répond souvent par un dogme.", "tip": "Hérésie = doctrine ; schisme = unité.", "extraExample": {"text": "Le gnosticisme est une hérésie du premier siècle.", "translation": "On l''étudie dans la leçon 6."}, "hint": "Elle commence par « h ».", "id": "eg.l01.e17", "pool": "lesson", "lessonId": "eg.l01", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l01.e18', 'eg', 'eg.l01', 'eg.g01.pourquoi_histoire', array['eg.g01.pourquoi_histoire','eg.v.empire_romain']::text[], 'free_answer', 'lesson', 'Quelle puissance domine presque tout le monde connu au temps de Jésus ?', array['l''Empire romain','empire romain','Rome','les Romains']::text[], 'L''Empire romain est le décor de la naissance de l''Église : il occupe Jérusalem et relie les peuples par ses routes.', 1, '{"unitIds": ["eg.g01.pourquoi_histoire", "eg.v.empire_romain"], "type": "free_answer", "difficulty": 1, "instruction": "Écris ta réponse.", "prompt": "Quelle puissance domine presque tout le monde connu au temps de Jésus ?", "promptLanguage": "fr", "answer": "l''Empire romain", "acceptedAnswers": ["l''Empire romain", "empire romain", "Rome", "les Romains"], "explanation": "L''Empire romain est le décor de la naissance de l''Église : il occupe Jérusalem et relie les peuples par ses routes.", "tip": "Rome est le décor.", "extraExample": {"text": "Les empereurs romains persécuteront les chrétiens.", "translation": "Mais les routes romaines aideront aussi les apôtres."}, "hint": "Sa capitale est Rome.", "id": "eg.l01.e18", "pool": "lesson", "lessonId": "eg.l01", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l01.e19', 'eg', 'eg.l01', 'eg.g01.pourquoi_histoire', array['eg.g01.pourquoi_histoire','eg.v.histoire_ecclesiastique']::text[], 'free_answer', 'lesson', 'Jusqu''à quel siècle va notre voyage dans l''histoire de l''Église ? (réponds en lettres)', array['vingtième','le vingtième','20e','20ème','vingtieme']::text[], 'Nous parcourons les vingt premiers siècles de l''Église, du premier au vingtième.', 2, '{"unitIds": ["eg.g01.pourquoi_histoire", "eg.v.histoire_ecclesiastique"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Jusqu''à quel siècle va notre voyage dans l''histoire de l''Église ? (réponds en lettres)", "promptLanguage": "fr", "answer": "vingtième", "acceptedAnswers": ["vingtième", "le vingtième", "20e", "20ème", "vingtieme"], "explanation": "Nous parcourons les vingt premiers siècles de l''Église, du premier au vingtième.", "tip": "Vingt siècles de mémoire.", "extraExample": {"text": "Chaque siècle a ses événements majeurs.", "translation": "Le premier est le plus court à apprendre."}, "hint": "Un nombre ordinal.", "id": "eg.l01.e19", "pool": "lesson", "lessonId": "eg.l01", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l02.e01', 'eg', 'eg.l02', 'eg.g01.pourquoi_histoire', array['eg.g01.pourquoi_histoire','eg.v.schisme']::text[], 'mcq', 'lesson', 'Quelle phrase décrit le mieux un schisme ?', array['une rupture de communion']::text[], 'Un schisme est une rupture de communion entre des Églises. Un enseignement qui s''écarte de la foi est une hérésie.', 2, '{"unitIds": ["eg.g01.pourquoi_histoire", "eg.v.schisme"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle phrase décrit le mieux un schisme ?", "promptLanguage": "fr", "answer": "une rupture de communion", "acceptedAnswers": ["une rupture de communion"], "explanation": "Un schisme est une rupture de communion entre des Églises. Un enseignement qui s''écarte de la foi est une hérésie.", "tip": "Schisme = unité rompue.", "extraExample": {"text": "Rome et Constantinople se séparent en 1054.", "translation": "C''est un schisme."}, "options": ["un enseignement qui s''écarte de la foi", "une vérité de foi", "une rupture de communion"], "id": "eg.l02.e01", "pool": "lesson", "lessonId": "eg.l02", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l02.e02', 'eg', 'eg.l02', 'eg.g01.pourquoi_histoire', array['eg.g01.pourquoi_histoire','eg.v.heresie']::text[], 'fill_blank', 'lesson', 'Beaucoup de dogmes sont nés pour répondre à une ___.', array['hérésie']::text[], 'Une erreur de doctrine oblige l''Église à préciser clairement sa foi : c''est la source de beaucoup de dogmes.', 2, '{"unitIds": ["eg.g01.pourquoi_histoire", "eg.v.heresie"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Beaucoup de dogmes sont nés pour répondre à une ___.", "promptLanguage": "fr", "answer": "hérésie", "acceptedAnswers": ["hérésie"], "explanation": "Une erreur de doctrine oblige l''Église à préciser clairement sa foi : c''est la source de beaucoup de dogmes.", "tip": "Erreur → dogme.", "extraExample": {"text": "Nicée répond à Arius.", "translation": "Le dogme explique la foi."}, "options": ["fête", "hérésie", "persécution"], "id": "eg.l02.e02", "pool": "lesson", "lessonId": "eg.l02", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l02.e03', 'eg', 'eg.l02', 'eg.g01.pourquoi_histoire', array['eg.g01.pourquoi_histoire','eg.v.empire_romain','eg.v.ponce_pilate']::text[], 'mcq', 'lesson', 'Quel empire domine la Judée, où Jésus est jugé par un gouverneur ?', array['l''Empire romain']::text[], 'La Judée est occupée par les Romains. Ponce Pilate est leur gouverneur local.', 1, '{"unitIds": ["eg.g01.pourquoi_histoire", "eg.v.empire_romain", "eg.v.ponce_pilate"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel empire domine la Judée, où Jésus est jugé par un gouverneur ?", "promptLanguage": "fr", "answer": "l''Empire romain", "acceptedAnswers": ["l''Empire romain"], "explanation": "La Judée est occupée par les Romains. Ponce Pilate est leur gouverneur local.", "tip": "Rome tient Jérusalem.", "extraExample": {"text": "Jésus est jugé par un gouverneur romain.", "translation": "Il s''appelle Ponce Pilate."}, "options": ["l''Empire romain", "l''Empire perse", "l''empire d''Alexandre"], "id": "eg.l02.e03", "pool": "lesson", "lessonId": "eg.l02", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l02.e04', 'eg', 'eg.l02', 'eg.g01.pourquoi_histoire', array['eg.g01.pourquoi_histoire','eg.v.ere_chretienne']::text[], 'mcq', 'lesson', 'À partir de quel événement compte-t-on les années de l''ère chrétienne ?', array['la naissance de Jésus-Christ']::text[], 'L''ère chrétienne compte depuis la naissance de Jésus-Christ, même si les calculs ont été faits plus tard.', 2, '{"unitIds": ["eg.g01.pourquoi_histoire", "eg.v.ere_chretienne"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "À partir de quel événement compte-t-on les années de l''ère chrétienne ?", "promptLanguage": "fr", "answer": "la naissance de Jésus-Christ", "acceptedAnswers": ["la naissance de Jésus-Christ"], "explanation": "L''ère chrétienne compte depuis la naissance de Jésus-Christ, même si les calculs ont été faits plus tard.", "tip": "Naissance, pas Pentecôte.", "extraExample": {"text": "On écrit « vers 30 après J.-C. » pour la Pentecôte.", "translation": "Le repère reste la naissance du Christ."}, "options": ["la naissance de Jésus-Christ", "la Pentecôte", "la mort de Jésus"], "id": "eg.l02.e04", "pool": "lesson", "lessonId": "eg.l02", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l02.e05', 'eg', 'eg.l02', 'eg.g02.pentecote_communaute', array['eg.g02.pentecote_communaute','eg.v.ponce_pilate']::text[], 'mcq', 'lesson', 'Sous quel gouverneur romain Jésus est-il crucifié ?', array['Ponce Pilate']::text[], 'Jésus est crucifié sous Ponce Pilate, gouverneur de Judée. Le Credo garde son nom pour dater l''événement.', 1, '{"unitIds": ["eg.g02.pentecote_communaute", "eg.v.ponce_pilate"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Sous quel gouverneur romain Jésus est-il crucifié ?", "promptLanguage": "fr", "answer": "Ponce Pilate", "acceptedAnswers": ["Ponce Pilate"], "explanation": "Jésus est crucifié sous Ponce Pilate, gouverneur de Judée. Le Credo garde son nom pour dater l''événement.", "tip": "Le Credo : « sous Ponce Pilate ».", "extraExample": {"text": "Néron ne règne que plus tard.", "translation": "Hérode Agrippa agit vers 44."}, "options": ["Néron", "Ponce Pilate", "Hérode Agrippa"], "errorPatterns": [{"equals": "Néron", "category": "word_confusion", "feedback": "Néron est empereur dans les années 50-60, bien après la crucifixion."}], "id": "eg.l02.e05", "pool": "lesson", "lessonId": "eg.l02", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l02.e06', 'eg', 'eg.l02', 'eg.g02.pentecote_communaute', array['eg.g02.pentecote_communaute','eg.v.jesus_christ']::text[], 'mcq', 'lesson', 'Quand Jésus est-il crucifié ?', array['au début des années 30']::text[], 'Jésus naît vers l''an 4 avant J.-C. et il est crucifié au début des années 30 de notre ère, après environ trois ans de prédication.', 2, '{"unitIds": ["eg.g02.pentecote_communaute", "eg.v.jesus_christ"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quand Jésus est-il crucifié ?", "promptLanguage": "fr", "answer": "au début des années 30", "acceptedAnswers": ["au début des années 30"], "explanation": "Jésus naît vers l''an 4 avant J.-C. et il est crucifié au début des années 30 de notre ère, après environ trois ans de prédication.", "tip": "Naissance vers -4, croix vers 30.", "extraExample": {"text": "En l''an 70, le Temple est détruit.", "translation": "C''est une génération plus tard."}, "options": ["au début des années 30", "vers l''an 4 avant J.-C.", "vers l''an 70"], "id": "eg.l02.e06", "pool": "lesson", "lessonId": "eg.l02", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l02.e07', 'eg', 'eg.l02', 'eg.g02.pentecote_communaute', array['eg.g02.pentecote_communaute']::text[], 'mcq', 'lesson', 'Que font les disciples juste après la mort de Jésus ?', array['ils se cachent']::text[], 'Les disciples ont peur d''être arrêtés par les Romains et leurs rêves s''écroulent. Ce n''est qu''après la Résurrection qu''ils retrouvent leur confiance.', 2, '{"unitIds": ["eg.g02.pentecote_communaute"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que font les disciples juste après la mort de Jésus ?", "promptLanguage": "fr", "answer": "ils se cachent", "acceptedAnswers": ["ils se cachent"], "explanation": "Les disciples ont peur d''être arrêtés par les Romains et leurs rêves s''écroulent. Ce n''est qu''après la Résurrection qu''ils retrouvent leur confiance.", "tip": "La peur avant la Pentecôte.", "extraExample": {"text": "Pierre aura peur lui aussi, avant la Pentecôte.", "translation": "Puis il prêchera devant la foule."}, "options": ["ils quittent la Judée", "ils se cachent", "ils prêchent au Temple"], "id": "eg.l02.e07", "pool": "lesson", "lessonId": "eg.l02", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l02.e08', 'eg', 'eg.l02', 'eg.g02.pentecote_communaute', array['eg.g02.pentecote_communaute','eg.v.chambre_haute']::text[], 'mcq', 'lesson', 'Où se retrouvent les apôtres après l''Ascension ?', array['dans la chambre haute']::text[], 'Ils reviennent à Jérusalem et montent dans la chambre haute, où ils prient avec Marie et d''autres croyants.', 1, '{"unitIds": ["eg.g02.pentecote_communaute", "eg.v.chambre_haute"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Où se retrouvent les apôtres après l''Ascension ?", "promptLanguage": "fr", "answer": "dans la chambre haute", "acceptedAnswers": ["dans la chambre haute"], "explanation": "Ils reviennent à Jérusalem et montent dans la chambre haute, où ils prient avec Marie et d''autres croyants.", "tip": "Haute = à l''étage.", "extraExample": {"text": "Ils sont environ cent vingt.", "translation": "Ils prient avant la Pentecôte."}, "options": ["dans la chambre haute", "dans le Temple", "à Antioche"], "id": "eg.l02.e08", "pool": "lesson", "lessonId": "eg.l02", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l02.e09', 'eg', 'eg.l02', 'eg.g02.pentecote_communaute', array['eg.g02.pentecote_communaute','eg.v.jesus_christ']::text[], 'mcq', 'lesson', 'Combien de personnes environ forment le petit groupe de la chambre haute ?', array['cent vingt']::text[], 'Le groupe compte environ cent vingt personnes, dont les apôtres, des femmes, Marie et les frères de Jésus. Les trois mille viennent plus tard, à la Pentecôte.', 2, '{"unitIds": ["eg.g02.pentecote_communaute", "eg.v.jesus_christ"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Combien de personnes environ forment le petit groupe de la chambre haute ?", "promptLanguage": "fr", "answer": "cent vingt", "acceptedAnswers": ["cent vingt"], "explanation": "Le groupe compte environ cent vingt personnes, dont les apôtres, des femmes, Marie et les frères de Jésus. Les trois mille viennent plus tard, à la Pentecôte.", "tip": "120 avant, 3000 après.", "extraExample": {"text": "Le Christ avait choisi douze apôtres.", "translation": "Mais le groupe est plus large."}, "options": ["trois mille", "cent vingt", "douze"], "id": "eg.l02.e09", "pool": "lesson", "lessonId": "eg.l02", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l02.e10', 'eg', 'eg.l02', 'eg.g02.pentecote_communaute', array['eg.g02.pentecote_communaute','eg.v.pentecote']::text[], 'mcq', 'lesson', 'Quel jour la tradition place-t-elle les débuts de l''Église ?', array['la Pentecôte']::text[], 'À la Pentecôte, l''Esprit Saint descend, Pierre prêche et la mission commence : la tradition y voit la naissance de l''Église.', 1, '{"unitIds": ["eg.g02.pentecote_communaute", "eg.v.pentecote"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel jour la tradition place-t-elle les débuts de l''Église ?", "promptLanguage": "fr", "answer": "la Pentecôte", "acceptedAnswers": ["la Pentecôte"], "explanation": "À la Pentecôte, l''Esprit Saint descend, Pierre prêche et la mission commence : la tradition y voit la naissance de l''Église.", "tip": "Esprit reçu = Église lancée.", "extraExample": {"text": "La Pentecôte a lieu cinquante jours après Pâques.", "translation": "Le mot veut dire « cinquantième »."}, "options": ["la Pentecôte", "la Résurrection", "l''Ascension"], "id": "eg.l02.e10", "pool": "lesson", "lessonId": "eg.l02", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l02.e11', 'eg', 'eg.l02', 'eg.g02.pentecote_communaute', array['eg.g02.pentecote_communaute','eg.v.saint_pierre']::text[], 'mcq', 'lesson', 'Combien de personnes se convertissent le jour de la première prédication de Pierre ?', array['trois mille']::text[], 'Environ trois mille personnes se convertissent à Jérusalem le jour de la Pentecôte. Peu après, les croyants atteignent environ cinq mille.', 2, '{"unitIds": ["eg.g02.pentecote_communaute", "eg.v.saint_pierre"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Combien de personnes se convertissent le jour de la première prédication de Pierre ?", "promptLanguage": "fr", "answer": "trois mille", "acceptedAnswers": ["trois mille"], "explanation": "Environ trois mille personnes se convertissent à Jérusalem le jour de la Pentecôte. Peu après, les croyants atteignent environ cinq mille.", "tip": "3000 le premier jour.", "extraExample": {"text": "Le groupe initial comptait cent vingt.", "translation": "L''Église est déjà une foule."}, "options": ["cinq cents", "trois mille", "cent vingt"], "id": "eg.l02.e11", "pool": "lesson", "lessonId": "eg.l02", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l02.e12', 'eg', 'eg.l02', 'eg.g02.pentecote_communaute', array['eg.g02.pentecote_communaute']::text[], 'mcq', 'lesson', 'Quel pays africain est cité parmi les pèlerins présents à Jérusalem le jour de la Pentecôte ?', array['l''Égypte']::text[], 'Les Actes citent des gens de l''Égypte et de la région de Cyrène parmi les pèlerins. Pour un Copte, c''est un premier lien de l''Égypte avec l''Évangile.', 3, '{"unitIds": ["eg.g02.pentecote_communaute"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quel pays africain est cité parmi les pèlerins présents à Jérusalem le jour de la Pentecôte ?", "promptLanguage": "fr", "answer": "l''Égypte", "acceptedAnswers": ["l''Égypte"], "explanation": "Les Actes citent des gens de l''Égypte et de la région de Cyrène parmi les pèlerins. Pour un Copte, c''est un premier lien de l''Égypte avec l''Évangile.", "tip": "Égypte présente dès la Pentecôte.", "extraExample": {"text": "Ac 2, 10 cite l''Égypte.", "translation": "Marc l''évangélisera plus tard."}, "options": ["l''Inde", "la Gaule", "l''Égypte"], "id": "eg.l02.e12", "pool": "lesson", "lessonId": "eg.l02", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l02.e13', 'eg', 'eg.l02', 'eg.g02.pentecote_communaute', array['eg.g02.pentecote_communaute','eg.v.apotre']::text[], 'fill_blank', 'lesson', 'Le mot grec « apôtre » veut dire « ___ ».', array['envoyé']::text[], 'Les apôtres sont envoyés par Jésus pour annoncer l''Évangile à toutes les nations.', 2, '{"unitIds": ["eg.g02.pentecote_communaute", "eg.v.apotre"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Le mot grec « apôtre » veut dire « ___ ».", "promptLanguage": "fr", "answer": "envoyé", "acceptedAnswers": ["envoyé"], "explanation": "Les apôtres sont envoyés par Jésus pour annoncer l''Évangile à toutes les nations.", "tip": "Apôtre = envoyé.", "extraExample": {"text": "Paul est lui aussi envoyé aux nations.", "translation": "Il se dit apôtre."}, "options": ["prophète", "envoyé", "ancien"], "id": "eg.l02.e13", "pool": "lesson", "lessonId": "eg.l02", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l02.e14', 'eg', 'eg.l02', 'eg.g02.pentecote_communaute', array['eg.g02.pentecote_communaute','eg.v.fraction_du_pain']::text[], 'fill_blank', 'lesson', 'Les croyants sont assidus à l''enseignement des apôtres, à la communion fraternelle, à la fraction du pain et aux ___.', array['prières']::text[], 'Ces quatre piliers (Ac 2, 42) résument la vie de la première communauté de Jérusalem.', 2, '{"unitIds": ["eg.g02.pentecote_communaute", "eg.v.fraction_du_pain"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Les croyants sont assidus à l''enseignement des apôtres, à la communion fraternelle, à la fraction du pain et aux ___.", "promptLanguage": "fr", "answer": "prières", "acceptedAnswers": ["prières"], "explanation": "Ces quatre piliers (Ac 2, 42) résument la vie de la première communauté de Jérusalem.", "tip": "Quatre piliers.", "extraExample": {"text": "L''Église d''aujourd''hui vit encore ainsi.", "translation": "Enseignement, partage, eucharistie, prière."}, "options": ["prières", "fêtes", "pèlerinages"], "id": "eg.l02.e14", "pool": "lesson", "lessonId": "eg.l02", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l02.e15', 'eg', 'eg.l02', 'eg.g02.pentecote_communaute', array['eg.g02.pentecote_communaute','eg.v.premiere_communaute']::text[], 'fill_blank', 'lesson', 'Dans la première communauté, les croyants mettent leurs ___ en commun.', array['biens']::text[], 'La mise en commun des biens, matériels et spirituels, montre l''unité de la première communauté.', 2, '{"unitIds": ["eg.g02.pentecote_communaute", "eg.v.premiere_communaute"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Dans la première communauté, les croyants mettent leurs ___ en commun.", "promptLanguage": "fr", "answer": "biens", "acceptedAnswers": ["biens"], "explanation": "La mise en commun des biens, matériels et spirituels, montre l''unité de la première communauté.", "tip": "Tout est partagé.", "extraExample": {"text": "Personne ne manque de rien.", "translation": "C''est un idéal pour l''Église."}, "options": ["calendriers", "biens", "dettes"], "id": "eg.l02.e15", "pool": "lesson", "lessonId": "eg.l02", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l02.e16', 'eg', 'eg.l02', 'eg.g02.pentecote_communaute', array['eg.g02.pentecote_communaute','eg.v.jerusalem']::text[], 'fill_blank', 'lesson', 'Après l''Ascension, les apôtres regagnent ___.', array['Jérusalem']::text[], 'Jérusalem est le lieu de la Passion, de la Résurrection et de la Pentecôte : l''Église y naît.', 1, '{"unitIds": ["eg.g02.pentecote_communaute", "eg.v.jerusalem"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Après l''Ascension, les apôtres regagnent ___.", "promptLanguage": "fr", "answer": "Jérusalem", "acceptedAnswers": ["Jérusalem"], "explanation": "Jérusalem est le lieu de la Passion, de la Résurrection et de la Pentecôte : l''Église y naît.", "tip": "Tout commence à Jérusalem.", "extraExample": {"text": "Elle tombera en 70.", "translation": "Les chrétiens se disperseront."}, "options": ["Antioche", "Alexandrie", "Jérusalem"], "id": "eg.l02.e16", "pool": "lesson", "lessonId": "eg.l02", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l02.e17', 'eg', 'eg.l02', 'eg.g02.pentecote_communaute', array['eg.g02.pentecote_communaute']::text[], 'fill_blank', 'lesson', 'Le Christ ressuscite le ___ jour.', array['troisième']::text[], 'Crucifié et enseveli, Jésus ressuscite le troisième jour, puis monte au ciel quarante jours plus tard.', 1, '{"unitIds": ["eg.g02.pentecote_communaute"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Le Christ ressuscite le ___ jour.", "promptLanguage": "fr", "answer": "troisième", "acceptedAnswers": ["troisième"], "explanation": "Crucifié et enseveli, Jésus ressuscite le troisième jour, puis monte au ciel quarante jours plus tard.", "tip": "Trois jours, puis quarante.", "extraExample": {"text": "Le troisième jour, c''est Pâques.", "translation": "L''Ascension arrive bien après."}, "options": ["septième", "quarantième", "troisième"], "id": "eg.l02.e17", "pool": "lesson", "lessonId": "eg.l02", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l02.e18', 'eg', 'eg.l02', 'eg.g02.pentecote_communaute', array['eg.g02.pentecote_communaute','eg.v.ascension','eg.v.pentecote','eg.v.chambre_haute','eg.v.ponce_pilate']::text[], 'match', 'lesson', 'Les étapes et les lieux', '{}'::text[], 'Chaque mot correspond à une étape de la route : Ponce Pilate à la croix, l''Ascension après la Résurrection, la chambre haute où l''on prie, la Pentecôte où l''Église naît.', 1, '{"unitIds": ["eg.g02.pentecote_communaute", "eg.v.ascension", "eg.v.pentecote", "eg.v.chambre_haute", "eg.v.ponce_pilate"], "type": "match", "difficulty": 1, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Les étapes et les lieux", "promptLanguage": "fr", "answer": "La Pentecôte = l''Esprit descend, l''Église naît ; L''Ascension = Jésus monte au ciel ; La chambre haute = le lieu de prière des apôtres ; Ponce Pilate = le gouverneur romain de Judée", "acceptedAnswers": [], "explanation": "Chaque mot correspond à une étape de la route : Ponce Pilate à la croix, l''Ascension après la Résurrection, la chambre haute où l''on prie, la Pentecôte où l''Église naît.", "tip": "Croix, Ascension, chambre haute, Pentecôte.", "pairs": [{"left": "La Pentecôte", "right": "l''Esprit descend, l''Église naît"}, {"left": "L''Ascension", "right": "Jésus monte au ciel"}, {"left": "La chambre haute", "right": "le lieu de prière des apôtres"}, {"left": "Ponce Pilate", "right": "le gouverneur romain de Judée"}], "id": "eg.l02.e18", "pool": "lesson", "lessonId": "eg.l02", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l02.e19', 'eg', 'eg.l02', 'eg.g02.pentecote_communaute', array['eg.g02.pentecote_communaute','eg.v.premiere_communaute','eg.v.saint_pierre']::text[], 'match', 'lesson', 'Les chiffres de la première communauté', '{}'::text[], 'Le groupe grandit très vite : cent vingt, puis trois mille à la Pentecôte, puis environ cinq mille. Quatre piliers le structurent.', 3, '{"unitIds": ["eg.g02.pentecote_communaute", "eg.v.premiere_communaute", "eg.v.saint_pierre"], "type": "match", "difficulty": 3, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Les chiffres de la première communauté", "promptLanguage": "fr", "answer": "Cent vingt = le groupe de la chambre haute ; Trois mille = convertis le jour de la Pentecôte ; Cinq mille = croyants peu après ; Quatre = piliers de la vie commune", "acceptedAnswers": [], "explanation": "Le groupe grandit très vite : cent vingt, puis trois mille à la Pentecôte, puis environ cinq mille. Quatre piliers le structurent.", "tip": "120 → 3000 → 5000.", "pairs": [{"left": "Cent vingt", "right": "le groupe de la chambre haute"}, {"left": "Trois mille", "right": "convertis le jour de la Pentecôte"}, {"left": "Cinq mille", "right": "croyants peu après"}, {"left": "Quatre", "right": "piliers de la vie commune"}], "id": "eg.l02.e19", "pool": "lesson", "lessonId": "eg.l02", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l02.e20', 'eg', 'eg.l02', 'eg.g02.pentecote_communaute', array['eg.g02.pentecote_communaute']::text[], 'reorder', 'lesson', 'Phrase-repère : la naissance de l''Église.', array['La Pentecôte marque la naissance de l''Église']::text[], 'La tradition chrétienne place à la Pentecôte les débuts de l''Église.', 1, '{"unitIds": ["eg.g02.pentecote_communaute"], "type": "reorder", "difficulty": 1, "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "prompt": "Phrase-repère : la naissance de l''Église.", "promptLanguage": "fr", "answer": "La Pentecôte marque la naissance de l''Église", "acceptedAnswers": ["La Pentecôte marque la naissance de l''Église"], "explanation": "La tradition chrétienne place à la Pentecôte les débuts de l''Église.", "tip": "Pentecôte = naissance de l''Église.", "extraExample": {"text": "L''Esprit Saint descend sur les apôtres.", "translation": "Pierre prêche à la foule."}, "tokens": ["naissance", "de", "l''Église", "La", "Pentecôte", "marque", "la"], "id": "eg.l02.e20", "pool": "lesson", "lessonId": "eg.l02", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l02.e21', 'eg', 'eg.l02', 'eg.g02.pentecote_communaute', array['eg.g02.pentecote_communaute','eg.v.pentecote']::text[], 'free_answer', 'lesson', 'Comment s''appelle la fête où l''Esprit Saint descend sur les apôtres, début de l''Église ?', array['la Pentecôte','Pentecôte','pentecote']::text[], 'C''est la Pentecôte, cinquante jours après la Résurrection.', 1, '{"unitIds": ["eg.g02.pentecote_communaute", "eg.v.pentecote"], "type": "free_answer", "difficulty": 1, "instruction": "Écris ta réponse.", "prompt": "Comment s''appelle la fête où l''Esprit Saint descend sur les apôtres, début de l''Église ?", "promptLanguage": "fr", "answer": "la Pentecôte", "acceptedAnswers": ["la Pentecôte", "Pentecôte", "pentecote"], "explanation": "C''est la Pentecôte, cinquante jours après la Résurrection.", "tip": "Cinquante jours après Pâques.", "extraExample": {"text": "Elle a lieu vers l''an 30.", "translation": "Pierre y prêche."}, "hint": "Son nom veut dire « cinquantième ».", "id": "eg.l02.e21", "pool": "lesson", "lessonId": "eg.l02", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l02.e22', 'eg', 'eg.l02', 'eg.g02.pentecote_communaute', array['eg.g02.pentecote_communaute','eg.v.fraction_du_pain']::text[], 'free_answer', 'lesson', 'Les premiers chrétiens célèbrent « la fraction du ___ ».', array['pain','la fraction du pain']::text[], 'La fraction du pain est le nom donné à l''eucharistie dans la première communauté.', 2, '{"unitIds": ["eg.g02.pentecote_communaute", "eg.v.fraction_du_pain"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Les premiers chrétiens célèbrent « la fraction du ___ ».", "promptLanguage": "fr", "answer": "pain", "acceptedAnswers": ["pain", "la fraction du pain"], "explanation": "La fraction du pain est le nom donné à l''eucharistie dans la première communauté.", "tip": "Rompre le pain.", "extraExample": {"text": "Jésus rompt le pain à la dernière Cène.", "translation": "Les disciples l''imitent."}, "hint": "Un aliment de base.", "id": "eg.l02.e22", "pool": "lesson", "lessonId": "eg.l02", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l02.e23', 'eg', 'eg.l02', 'eg.g02.pentecote_communaute', array['eg.g02.pentecote_communaute','eg.v.saint_pierre','eg.v.pentecote']::text[], 'free_answer', 'lesson', 'Quel apôtre prêche en public le jour de la Pentecôte ?', array['Pierre','saint Pierre','St Pierre']::text[], 'Pierre, le chef des apôtres, prend la parole : trois mille personnes se convertissent.', 1, '{"unitIds": ["eg.g02.pentecote_communaute", "eg.v.saint_pierre", "eg.v.pentecote"], "type": "free_answer", "difficulty": 1, "instruction": "Écris ta réponse.", "prompt": "Quel apôtre prêche en public le jour de la Pentecôte ?", "promptLanguage": "fr", "answer": "Pierre", "acceptedAnswers": ["Pierre", "saint Pierre", "St Pierre"], "explanation": "Pierre, le chef des apôtres, prend la parole : trois mille personnes se convertissent.", "tip": "Pierre porte la voix des Douze.", "extraExample": {"text": "Il sera martyrisé à Rome.", "translation": "Vers l''an 67."}, "hint": "Il a reçu ce nom de Jésus.", "id": "eg.l02.e23", "pool": "lesson", "lessonId": "eg.l02", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l03.e01', 'eg', 'eg.l03', 'eg.g02.pentecote_communaute', array['eg.g02.pentecote_communaute','eg.v.pentecote']::text[], 'mcq', 'lesson', 'Quelle fête marque la naissance de l''Église ?', array['la Pentecôte']::text[], 'À la Pentecôte, l''Esprit Saint descend sur les apôtres et l''Église naît à Jérusalem.', 1, '{"unitIds": ["eg.g02.pentecote_communaute", "eg.v.pentecote"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle fête marque la naissance de l''Église ?", "promptLanguage": "fr", "answer": "la Pentecôte", "acceptedAnswers": ["la Pentecôte"], "explanation": "À la Pentecôte, l''Esprit Saint descend sur les apôtres et l''Église naît à Jérusalem.", "tip": "Cinquante jours après Pâques.", "extraExample": {"text": "Trois mille personnes se convertissent ce jour-là.", "translation": "Pierre est le prédicateur."}, "options": ["la Résurrection", "la Pentecôte", "l''Ascension"], "id": "eg.l03.e01", "pool": "lesson", "lessonId": "eg.l03", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l03.e02', 'eg', 'eg.l03', 'eg.g02.pentecote_communaute', array['eg.g02.pentecote_communaute','eg.v.fraction_du_pain']::text[], 'fill_blank', 'lesson', 'La première communauté est fidèle à la ___ du pain.', array['fraction']::text[], 'La fraction du pain est le nom de l''eucharistie chez les premiers chrétiens.', 2, '{"unitIds": ["eg.g02.pentecote_communaute", "eg.v.fraction_du_pain"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "La première communauté est fidèle à la ___ du pain.", "promptLanguage": "fr", "answer": "fraction", "acceptedAnswers": ["fraction"], "explanation": "La fraction du pain est le nom de l''eucharistie chez les premiers chrétiens.", "tip": "Rompre le pain.", "extraExample": {"text": "Elle fait partie des quatre piliers.", "translation": "Enseignement, communion, fraction du pain, prières."}, "options": ["fraction", "bénédiction", "distribution"], "id": "eg.l03.e02", "pool": "lesson", "lessonId": "eg.l03", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l03.e03', 'eg', 'eg.l03', 'eg.g01.pourquoi_histoire', array['eg.g01.pourquoi_histoire','eg.v.schisme']::text[], 'free_answer', 'lesson', 'Comment appelle-t-on une rupture de communion entre des Églises ?', array['schisme','un schisme','le schisme']::text[], 'C''est un schisme : l''unité est rompue, même si la doctrine peut rester proche.', 2, '{"unitIds": ["eg.g01.pourquoi_histoire", "eg.v.schisme"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Comment appelle-t-on une rupture de communion entre des Églises ?", "promptLanguage": "fr", "answer": "schisme", "acceptedAnswers": ["schisme", "un schisme", "le schisme"], "explanation": "C''est un schisme : l''unité est rompue, même si la doctrine peut rester proche.", "tip": "Schisme = séparation.", "extraExample": {"text": "Il se distingue de l''hérésie.", "translation": "L''hérésie touche la doctrine."}, "hint": "Elle commence par « sch ».", "id": "eg.l03.e03", "pool": "lesson", "lessonId": "eg.l03", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l03.e04', 'eg', 'eg.l03', 'eg.g02.pentecote_communaute', array['eg.g02.pentecote_communaute','eg.v.jerusalem']::text[], 'mcq', 'lesson', 'Dans quelle ville naît l''Église ?', array['Jérusalem']::text[], 'L''Église naît à Jérusalem, à la Pentecôte. Antioche et Rome viendront ensuite.', 1, '{"unitIds": ["eg.g02.pentecote_communaute", "eg.v.jerusalem"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Dans quelle ville naît l''Église ?", "promptLanguage": "fr", "answer": "Jérusalem", "acceptedAnswers": ["Jérusalem"], "explanation": "L''Église naît à Jérusalem, à la Pentecôte. Antioche et Rome viendront ensuite.", "tip": "Tout commence à Jérusalem.", "extraExample": {"text": "Les apôtres y prêchent d''abord.", "translation": "Puis ils se dispersent."}, "options": ["Jérusalem", "Antioche", "Rome"], "id": "eg.l03.e04", "pool": "lesson", "lessonId": "eg.l03", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l03.e05', 'eg', 'eg.l03', 'eg.g03.etienne_paul_missions', array['eg.g03.etienne_paul_missions','eg.v.helleniste']::text[], 'mcq', 'lesson', 'Qui sont les hellénistes ?', array['les chrétiens de langue grecque']::text[], 'Les hellénistes sont des chrétiens de langue grecque. Leurs veuves sont oubliées dans le service quotidien, ce qui provoque le premier conflit.', 2, '{"unitIds": ["eg.g03.etienne_paul_missions", "eg.v.helleniste"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui sont les hellénistes ?", "promptLanguage": "fr", "answer": "les chrétiens de langue grecque", "acceptedAnswers": ["les chrétiens de langue grecque"], "explanation": "Les hellénistes sont des chrétiens de langue grecque. Leurs veuves sont oubliées dans le service quotidien, ce qui provoque le premier conflit.", "tip": "Hellène = grec.", "extraExample": {"text": "Le mot hellénique vient de Hellas, la Grèce.", "translation": "Ils parlent grec."}, "options": ["les chrétiens de langue grecque", "les chrétiens de langue hébraïque", "les prêtres du Temple"], "id": "eg.l03.e05", "pool": "lesson", "lessonId": "eg.l03", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l03.e06', 'eg', 'eg.l03', 'eg.g03.etienne_paul_missions', array['eg.g03.etienne_paul_missions','eg.v.helleniste']::text[], 'fill_blank', 'lesson', 'Les hellénistes se plaignent que leurs ___ soient oubliées dans le service quotidien.', array['veuves']::text[], 'Le service quotidien oublie les veuves des hellénistes : ce premier conflit mène au choix de sept hommes.', 2, '{"unitIds": ["eg.g03.etienne_paul_missions", "eg.v.helleniste"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Les hellénistes se plaignent que leurs ___ soient oubliées dans le service quotidien.", "promptLanguage": "fr", "answer": "veuves", "acceptedAnswers": ["veuves"], "explanation": "Le service quotidien oublie les veuves des hellénistes : ce premier conflit mène au choix de sept hommes.", "tip": "Veuves oubliées = conflit.", "extraExample": {"text": "Les apôtres ne peuvent tout faire.", "translation": "Ils délèguent."}, "options": ["veuves", "enfants", "prêtres"], "id": "eg.l03.e06", "pool": "lesson", "lessonId": "eg.l03", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l03.e07', 'eg', 'eg.l03', 'eg.g03.etienne_paul_missions', array['eg.g03.etienne_paul_missions']::text[], 'mcq', 'lesson', 'Combien d''hommes sont choisis pour le service des tables ?', array['sept']::text[], 'Les apôtres, occupés par la prédication, font choisir sept hommes pour le service. Étienne est l''un d''eux.', 2, '{"unitIds": ["eg.g03.etienne_paul_missions"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Combien d''hommes sont choisis pour le service des tables ?", "promptLanguage": "fr", "answer": "sept", "acceptedAnswers": ["sept"], "explanation": "Les apôtres, occupés par la prédication, font choisir sept hommes pour le service. Étienne est l''un d''eux.", "tip": "Douze apôtres, sept pour le service.", "extraExample": {"text": "Le service est confié à d''autres.", "translation": "Pour libérer les apôtres."}, "options": ["trois", "sept", "douze"], "id": "eg.l03.e07", "pool": "lesson", "lessonId": "eg.l03", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l03.e08', 'eg', 'eg.l03', 'eg.g03.etienne_paul_missions', array['eg.g03.etienne_paul_missions','eg.v.saint_etienne']::text[], 'mcq', 'lesson', 'Qui est le premier martyr chrétien ?', array['Étienne']::text[], 'Étienne est lapidé à Jérusalem vers 35, après avoir témoigné devant les autorités. Il est le premier martyr de l''Église.', 1, '{"unitIds": ["eg.g03.etienne_paul_missions", "eg.v.saint_etienne"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Qui est le premier martyr chrétien ?", "promptLanguage": "fr", "answer": "Étienne", "acceptedAnswers": ["Étienne"], "explanation": "Étienne est lapidé à Jérusalem vers 35, après avoir témoigné devant les autorités. Il est le premier martyr de l''Église.", "tip": "Étienne = premier.", "extraExample": {"text": "Jacques de Zébédée est martyrisé vers 44.", "translation": "Pierre vers 67."}, "options": ["Jacques", "Pierre", "Étienne"], "errorPatterns": [{"equals": "Jacques", "category": "word_confusion", "feedback": "Jacques de Zébédée meurt vers 44, après Étienne."}, {"equals": "Pierre", "category": "word_confusion", "feedback": "Pierre est martyrisé à Rome vers 67."}], "id": "eg.l03.e08", "pool": "lesson", "lessonId": "eg.l03", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l03.e09', 'eg', 'eg.l03', 'eg.g03.etienne_paul_missions', array['eg.g03.etienne_paul_missions','eg.v.saint_etienne']::text[], 'fill_blank', 'lesson', 'Étienne meurt ___ vers 35 : il est le premier martyr.', array['lapidé']::text[], 'Étienne est lapidé, c''est-à-dire tué à coups de pierres, vers 35.', 2, '{"unitIds": ["eg.g03.etienne_paul_missions", "eg.v.saint_etienne"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Étienne meurt ___ vers 35 : il est le premier martyr.", "promptLanguage": "fr", "answer": "lapidé", "acceptedAnswers": ["lapidé"], "explanation": "Étienne est lapidé, c''est-à-dire tué à coups de pierres, vers 35.", "tip": "Lapidé = pierres.", "extraExample": {"text": "Jacques de Zébédée est décapité.", "translation": "Chaque martyr a sa mort."}, "options": ["crucifié", "lapidé", "décapité"], "id": "eg.l03.e09", "pool": "lesson", "lessonId": "eg.l03", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l03.e10', 'eg', 'eg.l03', 'eg.g03.etienne_paul_missions', array['eg.g03.etienne_paul_missions','eg.v.martyr']::text[], 'free_answer', 'lesson', 'Quel mot, du grec « témoin », désigne celui qui meurt pour sa foi ?', array['martyr','un martyr','le martyr']::text[], 'Le martyr est un témoin du Christ jusqu''à la mort. Étienne est le premier.', 1, '{"unitIds": ["eg.g03.etienne_paul_missions", "eg.v.martyr"], "type": "free_answer", "difficulty": 1, "instruction": "Écris ta réponse.", "prompt": "Quel mot, du grec « témoin », désigne celui qui meurt pour sa foi ?", "promptLanguage": "fr", "answer": "martyr", "acceptedAnswers": ["martyr", "un martyr", "le martyr"], "explanation": "Le martyr est un témoin du Christ jusqu''à la mort. Étienne est le premier.", "tip": "Martyr = témoin.", "extraExample": {"text": "Marc sera martyr à Alexandrie.", "translation": "Le mot grec martys."}, "hint": "Il commence par « m ».", "id": "eg.l03.e10", "pool": "lesson", "lessonId": "eg.l03", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l03.e11', 'eg', 'eg.l03', 'eg.g03.etienne_paul_missions', array['eg.g03.etienne_paul_missions']::text[], 'mcq', 'lesson', 'Quel est l''effet de la persécution qui suit la mort d''Étienne ?', array['l''Évangile se répand']::text[], 'Les chrétiens se dispersent, mais ils annoncent l''Évangile là où ils vont. La persécution étend l''Église.', 2, '{"unitIds": ["eg.g03.etienne_paul_missions"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel est l''effet de la persécution qui suit la mort d''Étienne ?", "promptLanguage": "fr", "answer": "l''Évangile se répand", "acceptedAnswers": ["l''Évangile se répand"], "explanation": "Les chrétiens se dispersent, mais ils annoncent l''Évangile là où ils vont. La persécution étend l''Église.", "tip": "Persécuter disperse, disperser sème.", "extraExample": {"text": "Antioche reçoit ainsi l''Évangile.", "translation": "Les Samaritains aussi."}, "options": ["l''Église disparaît", "les apôtres cessent de prêcher", "l''Évangile se répand"], "id": "eg.l03.e11", "pool": "lesson", "lessonId": "eg.l03", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l03.e12', 'eg', 'eg.l03', 'eg.g03.etienne_paul_missions', array['eg.g03.etienne_paul_missions','eg.v.saint_paul']::text[], 'mcq', 'lesson', 'Sur quelle route Saul rencontre-t-il le Christ vers l''an 35 ?', array['la route de Damas']::text[], 'Sur la route de Damas, le Christ apparaît à Saul le persécuteur : il devient Paul.', 1, '{"unitIds": ["eg.g03.etienne_paul_missions", "eg.v.saint_paul"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Sur quelle route Saul rencontre-t-il le Christ vers l''an 35 ?", "promptLanguage": "fr", "answer": "la route de Damas", "acceptedAnswers": ["la route de Damas"], "explanation": "Sur la route de Damas, le Christ apparaît à Saul le persécuteur : il devient Paul.", "tip": "Damas = conversion.", "extraExample": {"text": "Il avait des lettres contre les chrétiens.", "translation": "Il est renversé."}, "options": ["la route de Rome", "la route d''Alexandrie", "la route de Damas"], "id": "eg.l03.e12", "pool": "lesson", "lessonId": "eg.l03", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l03.e13', 'eg', 'eg.l03', 'eg.g03.etienne_paul_missions', array['eg.g03.etienne_paul_missions','eg.v.saint_paul']::text[], 'fill_blank', 'lesson', 'Saul, devenu ___, est l''apôtre des nations.', array['Paul']::text[], 'Saul change de vie et de nom d''usage : Paul est l''apôtre des nations.', 1, '{"unitIds": ["eg.g03.etienne_paul_missions", "eg.v.saint_paul"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Saul, devenu ___, est l''apôtre des nations.", "promptLanguage": "fr", "answer": "Paul", "acceptedAnswers": ["Paul"], "explanation": "Saul change de vie et de nom d''usage : Paul est l''apôtre des nations.", "tip": "Saul → Paul.", "extraExample": {"text": "Paul est aussi citoyen romain.", "translation": "Il écrit de nombreuses lettres."}, "options": ["Pierre", "Barnabé", "Paul"], "id": "eg.l03.e13", "pool": "lesson", "lessonId": "eg.l03", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l03.e14', 'eg', 'eg.l03', 'eg.g03.etienne_paul_missions', array['eg.g03.etienne_paul_missions','eg.v.barnabe']::text[], 'free_answer', 'lesson', 'Comment s''appelle le compagnon de Paul dans ses premières missions ?', array['Barnabé','saint Barnabé','Barnabe']::text[], 'Barnabé accompagne Paul dans les synagogues puis chez les païens.', 2, '{"unitIds": ["eg.g03.etienne_paul_missions", "eg.v.barnabe"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Comment s''appelle le compagnon de Paul dans ses premières missions ?", "promptLanguage": "fr", "answer": "Barnabé", "acceptedAnswers": ["Barnabé", "saint Barnabé", "Barnabe"], "explanation": "Barnabé accompagne Paul dans les synagogues puis chez les païens.", "tip": "Paul et Barnabé vont ensemble.", "extraExample": {"text": "Barnabé est le cousin de Marc.", "translation": "Il sera utile pour la suite."}, "hint": "Son nom commence par « B ».", "id": "eg.l03.e14", "pool": "lesson", "lessonId": "eg.l03", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l03.e15', 'eg', 'eg.l03', 'eg.g03.etienne_paul_missions', array['eg.g03.etienne_paul_missions','eg.v.synagogue']::text[], 'mcq', 'lesson', 'Où Paul va-t-il d''abord dans chaque ville ?', array['la synagogue']::text[], 'Dans chaque ville, Paul va d''abord à la synagogue, pour convaincre les Juifs, qui connaissent déjà les Écritures.', 2, '{"unitIds": ["eg.g03.etienne_paul_missions", "eg.v.synagogue"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Où Paul va-t-il d''abord dans chaque ville ?", "promptLanguage": "fr", "answer": "la synagogue", "acceptedAnswers": ["la synagogue"], "explanation": "Dans chaque ville, Paul va d''abord à la synagogue, pour convaincre les Juifs, qui connaissent déjà les Écritures.", "tip": "D''abord ses frères juifs.", "extraExample": {"text": "Les synagogues sont partout dans l''Empire.", "translation": "Elles servent de porte d''entrée."}, "options": ["le marché", "la synagogue", "le palais du gouverneur"], "id": "eg.l03.e15", "pool": "lesson", "lessonId": "eg.l03", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l03.e16', 'eg', 'eg.l03', 'eg.g03.etienne_paul_missions', array['eg.g03.etienne_paul_missions','eg.v.paiens']::text[], 'mcq', 'lesson', 'Comment appelle-t-on les non-juifs auxquels Paul annonce l''Évangile ?', array['les païens']::text[], 'Les païens sont les non-juifs. Quand les synagogues refusent, Paul se tourne vers eux et rencontre un grand succès.', 1, '{"unitIds": ["eg.g03.etienne_paul_missions", "eg.v.paiens"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Comment appelle-t-on les non-juifs auxquels Paul annonce l''Évangile ?", "promptLanguage": "fr", "answer": "les païens", "acceptedAnswers": ["les païens"], "explanation": "Les païens sont les non-juifs. Quand les synagogues refusent, Paul se tourne vers eux et rencontre un grand succès.", "tip": "Païens = non-juifs.", "extraExample": {"text": "Beaucoup de Grecs accueillent l''Évangile.", "translation": "Sans devenir juifs."}, "options": ["les païens", "les hellénistes", "les pharisiens"], "id": "eg.l03.e16", "pool": "lesson", "lessonId": "eg.l03", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l03.e17', 'eg', 'eg.l03', 'eg.g03.etienne_paul_missions', array['eg.g03.etienne_paul_missions','eg.v.antioche','eg.v.chretiens']::text[], 'mcq', 'lesson', 'Dans quelle ville les disciples sont-ils appelés « chrétiens » pour la première fois ?', array['Antioche']::text[], 'À Antioche de Syrie, le nom de chrétiens apparaît pour la première fois pour désigner les disciples du Christ.', 2, '{"unitIds": ["eg.g03.etienne_paul_missions", "eg.v.antioche", "eg.v.chretiens"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Dans quelle ville les disciples sont-ils appelés « chrétiens » pour la première fois ?", "promptLanguage": "fr", "answer": "Antioche", "acceptedAnswers": ["Antioche"], "explanation": "À Antioche de Syrie, le nom de chrétiens apparaît pour la première fois pour désigner les disciples du Christ.", "tip": "Antioche = chrétiens.", "extraExample": {"text": "Le nom vient de Christ.", "translation": "Il est d''abord donné de l''extérieur."}, "options": ["Rome", "Antioche", "Jérusalem"], "id": "eg.l03.e17", "pool": "lesson", "lessonId": "eg.l03", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l03.e18', 'eg', 'eg.l03', 'eg.g03.etienne_paul_missions', array['eg.g03.etienne_paul_missions','eg.v.saint_paul']::text[], 'fill_blank', 'lesson', 'Paul arrive à Rome vers l''an ___.', array['61']::text[], 'Paul arrive à Rome vers 61, où il trouve déjà des chrétiens. Il y sera martyrisé vers 67.', 3, '{"unitIds": ["eg.g03.etienne_paul_missions", "eg.v.saint_paul"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète la phrase.", "prompt": "Paul arrive à Rome vers l''an ___.", "promptLanguage": "fr", "answer": "61", "acceptedAnswers": ["61"], "explanation": "Paul arrive à Rome vers 61, où il trouve déjà des chrétiens. Il y sera martyrisé vers 67.", "tip": "61 : Rome.", "extraExample": {"text": "Le concile de Jérusalem a lieu vers 49.", "translation": "La chute de Jérusalem en 70."}, "options": ["70", "61", "49"], "id": "eg.l03.e18", "pool": "lesson", "lessonId": "eg.l03", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l03.e19', 'eg', 'eg.l03', 'eg.g03.etienne_paul_missions', array['eg.g03.etienne_paul_missions','eg.v.saint_etienne','eg.v.saint_paul','eg.v.barnabe','eg.v.antioche']::text[], 'match', 'lesson', 'Personnes et lieux', '{}'::text[], 'Étienne meurt, Paul se convertit, Barnabé le suit, Antioche donne le nom de chrétiens.', 1, '{"unitIds": ["eg.g03.etienne_paul_missions", "eg.v.saint_etienne", "eg.v.saint_paul", "eg.v.barnabe", "eg.v.antioche"], "type": "match", "difficulty": 1, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Personnes et lieux", "promptLanguage": "fr", "answer": "Étienne = le premier martyr chrétien ; Saul = devient Paul sur la route de Damas ; Barnabé = le compagnon de Paul ; Antioche = les disciples sont appelés chrétiens", "acceptedAnswers": [], "explanation": "Étienne meurt, Paul se convertit, Barnabé le suit, Antioche donne le nom de chrétiens.", "tip": "Un martyr, un converti, un compagnon, une ville.", "pairs": [{"left": "Étienne", "right": "le premier martyr chrétien"}, {"left": "Saul", "right": "devient Paul sur la route de Damas"}, {"left": "Barnabé", "right": "le compagnon de Paul"}, {"left": "Antioche", "right": "les disciples sont appelés chrétiens"}], "id": "eg.l03.e19", "pool": "lesson", "lessonId": "eg.l03", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l03.e20', 'eg', 'eg.l03', 'eg.g03.etienne_paul_missions', array['eg.g03.etienne_paul_missions','eg.v.martyr','eg.v.paiens','eg.v.helleniste','eg.v.synagogue']::text[], 'match', 'lesson', 'Quatre mots à connaître', '{}'::text[], 'Ces quatre mots reviennent partout dans les Actes des apôtres.', 2, '{"unitIds": ["eg.g03.etienne_paul_missions", "eg.v.martyr", "eg.v.paiens", "eg.v.helleniste", "eg.v.synagogue"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Quatre mots à connaître", "promptLanguage": "fr", "answer": "Le martyr = un témoin jusqu''à la mort ; Les païens = les non-juifs ; Les hellénistes = les chrétiens de langue grecque ; La synagogue = le lieu de prière des Juifs", "acceptedAnswers": [], "explanation": "Ces quatre mots reviennent partout dans les Actes des apôtres.", "tip": "Martyr, païens, hellénistes, synagogue.", "pairs": [{"left": "Le martyr", "right": "un témoin jusqu''à la mort"}, {"left": "Les païens", "right": "les non-juifs"}, {"left": "Les hellénistes", "right": "les chrétiens de langue grecque"}, {"left": "La synagogue", "right": "le lieu de prière des Juifs"}], "id": "eg.l03.e20", "pool": "lesson", "lessonId": "eg.l03", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l03.e21', 'eg', 'eg.l03', 'eg.g03.etienne_paul_missions', array['eg.g03.etienne_paul_missions']::text[], 'reorder', 'lesson', 'Phrase-repère : la conversion de Paul.', array['Saul le persécuteur devient Paul l''apôtre des nations']::text[], 'Sur la route de Damas, vers 35, Saul rencontre le Christ et change de vie.', 2, '{"unitIds": ["eg.g03.etienne_paul_missions"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "prompt": "Phrase-repère : la conversion de Paul.", "promptLanguage": "fr", "answer": "Saul le persécuteur devient Paul l''apôtre des nations", "acceptedAnswers": ["Saul le persécuteur devient Paul l''apôtre des nations"], "explanation": "Sur la route de Damas, vers 35, Saul rencontre le Christ et change de vie.", "tip": "Persécuteur → apôtre.", "extraExample": {"text": "Le zèle de Saul est mis au service de l''Évangile.", "translation": "Dieu retourne sa force."}, "tokens": ["l''apôtre", "des", "nations", "Saul", "le", "persécuteur", "devient", "Paul"], "id": "eg.l03.e21", "pool": "lesson", "lessonId": "eg.l03", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l04.e01', 'eg', 'eg.l04', 'eg.g03.etienne_paul_missions', array['eg.g03.etienne_paul_missions','eg.v.saint_paul']::text[], 'mcq', 'lesson', 'Que devient Saul après sa rencontre avec le Christ ?', array['l''apôtre des nations']::text[], 'Saul le persécuteur devient Paul, l''apôtre des nations : il annonce l''Évangile aux païens.', 1, '{"unitIds": ["eg.g03.etienne_paul_missions", "eg.v.saint_paul"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Que devient Saul après sa rencontre avec le Christ ?", "promptLanguage": "fr", "answer": "l''apôtre des nations", "acceptedAnswers": ["l''apôtre des nations"], "explanation": "Saul le persécuteur devient Paul, l''apôtre des nations : il annonce l''Évangile aux païens.", "tip": "Persécuteur → apôtre.", "extraExample": {"text": "Il voyage avec Barnabé.", "translation": "Il arrive à Rome vers 61."}, "options": ["un scribe du Temple", "l''apôtre des nations", "un évêque de Rome"], "id": "eg.l04.e01", "pool": "lesson", "lessonId": "eg.l04", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l04.e02', 'eg', 'eg.l04', 'eg.g03.etienne_paul_missions', array['eg.g03.etienne_paul_missions','eg.v.paiens']::text[], 'mcq', 'lesson', 'Qui sont les païens ?', array['les non-juifs']::text[], 'Les païens sont les non-juifs. La question du concile : doivent-ils devenir juifs pour devenir chrétiens ?', 1, '{"unitIds": ["eg.g03.etienne_paul_missions", "eg.v.paiens"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Qui sont les païens ?", "promptLanguage": "fr", "answer": "les non-juifs", "acceptedAnswers": ["les non-juifs"], "explanation": "Les païens sont les non-juifs. La question du concile : doivent-ils devenir juifs pour devenir chrétiens ?", "tip": "Païens = non-juifs.", "extraExample": {"text": "Beaucoup de Grecs accueillent l''Évangile.", "translation": "Ils ne sont pas circoncis."}, "options": ["les chrétiens de langue grecque", "les prêtres du Temple", "les non-juifs"], "id": "eg.l04.e02", "pool": "lesson", "lessonId": "eg.l04", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
