insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l04.e04', 'eg', 'eg.l04', 'eg.g03.etienne_paul_missions', array['eg.g03.etienne_paul_missions','eg.v.saint_etienne']::text[], 'mcq', 'lesson', 'Vers quelle date Étienne est-il lapidé ?', array['vers 35']::text[], 'Étienne, premier martyr, est lapidé vers 35. Le concile de Jérusalem suit une quinzaine d''années plus tard.', 2, '{"unitIds": ["eg.g03.etienne_paul_missions", "eg.v.saint_etienne"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Vers quelle date Étienne est-il lapidé ?", "promptLanguage": "fr", "answer": "vers 35", "acceptedAnswers": ["vers 35"], "explanation": "Étienne, premier martyr, est lapidé vers 35. Le concile de Jérusalem suit une quinzaine d''années plus tard.", "tip": "35 Étienne, 49 concile, 67 Pierre et Paul.", "extraExample": {"text": "Paul se convertit à la même époque.", "translation": "Vers 35."}, "options": ["vers 35", "vers 49", "vers 67"], "id": "eg.l04.e04", "pool": "lesson", "lessonId": "eg.l04", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l04.e05', 'eg', 'eg.l04', 'eg.g04.concile_jerusalem', array['eg.g04.concile_jerusalem','eg.v.circoncision']::text[], 'mcq', 'lesson', 'Quel est le sujet du conflit d''Antioche ?', array['la circoncision']::text[], 'Des judéo-chrétiens exigent la circoncision pour les païens convertis, en vue du salut.', 1, '{"unitIds": ["eg.g04.concile_jerusalem", "eg.v.circoncision"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel est le sujet du conflit d''Antioche ?", "promptLanguage": "fr", "answer": "la circoncision", "acceptedAnswers": ["la circoncision"], "explanation": "Des judéo-chrétiens exigent la circoncision pour les païens convertis, en vue du salut.", "tip": "Antioche → circoncision.", "extraExample": {"text": "C''est le signe de l''alliance avec Abraham.", "translation": "La Loi de Moïse l''exige."}, "options": ["le baptême", "la circoncision", "le calendrier"], "errorPatterns": [{"equals": "le baptême", "category": "word_confusion", "feedback": "Le baptême est accepté par tous ; ce qui divise est la circoncision."}], "id": "eg.l04.e05", "pool": "lesson", "lessonId": "eg.l04", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l04.e06', 'eg', 'eg.l04', 'eg.g04.concile_jerusalem', array['eg.g04.concile_jerusalem','eg.v.judaisants']::text[], 'mcq', 'lesson', 'Comment appelle-t-on les chrétiens d''origine juive ?', array['judéo-chrétiens']::text[], 'Les judéo-chrétiens sont d''origine juive. Ceux qui veulent imposer la circoncision aux païens sont appelés judaïsants.', 2, '{"unitIds": ["eg.g04.concile_jerusalem", "eg.v.judaisants"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Comment appelle-t-on les chrétiens d''origine juive ?", "promptLanguage": "fr", "answer": "judéo-chrétiens", "acceptedAnswers": ["judéo-chrétiens"], "explanation": "Les judéo-chrétiens sont d''origine juive. Ceux qui veulent imposer la circoncision aux païens sont appelés judaïsants.", "tip": "Judéo = juif d''origine.", "extraExample": {"text": "Les hellénistes parlent grec.", "translation": "Ce n''est pas la même chose."}, "options": ["hellénistes", "païens", "judéo-chrétiens"], "id": "eg.l04.e06", "pool": "lesson", "lessonId": "eg.l04", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l04.e07', 'eg', 'eg.l04', 'eg.g04.concile_jerusalem', array['eg.g04.concile_jerusalem','eg.v.loi_de_moise','eg.v.circoncision']::text[], 'fill_blank', 'lesson', 'Si la circoncision devenait obligatoire, le christianisme resterait une branche du ___.', array['judaïsme']::text[], 'Tout païen devrait d''abord devenir juif pour devenir chrétien : le christianisme resterait une branche du judaïsme.', 2, '{"unitIds": ["eg.g04.concile_jerusalem", "eg.v.loi_de_moise", "eg.v.circoncision"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Si la circoncision devenait obligatoire, le christianisme resterait une branche du ___.", "promptLanguage": "fr", "answer": "judaïsme", "acceptedAnswers": ["judaïsme"], "explanation": "Tout païen devrait d''abord devenir juif pour devenir chrétien : le christianisme resterait une branche du judaïsme.", "tip": "Circoncision obligatoire = judaïsme.", "extraExample": {"text": "Le concile refuse cette solution.", "translation": "Le christianisme devient une foi pour tous."}, "options": ["judaïsme", "paganisme", "gnosticisme"], "id": "eg.l04.e07", "pool": "lesson", "lessonId": "eg.l04", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l04.e08', 'eg', 'eg.l04', 'eg.g04.concile_jerusalem', array['eg.g04.concile_jerusalem','eg.v.concile']::text[], 'mcq', 'lesson', 'Comment appelle-t-on une assemblée de responsables de l''Église qui décident ensemble ?', array['un concile']::text[], 'Un concile est une assemblée de responsables de l''Église, qui décident ensemble d''une question de foi ou de discipline.', 1, '{"unitIds": ["eg.g04.concile_jerusalem", "eg.v.concile"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Comment appelle-t-on une assemblée de responsables de l''Église qui décident ensemble ?", "promptLanguage": "fr", "answer": "un concile", "acceptedAnswers": ["un concile"], "explanation": "Un concile est une assemblée de responsables de l''Église, qui décident ensemble d''une question de foi ou de discipline.", "tip": "Concile = assemblée.", "extraExample": {"text": "Nicée en 325.", "translation": "Constantinople en 381."}, "options": ["un concile", "un schisme", "une synagogue"], "id": "eg.l04.e08", "pool": "lesson", "lessonId": "eg.l04", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l04.e09', 'eg', 'eg.l04', 'eg.g04.concile_jerusalem', array['eg.g04.concile_jerusalem','eg.v.concile_de_jerusalem']::text[], 'free_answer', 'lesson', 'Vers quelle année se tient le concile de Jérusalem ? (réponds par un nombre)', array['49','vers 49','l''an 49','en 49']::text[], 'Le concile de Jérusalem a lieu vers l''an 49, quinze ans environ après la conversion de Paul.', 2, '{"unitIds": ["eg.g04.concile_jerusalem", "eg.v.concile_de_jerusalem"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Vers quelle année se tient le concile de Jérusalem ? (réponds par un nombre)", "promptLanguage": "fr", "answer": "49", "acceptedAnswers": ["49", "vers 49", "l''an 49", "en 49"], "explanation": "Le concile de Jérusalem a lieu vers l''an 49, quinze ans environ après la conversion de Paul.", "tip": "49 = 1er concile.", "extraExample": {"text": "Néron persécutera en 64.", "translation": "Jérusalem tombera en 70."}, "hint": "Entre 45 et 50.", "id": "eg.l04.e09", "pool": "lesson", "lessonId": "eg.l04", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l04.e10', 'eg', 'eg.l04', 'eg.g04.concile_jerusalem', array['eg.g04.concile_jerusalem','eg.v.concile_de_jerusalem']::text[], 'mcq', 'lesson', 'Quel est le premier concile de l''histoire chrétienne ?', array['le concile de Jérusalem']::text[], 'Le concile de Jérusalem, vers 49, est le premier concile : il précède Nicée de plus de deux siècles.', 1, '{"unitIds": ["eg.g04.concile_jerusalem", "eg.v.concile_de_jerusalem"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel est le premier concile de l''histoire chrétienne ?", "promptLanguage": "fr", "answer": "le concile de Jérusalem", "acceptedAnswers": ["le concile de Jérusalem"], "explanation": "Le concile de Jérusalem, vers 49, est le premier concile : il précède Nicée de plus de deux siècles.", "tip": "Premier = Jérusalem.", "extraExample": {"text": "Nicée vient en 325.", "translation": "C''est le premier concile œcuménique."}, "options": ["le concile d''Antioche", "le concile de Jérusalem", "le concile de Nicée"], "id": "eg.l04.e10", "pool": "lesson", "lessonId": "eg.l04", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l04.e11', 'eg', 'eg.l04', 'eg.g04.concile_jerusalem', array['eg.g04.concile_jerusalem','eg.v.jacques_de_jerusalem']::text[], 'mcq', 'lesson', 'Qui conclut le débat au concile de Jérusalem ?', array['Jacques']::text[], 'Jacques, chef de l''Église de Jérusalem, conclut en s''appuyant sur les prophètes.', 2, '{"unitIds": ["eg.g04.concile_jerusalem", "eg.v.jacques_de_jerusalem"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui conclut le débat au concile de Jérusalem ?", "promptLanguage": "fr", "answer": "Jacques", "acceptedAnswers": ["Jacques"], "explanation": "Jacques, chef de l''Église de Jérusalem, conclut en s''appuyant sur les prophètes.", "tip": "Le chef de l''Église locale conclut.", "extraExample": {"text": "Il sera martyrisé en 62.", "translation": "Étienne est mort bien avant."}, "options": ["Étienne", "Marc", "Jacques"], "id": "eg.l04.e11", "pool": "lesson", "lessonId": "eg.l04", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l04.e12', 'eg', 'eg.l04', 'eg.g04.concile_jerusalem', array['eg.g04.concile_jerusalem','eg.v.saint_pierre']::text[], 'free_answer', 'lesson', 'Quel apôtre rappelle au concile que Dieu a donné l''Esprit aux païens sans les circoncire ?', array['Pierre','saint Pierre']::text[], 'Pierre témoigne : Dieu a donné l''Esprit Saint aux païens. Son autorité pèse dans la décision.', 2, '{"unitIds": ["eg.g04.concile_jerusalem", "eg.v.saint_pierre"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Quel apôtre rappelle au concile que Dieu a donné l''Esprit aux païens sans les circoncire ?", "promptLanguage": "fr", "answer": "Pierre", "acceptedAnswers": ["Pierre", "saint Pierre"], "explanation": "Pierre témoigne : Dieu a donné l''Esprit Saint aux païens. Son autorité pèse dans la décision.", "tip": "Pierre témoigne, Jacques conclut.", "extraExample": {"text": "Pierre avait déjà baptisé un centurion.", "translation": "Il connaît le cas des païens."}, "hint": "Le chef des apôtres.", "id": "eg.l04.e12", "pool": "lesson", "lessonId": "eg.l04", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l04.e13', 'eg', 'eg.l04', 'eg.g04.concile_jerusalem', array['eg.g04.concile_jerusalem']::text[], 'mcq', 'lesson', 'Que décide le concile de Jérusalem pour les païens convertis ?', array['la circoncision n''est plus obligatoire']::text[], 'Le concile décide que la circoncision n''est plus obligatoire pour les païens convertis : le salut vient du Christ.', 2, '{"unitIds": ["eg.g04.concile_jerusalem"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que décide le concile de Jérusalem pour les païens convertis ?", "promptLanguage": "fr", "answer": "la circoncision n''est plus obligatoire", "acceptedAnswers": ["la circoncision n''est plus obligatoire"], "explanation": "Le concile décide que la circoncision n''est plus obligatoire pour les païens convertis : le salut vient du Christ.", "tip": "Pas de circoncision obligatoire.", "extraExample": {"text": "Cela ouvre l''Église à toutes les nations.", "translation": "C''est le sens de Mt 28, 19."}, "options": ["ils doivent d''abord devenir juifs", "la circoncision n''est plus obligatoire", "la circoncision devient obligatoire"], "id": "eg.l04.e13", "pool": "lesson", "lessonId": "eg.l04", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l04.e14', 'eg', 'eg.l04', 'eg.g04.concile_jerusalem', array['eg.g04.concile_jerusalem']::text[], 'fill_blank', 'lesson', 'On demande aux païens de s''abstenir du sang, des bêtes étouffées, de l''immoralité et de la viande offerte aux ___.', array['idoles']::text[], 'Ces quatre règles permettent aux païens et aux judéo-chrétiens de vivre ensemble en paix.', 3, '{"unitIds": ["eg.g04.concile_jerusalem"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète la phrase.", "prompt": "On demande aux païens de s''abstenir du sang, des bêtes étouffées, de l''immoralité et de la viande offerte aux ___.", "promptLanguage": "fr", "answer": "idoles", "acceptedAnswers": ["idoles"], "explanation": "Ces quatre règles permettent aux païens et aux judéo-chrétiens de vivre ensemble en paix.", "tip": "Idoles : faux dieux.", "extraExample": {"text": "Le sang est sacré pour les Juifs.", "translation": "Les chrétiens d''origine juive en sont choqués."}, "options": ["pharisiens", "empereurs", "idoles"], "id": "eg.l04.e14", "pool": "lesson", "lessonId": "eg.l04", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l04.e15', 'eg', 'eg.l04', 'eg.g04.concile_jerusalem', array['eg.g04.concile_jerusalem']::text[], 'fill_blank', 'lesson', '« Il a paru bon à l''Esprit Saint et à ___ » (Ac 15, 28).', array['nous']::text[], 'La lettre du concile exprime la méthode : les responsables décident avec l''Esprit Saint.', 3, '{"unitIds": ["eg.g04.concile_jerusalem"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète la phrase.", "prompt": "« Il a paru bon à l''Esprit Saint et à ___ » (Ac 15, 28).", "promptLanguage": "fr", "answer": "nous", "acceptedAnswers": ["nous"], "explanation": "La lettre du concile exprime la méthode : les responsables décident avec l''Esprit Saint.", "tip": "Esprit Saint + nous.", "extraExample": {"text": "Tous les conciles reprendront cette idée.", "translation": "La décision est collégiale."}, "options": ["César", "nous", "Moïse"], "id": "eg.l04.e15", "pool": "lesson", "lessonId": "eg.l04", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l04.e16', 'eg', 'eg.l04', 'eg.g04.concile_jerusalem', array['eg.g04.concile_jerusalem','eg.v.salut']::text[], 'fill_blank', 'lesson', 'Les judaïsants affirment que la circoncision est nécessaire en vue du ___.', array['salut']::text[], 'Pour les judaïsants, il faut être circoncis pour être sauvé. Le concile répond que le salut vient du Christ.', 2, '{"unitIds": ["eg.g04.concile_jerusalem", "eg.v.salut"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Les judaïsants affirment que la circoncision est nécessaire en vue du ___.", "promptLanguage": "fr", "answer": "salut", "acceptedAnswers": ["salut"], "explanation": "Pour les judaïsants, il faut être circoncis pour être sauvé. Le concile répond que le salut vient du Christ.", "tip": "Salut = libération par le Christ.", "extraExample": {"text": "Paul répond dans l''épître aux Galates.", "translation": "Le salut est un don."}, "options": ["baptême", "voyage", "salut"], "id": "eg.l04.e16", "pool": "lesson", "lessonId": "eg.l04", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l04.e17', 'eg', 'eg.l04', 'eg.g04.concile_jerusalem', array['eg.g04.concile_jerusalem']::text[], 'mcq', 'lesson', 'Que représente la décision du concile pour le christianisme ?', array['la première rupture avec la communauté juive']::text[], 'Le christianisme n''est plus une branche du judaïsme : c''est le premier signe d''indépendance de la religion qui naît.', 3, '{"unitIds": ["eg.g04.concile_jerusalem"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Que représente la décision du concile pour le christianisme ?", "promptLanguage": "fr", "answer": "la première rupture avec la communauté juive", "acceptedAnswers": ["la première rupture avec la communauté juive"], "explanation": "Le christianisme n''est plus une branche du judaïsme : c''est le premier signe d''indépendance de la religion qui naît.", "tip": "Première rupture.", "extraExample": {"text": "La rupture sera longue à se réaliser.", "translation": "Mais elle a commencé."}, "options": ["la première rupture avec la communauté juive", "un retour au judaïsme", "la fin des conciles"], "id": "eg.l04.e17", "pool": "lesson", "lessonId": "eg.l04", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l04.e18', 'eg', 'eg.l04', 'eg.g04.concile_jerusalem', array['eg.g04.concile_jerusalem','eg.v.circoncision','eg.v.concile','eg.v.judaisants','eg.v.jacques_de_jerusalem']::text[], 'match', 'lesson', 'Les acteurs du concile', '{}'::text[], 'Ces quatre éléments résument le concile : un signe, une assemblée, des partisans de la Loi, un chef qui conclut.', 1, '{"unitIds": ["eg.g04.concile_jerusalem", "eg.v.circoncision", "eg.v.concile", "eg.v.judaisants", "eg.v.jacques_de_jerusalem"], "type": "match", "difficulty": 1, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Les acteurs du concile", "promptLanguage": "fr", "answer": "La circoncision = le signe de l''alliance avec Abraham ; Un concile = une assemblée qui décide ensemble ; Les judaïsants = veulent imposer la Loi aux païens ; Jacques = le chef de l''Église de Jérusalem", "acceptedAnswers": [], "explanation": "Ces quatre éléments résument le concile : un signe, une assemblée, des partisans de la Loi, un chef qui conclut.", "tip": "Un signe, une assemblée, un conflit, un chef.", "pairs": [{"left": "La circoncision", "right": "le signe de l''alliance avec Abraham"}, {"left": "Un concile", "right": "une assemblée qui décide ensemble"}, {"left": "Les judaïsants", "right": "veulent imposer la Loi aux païens"}, {"left": "Jacques", "right": "le chef de l''Église de Jérusalem"}], "id": "eg.l04.e18", "pool": "lesson", "lessonId": "eg.l04", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l04.e19', 'eg', 'eg.l04', 'eg.g04.concile_jerusalem', array['eg.g04.concile_jerusalem','eg.v.salut','eg.v.loi_de_moise']::text[], 'match', 'lesson', 'Qui dit quoi ?', '{}'::text[], 'Le concile est un vrai dialogue : chacun apporte un témoignage, puis la décision est envoyée aux Églises.', 3, '{"unitIds": ["eg.g04.concile_jerusalem", "eg.v.salut", "eg.v.loi_de_moise"], "type": "match", "difficulty": 3, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Qui dit quoi ?", "promptLanguage": "fr", "answer": "Pierre = rappelle que l''Esprit est donné aux païens ; Paul et Barnabé = racontent la conversion des païens ; Jacques = conclut en s''appuyant sur les prophètes ; Une lettre = part à Antioche", "acceptedAnswers": [], "explanation": "Le concile est un vrai dialogue : chacun apporte un témoignage, puis la décision est envoyée aux Églises.", "tip": "Témoigner, conclure, écrire.", "pairs": [{"left": "Pierre", "right": "rappelle que l''Esprit est donné aux païens"}, {"left": "Paul et Barnabé", "right": "racontent la conversion des païens"}, {"left": "Jacques", "right": "conclut en s''appuyant sur les prophètes"}, {"left": "Une lettre", "right": "part à Antioche"}], "id": "eg.l04.e19", "pool": "lesson", "lessonId": "eg.l04", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l04.e20', 'eg', 'eg.l04', 'eg.g04.concile_jerusalem', array['eg.g04.concile_jerusalem']::text[], 'reorder', 'lesson', 'Phrase-repère : la décision du concile.', array['Le concile de Jérusalem décide que la circoncision n''est plus obligatoire']::text[], 'Vers 49, le concile libère les païens convertis de la circoncision.', 2, '{"unitIds": ["eg.g04.concile_jerusalem"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "prompt": "Phrase-repère : la décision du concile.", "promptLanguage": "fr", "answer": "Le concile de Jérusalem décide que la circoncision n''est plus obligatoire", "acceptedAnswers": ["Le concile de Jérusalem décide que la circoncision n''est plus obligatoire"], "explanation": "Vers 49, le concile libère les païens convertis de la circoncision.", "tip": "49 = pas de circoncision obligatoire.", "extraExample": {"text": "Le salut vient du Christ.", "translation": "Pas de la Loi."}, "tokens": ["circoncision", "n''est", "plus", "obligatoire", "Le", "concile", "de", "Jérusalem", "décide", "que", "la"], "id": "eg.l04.e20", "pool": "lesson", "lessonId": "eg.l04", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l04.e21', 'eg', 'eg.l04', 'eg.g04.concile_jerusalem', array['eg.g04.concile_jerusalem','eg.v.circoncision']::text[], 'free_answer', 'lesson', 'Dans quelle ville de Syrie éclate le conflit sur la circoncision ?', array['Antioche','à Antioche']::text[], 'Le conflit éclate à Antioche, où de nombreux païens deviennent chrétiens. Il est porté à Jérusalem.', 1, '{"unitIds": ["eg.g04.concile_jerusalem", "eg.v.circoncision"], "type": "free_answer", "difficulty": 1, "instruction": "Écris ta réponse.", "prompt": "Dans quelle ville de Syrie éclate le conflit sur la circoncision ?", "promptLanguage": "fr", "answer": "Antioche", "acceptedAnswers": ["Antioche", "à Antioche"], "explanation": "Le conflit éclate à Antioche, où de nombreux païens deviennent chrétiens. Il est porté à Jérusalem.", "tip": "Antioche → Jérusalem.", "extraExample": {"text": "C''est là que naît le nom de chrétiens.", "translation": "Paul y est basé."}, "hint": "C''est la ville où l''on dit « chrétiens » pour la première fois.", "id": "eg.l04.e21", "pool": "lesson", "lessonId": "eg.l04", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l05.e01', 'eg', 'eg.l05', 'eg.g04.concile_jerusalem', array['eg.g04.concile_jerusalem','eg.v.concile_de_jerusalem']::text[], 'mcq', 'lesson', 'Vers quelle année a lieu le premier concile, celui de Jérusalem ?', array['vers l''an 49']::text[], 'Le concile de Jérusalem se tient vers l''an 49, avant les persécutions de Néron (64) et la chute de Jérusalem (70).', 2, '{"unitIds": ["eg.g04.concile_jerusalem", "eg.v.concile_de_jerusalem"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Vers quelle année a lieu le premier concile, celui de Jérusalem ?", "promptLanguage": "fr", "answer": "vers l''an 49", "acceptedAnswers": ["vers l''an 49"], "explanation": "Le concile de Jérusalem se tient vers l''an 49, avant les persécutions de Néron (64) et la chute de Jérusalem (70).", "tip": "49 : concile ; 64 : Néron ; 70 : chute.", "extraExample": {"text": "Le concile précède de quinze ans Néron.", "translation": "Il est antérieur aux grandes crises."}, "options": ["vers l''an 49", "vers l''an 64", "vers l''an 70"], "id": "eg.l05.e01", "pool": "lesson", "lessonId": "eg.l05", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l05.e02', 'eg', 'eg.l05', 'eg.g03.etienne_paul_missions', array['eg.g03.etienne_paul_missions','eg.v.martyr']::text[], 'fill_blank', 'lesson', 'Le mot « martyr » vient du grec et veut dire « ___ ».', array['témoin']::text[], 'Le martyr est un témoin du Christ jusqu''à la mort.', 1, '{"unitIds": ["eg.g03.etienne_paul_missions", "eg.v.martyr"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Le mot « martyr » vient du grec et veut dire « ___ ».", "promptLanguage": "fr", "answer": "témoin", "acceptedAnswers": ["témoin"], "explanation": "Le martyr est un témoin du Christ jusqu''à la mort.", "tip": "Martyr = témoin.", "extraExample": {"text": "Étienne est le premier martyr.", "translation": "Jacques, frère de Jean, le suit."}, "options": ["roi", "témoin", "soldat"], "id": "eg.l05.e02", "pool": "lesson", "lessonId": "eg.l05", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l05.e03', 'eg', 'eg.l05', 'eg.g04.concile_jerusalem', array['eg.g04.concile_jerusalem','eg.v.jacques_de_jerusalem']::text[], 'mcq', 'lesson', 'Jacques, qui avait conclu le concile de Jérusalem, était…', array['chef de l''Église de Jérusalem']::text[], 'Jacques de Jérusalem dirige l''Église de la ville et conclut le concile. Il ne faut pas le confondre avec Jacques, frère de Jean.', 2, '{"unitIds": ["eg.g04.concile_jerusalem", "eg.v.jacques_de_jerusalem"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Jacques, qui avait conclu le concile de Jérusalem, était…", "promptLanguage": "fr", "answer": "chef de l''Église de Jérusalem", "acceptedAnswers": ["chef de l''Église de Jérusalem"], "explanation": "Jacques de Jérusalem dirige l''Église de la ville et conclut le concile. Il ne faut pas le confondre avec Jacques, frère de Jean.", "tip": "Deux Jacques.", "extraExample": {"text": "Le premier est décapité vers 44.", "translation": "Le second est martyrisé en 62."}, "options": ["chef de l''Église de Jérusalem", "le frère de Jean", "un des sept hommes du service"], "id": "eg.l05.e03", "pool": "lesson", "lessonId": "eg.l05", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l05.e04', 'eg', 'eg.l05', 'eg.g01.pourquoi_histoire', array['eg.g01.pourquoi_histoire','eg.v.empire_romain']::text[], 'mcq', 'lesson', 'Quelle puissance déclenche les persécutions à partir de Néron ?', array['l''Empire romain']::text[], 'Les persécutions sont provoquées par les empereurs romains, maîtres du monde de l''époque. Avant Néron, les adversaires sont surtout les autorités juives.', 2, '{"unitIds": ["eg.g01.pourquoi_histoire", "eg.v.empire_romain"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle puissance déclenche les persécutions à partir de Néron ?", "promptLanguage": "fr", "answer": "l''Empire romain", "acceptedAnswers": ["l''Empire romain"], "explanation": "Les persécutions sont provoquées par les empereurs romains, maîtres du monde de l''époque. Avant Néron, les adversaires sont surtout les autorités juives.", "tip": "D''abord Jérusalem, ensuite Rome.", "extraExample": {"text": "Néron est empereur de 54 à 68.", "translation": "Domitien règne de 81 à 96."}, "options": ["l''Empire romain", "les pharisiens", "les Perses"], "id": "eg.l05.e04", "pool": "lesson", "lessonId": "eg.l05", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l05.e05', 'eg', 'eg.l05', 'eg.g05.persecutions_premier_siecle', array['eg.g05.persecutions_premier_siecle','eg.v.herode_agrippa','eg.v.jacques_de_zebedee']::text[], 'mcq', 'lesson', 'Qui fait décapiter Jacques, frère de Jean, vers 44 ?', array['Hérode Agrippa']::text[], 'Le roi Hérode Agrippa fait décapiter Jacques, frère de Jean, premier apôtre martyr.', 2, '{"unitIds": ["eg.g05.persecutions_premier_siecle", "eg.v.herode_agrippa", "eg.v.jacques_de_zebedee"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui fait décapiter Jacques, frère de Jean, vers 44 ?", "promptLanguage": "fr", "answer": "Hérode Agrippa", "acceptedAnswers": ["Hérode Agrippa"], "explanation": "Le roi Hérode Agrippa fait décapiter Jacques, frère de Jean, premier apôtre martyr.", "tip": "44 = Hérode Agrippa.", "extraExample": {"text": "Néron n''est pas encore empereur.", "translation": "Il le sera en 54."}, "options": ["Hérode Agrippa", "Néron", "Domitien"], "errorPatterns": [{"equals": "Néron", "category": "word_confusion", "feedback": "Néron ne persécutera qu''en 64."}], "id": "eg.l05.e05", "pool": "lesson", "lessonId": "eg.l05", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l05.e06', 'eg', 'eg.l05', 'eg.g05.persecutions_premier_siecle', array['eg.g05.persecutions_premier_siecle']::text[], 'mcq', 'lesson', 'Pourquoi Rome soupçonne-t-elle les chrétiens ?', array['ils refusent d''adorer l''empereur']::text[], 'Rome accepte les religions locales si l''on honore aussi l''empereur. Les chrétiens n''adorent que Dieu : on les soupçonne de menacer la paix.', 3, '{"unitIds": ["eg.g05.persecutions_premier_siecle"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi Rome soupçonne-t-elle les chrétiens ?", "promptLanguage": "fr", "answer": "ils refusent d''adorer l''empereur", "acceptedAnswers": ["ils refusent d''adorer l''empereur"], "explanation": "Rome accepte les religions locales si l''on honore aussi l''empereur. Les chrétiens n''adorent que Dieu : on les soupçonne de menacer la paix.", "tip": "Un seul Dieu, pas d''empereur-dieu.", "extraExample": {"text": "Domitien se fait appeler « seigneur et dieu ».", "translation": "Les chrétiens refusent."}, "options": ["ils refusent d''adorer l''empereur", "ils refusent de payer l''impôt", "ils attaquent l''armée"], "id": "eg.l05.e06", "pool": "lesson", "lessonId": "eg.l05", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l05.e07', 'eg', 'eg.l05', 'eg.g05.persecutions_premier_siecle', array['eg.g05.persecutions_premier_siecle','eg.v.incendie_de_rome']::text[], 'mcq', 'lesson', 'Quel événement frappe Rome en 64 ?', array['un grand incendie']::text[], 'En juillet 64, un grand incendie ravage Rome. La rumeur accuse Néron, qui détourne les soupçons.', 1, '{"unitIds": ["eg.g05.persecutions_premier_siecle", "eg.v.incendie_de_rome"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel événement frappe Rome en 64 ?", "promptLanguage": "fr", "answer": "un grand incendie", "acceptedAnswers": ["un grand incendie"], "explanation": "En juillet 64, un grand incendie ravage Rome. La rumeur accuse Néron, qui détourne les soupçons.", "tip": "64 = feu à Rome.", "extraExample": {"text": "L''incendie dure six jours.", "translation": "Une grande partie de la ville brûle."}, "options": ["une révolte juive", "un tremblement de terre", "un grand incendie"], "id": "eg.l05.e07", "pool": "lesson", "lessonId": "eg.l05", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l05.e08', 'eg', 'eg.l05', 'eg.g05.persecutions_premier_siecle', array['eg.g05.persecutions_premier_siecle','eg.v.neron']::text[], 'mcq', 'lesson', 'Sur qui Néron fait-il retomber les soupçons de l''incendie ?', array['les chrétiens']::text[], 'Pour détourner les soupçons, Néron accuse les chrétiens, qui sont arrêtés et torturés.', 1, '{"unitIds": ["eg.g05.persecutions_premier_siecle", "eg.v.neron"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Sur qui Néron fait-il retomber les soupçons de l''incendie ?", "promptLanguage": "fr", "answer": "les chrétiens", "acceptedAnswers": ["les chrétiens"], "explanation": "Pour détourner les soupçons, Néron accuse les chrétiens, qui sont arrêtés et torturés.", "tip": "Boucs émissaires.", "extraExample": {"text": "Ils ne se défendent pas.", "translation": "L''accusation est fausse."}, "options": ["les sénateurs", "les chrétiens", "les Juifs"], "errorPatterns": [{"equals": "les Juifs", "category": "word_confusion", "feedback": "Ce sont les chrétiens que Néron accuse, pas les Juifs."}], "id": "eg.l05.e08", "pool": "lesson", "lessonId": "eg.l05", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l05.e09', 'eg', 'eg.l05', 'eg.g05.persecutions_premier_siecle', array['eg.g05.persecutions_premier_siecle']::text[], 'mcq', 'lesson', 'Pourquoi Paul est-il décapité à Rome plutôt que crucifié ?', array['car il est citoyen romain']::text[], 'Paul est citoyen romain : la crucifixion lui est interdite. Il est décapité, alors que Pierre est crucifié.', 3, '{"unitIds": ["eg.g05.persecutions_premier_siecle"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi Paul est-il décapité à Rome plutôt que crucifié ?", "promptLanguage": "fr", "answer": "car il est citoyen romain", "acceptedAnswers": ["car il est citoyen romain"], "explanation": "Paul est citoyen romain : la crucifixion lui est interdite. Il est décapité, alors que Pierre est crucifié.", "tip": "Citoyen romain = décapité.", "extraExample": {"text": "Pierre n''est pas citoyen romain.", "translation": "Il est crucifié."}, "options": ["car il est citoyen romain", "car il est un ancien soldat", "car il s''est enfui"], "id": "eg.l05.e09", "pool": "lesson", "lessonId": "eg.l05", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l05.e10', 'eg', 'eg.l05', 'eg.g05.persecutions_premier_siecle', array['eg.g05.persecutions_premier_siecle']::text[], 'mcq', 'lesson', 'Quand Pierre et Paul sont-ils martyrisés à Rome, selon la tradition ?', array['vers l''an 67']::text[], 'Pierre et Paul sont martyrisés à Rome vers l''an 67, sous le règne de Néron.', 2, '{"unitIds": ["eg.g05.persecutions_premier_siecle"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quand Pierre et Paul sont-ils martyrisés à Rome, selon la tradition ?", "promptLanguage": "fr", "answer": "vers l''an 67", "acceptedAnswers": ["vers l''an 67"], "explanation": "Pierre et Paul sont martyrisés à Rome vers l''an 67, sous le règne de Néron.", "tip": "67 : les deux piliers.", "extraExample": {"text": "Néron meurt en 68.", "translation": "Le martyre précède sa fin."}, "options": ["vers l''an 81", "vers l''an 67", "vers l''an 44"], "id": "eg.l05.e10", "pool": "lesson", "lessonId": "eg.l05", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l05.e11', 'eg', 'eg.l05', 'eg.g05.persecutions_premier_siecle', array['eg.g05.persecutions_premier_siecle','eg.v.chute_de_jerusalem']::text[], 'mcq', 'lesson', 'Qui détruit le Temple de Jérusalem en 70 ?', array['Titus']::text[], 'Titus, général romain, prend Jérusalem en 70, détruit le Temple et disperse les Juifs.', 1, '{"unitIds": ["eg.g05.persecutions_premier_siecle", "eg.v.chute_de_jerusalem"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Qui détruit le Temple de Jérusalem en 70 ?", "promptLanguage": "fr", "answer": "Titus", "acceptedAnswers": ["Titus"], "explanation": "Titus, général romain, prend Jérusalem en 70, détruit le Temple et disperse les Juifs.", "tip": "70 = Titus.", "extraExample": {"text": "Titus deviendra empereur.", "translation": "Il est le fils de Vespasien."}, "options": ["Titus", "Néron", "Domitien"], "id": "eg.l05.e11", "pool": "lesson", "lessonId": "eg.l05", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l05.e12', 'eg', 'eg.l05', 'eg.g05.persecutions_premier_siecle', array['eg.g05.persecutions_premier_siecle','eg.v.domitien']::text[], 'mcq', 'lesson', 'Quel empereur est lié à la persécution de la fin du premier siècle ?', array['Domitien']::text[], 'Domitien, empereur de 81 à 96, persécute les chrétiens. Trajan règne au siècle suivant.', 2, '{"unitIds": ["eg.g05.persecutions_premier_siecle", "eg.v.domitien"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel empereur est lié à la persécution de la fin du premier siècle ?", "promptLanguage": "fr", "answer": "Domitien", "acceptedAnswers": ["Domitien"], "explanation": "Domitien, empereur de 81 à 96, persécute les chrétiens. Trajan règne au siècle suivant.", "tip": "Domitien = fin du Ier siècle.", "extraExample": {"text": "Trajan est du IIe siècle.", "translation": "Titus a détruit le Temple."}, "options": ["Titus", "Trajan", "Domitien"], "id": "eg.l05.e12", "pool": "lesson", "lessonId": "eg.l05", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l05.e13', 'eg', 'eg.l05', 'eg.g05.persecutions_premier_siecle', array['eg.g05.persecutions_premier_siecle','eg.v.revolte_juive']::text[], 'fill_blank', 'lesson', 'En 66, les Juifs se révoltent contre l''occupant ___.', array['romain']::text[], 'La révolte juive de 66 aboutit à la chute de Jérusalem en 70.', 2, '{"unitIds": ["eg.g05.persecutions_premier_siecle", "eg.v.revolte_juive"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "En 66, les Juifs se révoltent contre l''occupant ___.", "promptLanguage": "fr", "answer": "romain", "acceptedAnswers": ["romain"], "explanation": "La révolte juive de 66 aboutit à la chute de Jérusalem en 70.", "tip": "66 : révolte, 70 : chute.", "extraExample": {"text": "Rome envoie ses légions.", "translation": "Titus prend la ville."}, "options": ["romain", "perse", "grec"], "id": "eg.l05.e13", "pool": "lesson", "lessonId": "eg.l05", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l05.e14', 'eg', 'eg.l05', 'eg.g05.persecutions_premier_siecle', array['eg.g05.persecutions_premier_siecle','eg.v.jacques_de_zebedee']::text[], 'fill_blank', 'lesson', 'En 62, ___, chef de l''Église de Jérusalem, est martyrisé.', array['Jacques']::text[], 'Jacques, chef de l''Église de Jérusalem, est martyrisé en 62. Il avait conclu le concile de Jérusalem.', 2, '{"unitIds": ["eg.g05.persecutions_premier_siecle", "eg.v.jacques_de_zebedee"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "En 62, ___, chef de l''Église de Jérusalem, est martyrisé.", "promptLanguage": "fr", "answer": "Jacques", "acceptedAnswers": ["Jacques"], "explanation": "Jacques, chef de l''Église de Jérusalem, est martyrisé en 62. Il avait conclu le concile de Jérusalem.", "tip": "62 = Jacques de Jérusalem.", "extraExample": {"text": "Pierre meurt vers 67.", "translation": "Étienne vers 35."}, "options": ["Étienne", "Jacques", "Pierre"], "id": "eg.l05.e14", "pool": "lesson", "lessonId": "eg.l05", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l05.e15', 'eg', 'eg.l05', 'eg.g05.persecutions_premier_siecle', array['eg.g05.persecutions_premier_siecle','eg.v.domitien']::text[], 'fill_blank', 'lesson', 'Domitien règne de 81 à ___.', array['96']::text[], 'Domitien est empereur de 81 à 96. La persécution se situe surtout vers la fin de son règne.', 3, '{"unitIds": ["eg.g05.persecutions_premier_siecle", "eg.v.domitien"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète la phrase.", "prompt": "Domitien règne de 81 à ___.", "promptLanguage": "fr", "answer": "96", "acceptedAnswers": ["96"], "explanation": "Domitien est empereur de 81 à 96. La persécution se situe surtout vers la fin de son règne.", "tip": "81-96.", "extraExample": {"text": "Trajan lui succède.", "translation": "Le siècle se termine bientôt."}, "options": ["96", "70", "110"], "id": "eg.l05.e15", "pool": "lesson", "lessonId": "eg.l05", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l05.e16', 'eg', 'eg.l05', 'eg.g05.persecutions_premier_siecle', array['eg.g05.persecutions_premier_siecle','eg.v.neron']::text[], 'fill_blank', 'lesson', 'Pierre et Paul sont martyrisés à ___ vers l''an 67.', array['Rome']::text[], 'Les deux apôtres sont martyrisés à Rome, sous Néron, selon la tradition.', 2, '{"unitIds": ["eg.g05.persecutions_premier_siecle", "eg.v.neron"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Pierre et Paul sont martyrisés à ___ vers l''an 67.", "promptLanguage": "fr", "answer": "Rome", "acceptedAnswers": ["Rome"], "explanation": "Les deux apôtres sont martyrisés à Rome, sous Néron, selon la tradition.", "tip": "Rome = Pierre et Paul.", "extraExample": {"text": "Paul y arrive vers 61.", "translation": "Il est décapité."}, "options": ["Jérusalem", "Antioche", "Rome"], "id": "eg.l05.e16", "pool": "lesson", "lessonId": "eg.l05", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l05.e17', 'eg', 'eg.l05', 'eg.g05.persecutions_premier_siecle', array['eg.g05.persecutions_premier_siecle','eg.v.herode_agrippa','eg.v.neron','eg.v.chute_de_jerusalem','eg.v.domitien']::text[], 'match', 'lesson', 'Qui a fait quoi ?', '{}'::text[], 'Quatre acteurs, quatre moments : 44, 64, 70 et la fin du siècle.', 2, '{"unitIds": ["eg.g05.persecutions_premier_siecle", "eg.v.herode_agrippa", "eg.v.neron", "eg.v.chute_de_jerusalem", "eg.v.domitien"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Qui a fait quoi ?", "promptLanguage": "fr", "answer": "Hérode Agrippa = fait décapiter Jacques, frère de Jean ; Néron = accuse les chrétiens de l''incendie de Rome ; Titus = détruit le Temple de Jérusalem ; Domitien = persécute les chrétiens vers la fin du siècle", "acceptedAnswers": [], "explanation": "Quatre acteurs, quatre moments : 44, 64, 70 et la fin du siècle.", "tip": "Un nom, une date.", "pairs": [{"left": "Hérode Agrippa", "right": "fait décapiter Jacques, frère de Jean"}, {"left": "Néron", "right": "accuse les chrétiens de l''incendie de Rome"}, {"left": "Titus", "right": "détruit le Temple de Jérusalem"}, {"left": "Domitien", "right": "persécute les chrétiens vers la fin du siècle"}], "id": "eg.l05.e17", "pool": "lesson", "lessonId": "eg.l05", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l05.e18', 'eg', 'eg.l05', 'eg.g05.persecutions_premier_siecle', array['eg.g05.persecutions_premier_siecle','eg.v.revolte_juive','eg.v.incendie_de_rome']::text[], 'match', 'lesson', 'Les dates qui comptent', '{}'::text[], 'Ces quatre dates structurent le siècle : 44, 62, 64, 70.', 3, '{"unitIds": ["eg.g05.persecutions_premier_siecle", "eg.v.revolte_juive", "eg.v.incendie_de_rome"], "type": "match", "difficulty": 3, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Les dates qui comptent", "promptLanguage": "fr", "answer": "44 = martyre de Jacques, frère de Jean ; 62 = martyre de Jacques de Jérusalem ; 64 = incendie de Rome et persécution de Néron ; 70 = chute de Jérusalem", "acceptedAnswers": [], "explanation": "Ces quatre dates structurent le siècle : 44, 62, 64, 70.", "tip": "44, 62, 64, 70.", "pairs": [{"left": "44", "right": "martyre de Jacques, frère de Jean"}, {"left": "62", "right": "martyre de Jacques de Jérusalem"}, {"left": "64", "right": "incendie de Rome et persécution de Néron"}, {"left": "70", "right": "chute de Jérusalem"}], "id": "eg.l05.e18", "pool": "lesson", "lessonId": "eg.l05", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l05.e19', 'eg', 'eg.l05', 'eg.g05.persecutions_premier_siecle', array['eg.g05.persecutions_premier_siecle']::text[], 'reorder', 'lesson', 'Phrase-repère : 70.', array['En 70 Titus détruit le Temple de Jérusalem']::text[], 'En 70, les armées de Titus détruisent le Temple et dispersent les Juifs.', 2, '{"unitIds": ["eg.g05.persecutions_premier_siecle"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "prompt": "Phrase-repère : 70.", "promptLanguage": "fr", "answer": "En 70 Titus détruit le Temple de Jérusalem", "acceptedAnswers": ["En 70 Titus détruit le Temple de Jérusalem"], "explanation": "En 70, les armées de Titus détruisent le Temple et dispersent les Juifs.", "tip": "70 = Titus.", "extraExample": {"text": "La ville ne sera plus jamais la même.", "translation": "Les chrétiens se dispersent aussi."}, "tokens": ["détruit", "le", "Temple", "de", "Jérusalem", "En", "70", "Titus"], "id": "eg.l05.e19", "pool": "lesson", "lessonId": "eg.l05", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l05.e20', 'eg', 'eg.l05', 'eg.g05.persecutions_premier_siecle', array['eg.g05.persecutions_premier_siecle','eg.v.neron']::text[], 'free_answer', 'lesson', 'Quel empereur accuse les chrétiens de l''incendie de Rome en 64 ?', array['Néron','Neron']::text[], 'Néron détourne les soupçons de l''incendie sur les chrétiens et les fait torturer.', 1, '{"unitIds": ["eg.g05.persecutions_premier_siecle", "eg.v.neron"], "type": "free_answer", "difficulty": 1, "instruction": "Écris ta réponse.", "prompt": "Quel empereur accuse les chrétiens de l''incendie de Rome en 64 ?", "promptLanguage": "fr", "answer": "Néron", "acceptedAnswers": ["Néron", "Neron"], "explanation": "Néron détourne les soupçons de l''incendie sur les chrétiens et les fait torturer.", "tip": "64 = Néron.", "extraExample": {"text": "Il règne de 54 à 68.", "translation": "Pierre et Paul meurent sous son règne."}, "hint": "Son nom commence par N.", "id": "eg.l05.e20", "pool": "lesson", "lessonId": "eg.l05", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l05.e21', 'eg', 'eg.l05', 'eg.g05.persecutions_premier_siecle', array['eg.g05.persecutions_premier_siecle','eg.v.chute_de_jerusalem']::text[], 'free_answer', 'lesson', 'En quelle année Jérusalem tombe-t-elle devant Titus ?', array['70','en 70','l''an 70','vers 70']::text[], 'En 70, Titus prend Jérusalem et détruit le Temple, au terme de la révolte juive commencée en 66.', 2, '{"unitIds": ["eg.g05.persecutions_premier_siecle", "eg.v.chute_de_jerusalem"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "En quelle année Jérusalem tombe-t-elle devant Titus ?", "promptLanguage": "fr", "answer": "70", "acceptedAnswers": ["70", "en 70", "l''an 70", "vers 70"], "explanation": "En 70, Titus prend Jérusalem et détruit le Temple, au terme de la révolte juive commencée en 66.", "tip": "70 : chute.", "extraExample": {"text": "La guerre dure quatre ans.", "translation": "Les Juifs sont dispersés."}, "hint": "Entre 66 et 81.", "id": "eg.l05.e21", "pool": "lesson", "lessonId": "eg.l05", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l05.e22', 'eg', 'eg.l05', 'eg.g05.persecutions_premier_siecle', array['eg.g05.persecutions_premier_siecle','eg.v.temple_de_jerusalem']::text[], 'free_answer', 'lesson', 'Quel grand sanctuaire juif de Jérusalem est détruit par les Romains en 70 ?', array['le Temple','Temple','le Temple de Jérusalem']::text[], 'Le Temple est le centre du culte juif. Sa destruction en 70 met fin aux sacrifices.', 1, '{"unitIds": ["eg.g05.persecutions_premier_siecle", "eg.v.temple_de_jerusalem"], "type": "free_answer", "difficulty": 1, "instruction": "Écris ta réponse.", "prompt": "Quel grand sanctuaire juif de Jérusalem est détruit par les Romains en 70 ?", "promptLanguage": "fr", "answer": "le Temple", "acceptedAnswers": ["le Temple", "Temple", "le Temple de Jérusalem"], "explanation": "Le Temple est le centre du culte juif. Sa destruction en 70 met fin aux sacrifices.", "tip": "Temple détruit en 70.", "extraExample": {"text": "Les premiers chrétiens y priaient.", "translation": "Il n''a jamais été reconstruit."}, "hint": "Jésus y enseignait.", "id": "eg.l05.e22", "pool": "lesson", "lessonId": "eg.l05", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l06.e01', 'eg', 'eg.l06', 'eg.g05.persecutions_premier_siecle', array['eg.g05.persecutions_premier_siecle','eg.v.chute_de_jerusalem']::text[], 'fill_blank', 'lesson', 'En 70, les armées de ___ détruisent le Temple de Jérusalem.', array['Titus']::text[], 'Titus, général romain, prend Jérusalem et détruit le Temple en 70.', 1, '{"unitIds": ["eg.g05.persecutions_premier_siecle", "eg.v.chute_de_jerusalem"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "En 70, les armées de ___ détruisent le Temple de Jérusalem.", "promptLanguage": "fr", "answer": "Titus", "acceptedAnswers": ["Titus"], "explanation": "Titus, général romain, prend Jérusalem et détruit le Temple en 70.", "tip": "70 = Titus.", "extraExample": {"text": "La révolte avait commencé en 66.", "translation": "Les Juifs sont dispersés."}, "options": ["Néron", "Domitien", "Titus"], "id": "eg.l06.e01", "pool": "lesson", "lessonId": "eg.l06", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l06.e02', 'eg', 'eg.l06', 'eg.g04.concile_jerusalem', array['eg.g04.concile_jerusalem','eg.v.judaisants']::text[], 'mcq', 'lesson', 'Qui sont les judaïsants ?', array['chrétiens d''origine juive qui veulent imposer la Loi de Moïse aux païens']::text[], 'Les judaïsants veulent imposer la Loi de Moïse (dont la circoncision) aux païens convertis. Le concile de Jérusalem leur donne tort.', 2, '{"unitIds": ["eg.g04.concile_jerusalem", "eg.v.judaisants"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui sont les judaïsants ?", "promptLanguage": "fr", "answer": "chrétiens d''origine juive qui veulent imposer la Loi de Moïse aux païens", "acceptedAnswers": ["chrétiens d''origine juive qui veulent imposer la Loi de Moïse aux païens"], "explanation": "Les judaïsants veulent imposer la Loi de Moïse (dont la circoncision) aux païens convertis. Le concile de Jérusalem leur donne tort.", "tip": "Judaïsants = Loi imposée.", "extraExample": {"text": "Ils arrivent à Antioche vers 49.", "translation": "Ils font éclater le conflit."}, "options": ["disciples de Simon le magicien", "chrétiens d''origine juive qui veulent imposer la Loi de Moïse aux païens", "chrétiens de langue grecque"], "id": "eg.l06.e02", "pool": "lesson", "lessonId": "eg.l06", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l06.e03', 'eg', 'eg.l06', 'eg.g01.pourquoi_histoire', array['eg.g01.pourquoi_histoire','eg.v.heresie']::text[], 'fill_blank', 'lesson', 'Une hérésie touche la ___, un schisme touche l''unité.', array['doctrine']::text[], 'L''hérésie est une erreur de doctrine ; le schisme est une rupture de communion.', 1, '{"unitIds": ["eg.g01.pourquoi_histoire", "eg.v.heresie"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Une hérésie touche la ___, un schisme touche l''unité.", "promptLanguage": "fr", "answer": "doctrine", "acceptedAnswers": ["doctrine"], "explanation": "L''hérésie est une erreur de doctrine ; le schisme est une rupture de communion.", "tip": "Doctrine ou unité ?", "extraExample": {"text": "Le gnosticisme est une hérésie.", "translation": "La rupture de 1054 est un schisme."}, "options": ["doctrine", "liturgie", "politique"], "id": "eg.l06.e03", "pool": "lesson", "lessonId": "eg.l06", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l06.e04', 'eg', 'eg.l06', 'eg.g04.concile_jerusalem', array['eg.g04.concile_jerusalem','eg.v.concile_de_jerusalem']::text[], 'free_answer', 'lesson', 'Quel est le nom du premier concile de l''histoire chrétienne ?', array['le concile de Jérusalem','concile de Jérusalem','Jérusalem']::text[], 'Le concile de Jérusalem, vers l''an 49, est le premier concile.', 2, '{"unitIds": ["eg.g04.concile_jerusalem", "eg.v.concile_de_jerusalem"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Quel est le nom du premier concile de l''histoire chrétienne ?", "promptLanguage": "fr", "answer": "le concile de Jérusalem", "acceptedAnswers": ["le concile de Jérusalem", "concile de Jérusalem", "Jérusalem"], "explanation": "Le concile de Jérusalem, vers l''an 49, est le premier concile.", "tip": "Premier concile = Jérusalem.", "extraExample": {"text": "Nicée est de 325.", "translation": "Jérusalem est de 49."}, "hint": "Il a lieu vers 49.", "id": "eg.l06.e04", "pool": "lesson", "lessonId": "eg.l06", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l06.e05', 'eg', 'eg.l06', 'eg.g06.ecrits_heresies', array['eg.g06.ecrits_heresies','eg.v.tradition_orale']::text[], 'mcq', 'lesson', 'Que laisse Jésus comme écrit ?', array['aucun écrit']::text[], 'Jésus n''a laissé aucun écrit. Ce sont ses disciples qui transmettent son enseignement, d''abord oralement, puis par écrit.', 1, '{"unitIds": ["eg.g06.ecrits_heresies", "eg.v.tradition_orale"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Que laisse Jésus comme écrit ?", "promptLanguage": "fr", "answer": "aucun écrit", "acceptedAnswers": ["aucun écrit"], "explanation": "Jésus n''a laissé aucun écrit. Ce sont ses disciples qui transmettent son enseignement, d''abord oralement, puis par écrit.", "tip": "Pas de livre de Jésus.", "extraExample": {"text": "Les évangiles sont écrits par ses disciples.", "translation": "Après sa Résurrection."}, "options": ["aucun écrit", "un évangile", "des épîtres"], "errorPatterns": [{"equals": "un évangile", "category": "word_confusion", "feedback": "Les évangiles sont écrits par les disciples, pas par Jésus."}], "id": "eg.l06.e05", "pool": "lesson", "lessonId": "eg.l06", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l06.e06', 'eg', 'eg.l06', 'eg.g06.ecrits_heresies', array['eg.g06.ecrits_heresies','eg.v.tradition_orale']::text[], 'mcq', 'lesson', 'Comment l''enseignement de Jésus est-il d''abord transmis ?', array['oralement']::text[], 'Pendant une génération, il est transmis oralement par les disciples, sous forme de catéchèses.', 1, '{"unitIds": ["eg.g06.ecrits_heresies", "eg.v.tradition_orale"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Comment l''enseignement de Jésus est-il d''abord transmis ?", "promptLanguage": "fr", "answer": "oralement", "acceptedAnswers": ["oralement"], "explanation": "Pendant une génération, il est transmis oralement par les disciples, sous forme de catéchèses.", "tip": "Parole d''abord.", "extraExample": {"text": "Les épîtres sont écrites vers les années 50-60.", "translation": "Les évangiles ensuite."}, "options": ["oralement", "par des lettres", "par des livres"], "id": "eg.l06.e06", "pool": "lesson", "lessonId": "eg.l06", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l06.e07', 'eg', 'eg.l06', 'eg.g06.ecrits_heresies', array['eg.g06.ecrits_heresies','eg.v.tradition_orale']::text[], 'fill_blank', 'lesson', 'L''enseignement de Jésus a d''abord été transmis par la tradition ___.', array['orale']::text[], 'La tradition orale précède l''écriture : elle est faite des catéchèses des disciples.', 1, '{"unitIds": ["eg.g06.ecrits_heresies", "eg.v.tradition_orale"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "L''enseignement de Jésus a d''abord été transmis par la tradition ___.", "promptLanguage": "fr", "answer": "orale", "acceptedAnswers": ["orale"], "explanation": "La tradition orale précède l''écriture : elle est faite des catéchèses des disciples.", "tip": "Orale avant écrite.", "extraExample": {"text": "Les catéchèses sont mises par écrit plus tard.", "translation": "Seconde moitié du siècle."}, "options": ["écrite", "secrète", "orale"], "id": "eg.l06.e07", "pool": "lesson", "lessonId": "eg.l06", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l06.e08', 'eg', 'eg.l06', 'eg.g06.ecrits_heresies', array['eg.g06.ecrits_heresies']::text[], 'mcq', 'lesson', 'Pourquoi met-on l''enseignement de Jésus par écrit ?', array['pour garder fidèlement ce que les témoins ont reçu']::text[], 'Les témoins meurent, les Églises s''éloignent, de faux docteurs déforment l''enseignement : on écrit pour garder fidèlement ce qu''on a reçu.', 2, '{"unitIds": ["eg.g06.ecrits_heresies"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi met-on l''enseignement de Jésus par écrit ?", "promptLanguage": "fr", "answer": "pour garder fidèlement ce que les témoins ont reçu", "acceptedAnswers": ["pour garder fidèlement ce que les témoins ont reçu"], "explanation": "Les témoins meurent, les Églises s''éloignent, de faux docteurs déforment l''enseignement : on écrit pour garder fidèlement ce qu''on a reçu.", "tip": "Écrire = garder.", "extraExample": {"text": "Les évangiles sont écrits pour conserver la mémoire.", "translation": "C''est une mission de fidélité."}, "options": ["pour remplacer la prière", "pour fonder un nouvel empire", "pour garder fidèlement ce que les témoins ont reçu"], "id": "eg.l06.e08", "pool": "lesson", "lessonId": "eg.l06", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l06.e09', 'eg', 'eg.l06', 'eg.g06.ecrits_heresies', array['eg.g06.ecrits_heresies','eg.v.evangile']::text[], 'mcq', 'lesson', 'Que veut dire le mot « évangile » ?', array['bonne nouvelle']::text[], 'Évangile vient du grec euangelion, « bonne nouvelle » : l''annonce que Dieu sauve.', 1, '{"unitIds": ["eg.g06.ecrits_heresies", "eg.v.evangile"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Que veut dire le mot « évangile » ?", "promptLanguage": "fr", "answer": "bonne nouvelle", "acceptedAnswers": ["bonne nouvelle"], "explanation": "Évangile vient du grec euangelion, « bonne nouvelle » : l''annonce que Dieu sauve.", "tip": "Évangile = bonne nouvelle.", "extraExample": {"text": "Il y a quatre évangiles.", "translation": "Matthieu, Marc, Luc, Jean."}, "options": ["parole cachée", "loi nouvelle", "bonne nouvelle"], "id": "eg.l06.e09", "pool": "lesson", "lessonId": "eg.l06", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l06.e10', 'eg', 'eg.l06', 'eg.g06.ecrits_heresies', array['eg.g06.ecrits_heresies','eg.v.epitre','eg.v.nouveau_testament']::text[], 'mcq', 'lesson', 'Combien d''épîtres de Paul la tradition de l''Église compte-t-elle ?', array['quatorze']::text[], 'La tradition en compte quatorze, en y incluant l''épître aux Hébreux. Elles sont parmi les plus anciens textes du Nouveau Testament.', 2, '{"unitIds": ["eg.g06.ecrits_heresies", "eg.v.epitre", "eg.v.nouveau_testament"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Combien d''épîtres de Paul la tradition de l''Église compte-t-elle ?", "promptLanguage": "fr", "answer": "quatorze", "acceptedAnswers": ["quatorze"], "explanation": "La tradition en compte quatorze, en y incluant l''épître aux Hébreux. Elles sont parmi les plus anciens textes du Nouveau Testament.", "tip": "14 épîtres de Paul.", "extraExample": {"text": "Paul écrit aux Romains, aux Corinthiens, aux Galates.", "translation": "Et à d''autres communautés."}, "options": ["vingt", "quatorze", "sept"], "id": "eg.l06.e10", "pool": "lesson", "lessonId": "eg.l06", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l06.e11', 'eg', 'eg.l06', 'eg.g06.ecrits_heresies', array['eg.g06.ecrits_heresies','eg.v.epitre']::text[], 'free_answer', 'lesson', 'Comment appelle-t-on les lettres de Paul aux communautés ?', array['épîtres','les épîtres','épître','une épître']::text[], 'Une épître est une lettre d''un apôtre à une communauté. Paul en écrit quatorze, selon la tradition.', 1, '{"unitIds": ["eg.g06.ecrits_heresies", "eg.v.epitre"], "type": "free_answer", "difficulty": 1, "instruction": "Écris ta réponse.", "prompt": "Comment appelle-t-on les lettres de Paul aux communautés ?", "promptLanguage": "fr", "answer": "épîtres", "acceptedAnswers": ["épîtres", "les épîtres", "épître", "une épître"], "explanation": "Une épître est une lettre d''un apôtre à une communauté. Paul en écrit quatorze, selon la tradition.", "tip": "Épître = lettre.", "extraExample": {"text": "Pierre et Jean écrivent aussi des épîtres.", "translation": "Elles complètent les évangiles."}, "hint": "Du grec « lettre ».", "id": "eg.l06.e11", "pool": "lesson", "lessonId": "eg.l06", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l06.e12', 'eg', 'eg.l06', 'eg.g06.ecrits_heresies', array['eg.g06.ecrits_heresies']::text[], 'mcq', 'lesson', 'Quel évangéliste écrit aussi les Actes des apôtres ?', array['Luc']::text[], 'Luc écrit un évangile plein de détails, puis les Actes des apôtres, qui racontent les débuts de l''Église.', 2, '{"unitIds": ["eg.g06.ecrits_heresies"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel évangéliste écrit aussi les Actes des apôtres ?", "promptLanguage": "fr", "answer": "Luc", "acceptedAnswers": ["Luc"], "explanation": "Luc écrit un évangile plein de détails, puis les Actes des apôtres, qui racontent les débuts de l''Église.", "tip": "Luc = évangile + Actes.", "extraExample": {"text": "Les Actes couvrent environ trente ans.", "translation": "De la Pentecôte à Rome."}, "options": ["Luc", "Marc", "Matthieu"], "id": "eg.l06.e12", "pool": "lesson", "lessonId": "eg.l06", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l06.e13', 'eg', 'eg.l06', 'eg.g06.ecrits_heresies', array['eg.g06.ecrits_heresies','eg.v.evangile']::text[], 'mcq', 'lesson', 'Quel évangile est le plus court ?', array['Marc']::text[], 'L''évangile de Marc est le plus court : il raconte Jésus en action. Il est lié à l''Égypte par la tradition copte.', 2, '{"unitIds": ["eg.g06.ecrits_heresies", "eg.v.evangile"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel évangile est le plus court ?", "promptLanguage": "fr", "answer": "Marc", "acceptedAnswers": ["Marc"], "explanation": "L''évangile de Marc est le plus court : il raconte Jésus en action. Il est lié à l''Égypte par la tradition copte.", "tip": "Marc = bref.", "extraExample": {"text": "Il commence par « Commencement de l''Évangile ».", "translation": "Marc fonde l''Église d''Alexandrie."}, "options": ["Jean", "Matthieu", "Marc"], "id": "eg.l06.e13", "pool": "lesson", "lessonId": "eg.l06", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l06.e14', 'eg', 'eg.l06', 'eg.g06.ecrits_heresies', array['eg.g06.ecrits_heresies','eg.v.gnosticisme']::text[], 'mcq', 'lesson', 'Que veut dire le mot grec « gnose » ?', array['connaissance']::text[], 'Gnose veut dire « connaissance ». Les gnostiques prétendent sauver par une connaissance secrète.', 1, '{"unitIds": ["eg.g06.ecrits_heresies", "eg.v.gnosticisme"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Que veut dire le mot grec « gnose » ?", "promptLanguage": "fr", "answer": "connaissance", "acceptedAnswers": ["connaissance"], "explanation": "Gnose veut dire « connaissance ». Les gnostiques prétendent sauver par une connaissance secrète.", "tip": "Gnose = connaissance.", "extraExample": {"text": "Le mot « diagnostic » en vient.", "translation": "Connaître pour se sauver."}, "options": ["lumière", "sagesse", "connaissance"], "id": "eg.l06.e14", "pool": "lesson", "lessonId": "eg.l06", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l06.e15', 'eg', 'eg.l06', 'eg.g06.ecrits_heresies', array['eg.g06.ecrits_heresies','eg.v.gnosticisme']::text[], 'fill_blank', 'lesson', 'Les gnostiques croient à deux dieux : un Dieu bon et un dieu ___.', array['mauvais']::text[], 'Pour eux, un dieu mauvais a créé le monde. Le monde et le corps sont donc mauvais.', 2, '{"unitIds": ["eg.g06.ecrits_heresies", "eg.v.gnosticisme"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Les gnostiques croient à deux dieux : un Dieu bon et un dieu ___.", "promptLanguage": "fr", "answer": "mauvais", "acceptedAnswers": ["mauvais"], "explanation": "Pour eux, un dieu mauvais a créé le monde. Le monde et le corps sont donc mauvais.", "tip": "Dieu bon / dieu mauvais.", "extraExample": {"text": "Le salut serait de fuir le monde.", "translation": "Cela contredit la création bonne."}, "options": ["ancien", "mauvais", "inconnu"], "id": "eg.l06.e15", "pool": "lesson", "lessonId": "eg.l06", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l06.e16', 'eg', 'eg.l06', 'eg.g06.ecrits_heresies', array['eg.g06.ecrits_heresies','eg.v.gnosticisme']::text[], 'mcq', 'lesson', 'Selon les gnostiques, que représente le corps ?', array['une prison']::text[], 'Pour les gnostiques, le corps est une prison dont il faut libérer l''âme. L''Église croit au contraire que le corps est créé bon.', 2, '{"unitIds": ["eg.g06.ecrits_heresies", "eg.v.gnosticisme"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Selon les gnostiques, que représente le corps ?", "promptLanguage": "fr", "answer": "une prison", "acceptedAnswers": ["une prison"], "explanation": "Pour les gnostiques, le corps est une prison dont il faut libérer l''âme. L''Église croit au contraire que le corps est créé bon.", "tip": "Corps = prison pour eux.", "extraExample": {"text": "Certains pratiquent une abstinence extrême.", "translation": "D''autres une vie sans morale."}, "options": ["un don de Dieu", "une prison", "un temple"], "id": "eg.l06.e16", "pool": "lesson", "lessonId": "eg.l06", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l06.e17', 'eg', 'eg.l06', 'eg.g06.ecrits_heresies', array['eg.g06.ecrits_heresies','eg.v.docetisme']::text[], 'mcq', 'lesson', 'Que prétendent les gnostiques à propos de Jésus ?', array['il n''aurait eu que l''apparence d''un homme']::text[], 'Pour les gnostiques, Jésus n''aurait eu que l''apparence d''un homme, comme un fantôme. C''est le docétisme.', 3, '{"unitIds": ["eg.g06.ecrits_heresies", "eg.v.docetisme"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Que prétendent les gnostiques à propos de Jésus ?", "promptLanguage": "fr", "answer": "il n''aurait eu que l''apparence d''un homme", "acceptedAnswers": ["il n''aurait eu que l''apparence d''un homme"], "explanation": "Pour les gnostiques, Jésus n''aurait eu que l''apparence d''un homme, comme un fantôme. C''est le docétisme.", "tip": "Apparence = docétisme.", "extraExample": {"text": "Cela supprime la croix réelle.", "translation": "L''Église affirme l''Incarnation."}, "options": ["il n''aurait eu que l''apparence d''un homme", "il n''a jamais existé comme sage", "il n''a pas été crucifié par Rome"], "id": "eg.l06.e17", "pool": "lesson", "lessonId": "eg.l06", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l06.e18', 'eg', 'eg.l06', 'eg.g06.ecrits_heresies', array['eg.g06.ecrits_heresies','eg.v.docetisme']::text[], 'free_answer', 'lesson', 'Quel mot désigne l''idée que Jésus n''a eu que l''apparence d''un homme ?', array['docétisme','le docétisme','docetisme']::text[], 'Le docétisme (du grec dokein, « paraître ») nie que Jésus ait un vrai corps.', 3, '{"unitIds": ["eg.g06.ecrits_heresies", "eg.v.docetisme"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Quel mot désigne l''idée que Jésus n''a eu que l''apparence d''un homme ?", "promptLanguage": "fr", "answer": "docétisme", "acceptedAnswers": ["docétisme", "le docétisme", "docetisme"], "explanation": "Le docétisme (du grec dokein, « paraître ») nie que Jésus ait un vrai corps.", "tip": "Docétisme = apparence.", "extraExample": {"text": "Jean le combat.", "translation": "« Le Verbe s''est fait chair »."}, "hint": "Du grec « paraître ».", "id": "eg.l06.e18", "pool": "lesson", "lessonId": "eg.l06", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l06.e19', 'eg', 'eg.l06', 'eg.g06.ecrits_heresies', array['eg.g06.ecrits_heresies','eg.v.saint_jean']::text[], 'fill_blank', 'lesson', 'Saint Jean répond aux gnostiques : « Le Verbe s''est fait ___ » (Jn 1, 14).', array['chair']::text[], 'Jean affirme l''Incarnation : le Fils de Dieu a pris un vrai corps, en réponse aux gnostiques.', 2, '{"unitIds": ["eg.g06.ecrits_heresies", "eg.v.saint_jean"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Saint Jean répond aux gnostiques : « Le Verbe s''est fait ___ » (Jn 1, 14).", "promptLanguage": "fr", "answer": "chair", "acceptedAnswers": ["chair"], "explanation": "Jean affirme l''Incarnation : le Fils de Dieu a pris un vrai corps, en réponse aux gnostiques.", "tip": "Verbe fait chair.", "extraExample": {"text": "Jean 1, 14.", "translation": "Il combat la gnose."}, "options": ["esprit", "chair", "lumière"], "id": "eg.l06.e19", "pool": "lesson", "lessonId": "eg.l06", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l06.e20', 'eg', 'eg.l06', 'eg.g06.ecrits_heresies', array['eg.g06.ecrits_heresies','eg.v.saint_jean']::text[], 'mcq', 'lesson', 'Quel évangéliste de la fin du siècle répond à la gnose ?', array['Jean']::text[], 'Jean écrit à la fin du siècle et répond à la gnose en insistant sur l''Incarnation.', 2, '{"unitIds": ["eg.g06.ecrits_heresies", "eg.v.saint_jean"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel évangéliste de la fin du siècle répond à la gnose ?", "promptLanguage": "fr", "answer": "Jean", "acceptedAnswers": ["Jean"], "explanation": "Jean écrit à la fin du siècle et répond à la gnose en insistant sur l''Incarnation.", "tip": "Jean contre la gnose.", "extraExample": {"text": "Il meurt vers l''an 100.", "translation": "C''est le dernier apôtre vivant."}, "options": ["Jean", "Matthieu", "Marc"], "id": "eg.l06.e20", "pool": "lesson", "lessonId": "eg.l06", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l06.e21', 'eg', 'eg.l06', 'eg.g06.ecrits_heresies', array['eg.g06.ecrits_heresies','eg.v.simon_le_magicien']::text[], 'fill_blank', 'lesson', 'Simon le ___ (Ac 8) est considéré comme un ancêtre des gnostiques.', array['magicien']::text[], 'Simon le magicien est vu par les Pères comme l''ancêtre des gnostiques.', 2, '{"unitIds": ["eg.g06.ecrits_heresies", "eg.v.simon_le_magicien"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Simon le ___ (Ac 8) est considéré comme un ancêtre des gnostiques.", "promptLanguage": "fr", "answer": "magicien", "acceptedAnswers": ["magicien"], "explanation": "Simon le magicien est vu par les Pères comme l''ancêtre des gnostiques.", "tip": "Simon = magicien.", "extraExample": {"text": "Il veut acheter le don de l''Esprit.", "translation": "Pierre le reprend."}, "options": ["pharisien", "magicien", "pêcheur"], "id": "eg.l06.e21", "pool": "lesson", "lessonId": "eg.l06", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l06.e22', 'eg', 'eg.l06', 'eg.g06.ecrits_heresies', array['eg.g06.ecrits_heresies','eg.v.evangile']::text[], 'match', 'lesson', 'Quatre évangiles, quatre portraits', '{}'::text[], 'Chaque évangile met un accent : prophéties (Matthieu), action (Marc), détails (Luc), Verbe fait chair (Jean).', 2, '{"unitIds": ["eg.g06.ecrits_heresies", "eg.v.evangile"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Quatre évangiles, quatre portraits", "promptLanguage": "fr", "answer": "Matthieu = les prophéties accomplies ; Marc = le plus court, Jésus en action ; Luc = écrit aussi les Actes des apôtres ; Jean = le Verbe s''est fait chair", "acceptedAnswers": [], "explanation": "Chaque évangile met un accent : prophéties (Matthieu), action (Marc), détails (Luc), Verbe fait chair (Jean).", "tip": "Quatre évangélistes.", "pairs": [{"left": "Matthieu", "right": "les prophéties accomplies"}, {"left": "Marc", "right": "le plus court, Jésus en action"}, {"left": "Luc", "right": "écrit aussi les Actes des apôtres"}, {"left": "Jean", "right": "le Verbe s''est fait chair"}], "id": "eg.l06.e22", "pool": "lesson", "lessonId": "eg.l06", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l06.e23', 'eg', 'eg.l06', 'eg.g06.ecrits_heresies', array['eg.g06.ecrits_heresies','eg.v.gnosticisme','eg.v.docetisme','eg.v.epitre']::text[], 'match', 'lesson', 'Trois erreurs, une lettre', '{}'::text[], 'Gnose et docétisme nient le vrai corps du Christ ; les judaïsants nient la liberté des païens ; l''épître est la lettre qui y répond.', 3, '{"unitIds": ["eg.g06.ecrits_heresies", "eg.v.gnosticisme", "eg.v.docetisme", "eg.v.epitre"], "type": "match", "difficulty": 3, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Trois erreurs, une lettre", "promptLanguage": "fr", "answer": "La gnose = connaissance secrète qui méprise le corps ; Le docétisme = Jésus n''aurait que l''apparence d''un homme ; Les judaïsants = veulent imposer la Loi de Moïse ; Une épître = lettre d''un apôtre à une communauté", "acceptedAnswers": [], "explanation": "Gnose et docétisme nient le vrai corps du Christ ; les judaïsants nient la liberté des païens ; l''épître est la lettre qui y répond.", "tip": "Deux erreurs de doctrine, une lettre pour y répondre.", "pairs": [{"left": "La gnose", "right": "connaissance secrète qui méprise le corps"}, {"left": "Le docétisme", "right": "Jésus n''aurait que l''apparence d''un homme"}, {"left": "Les judaïsants", "right": "veulent imposer la Loi de Moïse"}, {"left": "Une épître", "right": "lettre d''un apôtre à une communauté"}], "id": "eg.l06.e23", "pool": "lesson", "lessonId": "eg.l06", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l06.e24', 'eg', 'eg.l06', 'eg.g06.ecrits_heresies', array['eg.g06.ecrits_heresies']::text[], 'reorder', 'lesson', 'Phrase-repère : la réponse de Jean.', array['Jean combat le gnosticisme en affirmant que le Verbe s''est fait chair']::text[], 'Jean répond à la gnose en rappelant que Dieu s''est vraiment fait homme.', 3, '{"unitIds": ["eg.g06.ecrits_heresies"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "prompt": "Phrase-repère : la réponse de Jean.", "promptLanguage": "fr", "answer": "Jean combat le gnosticisme en affirmant que le Verbe s''est fait chair", "acceptedAnswers": ["Jean combat le gnosticisme en affirmant que le Verbe s''est fait chair"], "explanation": "Jean répond à la gnose en rappelant que Dieu s''est vraiment fait homme.", "tip": "Verbe fait chair.", "extraExample": {"text": "Jn 1, 14.", "translation": "L''Incarnation est réelle."}, "tokens": ["combat", "le", "gnosticisme", "en", "affirmant", "que", "le", "Verbe", "s''est", "fait", "chair", "Jean"], "id": "eg.l06.e24", "pool": "lesson", "lessonId": "eg.l06", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l07.e01', 'eg', 'eg.l07', 'eg.g06.ecrits_heresies', array['eg.g06.ecrits_heresies','eg.v.evangile']::text[], 'mcq', 'lesson', 'Combien y a-t-il d''évangiles dans le Nouveau Testament ?', array['quatre']::text[], 'Il y a quatre évangiles : Matthieu, Marc, Luc et Jean.', 1, '{"unitIds": ["eg.g06.ecrits_heresies", "eg.v.evangile"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Combien y a-t-il d''évangiles dans le Nouveau Testament ?", "promptLanguage": "fr", "answer": "quatre", "acceptedAnswers": ["quatre"], "explanation": "Il y a quatre évangiles : Matthieu, Marc, Luc et Jean.", "tip": "4 évangiles, 14 épîtres de Paul.", "extraExample": {"text": "Matthieu, Marc, Luc, Jean.", "translation": "Chacun a son accent."}, "options": ["douze", "quatre", "trois"], "id": "eg.l07.e01", "pool": "lesson", "lessonId": "eg.l07", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l07.e02', 'eg', 'eg.l07', 'eg.g05.persecutions_premier_siecle', array['eg.g05.persecutions_premier_siecle','eg.v.neron']::text[], 'fill_blank', 'lesson', 'Les deux piliers, Pierre et Paul, sont martyrisés à Rome vers l''an ___.', array['67']::text[], 'Pierre et Paul sont martyrisés à Rome vers l''an 67.', 2, '{"unitIds": ["eg.g05.persecutions_premier_siecle", "eg.v.neron"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Les deux piliers, Pierre et Paul, sont martyrisés à Rome vers l''an ___.", "promptLanguage": "fr", "answer": "67", "acceptedAnswers": ["67"], "explanation": "Pierre et Paul sont martyrisés à Rome vers l''an 67.", "tip": "67 : Pierre et Paul.", "extraExample": {"text": "Le concile était vers 49.", "translation": "La chute de Jérusalem en 70."}, "options": ["49", "70", "67"], "id": "eg.l07.e02", "pool": "lesson", "lessonId": "eg.l07", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l07.e03', 'eg', 'eg.l07', 'eg.g05.persecutions_premier_siecle', array['eg.g05.persecutions_premier_siecle','eg.v.chute_de_jerusalem']::text[], 'mcq', 'lesson', 'Quelle ville est prise par Titus en 70 ?', array['Jérusalem']::text[], 'Titus prend Jérusalem en 70 et détruit le Temple.', 1, '{"unitIds": ["eg.g05.persecutions_premier_siecle", "eg.v.chute_de_jerusalem"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle ville est prise par Titus en 70 ?", "promptLanguage": "fr", "answer": "Jérusalem", "acceptedAnswers": ["Jérusalem"], "explanation": "Titus prend Jérusalem en 70 et détruit le Temple.", "tip": "70 : Jérusalem tombe.", "extraExample": {"text": "Rome est l''autre ville clé.", "translation": "Antioche est la base de Paul."}, "options": ["Rome", "Jérusalem", "Antioche"], "id": "eg.l07.e03", "pool": "lesson", "lessonId": "eg.l07", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l07.e04', 'eg', 'eg.l07', 'eg.g04.concile_jerusalem', array['eg.g04.concile_jerusalem','eg.v.circoncision']::text[], 'free_answer', 'lesson', 'Quel signe de l''alliance avec Abraham le concile de Jérusalem ne rend-il plus obligatoire pour les païens ?', array['la circoncision','circoncision']::text[], 'La circoncision, signe de l''alliance avec Abraham, n''est plus obligatoire pour les païens convertis.', 2, '{"unitIds": ["eg.g04.concile_jerusalem", "eg.v.circoncision"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Quel signe de l''alliance avec Abraham le concile de Jérusalem ne rend-il plus obligatoire pour les païens ?", "promptLanguage": "fr", "answer": "la circoncision", "acceptedAnswers": ["la circoncision", "circoncision"], "explanation": "La circoncision, signe de l''alliance avec Abraham, n''est plus obligatoire pour les païens convertis.", "tip": "Concile 49 = circoncision.", "extraExample": {"text": "Cela ouvre l''Église aux nations.", "translation": "Le salut vient du Christ."}, "hint": "Elle est liée à la Loi de Moïse.", "id": "eg.l07.e04", "pool": "lesson", "lessonId": "eg.l07", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l07.e05', 'eg', 'eg.l07', 'eg.g07.apotres_sieges', array['eg.g07.apotres_sieges']::text[], 'mcq', 'lesson', 'Quelle parole de Jésus envoie les apôtres vers toutes les nations ?', array['Allez donc, de toutes les nations faites des disciples']::text[], 'C''est la parole de Mt 28, 19 : l''envoi en mission, qui donne leur nom aux apôtres (« envoyés »).', 2, '{"unitIds": ["eg.g07.apotres_sieges"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle parole de Jésus envoie les apôtres vers toutes les nations ?", "promptLanguage": "fr", "answer": "Allez donc, de toutes les nations faites des disciples", "acceptedAnswers": ["Allez donc, de toutes les nations faites des disciples"], "explanation": "C''est la parole de Mt 28, 19 : l''envoi en mission, qui donne leur nom aux apôtres (« envoyés »).", "tip": "Mt 28, 19 : l''envoi.", "extraExample": {"text": "Elle est prononcée avant l''Ascension.", "translation": "Elle ouvre à toutes les nations."}, "options": ["Cherchez d''abord le Royaume de Dieu", "Aimez-vous les uns les autres", "Allez donc, de toutes les nations faites des disciples"], "id": "eg.l07.e05", "pool": "lesson", "lessonId": "eg.l07", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l07.e06', 'eg', 'eg.l07', 'eg.g07.apotres_sieges', array['eg.g07.apotres_sieges','eg.v.saint_andre']::text[], 'mcq', 'lesson', 'Quel apôtre aurait évangélisé la Grèce, selon la tradition ?', array['André']::text[], 'André, frère de Pierre, est associé à la Grèce par la tradition.', 2, '{"unitIds": ["eg.g07.apotres_sieges", "eg.v.saint_andre"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel apôtre aurait évangélisé la Grèce, selon la tradition ?", "promptLanguage": "fr", "answer": "André", "acceptedAnswers": ["André"], "explanation": "André, frère de Pierre, est associé à la Grèce par la tradition.", "tip": "André = Grèce.", "extraExample": {"text": "Paul prêche aussi en Grèce.", "translation": "André est martyrisé à Patras."}, "options": ["Thomas", "Matthieu", "André"], "id": "eg.l07.e06", "pool": "lesson", "lessonId": "eg.l07", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l07.e07', 'eg', 'eg.l07', 'eg.g07.apotres_sieges', array['eg.g07.apotres_sieges','eg.v.saint_thomas']::text[], 'mcq', 'lesson', 'Quel apôtre porte l''Évangile jusqu''en Inde, selon la tradition ?', array['Thomas']::text[], 'Thomas est associé à l''Inde : les chrétiens de Malabar l''honorent comme fondateur.', 1, '{"unitIds": ["eg.g07.apotres_sieges", "eg.v.saint_thomas"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel apôtre porte l''Évangile jusqu''en Inde, selon la tradition ?", "promptLanguage": "fr", "answer": "Thomas", "acceptedAnswers": ["Thomas"], "explanation": "Thomas est associé à l''Inde : les chrétiens de Malabar l''honorent comme fondateur.", "tip": "Thomas = Inde.", "extraExample": {"text": "C''est l''un des plus lointains voyages.", "translation": "Il est martyrisé vers 72."}, "options": ["Thomas", "André", "Jean"], "id": "eg.l07.e07", "pool": "lesson", "lessonId": "eg.l07", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l07.e08', 'eg', 'eg.l07', 'eg.g07.apotres_sieges', array['eg.g07.apotres_sieges','eg.v.saint_matthieu']::text[], 'mcq', 'lesson', 'Quel apôtre est associé à l''Éthiopie ?', array['Matthieu']::text[], 'Matthieu est associé à l''Éthiopie et à la Perse par la tradition.', 2, '{"unitIds": ["eg.g07.apotres_sieges", "eg.v.saint_matthieu"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel apôtre est associé à l''Éthiopie ?", "promptLanguage": "fr", "answer": "Matthieu", "acceptedAnswers": ["Matthieu"], "explanation": "Matthieu est associé à l''Éthiopie et à la Perse par la tradition.", "tip": "Matthieu = Éthiopie.", "extraExample": {"text": "Ancien collecteur d''impôts.", "translation": "Auteur d''un évangile."}, "options": ["Thomas", "Jacques", "Matthieu"], "id": "eg.l07.e08", "pool": "lesson", "lessonId": "eg.l07", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l07.e09', 'eg', 'eg.l07', 'eg.g07.apotres_sieges', array['eg.g07.apotres_sieges','eg.v.saint_barthelemy']::text[], 'mcq', 'lesson', 'Quel apôtre est associé à l''Arménie ?', array['Barthélemy']::text[], 'La tradition fait prêcher Barthélemy en Arménie, où l''Église arménienne l''honore comme fondateur.', 3, '{"unitIds": ["eg.g07.apotres_sieges", "eg.v.saint_barthelemy"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quel apôtre est associé à l''Arménie ?", "promptLanguage": "fr", "answer": "Barthélemy", "acceptedAnswers": ["Barthélemy"], "explanation": "La tradition fait prêcher Barthélemy en Arménie, où l''Église arménienne l''honore comme fondateur.", "tip": "Barthélemy = Arménie.", "extraExample": {"text": "Il fait partie des Douze.", "translation": "Il est cité dans les évangiles."}, "options": ["Matthieu", "André", "Barthélemy"], "id": "eg.l07.e09", "pool": "lesson", "lessonId": "eg.l07", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l07.e10', 'eg', 'eg.l07', 'eg.g07.apotres_sieges', array['eg.g07.apotres_sieges']::text[], 'mcq', 'lesson', 'Où Jean s''installe-t-il après avoir quitté Jérusalem ?', array['en Asie Mineure']::text[], 'Jean prêche à Jérusalem puis s''installe en Asie Mineure, à Éphèse.', 2, '{"unitIds": ["eg.g07.apotres_sieges"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Où Jean s''installe-t-il après avoir quitté Jérusalem ?", "promptLanguage": "fr", "answer": "en Asie Mineure", "acceptedAnswers": ["en Asie Mineure"], "explanation": "Jean prêche à Jérusalem puis s''installe en Asie Mineure, à Éphèse.", "tip": "Jean = Asie Mineure.", "extraExample": {"text": "Il y écrit son évangile.", "translation": "Il y meurt vers l''an 100."}, "options": ["en Égypte", "en Inde", "en Asie Mineure"], "id": "eg.l07.e10", "pool": "lesson", "lessonId": "eg.l07", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l07.e11', 'eg', 'eg.l07', 'eg.g07.apotres_sieges', array['eg.g07.apotres_sieges','eg.v.saint_jean']::text[], 'free_answer', 'lesson', 'Quel apôtre est le dernier apôtre vivant, mort vers l''an 100 ?', array['Jean','saint Jean']::text[], 'Jean meurt vers l''an 100 : avec lui se ferme l''âge des apôtres.', 1, '{"unitIds": ["eg.g07.apotres_sieges", "eg.v.saint_jean"], "type": "free_answer", "difficulty": 1, "instruction": "Écris ta réponse.", "prompt": "Quel apôtre est le dernier apôtre vivant, mort vers l''an 100 ?", "promptLanguage": "fr", "answer": "Jean", "acceptedAnswers": ["Jean", "saint Jean"], "explanation": "Jean meurt vers l''an 100 : avec lui se ferme l''âge des apôtres.", "tip": "Jean = dernier.", "extraExample": {"text": "Il est exilé à Patmos sous Domitien.", "translation": "Il écrit l''Apocalypse."}, "hint": "Il écrit l''évangile du Verbe.", "id": "eg.l07.e11", "pool": "lesson", "lessonId": "eg.l07", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l07.e12', 'eg', 'eg.l07', 'eg.g07.apotres_sieges', array['eg.g07.apotres_sieges','eg.v.siege_apostolique']::text[], 'mcq', 'lesson', 'Qu''est-ce qu''un siège apostolique ?', array['une Église fondée par un apôtre']::text[], 'Un siège apostolique est une Église fondée par un apôtre ou un de ses proches ; son évêque lui succède.', 2, '{"unitIds": ["eg.g07.apotres_sieges", "eg.v.siege_apostolique"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qu''est-ce qu''un siège apostolique ?", "promptLanguage": "fr", "answer": "une Église fondée par un apôtre", "acceptedAnswers": ["une Église fondée par un apôtre"], "explanation": "Un siège apostolique est une Église fondée par un apôtre ou un de ses proches ; son évêque lui succède.", "tip": "Apostolique = fondée par un apôtre.", "extraExample": {"text": "Alexandrie est un siège apostolique.", "translation": "Rome aussi."}, "options": ["une Église fondée par un empereur", "un concile d''évêques", "une Église fondée par un apôtre"], "id": "eg.l07.e12", "pool": "lesson", "lessonId": "eg.l07", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l07.e13', 'eg', 'eg.l07', 'eg.g07.apotres_sieges', array['eg.g07.apotres_sieges','eg.v.succession_apostolique']::text[], 'mcq', 'lesson', 'Que garantit la succession apostolique ?', array['que la foi enseignée est celle des origines']::text[], 'La chaîne d''évêques qui remonte aux apôtres garantit que la foi enseignée est celle des origines.', 3, '{"unitIds": ["eg.g07.apotres_sieges", "eg.v.succession_apostolique"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Que garantit la succession apostolique ?", "promptLanguage": "fr", "answer": "que la foi enseignée est celle des origines", "acceptedAnswers": ["que la foi enseignée est celle des origines"], "explanation": "La chaîne d''évêques qui remonte aux apôtres garantit que la foi enseignée est celle des origines.", "tip": "Chaîne = fidélité.", "extraExample": {"text": "Les hérésies sont jugées à cette mesure.", "translation": "On regarde la foi des origines."}, "options": ["que l''Église n''a jamais de conflits", "que la foi enseignée est celle des origines", "que l''évêque est toujours d''accord avec l''empereur"], "id": "eg.l07.e13", "pool": "lesson", "lessonId": "eg.l07", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l07.e14', 'eg', 'eg.l07', 'eg.g07.apotres_sieges', array['eg.g07.apotres_sieges','eg.v.succession_apostolique']::text[], 'fill_blank', 'lesson', 'Les évêques succèdent aux apôtres en recevant l''imposition des ___.', array['mains']::text[], 'Les évêques sont ordonnés par l''imposition des mains, geste hérité des apôtres.', 2, '{"unitIds": ["eg.g07.apotres_sieges", "eg.v.succession_apostolique"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Les évêques succèdent aux apôtres en recevant l''imposition des ___.", "promptLanguage": "fr", "answer": "mains", "acceptedAnswers": ["mains"], "explanation": "Les évêques sont ordonnés par l''imposition des mains, geste hérité des apôtres.", "tip": "Mains = transmission.", "extraExample": {"text": "Les apôtres l''ont reçu du Christ.", "translation": "Et le transmettent."}, "options": ["mains", "pieds", "lettres"], "id": "eg.l07.e14", "pool": "lesson", "lessonId": "eg.l07", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l07.e15', 'eg', 'eg.l07', 'eg.g07.apotres_sieges', array['eg.g07.apotres_sieges','eg.v.succession_apostolique']::text[], 'fill_blank', 'lesson', 'La chaîne ininterrompue d''évêques qui remonte aux apôtres s''appelle la ___ apostolique.', array['succession']::text[], 'Succession apostolique : de chaque évêque à son prédécesseur, jusqu''aux apôtres.', 2, '{"unitIds": ["eg.g07.apotres_sieges", "eg.v.succession_apostolique"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "La chaîne ininterrompue d''évêques qui remonte aux apôtres s''appelle la ___ apostolique.", "promptLanguage": "fr", "answer": "succession", "acceptedAnswers": ["succession"], "explanation": "Succession apostolique : de chaque évêque à son prédécesseur, jusqu''aux apôtres.", "tip": "Succession = chaîne.", "extraExample": {"text": "Le pape copte est successeur de Marc.", "translation": "Il y a une chaîne de plus de 1900 ans."}, "options": ["tradition", "assemblée", "succession"], "id": "eg.l07.e15", "pool": "lesson", "lessonId": "eg.l07", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
