insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l07.e18', 'eg', 'eg.l07', 'eg.g07.apotres_sieges', array['eg.g07.apotres_sieges','eg.v.saint_andre','eg.v.saint_thomas','eg.v.saint_matthieu','eg.v.saint_barthelemy']::text[], 'match', 'lesson', 'Un apôtre, un pays (selon la tradition)', '{}'::text[], 'La tradition associe chaque apôtre à un pays : André à la Grèce, Thomas à l''Inde, Matthieu à l''Éthiopie, Barthélemy à l''Arménie.', 2, '{"unitIds": ["eg.g07.apotres_sieges", "eg.v.saint_andre", "eg.v.saint_thomas", "eg.v.saint_matthieu", "eg.v.saint_barthelemy"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Un apôtre, un pays (selon la tradition)", "promptLanguage": "fr", "answer": "André = la Grèce ; Thomas = l''Inde ; Matthieu = l''Éthiopie ; Barthélemy = l''Arménie", "acceptedAnswers": [], "explanation": "La tradition associe chaque apôtre à un pays : André à la Grèce, Thomas à l''Inde, Matthieu à l''Éthiopie, Barthélemy à l''Arménie.", "tip": "Quatre apôtres, quatre pays.", "pairs": [{"left": "André", "right": "la Grèce"}, {"left": "Thomas", "right": "l''Inde"}, {"left": "Matthieu", "right": "l''Éthiopie"}, {"left": "Barthélemy", "right": "l''Arménie"}], "id": "eg.l07.e18", "pool": "lesson", "lessonId": "eg.l07", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l07.e19', 'eg', 'eg.l07', 'eg.g07.apotres_sieges', array['eg.g07.apotres_sieges','eg.v.siege_apostolique']::text[], 'match', 'lesson', 'Un siège, un fondateur', '{}'::text[], 'Les sièges apostoliques du Ier siècle ont chacun un fondateur : Jacques, Pierre et Paul, Jean, Marc.', 3, '{"unitIds": ["eg.g07.apotres_sieges", "eg.v.siege_apostolique"], "type": "match", "difficulty": 3, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Un siège, un fondateur", "promptLanguage": "fr", "answer": "Jérusalem = Jacques ; Rome = Pierre et Paul ; Éphèse = Jean ; Alexandrie = Marc", "acceptedAnswers": [], "explanation": "Les sièges apostoliques du Ier siècle ont chacun un fondateur : Jacques, Pierre et Paul, Jean, Marc.", "tip": "Chaque siège a son apôtre.", "pairs": [{"left": "Jérusalem", "right": "Jacques"}, {"left": "Rome", "right": "Pierre et Paul"}, {"left": "Éphèse", "right": "Jean"}, {"left": "Alexandrie", "right": "Marc"}], "id": "eg.l07.e19", "pool": "lesson", "lessonId": "eg.l07", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l07.e20', 'eg', 'eg.l07', 'eg.g07.apotres_sieges', array['eg.g07.apotres_sieges']::text[], 'reorder', 'lesson', 'Phrase-repère : le siège apostolique.', array['Un siège apostolique est une Église fondée par un apôtre']::text[], 'Le siège apostolique est fondé par un apôtre ou un de ses proches.', 2, '{"unitIds": ["eg.g07.apotres_sieges"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "prompt": "Phrase-repère : le siège apostolique.", "promptLanguage": "fr", "answer": "Un siège apostolique est une Église fondée par un apôtre", "acceptedAnswers": ["Un siège apostolique est une Église fondée par un apôtre"], "explanation": "Le siège apostolique est fondé par un apôtre ou un de ses proches.", "tip": "Apostolique = fondé par un apôtre.", "extraExample": {"text": "Alexandrie est fondée par Marc.", "translation": "Rome par Pierre et Paul."}, "tokens": ["une", "Église", "fondée", "par", "un", "apôtre", "Un", "siège", "apostolique", "est"], "id": "eg.l07.e20", "pool": "lesson", "lessonId": "eg.l07", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
