insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l12.e18', 'eg', 'eg.l12', 'eg.g12.persecutions_ichthus', array['eg.g12.persecutions_ichthus','eg.v.culte_de_l_empereur']::text[], 'reorder', 'lesson', 'Reconstitue la phrase-repère (eg.l12).', array['Les chrétiens refusent le culte de l''empereur']::text[], 'Ce refus est la cause profonde des persécutions.', 2, '{"unitIds": ["eg.g12.persecutions_ichthus", "eg.v.culte_de_l_empereur"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre.", "prompt": "Reconstitue la phrase-repère (eg.l12).", "promptLanguage": "fr", "answer": "Les chrétiens refusent le culte de l''empereur", "acceptedAnswers": ["Les chrétiens refusent le culte de l''empereur"], "explanation": "Ce refus est la cause profonde des persécutions.", "tip": "Refus du culte = persécution.", "extraExample": {"text": "Offrir de l''encens à l''empereur est un acte religieux.", "translation": "Les chrétiens ne le font pas."}, "tokens": ["culte", "de", "l''empereur", "refusent", "Les", "le", "chrétiens"], "id": "eg.l12.e18", "pool": "lesson", "lessonId": "eg.l12", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l12.e19', 'eg', 'eg.l12', 'eg.g12.persecutions_ichthus', array['eg.g12.persecutions_ichthus','eg.v.ichthys']::text[], 'free_answer', 'lesson', 'Quel mot grec, qui veut dire poisson, sert de symbole aux chrétiens ?', array['ICHTHYS','ichthus','Ichtus']::text[], 'ICHTHYS est aussi un sigle : Jésus Christ Fils de Dieu Sauveur.', 2, '{"unitIds": ["eg.g12.persecutions_ichthus", "eg.v.ichthys"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Quel mot grec, qui veut dire poisson, sert de symbole aux chrétiens ?", "promptLanguage": "fr", "answer": "ICHTHYS", "acceptedAnswers": ["ICHTHYS", "ichthus", "Ichtus"], "explanation": "ICHTHYS est aussi un sigle : Jésus Christ Fils de Dieu Sauveur.", "tip": "Poisson = ICHTHYS.", "extraExample": {"text": "Chaque lettre est une initiale.", "translation": "Le tout forme une confession de foi."}, "id": "eg.l12.e19", "pool": "lesson", "lessonId": "eg.l12", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l12.e20', 'eg', 'eg.l12', 'eg.g12.persecutions_ichthus', array['eg.g12.persecutions_ichthus','eg.v.martyr']::text[], 'free_answer', 'lesson', 'Comment appelle-t-on un chrétien qui meurt plutôt que de renier le Christ ?', array['un martyr','martyr','le martyr','une martyre','martyre']::text[], 'Du grec martys, « témoin ».', 2, '{"unitIds": ["eg.g12.persecutions_ichthus", "eg.v.martyr"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Comment appelle-t-on un chrétien qui meurt plutôt que de renier le Christ ?", "promptLanguage": "fr", "answer": "un martyr", "acceptedAnswers": ["un martyr", "martyr", "le martyr", "une martyre", "martyre"], "explanation": "Du grec martys, « témoin ».", "tip": "Martyr = témoin.", "extraExample": {"text": "Polycarpe est un martyr.", "translation": "Blandine aussi."}, "id": "eg.l12.e20", "pool": "lesson", "lessonId": "eg.l12", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l12.e21', 'eg', 'eg.l12', 'eg.g12.persecutions_ichthus', array['eg.g12.persecutions_ichthus','eg.v.trajan']::text[], 'free_answer', 'lesson', 'Quel empereur est le troisième à persécuter les chrétiens selon la tradition ?', array['Trajan','l''empereur Trajan']::text[], 'Trajan est suivi par Marc Aurèle (4e) et Septime Sévère (5e).', 3, '{"unitIds": ["eg.g12.persecutions_ichthus", "eg.v.trajan"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Quel empereur est le troisième à persécuter les chrétiens selon la tradition ?", "promptLanguage": "fr", "answer": "Trajan", "acceptedAnswers": ["Trajan", "l''empereur Trajan"], "explanation": "Trajan est suivi par Marc Aurèle (4e) et Septime Sévère (5e).", "tip": "Trajan = 3.", "extraExample": {"text": "Pline lui écrit pour savoir quoi faire.", "translation": "Sa réponse devient une règle."}, "id": "eg.l12.e21", "pool": "lesson", "lessonId": "eg.l12", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l13.e01', 'eg', 'eg.l13', 'eg.g13.apologistes', array['eg.g13.apologistes']::text[], 'match', 'lesson', 'Deux familles d''écrivains', '{}'::text[], 'Deux publics différents : les chrétiens (apostoliques) et les païens (apologistes).', 1, '{"unitIds": ["eg.g13.apologistes"], "type": "match", "difficulty": 1, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Deux familles d''écrivains", "promptLanguage": "fr", "answer": "Pères apostoliques = écrivent aux chrétiens pour les enseigner ; Apologistes = écrivent aux païens pour défendre la foi ; Justin Martyr = philosophe converti, martyr à Rome vers 165 ; Tertullien = juriste de Carthage, premier grand auteur latin", "acceptedAnswers": [], "explanation": "Deux publics différents : les chrétiens (apostoliques) et les païens (apologistes).", "tip": "Dedans / dehors.", "pairs": [{"left": "Pères apostoliques", "right": "écrivent aux chrétiens pour les enseigner"}, {"left": "Apologistes", "right": "écrivent aux païens pour défendre la foi"}, {"left": "Justin Martyr", "right": "philosophe converti, martyr à Rome vers 165"}, {"left": "Tertullien", "right": "juriste de Carthage, premier grand auteur latin"}], "id": "eg.l13.e01", "pool": "lesson", "lessonId": "eg.l13", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l13.e02', 'eg', 'eg.l13', 'eg.g13.apologistes', array['eg.g13.apologistes','eg.v.dialogue_avec_tryphon','eg.v.apologetique']::text[], 'match', 'lesson', 'Quelle œuvre pour quel auteur ?', '{}'::text[], 'Chaque auteur a ses œuvres à retenir.', 2, '{"unitIds": ["eg.g13.apologistes", "eg.v.dialogue_avec_tryphon", "eg.v.apologetique"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Quelle œuvre pour quel auteur ?", "promptLanguage": "fr", "answer": "Justin = Dialogue avec Tryphon ; Tertullien = Apologétique ; Polycarpe = lettre aux Philippiens", "acceptedAnswers": [], "explanation": "Chaque auteur a ses œuvres à retenir.", "tip": "Justin-Tryphon, Tertullien-Apologétique.", "pairs": [{"left": "Justin", "right": "Dialogue avec Tryphon"}, {"left": "Tertullien", "right": "Apologétique"}, {"left": "Polycarpe", "right": "lettre aux Philippiens"}], "id": "eg.l13.e02", "pool": "lesson", "lessonId": "eg.l13", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l13.e03', 'eg', 'eg.l13', 'eg.g13.apologistes', array['eg.g13.apologistes','eg.v.apologiste']::text[], 'mcq', 'lesson', 'Que signifie le mot grec apologia ?', array['défense']::text[], 'Les apologistes défendent la foi devant ceux de l''extérieur.', 1, '{"unitIds": ["eg.g13.apologistes", "eg.v.apologiste"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Que signifie le mot grec apologia ?", "promptLanguage": "fr", "answer": "défense", "acceptedAnswers": ["défense"], "explanation": "Les apologistes défendent la foi devant ceux de l''extérieur.", "tip": "Apologie = défense.", "extraExample": {"text": "Une apologie n''est pas une excuse mais une défense argumentée.", "translation": "Elle répond à des accusations."}, "options": ["prière", "louange", "défense", "enseignement"], "id": "eg.l13.e03", "pool": "lesson", "lessonId": "eg.l13", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l13.e04', 'eg', 'eg.l13', 'eg.g13.apologistes', array['eg.g13.apologistes','eg.v.apologiste']::text[], 'mcq', 'lesson', 'À qui s''adressent les apologistes ?', array['à des gens extérieurs à la communauté chrétienne']::text[], 'Ils écrivent aux empereurs, aux magistrats, aux philosophes, c''est-à-dire à ceux qui ne sont pas chrétiens.', 1, '{"unitIds": ["eg.g13.apologistes", "eg.v.apologiste"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "À qui s''adressent les apologistes ?", "promptLanguage": "fr", "answer": "à des gens extérieurs à la communauté chrétienne", "acceptedAnswers": ["à des gens extérieurs à la communauté chrétienne"], "explanation": "Ils écrivent aux empereurs, aux magistrats, aux philosophes, c''est-à-dire à ceux qui ne sont pas chrétiens.", "tip": "Apologistes = au dehors.", "extraExample": {"text": "Justin écrit à l''empereur.", "translation": "Tertullien écrit aux magistrats."}, "options": ["uniquement aux évêques", "aux chrétiens de leur ville", "aux seuls disciples des apôtres", "à des gens extérieurs à la communauté chrétienne"], "id": "eg.l13.e04", "pool": "lesson", "lessonId": "eg.l13", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l13.e05', 'eg', 'eg.l13', 'eg.g13.apologistes', array['eg.g13.apologistes','eg.v.paganisme']::text[], 'mcq', 'lesson', 'De quoi les païens accusent-ils les chrétiens ?', array['d''être athées']::text[], 'Les chrétiens n''adorent pas les dieux de l''Empire : les païens les prennent pour des athées.', 2, '{"unitIds": ["eg.g13.apologistes", "eg.v.paganisme"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "De quoi les païens accusent-ils les chrétiens ?", "promptLanguage": "fr", "answer": "d''être athées", "acceptedAnswers": ["d''être athées"], "explanation": "Les chrétiens n''adorent pas les dieux de l''Empire : les païens les prennent pour des athées.", "tip": "Athées = sans dieux (aux yeux des païens).", "extraExample": {"text": "Les chrétiens répondent qu''ils adorent le seul vrai Dieu.", "translation": "Ils ne sont donc pas athées."}, "options": ["d''être athées", "d''adorer trop de dieux", "de refuser la prière", "de piller les temples"], "id": "eg.l13.e05", "pool": "lesson", "lessonId": "eg.l13", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l13.e06', 'eg', 'eg.l13', 'eg.g13.apologistes', array['eg.g13.apologistes','eg.v.culte_de_l_empereur']::text[], 'mcq', 'lesson', 'Que répondent les apologistes à propos de l''empereur ?', array['nous prions pour l''empereur sans l''adorer']::text[], 'Les chrétiens sont de bons citoyens : ils prient pour l''empereur, mais l''adoration est réservée à Dieu.', 2, '{"unitIds": ["eg.g13.apologistes", "eg.v.culte_de_l_empereur"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que répondent les apologistes à propos de l''empereur ?", "promptLanguage": "fr", "answer": "nous prions pour l''empereur sans l''adorer", "acceptedAnswers": ["nous prions pour l''empereur sans l''adorer"], "explanation": "Les chrétiens sont de bons citoyens : ils prient pour l''empereur, mais l''adoration est réservée à Dieu.", "tip": "Prier pour ≠ adorer.", "extraExample": {"text": "Un chrétien paie l''impôt et prie pour l''empereur.", "translation": "Mais il ne lui rend pas un culte."}, "options": ["nous l''adorons comme un dieu", "nous prions pour l''empereur sans l''adorer", "nous le refusons comme chef", "nous ne le connaissons pas"], "id": "eg.l13.e06", "pool": "lesson", "lessonId": "eg.l13", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l13.e07', 'eg', 'eg.l13', 'eg.g13.apologistes', array['eg.g13.apologistes','eg.v.justin_martyr']::text[], 'mcq', 'lesson', 'D''où vient Justin Martyr ?', array['Naplouse, en Palestine']::text[], 'Justin naît dans une famille païenne de Naplouse. Il cherche la vérité chez les philosophes avant de se convertir.', 2, '{"unitIds": ["eg.g13.apologistes", "eg.v.justin_martyr"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "D''où vient Justin Martyr ?", "promptLanguage": "fr", "answer": "Naplouse, en Palestine", "acceptedAnswers": ["Naplouse, en Palestine"], "explanation": "Justin naît dans une famille païenne de Naplouse. Il cherche la vérité chez les philosophes avant de se convertir.", "tip": "Justin = Naplouse.", "extraExample": {"text": "Il enseigne ensuite à Rome.", "translation": "Il y meurt martyr vers 165."}, "options": ["Carthage", "Smyrne", "Naplouse, en Palestine", "Alexandrie"], "id": "eg.l13.e07", "pool": "lesson", "lessonId": "eg.l13", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l13.e08', 'eg', 'eg.l13', 'eg.g13.apologistes', array['eg.g13.apologistes','eg.v.semences_du_verbe']::text[], 'mcq', 'lesson', 'Que sont les « semences du Verbe » pour Justin ?', array['des parts de vérité']::text[], 'Le Verbe éclaire tout homme : les philosophes ont donc entrevu des parts de vérité, que le Christ révèle en entier.', 2, '{"unitIds": ["eg.g13.apologistes", "eg.v.semences_du_verbe"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que sont les « semences du Verbe » pour Justin ?", "promptLanguage": "fr", "answer": "des parts de vérité", "acceptedAnswers": ["des parts de vérité"], "explanation": "Le Verbe éclaire tout homme : les philosophes ont donc entrevu des parts de vérité, que le Christ révèle en entier.", "tip": "Semences = graines de vérité.", "extraExample": {"text": "Socrate cherchait la vérité, selon Justin.", "translation": "Le Christ la donne en plénitude."}, "options": ["des livres cachés des apôtres", "des prophéties de Montanus", "des miracles des martyrs", "des parts de vérité"], "id": "eg.l13.e08", "pool": "lesson", "lessonId": "eg.l13", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l13.e09', 'eg', 'eg.l13', 'eg.g13.apologistes', array['eg.g13.apologistes','eg.v.tertullien']::text[], 'mcq', 'lesson', 'Où vit Tertullien ?', array['à Carthage']::text[], 'Carthage est en Afrique du Nord. Tertullien y écrit en latin, ce qui en fait le premier grand auteur chrétien latin.', 2, '{"unitIds": ["eg.g13.apologistes", "eg.v.tertullien"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Où vit Tertullien ?", "promptLanguage": "fr", "answer": "à Carthage", "acceptedAnswers": ["à Carthage"], "explanation": "Carthage est en Afrique du Nord. Tertullien y écrit en latin, ce qui en fait le premier grand auteur chrétien latin.", "tip": "Tertullien = Carthage.", "extraExample": {"text": "Carthage est dans l''actuelle Tunisie.", "translation": "Elle est proche de l''Égypte en Afrique du Nord."}, "options": ["à Carthage", "à Antioche", "à Lyon", "à Jérusalem"], "id": "eg.l13.e09", "pool": "lesson", "lessonId": "eg.l13", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l13.e10', 'eg', 'eg.l13', 'eg.g13.apologistes', array['eg.g13.apologistes','eg.v.sang_des_martyrs']::text[], 'mcq', 'lesson', 'Quelle phrase célèbre écrit Tertullien ?', array['le sang des martyrs est une semence de chrétiens']::text[], 'Plus on persécute, plus le courage des martyrs interroge et convainc : de nouveaux chrétiens naissent.', 2, '{"unitIds": ["eg.g13.apologistes", "eg.v.sang_des_martyrs"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle phrase célèbre écrit Tertullien ?", "promptLanguage": "fr", "answer": "le sang des martyrs est une semence de chrétiens", "acceptedAnswers": ["le sang des martyrs est une semence de chrétiens"], "explanation": "Plus on persécute, plus le courage des martyrs interroge et convainc : de nouveaux chrétiens naissent.", "tip": "Sang des martyrs = semence.", "extraExample": {"text": "Les persécutions n''ont pas détruit l''Église.", "translation": "Elles l''ont fait grandir."}, "options": ["la foi déplace les montagnes", "le sang des martyrs est une semence de chrétiens", "l''Église est une mère", "le Christ est le Verbe"], "id": "eg.l13.e10", "pool": "lesson", "lessonId": "eg.l13", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l13.e11', 'eg', 'eg.l13', 'eg.v.marc_aurele', array['eg.v.marc_aurele']::text[], 'mcq', 'lesson', 'Quel empereur ordonne la quatrième persécution, pendant la vie de Justin ?', array['Marc Aurèle']::text[], 'Rappel de la leçon précédente : Marc Aurèle (161-180) ; Justin est martyrisé à Rome vers 165.', 3, '{"unitIds": ["eg.v.marc_aurele"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quel empereur ordonne la quatrième persécution, pendant la vie de Justin ?", "promptLanguage": "fr", "answer": "Marc Aurèle", "acceptedAnswers": ["Marc Aurèle"], "explanation": "Rappel de la leçon précédente : Marc Aurèle (161-180) ; Justin est martyrisé à Rome vers 165.", "tip": "Marc Aurèle = 4e.", "extraExample": {"text": "Trajan est le troisième.", "translation": "Septime Sévère est le cinquième."}, "options": ["Trajan", "Septime Sévère", "Marc Aurèle", "Néron"], "id": "eg.l13.e11", "pool": "lesson", "lessonId": "eg.l13", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l13.e12', 'eg', 'eg.l13', 'eg.v.polycarpe_de_smyrne', array['eg.v.polycarpe_de_smyrne']::text[], 'mcq', 'lesson', 'Quel Père apostolique est lié à l''apôtre Jean ?', array['Polycarpe de Smyrne']::text[], 'Rappel de la leçon sur les Pères apostoliques : Polycarpe est disciple direct de Jean.', 3, '{"unitIds": ["eg.v.polycarpe_de_smyrne"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quel Père apostolique est lié à l''apôtre Jean ?", "promptLanguage": "fr", "answer": "Polycarpe de Smyrne", "acceptedAnswers": ["Polycarpe de Smyrne"], "explanation": "Rappel de la leçon sur les Pères apostoliques : Polycarpe est disciple direct de Jean.", "tip": "Polycarpe = Jean.", "extraExample": {"text": "Irénée est son disciple.", "translation": "La chaîne se prolonge."}, "options": ["Clément de Rome", "Ignace d''Antioche", "Justin Martyr", "Polycarpe de Smyrne"], "id": "eg.l13.e12", "pool": "lesson", "lessonId": "eg.l13", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l13.e13', 'eg', 'eg.l13', 'eg.g13.apologistes', array['eg.g13.apologistes','eg.v.paganisme']::text[], 'fill_blank', 'lesson', 'Les apologistes défendent la foi devant les ___.', array['païens']::text[], 'Ils parlent à ceux qui ne sont pas chrétiens.', 1, '{"unitIds": ["eg.g13.apologistes", "eg.v.paganisme"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Les apologistes défendent la foi devant les ___.", "promptLanguage": "fr", "answer": "païens", "acceptedAnswers": ["païens"], "explanation": "Ils parlent à ceux qui ne sont pas chrétiens.", "tip": "Apologistes = païens.", "extraExample": {"text": "Les Pères apostoliques parlent aux chrétiens.", "translation": "Les apologistes, aux païens."}, "options": ["évêques", "païens", "prophètes", "disciples"], "id": "eg.l13.e13", "pool": "lesson", "lessonId": "eg.l13", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l13.e14', 'eg', 'eg.l13', 'eg.g13.apologistes', array['eg.g13.apologistes','eg.v.apologetique']::text[], 'fill_blank', 'lesson', 'Tertullien écrit l''Apologétique en ___.', array['197']::text[], 'Une date à retenir : 197, la fin du IIe siècle.', 2, '{"unitIds": ["eg.g13.apologistes", "eg.v.apologetique"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Tertullien écrit l''Apologétique en ___.", "promptLanguage": "fr", "answer": "197", "acceptedAnswers": ["197"], "explanation": "Une date à retenir : 197, la fin du IIe siècle.", "tip": "197 = Apologétique.", "extraExample": {"text": "En 313, Constantin donne l''édit de Milan.", "translation": "Rien à voir avec 197."}, "options": ["155", "251", "197", "313"], "id": "eg.l13.e14", "pool": "lesson", "lessonId": "eg.l13", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
