insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l16.e17', 'eg', 'eg.l16', 'eg.g16.canon_regle_de_foi', array['eg.g16.canon_regle_de_foi','eg.v.epacte']::text[], 'fill_blank', 'lesson', 'Démétrios place le carême juste avant la semaine ___.', array['sainte']::text[], 'Le carême précède immédiatement la semaine sainte.', 2, '{"unitIds": ["eg.g16.canon_regle_de_foi", "eg.v.epacte"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Démétrios place le carême juste avant la semaine ___.", "promptLanguage": "fr", "answer": "sainte", "acceptedAnswers": ["sainte"], "explanation": "Le carême précède immédiatement la semaine sainte.", "tip": "Carême → semaine sainte.", "extraExample": {"text": "Il fixe aussi les règles des jeûnes.", "translation": "Il promeut l''épacte."}, "options": ["pascale", "sainte", "grande", "blanche"], "id": "eg.l16.e17", "pool": "lesson", "lessonId": "eg.l16", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
