insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l18.e03', 'eg', 'eg.l18', 'eg.g18.edits_de_maximin_a_valerien', array['eg.g18.edits_de_maximin_a_valerien','eg.v.maximin']::text[], 'mcq', 'lesson', 'Quel empereur ordonne la sixième persécution, vers 235 ?', array['Maximin']::text[], 'Maximin prend le pouvoir en 235 et s''en prend d''abord aux chefs de l''Église.', 1, '{"id": "eg.l18.e03", "unitIds": ["eg.g18.edits_de_maximin_a_valerien", "eg.v.maximin"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel empereur ordonne la sixième persécution, vers 235 ?", "promptLanguage": "fr", "answer": "Maximin", "acceptedAnswers": ["Maximin"], "explanation": "Maximin prend le pouvoir en 235 et s''en prend d''abord aux chefs de l''Église.", "tip": "Six = Maximin.", "extraExample": {"text": "Il vise les évêques et les prêtres.", "translation": "Il veut décapiter la communauté."}, "options": ["Maximin", "Dèce", "Valérien", "Dioclétien"], "errorPatterns": [{"equals": "Dèce", "category": "word_confusion", "feedback": "Dèce ordonne la septième, vers 249."}], "pool": "lesson", "lessonId": "eg.l18", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
