insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l19.e01', 'eg', 'eg.l19', 'eg.g19.diocletien_ere_des_martyrs', array['eg.g19.diocletien_ere_des_martyrs','eg.v.diocletien','eg.v.grande_persecution_303']::text[], 'match', 'lesson', 'Les dates de Dioclétien', '{}'::text[], '284 : début du règne de Dioclétien ; 303 : sommet de la persécution ; les autres dates sont celles des vagues précédentes.', 1, '{"id": "eg.l19.e01", "unitIds": ["eg.g19.diocletien_ere_des_martyrs", "eg.v.diocletien", "eg.v.grande_persecution_303"], "type": "match", "difficulty": 1, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Les dates de Dioclétien", "promptLanguage": "fr", "pairs": [{"left": "284", "right": "accession de Dioclétien et an 1 du calendrier copte"}, {"left": "303", "right": "grande persécution"}, {"left": "vers 274", "right": "neuvième persécution"}, {"left": "250", "right": "édit de Dèce"}], "answer": "284 = accession de Dioclétien et an 1 du calendrier copte ; 303 = grande persécution ; vers 274 = neuvième persécution ; 250 = édit de Dèce", "acceptedAnswers": [], "explanation": "284 : début du règne de Dioclétien ; 303 : sommet de la persécution ; les autres dates sont celles des vagues précédentes.", "tip": "284 = début, 303 = sommet.", "pool": "lesson", "lessonId": "eg.l19", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
