insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l21.e22', 'eg', 'eg.l21', 'eg.g20.premiers_ermites', array['eg.g20.premiers_ermites','eg.v.paul_de_thebes']::text[], 'free_answer', 'lesson', 'Révision : quel saint est le premier des ermites ?', array['Paul de Thèbes','saint Paul de Thèbes','Paul']::text[], 'Paul de Thèbes est le premier ermite. (Leçon 20.) Attention à ne pas le confondre avec Paul de Samosate.', 2, '{"id": "eg.l21.e22", "unitIds": ["eg.g20.premiers_ermites", "eg.v.paul_de_thebes"], "type": "free_answer", "difficulty": 2, "instruction": "Écris la réponse.", "prompt": "Révision : quel saint est le premier des ermites ?", "promptLanguage": "fr", "answer": "Paul de Thèbes", "acceptedAnswers": ["Paul de Thèbes", "saint Paul de Thèbes", "Paul"], "explanation": "Paul de Thèbes est le premier ermite. (Leçon 20.) Attention à ne pas le confondre avec Paul de Samosate.", "tip": "Thèbes = désert ; Samosate = hérésie.", "extraExample": {"text": "Antoine est le père des moines.", "translation": "Paul de Samosate est un évêque hérétique."}, "pool": "lesson", "lessonId": "eg.l21", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l22.e01', 'eg', 'eg.l22', 'eg.g22.novatien_et_mani', array['eg.g22.novatien_et_mani','eg.v.novatien','eg.v.cyprien','eg.v.mani','eg.v.augustin']::text[], 'match', 'lesson', 'Quatre noms, quatre rôles', '{}'::text[], 'Novatien et Cyprien se répondent sur les tombés ; Mani et Augustin sont liés par le manichéisme.', 1, '{"id": "eg.l22.e01", "unitIds": ["eg.g22.novatien_et_mani", "eg.v.novatien", "eg.v.cyprien", "eg.v.mani", "eg.v.augustin"], "type": "match", "difficulty": 1, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Quatre noms, quatre rôles", "promptLanguage": "fr", "pairs": [{"left": "Novatien", "right": "théologien romain"}, {"left": "Cyprien", "right": "évêque de Carthage"}, {"left": "Mani", "right": "Perse, fondateur du manichéisme"}, {"left": "Augustin", "right": "ancien manichéen devenu chrétien"}], "answer": "Novatien = théologien romain ; Cyprien = évêque de Carthage ; Mani = Perse, fondateur du manichéisme ; Augustin = ancien manichéen devenu chrétien", "acceptedAnswers": [], "explanation": "Novatien et Cyprien se répondent sur les tombés ; Mani et Augustin sont liés par le manichéisme.", "tip": "Novatien/Cyprien : pardon. Mani/Augustin : manichéisme.", "pool": "lesson", "lessonId": "eg.l22", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l22.e02', 'eg', 'eg.l22', 'eg.g22.novatien_et_mani', array['eg.g22.novatien_et_mani','eg.v.penitence','eg.v.tombes','eg.v.manicheisme','eg.v.novatianisme']::text[], 'match', 'lesson', 'Notions du débat sur les tombés', '{}'::text[], 'Quatre notions : le problème, la solution de l''Église, l''erreur de Novatien et celle de Mani.', 2, '{"id": "eg.l22.e02", "unitIds": ["eg.g22.novatien_et_mani", "eg.v.penitence", "eg.v.tombes", "eg.v.manicheisme", "eg.v.novatianisme"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Notions du débat sur les tombés", "promptLanguage": "fr", "pairs": [{"left": "Les tombés", "right": "les chrétiens qui ont renié la foi"}, {"left": "La pénitence", "right": "chemin de repentir pour revenir à l''Église"}, {"left": "Le novatianisme", "right": "l''Église doit être préservée dans sa pureté"}, {"left": "Le manichéisme", "right": "un Dieu bon et un démiurge mauvais"}], "answer": "Les tombés = les chrétiens qui ont renié la foi ; La pénitence = chemin de repentir pour revenir à l''Église ; Le novatianisme = l''Église doit être préservée dans sa pureté ; Le manichéisme = un Dieu bon et un démiurge mauvais", "acceptedAnswers": [], "explanation": "Quatre notions : le problème, la solution de l''Église, l''erreur de Novatien et celle de Mani.", "tip": "Problème → pénitence → erreur de Novatien.", "pool": "lesson", "lessonId": "eg.l22", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l22.e03', 'eg', 'eg.l22', 'eg.g22.novatien_et_mani', array['eg.g22.novatien_et_mani','eg.v.novatien']::text[], 'mcq', 'lesson', 'Qui est Novatien ?', array['Un théologien romain']::text[], 'Novatien est un théologien romain, consacré évêque de Rome en 251.', 1, '{"id": "eg.l22.e03", "unitIds": ["eg.g22.novatien_et_mani", "eg.v.novatien"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Qui est Novatien ?", "promptLanguage": "fr", "answer": "Un théologien romain", "acceptedAnswers": ["Un théologien romain"], "explanation": "Novatien est un théologien romain, consacré évêque de Rome en 251.", "tip": "Novatien = Rome.", "extraExample": {"text": "Il n''est pas un persécuteur.", "translation": "Il est chrétien."}, "options": ["Un théologien romain", "Un empereur persécuteur", "Un évêque d''Alexandrie", "Un moine du désert"], "pool": "lesson", "lessonId": "eg.l22", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l22.e04', 'eg', 'eg.l22', 'eg.g22.novatien_et_mani', array['eg.g22.novatien_et_mani','eg.v.tombes']::text[], 'mcq', 'lesson', 'Qui sont les « tombés » ?', array['Les chrétiens qui ont renié la foi']::text[], 'Les tombés ont cédé sous la persécution, par exemple en sacrifiant.', 1, '{"id": "eg.l22.e04", "unitIds": ["eg.g22.novatien_et_mani", "eg.v.tombes"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Qui sont les « tombés » ?", "promptLanguage": "fr", "answer": "Les chrétiens qui ont renié la foi", "acceptedAnswers": ["Les chrétiens qui ont renié la foi"], "explanation": "Les tombés ont cédé sous la persécution, par exemple en sacrifiant.", "tip": "Tombé = a renié la foi.", "extraExample": {"text": "Certains avaient un faux libellus.", "translation": "Ils veulent revenir."}, "options": ["Les martyrs morts", "Les évêques exilés", "Les ermites du désert", "Les chrétiens qui ont renié la foi"], "pool": "lesson", "lessonId": "eg.l22", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l22.e05', 'eg', 'eg.l22', 'eg.g22.novatien_et_mani', array['eg.g22.novatien_et_mani','eg.v.novatien']::text[], 'mcq', 'lesson', 'En quelle année Novatien est-il consacré évêque de Rome ?', array['251']::text[], 'Novatien est consacré évêque de Rome en 251 et excommunié la même année.', 2, '{"id": "eg.l22.e05", "unitIds": ["eg.g22.novatien_et_mani", "eg.v.novatien"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "En quelle année Novatien est-il consacré évêque de Rome ?", "promptLanguage": "fr", "answer": "251", "acceptedAnswers": ["251"], "explanation": "Novatien est consacré évêque de Rome en 251 et excommunié la même année.", "tip": "251 = Novatien.", "extraExample": {"text": "Rappel : 269 est Paul de Samosate.", "translation": "303 est la grande persécution."}, "options": ["269", "303", "251", "235"], "errorPatterns": [{"equals": "269", "category": "word_confusion", "feedback": "269 est la condamnation de Paul de Samosate."}], "pool": "lesson", "lessonId": "eg.l22", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l22.e06', 'eg', 'eg.l22', 'eg.g22.novatien_et_mani', array['eg.g22.novatien_et_mani','eg.v.novatianisme']::text[], 'mcq', 'lesson', 'Que veut Novatien pour l''Église ?', array['L''Église doit être préservée dans sa pureté']::text[], 'Il refuse le retour des tombés pour ne pas souiller l''Église.', 2, '{"id": "eg.l22.e06", "unitIds": ["eg.g22.novatien_et_mani", "eg.v.novatianisme"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que veut Novatien pour l''Église ?", "promptLanguage": "fr", "answer": "L''Église doit être préservée dans sa pureté", "acceptedAnswers": ["L''Église doit être préservée dans sa pureté"], "explanation": "Il refuse le retour des tombés pour ne pas souiller l''Église.", "tip": "Novatien = pureté sans pardon.", "extraExample": {"text": "Cela revient à fermer la porte.", "translation": "L''Église ne le suit pas."}, "options": ["L''empereur doit gouverner l''Église", "L''Église doit être préservée dans sa pureté", "Tout le monde doit être pardonné", "Les évêques doivent se marier"], "pool": "lesson", "lessonId": "eg.l22", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l22.e07', 'eg', 'eg.l22', 'eg.g22.novatien_et_mani', array['eg.g22.novatien_et_mani','eg.v.penitence']::text[], 'mcq', 'lesson', 'Que répond l''Église aux tombés qui se repentent ?', array['Recevoir les vrais pénitents']::text[], 'L''Église reçoit dans son giron ceux qui se repentent sincèrement.', 2, '{"id": "eg.l22.e07", "unitIds": ["eg.g22.novatien_et_mani", "eg.v.penitence"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que répond l''Église aux tombés qui se repentent ?", "promptLanguage": "fr", "answer": "Recevoir les vrais pénitents", "acceptedAnswers": ["Recevoir les vrais pénitents"], "explanation": "L''Église reçoit dans son giron ceux qui se repentent sincèrement.", "tip": "Pénitence = chemin de retour.", "extraExample": {"text": "Le Christ cherche les pécheurs.", "translation": "Le pardon est possible."}, "options": ["Recevoir les vrais pénitents", "Les exiler pour toujours", "Les remplacer par d''autres", "Les déclarer martyrs"], "pool": "lesson", "lessonId": "eg.l22", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
