insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l22.e09', 'eg', 'eg.l22', 'eg.g22.novatien_et_mani', array['eg.g22.novatien_et_mani','eg.v.mani']::text[], 'mcq', 'lesson', 'De quelle origine est Mani ?', array['Perse']::text[], 'Mani est un Perse, fondateur du manichéisme.', 1, '{"id": "eg.l22.e09", "unitIds": ["eg.g22.novatien_et_mani", "eg.v.mani"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "De quelle origine est Mani ?", "promptLanguage": "fr", "answer": "Perse", "acceptedAnswers": ["Perse"], "explanation": "Mani est un Perse, fondateur du manichéisme.", "tip": "Mani = Perse.", "extraExample": {"text": "Le manichéisme se veut une variante du mazdéisme.", "translation": "C''est la religion des Perses."}, "options": ["Égyptienne", "Grecque", "Perse", "Romaine"], "pool": "lesson", "lessonId": "eg.l22", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l22.e10', 'eg', 'eg.l22', 'eg.g22.novatien_et_mani', array['eg.g22.novatien_et_mani','eg.v.manicheisme']::text[], 'mcq', 'lesson', 'Quels sont les deux principes du manichéisme ?', array['Un Dieu bon et un démiurge mauvais']::text[], 'Dieu bon : esprits. Démiurge mauvais : matière et corps.', 2, '{"id": "eg.l22.e10", "unitIds": ["eg.g22.novatien_et_mani", "eg.v.manicheisme"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quels sont les deux principes du manichéisme ?", "promptLanguage": "fr", "answer": "Un Dieu bon et un démiurge mauvais", "acceptedAnswers": ["Un Dieu bon et un démiurge mauvais"], "explanation": "Dieu bon : esprits. Démiurge mauvais : matière et corps.", "tip": "Deux principes : bon et mauvais.", "extraExample": {"text": "Le corps est donc mauvais.", "translation": "Cela contredit l''Incarnation."}, "options": ["Le ciel et la mer", "Un Dieu bon et un démiurge mauvais", "Le Père et le Fils", "L''Ancien et le Nouveau Testament"], "pool": "lesson", "lessonId": "eg.l22", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l22.e11', 'eg', 'eg.l22', 'eg.g22.novatien_et_mani', array['eg.g22.novatien_et_mani','eg.v.manicheisme']::text[], 'mcq', 'lesson', 'Que pense Mani des religions ?', array['Toutes les religions sont valides']::text[], 'Il cite comme prophètes Adam, Noé, Abraham, Zoroastre, Bouddha, Jésus, Paul et Mani.', 3, '{"id": "eg.l22.e11", "unitIds": ["eg.g22.novatien_et_mani", "eg.v.manicheisme"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Que pense Mani des religions ?", "promptLanguage": "fr", "answer": "Toutes les religions sont valides", "acceptedAnswers": ["Toutes les religions sont valides"], "explanation": "Il cite comme prophètes Adam, Noé, Abraham, Zoroastre, Bouddha, Jésus, Paul et Mani.", "tip": "Mani = toutes valides.", "extraExample": {"text": "L''Église croit au Christ unique Sauveur.", "translation": "La différence est nette."}, "options": ["Toutes les religions sont valides", "Seul le christianisme est vrai", "Seul le mazdéisme est vrai", "Aucune n''est vraie"], "pool": "lesson", "lessonId": "eg.l22", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
