insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l24.e01', 'eg', 'eg.l24', 'eg.g24.structure_de_l_eglise', array['eg.g24.structure_de_l_eglise','eg.v.diacre','eg.v.pretre']::text[], 'match', 'lesson', 'Trois mots grecs, trois services', '{}'::text[], 'Épiscope, diacre, presbytre : les trois mots grecs du début deviennent les trois degrés.', 1, '{"id": "eg.l24.e01", "unitIds": ["eg.g24.structure_de_l_eglise", "eg.v.diacre", "eg.v.pretre"], "type": "match", "difficulty": 1, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Trois mots grecs, trois services", "promptLanguage": "fr", "pairs": [{"left": "Les surveillants", "right": "les évêques"}, {"left": "Les serviteurs", "right": "les diacres"}, {"left": "Les anciens", "right": "les prêtres"}, {"left": "Les confesseurs", "right": "chrétiens qui ont souffert pour leur foi sans mourir"}], "answer": "Les surveillants = les évêques ; Les serviteurs = les diacres ; Les anciens = les prêtres ; Les confesseurs = chrétiens qui ont souffert pour leur foi sans mourir", "acceptedAnswers": [], "explanation": "Épiscope, diacre, presbytre : les trois mots grecs du début deviennent les trois degrés.", "tip": "Surveillant, serviteur, ancien.", "pool": "lesson", "lessonId": "eg.l24", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
