insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l24.e07', 'eg', 'eg.l24', 'eg.g24.structure_de_l_eglise', array['eg.g24.structure_de_l_eglise','eg.v.confesseur']::text[], 'mcq', 'lesson', 'Qu''est-ce qu''un confesseur ? Quelqu''un qui...', array['a souffert pour sa foi sans mourir martyr']::text[], 'Le titre est donné à ceux qui ont survécu aux persécutions.', 2, '{"id": "eg.l24.e07", "unitIds": ["eg.g24.structure_de_l_eglise", "eg.v.confesseur"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qu''est-ce qu''un confesseur ? Quelqu''un qui...", "promptLanguage": "fr", "answer": "a souffert pour sa foi sans mourir martyr", "acceptedAnswers": ["a souffert pour sa foi sans mourir martyr"], "explanation": "Le titre est donné à ceux qui ont survécu aux persécutions.", "tip": "Confesseur = survivant de la persécution.", "extraExample": {"text": "Le martyr, lui, meurt.", "translation": "Les deux sont honorés."}, "options": ["a souffert pour sa foi sans mourir martyr", "entend la confession des fidèles", "a fui au désert", "a été exilé par un concile"], "pool": "lesson", "lessonId": "eg.l24", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l24.e08', 'eg', 'eg.l24', 'eg.g24.structure_de_l_eglise', array['eg.g24.structure_de_l_eglise','eg.v.confesseur']::text[], 'mcq', 'lesson', 'Que peut faire un confesseur sans être ordonné prêtre ?', array['diriger les offices']::text[], 'Il reçoit souvent la charge de diriger les offices, mais doit être ordonné pour devenir évêque.', 3, '{"id": "eg.l24.e08", "unitIds": ["eg.g24.structure_de_l_eglise", "eg.v.confesseur"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Que peut faire un confesseur sans être ordonné prêtre ?", "promptLanguage": "fr", "answer": "diriger les offices", "acceptedAnswers": ["diriger les offices"], "explanation": "Il reçoit souvent la charge de diriger les offices, mais doit être ordonné pour devenir évêque.", "tip": "Confesseur = honneur, pas ordination automatique.", "extraExample": {"text": "Pour devenir évêque, il doit être ordonné.", "translation": "La Tradition apostolique d''Hippolyte le précise."}, "options": ["ordonner d''autres prêtres", "devenir évêque d''office", "gouverner l''empire", "diriger les offices"], "pool": "lesson", "lessonId": "eg.l24", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l24.e09', 'eg', 'eg.l24', 'eg.g24.structure_de_l_eglise', array['eg.g24.structure_de_l_eglise','eg.v.prophetes_des_premiers_temps']::text[], 'mcq', 'lesson', 'Que sont devenus les prophètes des premiers temps ?', array['Ils ont disparu avec la fin des temps apostoliques']::text[], 'Leur rôle disparaît quand les évangiles sont rédigés.', 3, '{"id": "eg.l24.e09", "unitIds": ["eg.g24.structure_de_l_eglise", "eg.v.prophetes_des_premiers_temps"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Que sont devenus les prophètes des premiers temps ?", "promptLanguage": "fr", "answer": "Ils ont disparu avec la fin des temps apostoliques", "acceptedAnswers": ["Ils ont disparu avec la fin des temps apostoliques"], "explanation": "Leur rôle disparaît quand les évangiles sont rédigés.", "tip": "Prophètes = temps apostoliques.", "extraExample": {"text": "Ils sont cités dans les Actes.", "translation": "Ils avaient un rôle de parole."}, "options": ["Ils ont été martyrisés par Dèce", "Ils ont fondé les monastères", "Ils ont disparu avec la fin des temps apostoliques", "Ils sont devenus évêques"], "pool": "lesson", "lessonId": "eg.l24", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l24.e10', 'eg', 'eg.l24', 'eg.g24.structure_de_l_eglise', array['eg.g24.structure_de_l_eglise','eg.v.heraclas']::text[], 'mcq', 'lesson', 'Qui est le premier évêque d''Alexandrie appelé pape ?', array['Héraclas']::text[], 'Depuis Héraclas, le 13e évêque, l''évêque d''Alexandrie porte le titre de pape.', 2, '{"id": "eg.l24.e10", "unitIds": ["eg.g24.structure_de_l_eglise", "eg.v.heraclas"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui est le premier évêque d''Alexandrie appelé pape ?", "promptLanguage": "fr", "answer": "Héraclas", "acceptedAnswers": ["Héraclas"], "explanation": "Depuis Héraclas, le 13e évêque, l''évêque d''Alexandrie porte le titre de pape.", "tip": "Pape = Héraclas.", "extraExample": {"text": "Denys est le 14e.", "translation": "Marc fonde l''Église d''Alexandrie."}, "options": ["Cyprien", "Héraclas", "Denys", "Marc"], "pool": "lesson", "lessonId": "eg.l24", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l24.e11', 'eg', 'eg.l24', 'eg.g24.structure_de_l_eglise', array['eg.g24.structure_de_l_eglise','eg.v.patriarche_a_partir_de_451']::text[], 'mcq', 'lesson', 'À partir de quelle année utilise-t-on le titre de patriarche ?', array['451']::text[], 'Le titre de patriarche n''apparaît qu''à partir de 451.', 3, '{"id": "eg.l24.e11", "unitIds": ["eg.g24.structure_de_l_eglise", "eg.v.patriarche_a_partir_de_451"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "À partir de quelle année utilise-t-on le titre de patriarche ?", "promptLanguage": "fr", "answer": "451", "acceptedAnswers": ["451"], "explanation": "Le titre de patriarche n''apparaît qu''à partir de 451.", "tip": "Patriarche = 451.", "extraExample": {"text": "Pape est plus ancien.", "translation": "Il date d''Héraclas."}, "options": ["451", "250", "325", "284"], "errorPatterns": [{"equals": "325", "category": "word_confusion", "feedback": "325 est la date du concile de Nicée, pas celle du titre de patriarche."}], "pool": "lesson", "lessonId": "eg.l24", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
