insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l24.e21', 'eg', 'eg.l24', 'eg.g21.erreurs_sur_la_trinite', array['eg.g21.erreurs_sur_la_trinite','eg.v.denys_d_alexandrie']::text[], 'free_answer', 'lesson', 'Révision : quel patriarche d''Alexandrie (le 14e) écrit au concile d''Antioche ? (un prénom)', array['Denys','pape Denys','Denys d''Alexandrie']::text[], 'Denys, 14e patriarche d''Alexandrie, écrit au concile d''Antioche. (Leçon 21.)', 2, '{"id": "eg.l24.e21", "unitIds": ["eg.g21.erreurs_sur_la_trinite", "eg.v.denys_d_alexandrie"], "type": "free_answer", "difficulty": 2, "instruction": "Écris la réponse.", "prompt": "Révision : quel patriarche d''Alexandrie (le 14e) écrit au concile d''Antioche ? (un prénom)", "promptLanguage": "fr", "answer": "Denys", "acceptedAnswers": ["Denys", "pape Denys", "Denys d''Alexandrie"], "explanation": "Denys, 14e patriarche d''Alexandrie, écrit au concile d''Antioche. (Leçon 21.)", "tip": "Denys = 14e.", "extraExample": {"text": "Il combat Sabellius et Novatien.", "translation": "Il est trop âgé pour voyager."}, "pool": "lesson", "lessonId": "eg.l24", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l25.e01', 'eg', 'eg.l25', 'eg.g25.grande_persecution', array['eg.g25.grande_persecution','eg.v.diocletien','eg.v.galere','eg.v.pierre_sceau_des_martyrs']::text[], 'match', 'lesson', 'Qui est qui dans la grande persécution ?', '{}'::text[], 'Dioclétien lance la persécution, Galère la poursuit, Pierre la clôt par son martyre, et Eusèbe la raconte.', 1, '{"unitIds": ["eg.g25.grande_persecution", "eg.v.diocletien", "eg.v.galere", "eg.v.pierre_sceau_des_martyrs"], "type": "match", "difficulty": 1, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Qui est qui dans la grande persécution ?", "promptLanguage": "fr", "pairs": [{"left": "Dioclétien", "right": "l''empereur qui publie les quatre édits en 303"}, {"left": "Galère", "right": "son second, qui lui succède en 305"}, {"left": "Pierre d''Alexandrie", "right": "le pape « sceau des martyrs »"}, {"left": "Eusèbe de Césarée", "right": "l''historien qui décrit les martyrs d''Égypte"}], "answer": "Dioclétien = l''empereur qui publie les quatre édits en 303 ; Galère = son second, qui lui succède en 305 ; Pierre d''Alexandrie = le pape « sceau des martyrs » ; Eusèbe de Césarée = l''historien qui décrit les martyrs d''Égypte", "acceptedAnswers": [], "explanation": "Dioclétien lance la persécution, Galère la poursuit, Pierre la clôt par son martyre, et Eusèbe la raconte.", "tip": "Le trio : Dioclétien commence, Galère aggrave, Pierre clôt.", "extraExample": {"text": "Le calendrier copte compte les années à partir de 284, début du règne de Dioclétien.", "translation": "Chaque année copte rappelle les martyrs : c''est l''« ère des martyrs »."}, "id": "eg.l25.e01", "pool": "lesson", "lessonId": "eg.l25", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l25.e02', 'eg', 'eg.l25', 'eg.g25.grande_persecution', array['eg.g25.grande_persecution','eg.v.diocletien','eg.v.quatre_edits']::text[], 'mcq', 'lesson', 'Quel empereur publie en 303 les quatre édits contre les chrétiens ?', array['Dioclétien']::text[], 'C''est Dioclétien qui, en 303, publie quatre édits pour éradiquer le christianisme. Néron et Dèce sont d''autres persécuteurs, plus anciens.', 1, '{"unitIds": ["eg.g25.grande_persecution", "eg.v.diocletien", "eg.v.quatre_edits"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel empereur publie en 303 les quatre édits contre les chrétiens ?", "promptLanguage": "fr", "options": ["Dioclétien", "Constantin", "Néron", "Dèce"], "answer": "Dioclétien", "acceptedAnswers": ["Dioclétien"], "explanation": "C''est Dioclétien qui, en 303, publie quatre édits pour éradiquer le christianisme. Néron et Dèce sont d''autres persécuteurs, plus anciens.", "tip": "303 = quatre édits = Dioclétien.", "extraExample": {"text": "Eusèbe de Césarée a décrit de ses yeux les martyrs d''Égypte.", "translation": "Son récit est un témoignage d''époque, pas une légende tardive."}, "errorPatterns": [{"equals": "Constantin", "category": "word_confusion", "feedback": "Constantin sera au contraire l''empereur de la paix, à partir de 313."}, {"equals": "Néron", "category": "word_confusion", "feedback": "Néron lance la toute première persécution, en 64."}, {"equals": "Dèce", "category": "word_confusion", "feedback": "Dèce lance la première persécution générale, vers 250."}], "id": "eg.l25.e02", "pool": "lesson", "lessonId": "eg.l25", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l25.e03', 'eg', 'eg.l25', 'eg.g25.grande_persecution', array['eg.g25.grande_persecution','eg.v.grande_persecution_303']::text[], 'mcq', 'lesson', 'Quelles sont les dates de la grande persécution ?', array['de 303 à 311']::text[], 'La grande persécution commence avec les édits de 303 et s''arrête avec l''édit de tolérance de Galère en 311.', 1, '{"unitIds": ["eg.g25.grande_persecution", "eg.v.grande_persecution_303"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quelles sont les dates de la grande persécution ?", "promptLanguage": "fr", "options": ["de 303 à 311", "de 250 à 260", "de 313 à 325", "de 284 à 303"], "answer": "de 303 à 311", "acceptedAnswers": ["de 303 à 311"], "explanation": "La grande persécution commence avec les édits de 303 et s''arrête avec l''édit de tolérance de Galère en 311.", "tip": "Édits en 303, tolérance en 311.", "extraExample": {"text": "Galère, malade, signe l''édit de 311 peu avant sa mort.", "translation": "La violence n''a pas éteint la foi : même le persécuteur finit par le reconnaître."}, "errorPatterns": [{"equals": "de 313 à 325", "category": "word_confusion", "feedback": "313 est l''édit de Milan et 325 le concile de Nicée : c''est la paix, pas la persécution."}, {"equals": "de 250 à 260", "category": "word_confusion", "feedback": "C''est l''époque de Dèce et de Valérien, plus tôt dans le IIIe siècle."}], "id": "eg.l25.e03", "pool": "lesson", "lessonId": "eg.l25", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l25.e04', 'eg', 'eg.l25', 'eg.g25.grande_persecution', array['eg.g25.grande_persecution','eg.v.diocletien']::text[], 'mcq', 'lesson', 'Quelles régions Dioclétien se réserve-t-il en divisant l''empire ?', array['L''Égypte et l''Orient']::text[], 'Dioclétien garde pour lui l''Égypte et l''Orient. C''est pourquoi l''Église d''Alexandrie le sent de très près.', 1, '{"unitIds": ["eg.g25.grande_persecution", "eg.v.diocletien"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quelles régions Dioclétien se réserve-t-il en divisant l''empire ?", "promptLanguage": "fr", "options": ["L''Égypte et l''Orient", "La Gaule et la Bretagne", "L''Italie et l''Afrique du Nord", "La Grèce et l''Espagne"], "answer": "L''Égypte et l''Orient", "acceptedAnswers": ["L''Égypte et l''Orient"], "explanation": "Dioclétien garde pour lui l''Égypte et l''Orient. C''est pourquoi l''Église d''Alexandrie le sent de très près.", "tip": "Dioclétien = Égypte et Orient : c''est chez nous.", "extraExample": {"text": "Le calendrier copte compte les années à partir de 284, début du règne de Dioclétien.", "translation": "Chaque année copte rappelle les martyrs : c''est l''« ère des martyrs »."}, "id": "eg.l25.e04", "pool": "lesson", "lessonId": "eg.l25", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l25.e05', 'eg', 'eg.l25', 'eg.g25.grande_persecution', array['eg.g25.grande_persecution','eg.v.galere']::text[], 'mcq', 'lesson', 'Qui Dioclétien choisit-il comme second ?', array['Galère']::text[], 'Dioclétien associe Galère au pouvoir, avec le titre d''Auguste. Galère lui succède en 305 et se montre encore plus cruel.', 2, '{"unitIds": ["eg.g25.grande_persecution", "eg.v.galere"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui Dioclétien choisit-il comme second ?", "promptLanguage": "fr", "options": ["Galère", "Constantin", "Licinius", "Maxence"], "answer": "Galère", "acceptedAnswers": ["Galère"], "explanation": "Dioclétien associe Galère au pouvoir, avec le titre d''Auguste. Galère lui succède en 305 et se montre encore plus cruel.", "tip": "Galère = second, puis successeur.", "extraExample": {"text": "Eusèbe de Césarée a décrit de ses yeux les martyrs d''Égypte.", "translation": "Son récit est un témoignage d''époque, pas une légende tardive."}, "errorPatterns": [{"equals": "Constantin", "category": "word_confusion", "feedback": "Constantin devient empereur en 306, à l''autre bout de l''empire."}], "id": "eg.l25.e05", "pool": "lesson", "lessonId": "eg.l25", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l25.e06', 'eg', 'eg.l25', 'eg.g25.grande_persecution', array['eg.g25.grande_persecution','eg.v.quatre_edits']::text[], 'fill_blank', 'lesson', 'En ___, Dioclétien publie quatre édits pour éradiquer le christianisme.', array['303']::text[], 'Les quatre édits datent de 303 : ils marquent le début de la grande persécution.', 2, '{"unitIds": ["eg.g25.grande_persecution", "eg.v.quatre_edits"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "En ___, Dioclétien publie quatre édits pour éradiquer le christianisme.", "promptLanguage": "fr", "options": ["303", "284", "313", "325"], "answer": "303", "acceptedAnswers": ["303"], "explanation": "Les quatre édits datent de 303 : ils marquent le début de la grande persécution.", "tip": "303 = trois, zéro, trois : le début de la grande épreuve.", "extraExample": {"text": "Galère, malade, signe l''édit de 311 peu avant sa mort.", "translation": "La violence n''a pas éteint la foi : même le persécuteur finit par le reconnaître."}, "errorPatterns": [{"equals": "284", "category": "word_confusion", "feedback": "284 est l''année où Dioclétien devient empereur."}, {"equals": "313", "category": "word_confusion", "feedback": "313 est l''édit de Milan, qui ouvre la paix."}], "id": "eg.l25.e06", "pool": "lesson", "lessonId": "eg.l25", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = exclu