insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l25.e07', 'eg', 'eg.l25', 'eg.g25.grande_persecution', array['eg.g25.grande_persecution','eg.v.quatre_edits']::text[], 'mcq', 'lesson', 'Que prévoit le premier édit de 303 ?', array['Les églises sont rasées et les livres saints brûlés']::text[], 'Le premier édit s''attaque aux lieux et aux livres : les églises sont rasées, les livres saints brûlés. Les chefs de l''Église ne sont visés qu''aux édits suivants.', 2, '{"unitIds": ["eg.g25.grande_persecution", "eg.v.quatre_edits"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que prévoit le premier édit de 303 ?", "promptLanguage": "fr", "options": ["Les églises sont rasées et les livres saints brûlés", "Les chefs de l''Église seront exilés à vie", "Tous les chrétiens seront baptisés de force", "L''Église aura des biens en plus"], "answer": "Les églises sont rasées et les livres saints brûlés", "acceptedAnswers": ["Les églises sont rasées et les livres saints brûlés"], "explanation": "Le premier édit s''attaque aux lieux et aux livres : les églises sont rasées, les livres saints brûlés. Les chefs de l''Église ne sont visés qu''aux édits suivants.", "tip": "Premier édit : on détruit les églises et les livres.", "extraExample": {"text": "Le calendrier copte compte les années à partir de 284, début du règne de Dioclétien.", "translation": "Chaque année copte rappelle les martyrs : c''est l''« ère des martyrs »."}, "id": "eg.l25.e07", "pool": "lesson", "lessonId": "eg.l25", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l25.e08', 'eg', 'eg.l25', 'eg.g25.grande_persecution', array['eg.g25.grande_persecution','eg.v.quatre_edits']::text[], 'mcq', 'lesson', 'Qui est visé par les deuxième et troisième édits ?', array['Les chefs de l''Église']::text[], 'Le deuxième édit jette les chefs de l''Église en prison, le troisième les torture s''ils refusent de sacrifier aux dieux. Le quatrième étend ces mesures à tous les chrétiens.', 2, '{"unitIds": ["eg.g25.grande_persecution", "eg.v.quatre_edits"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui est visé par les deuxième et troisième édits ?", "promptLanguage": "fr", "options": ["Les chefs de l''Église", "Les seuls esclaves", "Les soldats", "Les marchands"], "answer": "Les chefs de l''Église", "acceptedAnswers": ["Les chefs de l''Église"], "explanation": "Le deuxième édit jette les chefs de l''Église en prison, le troisième les torture s''ils refusent de sacrifier aux dieux. Le quatrième étend ces mesures à tous les chrétiens.", "tip": "Deux et trois : les chefs. Quatre : tout le monde.", "extraExample": {"text": "Eusèbe de Césarée a décrit de ses yeux les martyrs d''Égypte.", "translation": "Son récit est un témoignage d''époque, pas une légende tardive."}, "id": "eg.l25.e08", "pool": "lesson", "lessonId": "eg.l25", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.depre