insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l25.e09', 'eg', 'eg.l25', 'eg.g25.grande_persecution', array['eg.g25.grande_persecution','eg.v.galere']::text[], 'fill_blank', 'lesson', 'Galère invente régulièrement de nouvelles ___.', array['tortures','des tortures']::text[], 'La cruauté de Galère dépasse celle de ses prédécesseurs : il invente sans cesse de nouvelles tortures.', 2, '{"unitIds": ["eg.g25.grande_persecution", "eg.v.galere"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Galère invente régulièrement de nouvelles ___.", "promptLanguage": "fr", "options": ["tortures", "lois", "églises", "provinces"], "answer": "tortures", "acceptedAnswers": ["tortures", "des tortures"], "explanation": "La cruauté de Galère dépasse celle de ses prédécesseurs : il invente sans cesse de nouvelles tortures.", "tip": "Galère = tortures inventées.", "extraExample": {"text": "Galère, malade, signe l''édit de 311 peu avant sa mort.", "translation": "La violence n''a pas éteint la foi : même le persécuteur finit par le reconnaître."}, "id": "eg.l25.e09", "pool": "lesson", "lessonId": "eg.l25", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l25.e10', 'eg', 'eg.l25', 'eg.g25.grande_persecution', array['eg.g25.grande_persecution','eg.v.pierre_sceau_des_martyrs']::text[], 'mcq', 'lesson', 'Quel pape d''Alexandrie, martyrisé en 311, est appelé « le sceau des martyrs » ?', array['Pierre']::text[], 'Le pape Pierre meurt martyr en 311, à la fin de la grande persécution : on l''appelle le sceau des martyrs parce qu''il clôt cette liste.', 2, '{"unitIds": ["eg.g25.grande_persecution", "eg.v.pierre_sceau_des_martyrs"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel pape d''Alexandrie, martyrisé en 311, est appelé « le sceau des martyrs » ?", "promptLanguage": "fr", "options": ["Pierre", "Alexandre", "Athanase", "Marc"], "answer": "Pierre", "acceptedAnswers": ["Pierre"], "explanation": "Le pape Pierre meurt martyr en 311, à la fin de la grande persécution : on l''appelle le sceau des martyrs parce qu''il clôt cette liste.", "tip": "Un sceau ferme une lettre : Pierre ferme la liste des martyrs.", "extraExample": {"text": "Le calendrier copte compte les années à partir de 284, début du règne de Dioclétien.", "translation": "Chaque année copte rappelle les martyrs : c''est l''« ère des martyrs »."}, "errorPatterns": [{"equals": "Alexandre", "category": "word_confusion", "feedback": "Alexandre sera pape après lui et affrontera Arius."}, {"equals": "Marc", "category": "word_confusion", "feedback": "Marc est le fondateur de l''Église d''Alexandrie, au Ier siècle."}], "id": "eg.l25.e10", "pool": "lesson", "lessonId": "eg.l25", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, 