insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l25.e11', 'eg', 'eg.l25', 'eg.g25.grande_persecution', array['eg.g25.grande_persecution','eg.v.saint_mina']::text[], 'mcq', 'lesson', 'En quelle année saint Mina est-il martyrisé ?', array['Vers 309']::text[], 'Saint Mina meurt vers 309. Georges (303), Catherine (305), Barbara (306) et le pape Pierre (311) sont les autres noms que la tradition retient.', 3, '{"unitIds": ["eg.g25.grande_persecution", "eg.v.saint_mina"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "En quelle année saint Mina est-il martyrisé ?", "promptLanguage": "fr", "options": ["Vers 309", "Vers 303", "Vers 305", "Vers 311"], "answer": "Vers 309", "acceptedAnswers": ["Vers 309"], "explanation": "Saint Mina meurt vers 309. Georges (303), Catherine (305), Barbara (306) et le pape Pierre (311) sont les autres noms que la tradition retient.", "tip": "Georges ouvre (303), Mina arrive vers la fin (309).", "extraExample": {"text": "Eusèbe de Césarée a décrit de ses yeux les martyrs d''Égypte.", "translation": "Son récit est un témoignage d''époque, pas une légende tardive."}, "errorPatterns": [{"equals": "Vers 303", "category": "word_confusion", "feedback": "303, c''est Georges."}, {"equals": "Vers 311", "category": "word_confusion", "feedback": "311, c''est le pape Pierre."}], "id": "eg.l25.e11", "pool": "lesson", "lessonId": "eg.l25", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l25.e12', 'eg', 'eg.l25', 'eg.g25.grande_persecution', array['eg.g25.grande_persecution','eg.v.saint_georges','eg.v.saint_mina']::text[], 'match', 'lesson', 'Associe chaque martyr à son année.', '{}'::text[], 'La tradition place ces martyrs à différents moments de la grande persécution, entre 303 et 311.', 3, '{"unitIds": ["eg.g25.grande_persecution", "eg.v.saint_georges", "eg.v.saint_mina"], "type": "match", "difficulty": 3, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Associe chaque martyr à son année.", "promptLanguage": "fr", "pairs": [{"left": "Saint Georges", "right": "vers 303"}, {"left": "Sainte Catherine", "right": "305"}, {"left": "Sainte Barbara", "right": "306"}, {"left": "Saint Mina", "right": "vers 309"}], "answer": "Saint Georges = vers 303 ; Sainte Catherine = 305 ; Sainte Barbara = 306 ; Saint Mina = vers 309", "acceptedAnswers": [], "explanation": "La tradition place ces martyrs à différents moments de la grande persécution, entre 303 et 311.", "tip": "Georges 303, Catherine 305, Barbara 306, Mina 309.", "extraExample": {"text": "Galère, malade, signe l''édit de 311 peu avant sa mort.", "translation": "La violence n''a pas éteint la foi : même le persécuteur finit par le reconnaître."}, "id": "eg.l25.e12", "pool": "lesson", "lessonId": "eg.l25", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated 