insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l25.e13', 'eg', 'eg.l25', 'eg.g19.diocletien_ere_des_martyrs', array['eg.g19.diocletien_ere_des_martyrs','eg.v.ere_des_martyrs','eg.v.diocletien']::text[], 'mcq', 'lesson', 'Depuis quelle année le calendrier copte compte-t-il ses années ?', array['284']::text[], '284 est l''année où Dioclétien devient empereur. Les Coptes comptent depuis cette date, appelée l''ère des martyrs, en mémoire de la grande persécution.', 3, '{"unitIds": ["eg.g19.diocletien_ere_des_martyrs", "eg.v.ere_des_martyrs", "eg.v.diocletien"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Depuis quelle année le calendrier copte compte-t-il ses années ?", "promptLanguage": "fr", "options": ["284", "303", "313", "33"], "answer": "284", "acceptedAnswers": ["284"], "explanation": "284 est l''année où Dioclétien devient empereur. Les Coptes comptent depuis cette date, appelée l''ère des martyrs, en mémoire de la grande persécution.", "tip": "Chaque année copte rappelle les martyrs.", "extraExample": {"text": "Le calendrier copte compte les années à partir de 284, début du règne de Dioclétien.", "translation": "Chaque année copte rappelle les martyrs : c''est l''« ère des martyrs »."}, "errorPatterns": [{"equals": "303", "category": "word_confusion", "feedback": "303 est l''année des quatre édits, mais l''ère commence en 284, à l''avènement de Dioclétien."}], "id": "eg.l25.e13", "pool": "lesson", "lessonId": "eg.l25", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.