insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l25.e19', 'eg', 'eg.l25', 'eg.g17.chretiens_mal_vus', array['eg.g17.chretiens_mal_vus']::text[], 'mcq', 'lesson', 'Quel empereur lance la première persécution des chrétiens, en 64 ?', array['Néron']::text[], 'Néron accuse les chrétiens de Rome après l''incendie de 64 : c''est la première persécution. Dèce lance la première persécution générale, vers 250.', 2, '{"unitIds": ["eg.g17.chretiens_mal_vus"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel empereur lance la première persécution des chrétiens, en 64 ?", "promptLanguage": "fr", "options": ["Néron", "Dioclétien", "Galère", "Dèce"], "answer": "Néron", "acceptedAnswers": ["Néron"], "explanation": "Néron accuse les chrétiens de Rome après l''incendie de 64 : c''est la première persécution. Dèce lance la première persécution générale, vers 250.", "tip": "Néron ouvre la liste, Dioclétien la ferme presque.", "extraExample": {"text": "Le calendrier copte compte les années à partir de 284, début du règne de Dioclétien.", "translation": "Chaque année copte rappelle les martyrs : c''est l''« ère des martyrs »."}, "id": "eg.l25.e19", "pool": "lesson", "lessonId": "eg.l25", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l25.e20', 'eg', 'eg.l25', 'eg.g18.edits_de_maximin_a_valerien', array['eg.g18.edits_de_maximin_a_valerien','eg.v.dece']::text[], 'free_answer', 'lesson', 'Quel empereur lance, vers 250, la première persécution générale ?', array['Dèce','Decius','Dece','l''empereur Dèce']::text[], 'Dèce, vers 250, ordonne à tous les habitants de l''empire de sacrifier aux dieux : c''est la première persécution à l''échelle de tout l''empire.', 3, '{"unitIds": ["eg.g18.edits_de_maximin_a_valerien", "eg.v.dece"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Quel empereur lance, vers 250, la première persécution générale ?", "promptLanguage": "fr", "answer": "Dèce", "acceptedAnswers": ["Dèce", "Decius", "Dece", "l''empereur Dèce"], "explanation": "Dèce, vers 250, ordonne à tous les habitants de l''empire de sacrifier aux dieux : c''est la première persécution à l''échelle de tout l''empire.", "tip": "Dèce = première persécution générale.", "extraExample": {"text": "Eusèbe de Césarée a décrit de ses yeux les martyrs d''Égypte.", "translation": "Son récit est un témoignage d''époque, pas une légende tardive."}, "id": "eg.l25.e20", "pool": "lesson", "lessonId": "eg.l25", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l25.e21', 'eg', 'eg.l25', 'eg.g25.grande_persecution', array['eg.g25.grande_persecution','eg.v.pierre_sceau_des_martyrs']::text[], 'free_answer', 'lesson', 'Qui a fondé l''Église d''Alexandrie ?', array['Saint Marc','Marc','l''apôtre Marc']::text[], 'L''Église d''Alexandrie a été fondée par saint Marc : c''est pourquoi le patriarche copte est le successeur du siège de saint Marc.', 2, '{"unitIds": ["eg.g25.grande_persecution", "eg.v.pierre_sceau_des_martyrs"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Qui a fondé l''Église d''Alexandrie ?", "promptLanguage": "fr", "answer": "Saint Marc", "acceptedAnswers": ["Saint Marc", "Marc", "l''apôtre Marc"], "explanation": "L''Église d''Alexandrie a été fondée par saint Marc : c''est pourquoi le patriarche copte est le successeur du siège de saint Marc.", "tip": "Marc = fondateur ; sa chaire = le siège d''Alexandrie.", "extraExample": {"text": "Galère, malade, signe l''édit de 311 peu avant sa mort.", "translation": "La violence n''a pas éteint la foi : même le persécuteur finit par le reconnaître."}, "id": "eg.l25.e21", "pool": "lesson", "lessonId": "eg.l25", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l26.e01', 'eg', 'eg.l26', 'eg.g26.constantin', array['eg.g26.constantin','eg.v.constantin','eg.v.helene','eg.v.licinius','eg.v.maxence']::text[], 'match', 'lesson', 'Qui est qui à l''époque de Constantin ?', '{}'::text[], 'Constantin vainc Maxence en 312, signe la paix avec Licinius en 313, et sa mère Hélène bâtit des églises.', 1, '{"unitIds": ["eg.g26.constantin", "eg.v.constantin", "eg.v.helene", "eg.v.licinius", "eg.v.maxence"], "type": "match", "difficulty": 1, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Qui est qui à l''époque de Constantin ?", "promptLanguage": "fr", "pairs": [{"left": "Constantin", "right": "l''empereur de la croix et de la paix"}, {"left": "Hélène", "right": "sa mère, qui retrouve la Sainte Croix"}, {"left": "Licinius", "right": "le collègue qui signe l''édit de Milan"}, {"left": "Maxence", "right": "le rival vaincu à Rome en 312"}], "answer": "Constantin = l''empereur de la croix et de la paix ; Hélène = sa mère, qui retrouve la Sainte Croix ; Licinius = le collègue qui signe l''édit de Milan ; Maxence = le rival vaincu à Rome en 312", "acceptedAnswers": [], "explanation": "Constantin vainc Maxence en 312, signe la paix avec Licinius en 313, et sa mère Hélène bâtit des églises.", "tip": "Quatre noms : Constantin, Hélène, Licinius, Maxence.", "extraExample": {"text": "Constantin meurt en 337, baptisé tard, peu avant sa mort.", "translation": "Il protège l''Église, mais il reste un empereur avec ses calculs politiques."}, "id": "eg.l26.e01", "pool": "lesson", "lessonId": "eg.l26", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l26.e02', 'eg', 'eg.l26', 'eg.g26.constantin', array['eg.g26.constantin','eg.v.helene']::text[], 'mcq', 'lesson', 'Comment s''appelle la mère de Constantin ?', array['Hélène']::text[], 'Constantin est le fils de Constance Ier Chlore et d''Hélène. Catherine et Barbara sont des martyres de la persécution précédente.', 1, '{"unitIds": ["eg.g26.constantin", "eg.v.helene"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Comment s''appelle la mère de Constantin ?", "promptLanguage": "fr", "options": ["Hélène", "Catherine", "Barbara", "Marie"], "answer": "Hélène", "acceptedAnswers": ["Hélène"], "explanation": "Constantin est le fils de Constance Ier Chlore et d''Hélène. Catherine et Barbara sont des martyres de la persécution précédente.", "tip": "Hélène = mère, Sainte Croix.", "extraExample": {"text": "Constantinople est aujourd''hui Istanbul.", "translation": "La ville porte la trace de Constantin depuis plus de seize siècles."}, "errorPatterns": [{"equals": "Catherine", "category": "word_confusion", "feedback": "Catherine est une martyre de 305."}, {"equals": "Barbara", "category": "word_confusion", "feedback": "Barbara est une martyre de 306."}], "id": "eg.l26.e02", "pool": "lesson", "lessonId": "eg.l26", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l26.e03', 'eg', 'eg.l26', 'eg.g26.constantin', array['eg.g26.constantin','eg.v.maxence','eg.v.constantin']::text[], 'mcq', 'lesson', 'Contre qui Constantin marche-t-il sur Rome en 312 ?', array['Maxence']::text[], 'Maxence règne à Rome et Constantin veut s''en emparer. Licinius sera au contraire son allié à Milan.', 1, '{"unitIds": ["eg.g26.constantin", "eg.v.maxence", "eg.v.constantin"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Contre qui Constantin marche-t-il sur Rome en 312 ?", "promptLanguage": "fr", "options": ["Maxence", "Licinius", "Dioclétien", "Arius"], "answer": "Maxence", "acceptedAnswers": ["Maxence"], "explanation": "Maxence règne à Rome et Constantin veut s''en emparer. Licinius sera au contraire son allié à Milan.", "tip": "312 : Constantin contre Maxence.", "extraExample": {"text": "L''Arménie adopte le christianisme comme religion d''État dès 301.", "translation": "Elle le fait avant l''Empire romain lui-même."}, "errorPatterns": [{"equals": "Licinius", "category": "word_confusion", "feedback": "Licinius signera la paix avec Constantin l''année suivante."}, {"equals": "Dioclétien", "category": "word_confusion", "feedback": "Dioclétien a abdiqué en 305."}], "id": "eg.l26.e03", "pool": "lesson", "lessonId": "eg.l26", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l26.e04', 'eg', 'eg.l26', 'eg.g26.constantin', array['eg.g26.constantin','eg.v.constantin']::text[], 'mcq', 'lesson', 'Quels mots sont écrits autour de la croix lumineuse que voit Constantin ?', array['« Avec ceci tu vaincras »']::text[], 'Selon le récit, c''est le message écrit en grec dans le ciel. Constantin en fait le signe de son armée.', 2, '{"unitIds": ["eg.g26.constantin", "eg.v.constantin"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quels mots sont écrits autour de la croix lumineuse que voit Constantin ?", "promptLanguage": "fr", "options": ["« Avec ceci tu vaincras »", "« Tu es mon Fils bien-aimé »", "« Je suis la voie »", "« Aime ton prochain »"], "answer": "« Avec ceci tu vaincras »", "acceptedAnswers": ["« Avec ceci tu vaincras »"], "explanation": "Selon le récit, c''est le message écrit en grec dans le ciel. Constantin en fait le signe de son armée.", "tip": "La croix, signe de la victoire.", "extraExample": {"text": "Constantin meurt en 337, baptisé tard, peu avant sa mort.", "translation": "Il protège l''Église, mais il reste un empereur avec ses calculs politiques."}, "id": "eg.l26.e04", "pool": "lesson", "lessonId": "eg.l26", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l26.e05', 'eg', 'eg.l26', 'eg.g26.constantin', array['eg.g26.constantin','eg.v.constantin']::text[], 'fill_blank', 'lesson', 'Après sa vision, Constantin fait dessiner une ___ sur son drapeau et sur les armes.', array['croix','une croix','la croix']::text[], 'Constantin obéit à l''ange : il marque son drapeau et les armes d''une croix avant d''aller combattre Maxence.', 2, '{"unitIds": ["eg.g26.constantin", "eg.v.constantin"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Après sa vision, Constantin fait dessiner une ___ sur son drapeau et sur les armes.", "promptLanguage": "fr", "options": ["croix", "aigle", "colombe", "étoile"], "answer": "croix", "acceptedAnswers": ["croix", "une croix", "la croix"], "explanation": "Constantin obéit à l''ange : il marque son drapeau et les armes d''une croix avant d''aller combattre Maxence.", "tip": "La croix sur le drapeau.", "extraExample": {"text": "Constantinople est aujourd''hui Istanbul.", "translation": "La ville porte la trace de Constantin depuis plus de seize siècles."}, "id": "eg.l26.e05", "pool": "lesson", "lessonId": "eg.l26", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l26.e06', 'eg', 'eg.l26', 'eg.g26.constantin', array['eg.g26.constantin','eg.v.maxence']::text[], 'mcq', 'lesson', 'Comment meurt Maxence ?', array['Le pont sur le Tibre s''écroule']::text[], 'En fuyant, Maxence passe un pont dressé sur le Tibre. Le pont s''écroule et il meurt avec beaucoup de ses soldats.', 2, '{"unitIds": ["eg.g26.constantin", "eg.v.maxence"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Comment meurt Maxence ?", "promptLanguage": "fr", "options": ["Le pont sur le Tibre s''écroule", "Il est exécuté à Milan", "Il meurt de maladie à Rome", "Il est exilé à Constantinople"], "answer": "Le pont sur le Tibre s''écroule", "acceptedAnswers": ["Le pont sur le Tibre s''écroule"], "explanation": "En fuyant, Maxence passe un pont dressé sur le Tibre. Le pont s''écroule et il meurt avec beaucoup de ses soldats.", "tip": "Tibre, pont, Maxence.", "extraExample": {"text": "L''Arménie adopte le christianisme comme religion d''État dès 301.", "translation": "Elle le fait avant l''Empire romain lui-même."}, "id": "eg.l26.e06", "pool": "lesson", "lessonId": "eg.l26", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l26.e07', 'eg', 'eg.l26', 'eg.g26.constantin', array['eg.g26.constantin','eg.v.edit_de_milan']::text[], 'mcq', 'lesson', 'Quel édit met fin aux persécutions romaines en 313 ?', array['L''édit de Milan']::text[], 'Signé par Constantin et Licinius à Milan en 313, il met fin aux persécutions romaines. L''édit de Galère (311) n''était qu''une tolérance.', 1, '{"unitIds": ["eg.g26.constantin", "eg.v.edit_de_milan"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel édit met fin aux persécutions romaines en 313 ?", "promptLanguage": "fr", "options": ["L''édit de Milan", "L''édit de Nicée", "L''édit de Galère", "L''édit de Rome"], "answer": "L''édit de Milan", "acceptedAnswers": ["L''édit de Milan"], "explanation": "Signé par Constantin et Licinius à Milan en 313, il met fin aux persécutions romaines. L''édit de Galère (311) n''était qu''une tolérance.", "tip": "313 = Milan.", "extraExample": {"text": "Constantin meurt en 337, baptisé tard, peu avant sa mort.", "translation": "Il protège l''Église, mais il reste un empereur avec ses calculs politiques."}, "errorPatterns": [{"equals": "L''édit de Galère", "category": "word_confusion", "feedback": "L''édit de Galère date de 311 : c''est une tolérance, pas encore la liberté."}], "id": "eg.l26.e07", "pool": "lesson", "lessonId": "eg.l26", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l26.e08', 'eg', 'eg.l26', 'eg.g26.constantin', array['eg.g26.constantin','eg.v.licinius']::text[], 'mcq', 'lesson', 'Qui signe l''édit de Milan avec Constantin ?', array['Licinius']::text[], 'L''édit de Milan est la déclaration commune de Constantin et de Licinius. Galère est mort en 311, Maxence en 312.', 2, '{"unitIds": ["eg.g26.constantin", "eg.v.licinius"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui signe l''édit de Milan avec Constantin ?", "promptLanguage": "fr", "options": ["Licinius", "Galère", "Maxence", "Dioclétien"], "answer": "Licinius", "acceptedAnswers": ["Licinius"], "explanation": "L''édit de Milan est la déclaration commune de Constantin et de Licinius. Galère est mort en 311, Maxence en 312.", "tip": "Deux empereurs, une paix : Constantin et Licinius.", "extraExample": {"text": "Constantinople est aujourd''hui Istanbul.", "translation": "La ville porte la trace de Constantin depuis plus de seize siècles."}, "id": "eg.l26.e08", "pool": "lesson", "lessonId": "eg.l26", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l26.e09', 'eg', 'eg.l26', 'eg.g26.constantin', array['eg.g26.constantin','eg.v.edit_de_milan']::text[], 'fill_blank', 'lesson', 'Avec l''édit de Milan, les biens confisqués des chrétiens sont ___.', array['restitués']::text[], 'La paix de Milan est concrète : on rend aux chrétiens ce qu''on leur avait pris.', 2, '{"unitIds": ["eg.g26.constantin", "eg.v.edit_de_milan"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Avec l''édit de Milan, les biens confisqués des chrétiens sont ___.", "promptLanguage": "fr", "options": ["restitués", "brûlés", "vendus", "partagés"], "answer": "restitués", "acceptedAnswers": ["restitués"], "explanation": "La paix de Milan est concrète : on rend aux chrétiens ce qu''on leur avait pris.", "tip": "Milan : on rend les biens.", "extraExample": {"text": "L''Arménie adopte le christianisme comme religion d''État dès 301.", "translation": "Elle le fait avant l''Empire romain lui-même."}, "id": "eg.l26.e09", "pool": "lesson", "lessonId": "eg.l26", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l26.e10', 'eg', 'eg.l26', 'eg.g26.constantin', array['eg.g26.constantin','eg.v.armenie']::text[], 'mcq', 'lesson', 'Quel est le premier pays du monde à adopter le christianisme comme religion d''État, en 301 ?', array['L''Arménie']::text[], 'L''Arménie devient chrétienne en 301, avant l''Empire romain lui-même.', 1, '{"unitIds": ["eg.g26.constantin", "eg.v.armenie"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel est le premier pays du monde à adopter le christianisme comme religion d''État, en 301 ?", "promptLanguage": "fr", "options": ["L''Arménie", "L''Égypte", "La Grèce", "Rome"], "answer": "L''Arménie", "acceptedAnswers": ["L''Arménie"], "explanation": "L''Arménie devient chrétienne en 301, avant l''Empire romain lui-même.", "tip": "301 = Arménie.", "extraExample": {"text": "Constantin meurt en 337, baptisé tard, peu avant sa mort.", "translation": "Il protège l''Église, mais il reste un empereur avec ses calculs politiques."}, "errorPatterns": [{"equals": "L''Égypte", "category": "word_confusion", "feedback": "L''Égypte est chrétienne depuis saint Marc, mais pas comme religion d''État en 301."}, {"equals": "Rome", "category": "word_confusion", "feedback": "Rome n''adopte le christianisme comme religion d''État qu''en 380."}], "id": "eg.l26.e10", "pool": "lesson", "lessonId": "eg.l26", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l26.e11', 'eg', 'eg.l26', 'eg.g26.constantin', array['eg.g26.constantin','eg.v.constantin']::text[], 'mcq', 'lesson', 'Que décide Constantin en 321 ?', array['Le dimanche, jour de repos hebdomadaire']::text[], 'En 321, Constantin décrète le dimanche comme jour de repos dans l''empire, ce qui aide les chrétiens à se réunir.', 2, '{"unitIds": ["eg.g26.constantin", "eg.v.constantin"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que décide Constantin en 321 ?", "promptLanguage": "fr", "options": ["Le dimanche, jour de repos hebdomadaire", "Les églises deviennent gratuites", "Les évêques deviennent sénateurs", "Le baptême devient obligatoire"], "answer": "Le dimanche, jour de repos hebdomadaire", "acceptedAnswers": ["Le dimanche, jour de repos hebdomadaire"], "explanation": "En 321, Constantin décrète le dimanche comme jour de repos dans l''empire, ce qui aide les chrétiens à se réunir.", "tip": "321 = dimanche.", "extraExample": {"text": "Constantinople est aujourd''hui Istanbul.", "translation": "La ville porte la trace de Constantin depuis plus de seize siècles."}, "id": "eg.l26.e11", "pool": "lesson", "lessonId": "eg.l26", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l26.e12', 'eg', 'eg.l26', 'eg.g26.constantin', array['eg.g26.constantin','eg.v.helene']::text[], 'mcq', 'lesson', 'Que fait Hélène, mère de Constantin, à Jérusalem ?', array['Elle retrouve la Sainte Croix et fait bâtir la basilique de la Résurrection']::text[], 'Hélène est connue pour avoir retrouvé la Sainte Croix et bâti des églises, dont la basilique de la Résurrection.', 2, '{"unitIds": ["eg.g26.constantin", "eg.v.helene"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que fait Hélène, mère de Constantin, à Jérusalem ?", "promptLanguage": "fr", "options": ["Elle retrouve la Sainte Croix et fait bâtir la basilique de la Résurrection", "Elle fonde Constantinople", "Elle signe l''édit de Milan", "Elle préside le concile de Nicée"], "answer": "Elle retrouve la Sainte Croix et fait bâtir la basilique de la Résurrection", "acceptedAnswers": ["Elle retrouve la Sainte Croix et fait bâtir la basilique de la Résurrection"], "explanation": "Hélène est connue pour avoir retrouvé la Sainte Croix et bâti des églises, dont la basilique de la Résurrection.", "tip": "Hélène = Croix + églises.", "extraExample": {"text": "L''Arménie adopte le christianisme comme religion d''État dès 301.", "translation": "Elle le fait avant l''Empire romain lui-même."}, "id": "eg.l26.e12", "pool": "lesson", "lessonId": "eg.l26", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l26.e13', 'eg', 'eg.l26', 'eg.g26.constantin', array['eg.g26.constantin','eg.v.constantinople']::text[], 'fill_blank', 'lesson', 'En 330, Constantin fonde ___, « la ville de Constantin ».', array['Constantinople']::text[], 'Constantinople remplace Byzance et devient la capitale de l''empire d''Orient.', 2, '{"unitIds": ["eg.g26.constantin", "eg.v.constantinople"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "En 330, Constantin fonde ___, « la ville de Constantin ».", "promptLanguage": "fr", "options": ["Constantinople", "Nicée", "Milan", "Alexandrie"], "answer": "Constantinople", "acceptedAnswers": ["Constantinople"], "explanation": "Constantinople remplace Byzance et devient la capitale de l''empire d''Orient.", "tip": "Constantin + ville = Constantinople.", "extraExample": {"text": "Constantin meurt en 337, baptisé tard, peu avant sa mort.", "translation": "Il protège l''Église, mais il reste un empereur avec ses calculs politiques."}, "id": "eg.l26.e13", "pool": "lesson", "lessonId": "eg.l26", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l26.e14', 'eg', 'eg.l26', 'eg.g26.constantin', array['eg.g26.constantin','eg.v.eveque_du_dehors']::text[], 'free_answer', 'lesson', 'Quel titre l''empereur se donne-t-il pour les affaires extérieures de l''Église ?', array['L''évêque du dehors','évêque du dehors','eveque du dehors']::text[], 'Constantin se dit « évêque du dehors » : il s''occupe des affaires extérieures de l''Église, mais s''immisce aussi dans les débats de foi.', 3, '{"unitIds": ["eg.g26.constantin", "eg.v.eveque_du_dehors"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Quel titre l''empereur se donne-t-il pour les affaires extérieures de l''Église ?", "promptLanguage": "fr", "answer": "L''évêque du dehors", "acceptedAnswers": ["L''évêque du dehors", "évêque du dehors", "eveque du dehors"], "explanation": "Constantin se dit « évêque du dehors » : il s''occupe des affaires extérieures de l''Église, mais s''immisce aussi dans les débats de foi.", "tip": "Évêque du dehors = l''empereur.", "extraExample": {"text": "Constantinople est aujourd''hui Istanbul.", "translation": "La ville porte la trace de Constantin depuis plus de seize siècles."}, "hint": "Il est dehors, pas dedans.", "id": "eg.l26.e14", "pool": "lesson", "lessonId": "eg.l26", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l26.e15', 'eg', 'eg.l26', 'eg.g26.constantin', array['eg.g26.constantin','eg.v.eveque_du_dehors']::text[], 'mcq', 'lesson', 'Quel danger la proximité entre l''empereur et le clergé crée-t-elle ?', array['L''Église se mêle à la politique']::text[], 'Quand le travail calme et spirituel de l''Église se mélange au pouvoir temporel, l''empereur peut orienter les débats. On le verra dans la querelle d''Arius.', 3, '{"unitIds": ["eg.g26.constantin", "eg.v.eveque_du_dehors"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quel danger la proximité entre l''empereur et le clergé crée-t-elle ?", "promptLanguage": "fr", "options": ["L''Église se mêle à la politique", "L''Église devient pauvre", "Les évêques n''ont plus le droit de prêcher", "Les églises sont fermées"], "answer": "L''Église se mêle à la politique", "acceptedAnswers": ["L''Église se mêle à la politique"], "explanation": "Quand le travail calme et spirituel de l''Église se mélange au pouvoir temporel, l''empereur peut orienter les débats. On le verra dans la querelle d''Arius.", "tip": "Le danger de la faveur : le pouvoir veut peser.", "extraExample": {"text": "L''Arménie adopte le christianisme comme religion d''État dès 301.", "translation": "Elle le fait avant l''Empire romain lui-même."}, "id": "eg.l26.e15", "pool": "lesson", "lessonId": "eg.l26", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l26.e16', 'eg', 'eg.l26', 'eg.g26.constantin', array['eg.g26.constantin','eg.v.edit_de_milan']::text[], 'reorder', 'lesson', 'Phrase-repère : la paix des chrétiens.', array['L''édit de Milan met fin aux persécutions en 313','En 313 l''édit de Milan met fin aux persécutions']::text[], '313 est la date de la paix.', 2, '{"unitIds": ["eg.g26.constantin", "eg.v.edit_de_milan"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "prompt": "Phrase-repère : la paix des chrétiens.", "promptLanguage": "fr", "tokens": ["L''édit", "313", "en", "Milan", "persécutions", "fin", "met", "de", "aux"], "answer": "L''édit de Milan met fin aux persécutions en 313", "acceptedAnswers": ["L''édit de Milan met fin aux persécutions en 313", "En 313 l''édit de Milan met fin aux persécutions"], "explanation": "313 est la date de la paix.", "tip": "313 : Milan, la paix.", "extraExample": {"text": "Constantin meurt en 337, baptisé tard, peu avant sa mort.", "translation": "Il protège l''Église, mais il reste un empereur avec ses calculs politiques."}, "id": "eg.l26.e16", "pool": "lesson", "lessonId": "eg.l26", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
