insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l29.e19', 'eg', 'eg.l29', 'eg.g29.athanase', array['eg.g29.athanase','eg.v.athanase']::text[], 'reorder', 'lesson', 'Phrase-repère : Athanase.', array['Athanase est le défenseur de la foi']::text[], 'Le surnom dit tout : Athanase défend la foi de Nicée.', 2, '{"unitIds": ["eg.g29.athanase", "eg.v.athanase"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "prompt": "Phrase-repère : Athanase.", "promptLanguage": "fr", "tokens": ["défenseur", "foi", "Athanase", "la", "est", "le", "de"], "answer": "Athanase est le défenseur de la foi", "acceptedAnswers": ["Athanase est le défenseur de la foi"], "explanation": "Le surnom dit tout : Athanase défend la foi de Nicée.", "tip": "Athanase = défenseur de la foi.", "extraExample": {"text": "Athanase aurait dit : « le monde est contre moi, et je suis contre le monde ».", "translation": "Pour lui, tenir la vérité compte plus que d''avoir la foule avec soi."}, "id": "eg.l29.e19", "pool": "lesson", "lessonId": "eg.l29", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l29.e20', 'eg', 'eg.l29', 'eg.g28.concile_de_nicee', array['eg.g28.concile_de_nicee','eg.v.concile_de_nicee','eg.v.concile_de_nicee']::text[], 'mcq', 'lesson', 'Quelle fonction Athanase occupe-t-il auprès du pape Alexandre à Nicée ?', array['Diacre']::text[], 'À Nicée, Athanase est le jeune diacre du pape Alexandre : il expose les erreurs d''Arius devant les évêques.', 2, '{"unitIds": ["eg.g28.concile_de_nicee", "eg.v.concile_de_nicee", "eg.v.concile_de_nicee"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle fonction Athanase occupe-t-il auprès du pape Alexandre à Nicée ?", "promptLanguage": "fr", "options": ["Diacre", "Évêque de Rome", "Empereur", "Moine du désert"], "answer": "Diacre", "acceptedAnswers": ["Diacre"], "explanation": "À Nicée, Athanase est le jeune diacre du pape Alexandre : il expose les erreurs d''Arius devant les évêques.", "tip": "Diacre à Nicée, pape ensuite.", "extraExample": {"text": "Athanase reste patriarche plus de quarante ans, malgré les exils.", "translation": "Toute une vie donnée à une seule question : Jésus est-il Dieu ?"}, "id": "eg.l29.e20", "pool": "lesson", "lessonId": "eg.l29", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l29.e21', 'eg', 'eg.l29', 'eg.g27.arius', array['eg.g27.arius','eg.v.homoousios','eg.v.homoousios']::text[], 'fill_blank', 'lesson', 'Pour Athanase et pour le concile de Nicée, le Fils est ___ au Père, c''est-à-dire de même substance.', array['homoousios']::text[], 'Homoousios est le mot de Nicée, défendu par Athanase. Homoiousios est la position semi-arienne.', 3, '{"unitIds": ["eg.g27.arius", "eg.v.homoousios", "eg.v.homoousios"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète la phrase.", "prompt": "Pour Athanase et pour le concile de Nicée, le Fils est ___ au Père, c''est-à-dire de même substance.", "promptLanguage": "fr", "options": ["homoousios", "homoiousios", "créé", "inférieur"], "answer": "homoousios", "acceptedAnswers": ["homoousios"], "explanation": "Homoousios est le mot de Nicée, défendu par Athanase. Homoiousios est la position semi-arienne.", "tip": "Homoousios = même substance.", "extraExample": {"text": "La liste de 27 livres d''Athanase est celle de toutes nos Bibles chrétiennes d''aujourd''hui.", "translation": "Un évêque d''Alexandrie a donc aidé à fixer notre Nouveau Testament."}, "id": "eg.l29.e21", "pool": "lesson", "lessonId": "eg.l29", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l29.e22', 'eg', 'eg.l29', 'eg.g27.arius', array['eg.g27.arius','eg.v.divinite_du_christ','eg.v.divinite_du_christ']::text[], 'mcq', 'lesson', 'Selon le cours, que ne pourrait pas faire le Christ s''il n''était qu''une créature ?', array['Nous sauver']::text[], 'Seul Dieu peut sauver l''homme. C''est pourquoi Athanase défend sans relâche la divinité du Christ.', 3, '{"unitIds": ["eg.g27.arius", "eg.v.divinite_du_christ", "eg.v.divinite_du_christ"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Selon le cours, que ne pourrait pas faire le Christ s''il n''était qu''une créature ?", "promptLanguage": "fr", "options": ["Nous sauver", "Naître à Bethléem", "Parler aux apôtres", "Marcher sur l''eau"], "answer": "Nous sauver", "acceptedAnswers": ["Nous sauver"], "explanation": "Seul Dieu peut sauver l''homme. C''est pourquoi Athanase défend sans relâche la divinité du Christ.", "tip": "Pas Dieu, pas Sauveur.", "extraExample": {"text": "Athanase aurait dit : « le monde est contre moi, et je suis contre le monde ».", "translation": "Pour lui, tenir la vérité compte plus que d''avoir la foule avec soi."}, "id": "eg.l29.e22", "pool": "lesson", "lessonId": "eg.l29", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l30.e01', 'eg', 'eg.l30', 'eg.g30.peres_du_desert', array['eg.g30.peres_du_desert','eg.v.saint_paul_l_ermite','eg.v.saint_antoine','eg.v.saint_pacome','eg.v.saint_macaire_le_grand']::text[], 'match', 'lesson', 'Qui est qui au désert ?', '{}'::text[], 'Paul est le premier ermite, Antoine le père des moines, Pacôme fonde la vie en communauté, et Macaire est le père de Scété.', 1, '{"unitIds": ["eg.g30.peres_du_desert", "eg.v.saint_paul_l_ermite", "eg.v.saint_antoine", "eg.v.saint_pacome", "eg.v.saint_macaire_le_grand"], "type": "match", "difficulty": 1, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Qui est qui au désert ?", "promptLanguage": "fr", "pairs": [{"left": "Saint Paul", "right": "le premier ermite"}, {"left": "Saint Antoine", "right": "le père des moines"}, {"left": "Saint Pacôme", "right": "fondateur des premiers monastères cénobitiques"}, {"left": "Saint Macaire", "right": "père de Scété"}], "answer": "Saint Paul = le premier ermite ; Saint Antoine = le père des moines ; Saint Pacôme = fondateur des premiers monastères cénobitiques ; Saint Macaire = père de Scété", "acceptedAnswers": [], "explanation": "Paul est le premier ermite, Antoine le père des moines, Pacôme fonde la vie en communauté, et Macaire est le père de Scété.", "tip": "Paul, Antoine, Pacôme, Macaire.", "extraExample": {"text": "Aujourd''hui encore, des moines vivent dans le désert de Wadi Natroun, là où vécut saint Macaire.", "translation": "La tradition n''a jamais été interrompue depuis le IVe siècle."}, "id": "eg.l30.e01", "pool": "lesson", "lessonId": "eg.l30", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l30.e02', 'eg', 'eg.l30', 'eg.g30.peres_du_desert', array['eg.g30.peres_du_desert','eg.v.monachisme']::text[], 'mcq', 'lesson', 'Dans quel pays le mouvement monastique chrétien commence-t-il ?', array['En Égypte']::text[], 'Le monachisme naît en Égypte, d''où l''expression « l''Égypte, mère du monachisme ».', 1, '{"unitIds": ["eg.g30.peres_du_desert", "eg.v.monachisme"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Dans quel pays le mouvement monastique chrétien commence-t-il ?", "promptLanguage": "fr", "options": ["En Égypte", "En Grèce", "À Rome", "En Arménie"], "answer": "En Égypte", "acceptedAnswers": ["En Égypte"], "explanation": "Le monachisme naît en Égypte, d''où l''expression « l''Égypte, mère du monachisme ».", "tip": "Moines = Égypte.", "extraExample": {"text": "Le monastère de saint Antoine, près de la mer Rouge, est l''un des plus anciens monastères du monde.", "translation": "Il garde le souvenir du père des moines."}, "errorPatterns": [{"equals": "À Rome", "category": "word_confusion", "feedback": "Le monachisme n''arrive à Rome que plus tard, grâce à La Vie d''Antoine."}], "id": "eg.l30.e02", "pool": "lesson", "lessonId": "eg.l30", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l30.e03', 'eg', 'eg.l30', 'eg.g30.peres_du_desert', array['eg.g30.peres_du_desert','eg.v.monachisme']::text[], 'mcq', 'lesson', 'Quels sont les trois principes de la vie monastique ?', array['La pauvreté, l''obéissance et la chasteté']::text[], 'Le moine renonce à posséder, à décider seul, et à fonder une famille, pour se donner entièrement à Dieu.', 1, '{"unitIds": ["eg.g30.peres_du_desert", "eg.v.monachisme"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quels sont les trois principes de la vie monastique ?", "promptLanguage": "fr", "options": ["La pauvreté, l''obéissance et la chasteté", "La richesse, la liberté et la gloire", "Le travail, le sport et le repos", "La prière, l''argent et le pouvoir"], "answer": "La pauvreté, l''obéissance et la chasteté", "acceptedAnswers": ["La pauvreté, l''obéissance et la chasteté"], "explanation": "Le moine renonce à posséder, à décider seul, et à fonder une famille, pour se donner entièrement à Dieu.", "tip": "Pauvreté, obéissance, chasteté.", "extraExample": {"text": "Saint Benoît (VIe siècle) a rédigé sa règle de 73 chapitres pour le Mont-Cassin.", "translation": "La vie communautaire d''Égypte a inspiré les moines d''Occident."}, "id": "eg.l30.e03", "pool": "lesson", "lessonId": "eg.l30", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l30.e04', 'eg', 'eg.l30', 'eg.g30.peres_du_desert', array['eg.g30.peres_du_desert','eg.v.monachisme']::text[], 'fill_blank', 'lesson', 'La vie monastique repose sur la pauvreté, l''___ et la chasteté.', array['obéissance']::text[], 'Le moine apprend à obéir pour mourir à sa propre volonté. C''est le deuxième des trois principes.', 2, '{"unitIds": ["eg.g30.peres_du_desert", "eg.v.monachisme"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "La vie monastique repose sur la pauvreté, l''___ et la chasteté.", "promptLanguage": "fr", "options": ["obéissance", "autorité", "liberté", "fortune"], "answer": "obéissance", "acceptedAnswers": ["obéissance"], "explanation": "Le moine apprend à obéir pour mourir à sa propre volonté. C''est le deuxième des trois principes.", "tip": "Pauvreté, obéissance, chasteté.", "extraExample": {"text": "Aujourd''hui encore, des moines vivent dans le désert de Wadi Natroun, là où vécut saint Macaire.", "translation": "La tradition n''a jamais été interrompue depuis le IVe siècle."}, "id": "eg.l30.e04", "pool": "lesson", "lessonId": "eg.l30", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l30.e05', 'eg', 'eg.l30', 'eg.g30.peres_du_desert', array['eg.g30.peres_du_desert','eg.v.saint_antoine']::text[], 'mcq', 'lesson', 'En quelle année naît saint Antoine ?', array['251']::text[], 'Antoine est né en 251, en Haute-Égypte, et mort en 356. 342 est la mort de Paul, 391 celle de Macaire.', 1, '{"unitIds": ["eg.g30.peres_du_desert", "eg.v.saint_antoine"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "En quelle année naît saint Antoine ?", "promptLanguage": "fr", "options": ["251", "356", "342", "391"], "answer": "251", "acceptedAnswers": ["251"], "explanation": "Antoine est né en 251, en Haute-Égypte, et mort en 356. 342 est la mort de Paul, 391 celle de Macaire.", "tip": "251-356.", "extraExample": {"text": "Le monastère de saint Antoine, près de la mer Rouge, est l''un des plus anciens monastères du monde.", "translation": "Il garde le souvenir du père des moines."}, "errorPatterns": [{"equals": "356", "category": "word_confusion", "feedback": "356 est l''année de sa mort."}, {"equals": "342", "category": "word_confusion", "feedback": "342 est la mort de saint Paul l''ermite."}, {"equals": "391", "category": "word_confusion", "feedback": "391 est la mort de saint Macaire."}], "id": "eg.l30.e05", "pool": "lesson", "lessonId": "eg.l30", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l30.e06', 'eg', 'eg.l30', 'eg.g30.peres_du_desert', array['eg.g30.peres_du_desert','eg.v.saint_antoine']::text[], 'fill_blank', 'lesson', 'Saint Antoine meurt en ___.', array['356']::text[], 'Antoine meurt en 356, plus de cent ans après sa naissance.', 3, '{"unitIds": ["eg.g30.peres_du_desert", "eg.v.saint_antoine"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète la phrase.", "prompt": "Saint Antoine meurt en ___.", "promptLanguage": "fr", "options": ["356", "251", "342", "391"], "answer": "356", "acceptedAnswers": ["356"], "explanation": "Antoine meurt en 356, plus de cent ans après sa naissance.", "tip": "251 → 356.", "extraExample": {"text": "Saint Benoît (VIe siècle) a rédigé sa règle de 73 chapitres pour le Mont-Cassin.", "translation": "La vie communautaire d''Égypte a inspiré les moines d''Occident."}, "id": "eg.l30.e06", "pool": "lesson", "lessonId": "eg.l30", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l30.e07', 'eg', 'eg.l30', 'eg.g30.peres_du_desert', array['eg.g30.peres_du_desert','eg.v.saint_antoine']::text[], 'mcq', 'lesson', 'D''où vient saint Antoine ?', array['De Haute-Égypte']::text[], 'Antoine est un Copte de Haute-Égypte. Les premiers moines, tous ses disciples, sont donc aussi Égyptiens.', 2, '{"unitIds": ["eg.g30.peres_du_desert", "eg.v.saint_antoine"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "D''où vient saint Antoine ?", "promptLanguage": "fr", "options": ["De Haute-Égypte", "De Rome", "D''Arménie", "De Grèce"], "answer": "De Haute-Égypte", "acceptedAnswers": ["De Haute-Égypte"], "explanation": "Antoine est un Copte de Haute-Égypte. Les premiers moines, tous ses disciples, sont donc aussi Égyptiens.", "tip": "Antoine le Copte.", "extraExample": {"text": "Aujourd''hui encore, des moines vivent dans le désert de Wadi Natroun, là où vécut saint Macaire.", "translation": "La tradition n''a jamais été interrompue depuis le IVe siècle."}, "id": "eg.l30.e07", "pool": "lesson", "lessonId": "eg.l30", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l30.e08', 'eg', 'eg.l30', 'eg.g30.peres_du_desert', array['eg.g30.peres_du_desert','eg.v.saint_antoine']::text[], 'mcq', 'lesson', 'Quel titre porte saint Antoine ?', array['Le père des moines']::text[], 'Antoine est le premier moine du monde : on l''appelle le père des moines. Athanase est le défenseur de la foi et Pierre le sceau des martyrs.', 1, '{"unitIds": ["eg.g30.peres_du_desert", "eg.v.saint_antoine"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel titre porte saint Antoine ?", "promptLanguage": "fr", "options": ["Le père des moines", "Le défenseur de la foi", "Le sceau des martyrs", "Le théologien"], "answer": "Le père des moines", "acceptedAnswers": ["Le père des moines"], "explanation": "Antoine est le premier moine du monde : on l''appelle le père des moines. Athanase est le défenseur de la foi et Pierre le sceau des martyrs.", "tip": "Antoine = père des moines.", "extraExample": {"text": "Le monastère de saint Antoine, près de la mer Rouge, est l''un des plus anciens monastères du monde.", "translation": "Il garde le souvenir du père des moines."}, "errorPatterns": [{"equals": "Le défenseur de la foi", "category": "word_confusion", "feedback": "C''est le surnom d''Athanase."}, {"equals": "Le sceau des martyrs", "category": "word_confusion", "feedback": "C''est le pape Pierre."}], "id": "eg.l30.e08", "pool": "lesson", "lessonId": "eg.l30", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l30.e09', 'eg', 'eg.l30', 'eg.g30.peres_du_desert', array['eg.g30.peres_du_desert','eg.v.saint_pacome']::text[], 'mcq', 'lesson', 'Qui fonde les premiers monastères cénobitiques en Haute-Égypte ?', array['Saint Pacôme']::text[], 'Antoine vit seul, mais Pacôme rassemble les moines dans des monastères et leur donne une règle.', 1, '{"unitIds": ["eg.g30.peres_du_desert", "eg.v.saint_pacome"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Qui fonde les premiers monastères cénobitiques en Haute-Égypte ?", "promptLanguage": "fr", "options": ["Saint Pacôme", "Saint Antoine", "Saint Paul", "Arius"], "answer": "Saint Pacôme", "acceptedAnswers": ["Saint Pacôme"], "explanation": "Antoine vit seul, mais Pacôme rassemble les moines dans des monastères et leur donne une règle.", "tip": "Pacôme = règle et communauté.", "extraExample": {"text": "Saint Benoît (VIe siècle) a rédigé sa règle de 73 chapitres pour le Mont-Cassin.", "translation": "La vie communautaire d''Égypte a inspiré les moines d''Occident."}, "errorPatterns": [{"equals": "Saint Antoine", "category": "word_confusion", "feedback": "Antoine est le modèle de la vie solitaire."}], "id": "eg.l30.e09", "pool": "lesson", "lessonId": "eg.l30", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l30.e10', 'eg', 'eg.l30', 'eg.g30.peres_du_desert', array['eg.g30.peres_du_desert','eg.v.vie_cenobitique']::text[], 'mcq', 'lesson', 'Que veut dire « cénobitique » ?', array['Vie en communauté']::text[], 'Les moines cénobites vivent ensemble sous une règle, à la différence des ermites.', 2, '{"unitIds": ["eg.g30.peres_du_desert", "eg.v.vie_cenobitique"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que veut dire « cénobitique » ?", "promptLanguage": "fr", "options": ["Vie en communauté", "Vie en solitude", "Vie dans les villes", "Vie de soldat"], "answer": "Vie en communauté", "acceptedAnswers": ["Vie en communauté"], "explanation": "Les moines cénobites vivent ensemble sous une règle, à la différence des ermites.", "tip": "Cénobite = ensemble.", "extraExample": {"text": "Aujourd''hui encore, des moines vivent dans le désert de Wadi Natroun, là où vécut saint Macaire.", "translation": "La tradition n''a jamais été interrompue depuis le IVe siècle."}, "id": "eg.l30.e10", "pool": "lesson", "lessonId": "eg.l30", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l30.e11', 'eg', 'eg.l30', 'eg.g30.peres_du_desert', array['eg.g30.peres_du_desert','eg.v.saint_macaire_le_grand','eg.v.scete']::text[], 'mcq', 'lesson', 'Dans quel désert vit saint Macaire le Grand ?', array['Scété']::text[], 'Macaire rassemble des disciples à Scété. Son nom reste associé à ce désert.', 2, '{"unitIds": ["eg.g30.peres_du_desert", "eg.v.saint_macaire_le_grand", "eg.v.scete"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Dans quel désert vit saint Macaire le Grand ?", "promptLanguage": "fr", "options": ["Scété", "Le Sinaï", "Nicée", "La Libye"], "answer": "Scété", "acceptedAnswers": ["Scété"], "explanation": "Macaire rassemble des disciples à Scété. Son nom reste associé à ce désert.", "tip": "Macaire = Scété.", "extraExample": {"text": "Le monastère de saint Antoine, près de la mer Rouge, est l''un des plus anciens monastères du monde.", "translation": "Il garde le souvenir du père des moines."}, "id": "eg.l30.e11", "pool": "lesson", "lessonId": "eg.l30", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l30.e12', 'eg', 'eg.l30', 'eg.g30.peres_du_desert', array['eg.g30.peres_du_desert','eg.v.monachisme']::text[], 'fill_blank', 'lesson', 'Vers la fin du IVe siècle, ___ moines vivent au désert.', array['plusieurs milliers de']::text[], 'Le monachisme attire les foules : plusieurs milliers de moines vivent au désert, et on vient du monde entier.', 3, '{"unitIds": ["eg.g30.peres_du_desert", "eg.v.monachisme"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète la phrase.", "prompt": "Vers la fin du IVe siècle, ___ moines vivent au désert.", "promptLanguage": "fr", "options": ["plusieurs milliers de", "quelques dizaines de", "trois", "un seul"], "answer": "plusieurs milliers de", "acceptedAnswers": ["plusieurs milliers de"], "explanation": "Le monachisme attire les foules : plusieurs milliers de moines vivent au désert, et on vient du monde entier.", "tip": "Des milliers.", "extraExample": {"text": "Saint Benoît (VIe siècle) a rédigé sa règle de 73 chapitres pour le Mont-Cassin.", "translation": "La vie communautaire d''Égypte a inspiré les moines d''Occident."}, "id": "eg.l30.e12", "pool": "lesson", "lessonId": "eg.l30", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l30.e13', 'eg', 'eg.l30', 'eg.g30.peres_du_desert', array['eg.g30.peres_du_desert','eg.v.saint_antoine','eg.v.saint_pacome','eg.v.chenoute']::text[], 'match', 'lesson', 'Les trois systèmes monastiques.', '{}'::text[], 'Antoine (solitude), Pacôme (communauté) et Chénouté (discipline stricte, Ve siècle) sont les trois systèmes monastiques.', 3, '{"unitIds": ["eg.g30.peres_du_desert", "eg.v.saint_antoine", "eg.v.saint_pacome", "eg.v.chenoute"], "type": "match", "difficulty": 3, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Les trois systèmes monastiques.", "promptLanguage": "fr", "pairs": [{"left": "Saint Antoine", "right": "la vie solitaire"}, {"left": "Saint Pacôme", "right": "la vie en communauté"}, {"left": "Saint Chénouté", "right": "une discipline communautaire stricte, plus tard"}], "answer": "Saint Antoine = la vie solitaire ; Saint Pacôme = la vie en communauté ; Saint Chénouté = une discipline communautaire stricte, plus tard", "acceptedAnswers": [], "explanation": "Antoine (solitude), Pacôme (communauté) et Chénouté (discipline stricte, Ve siècle) sont les trois systèmes monastiques.", "tip": "Solitude, communauté, discipline.", "extraExample": {"text": "Aujourd''hui encore, des moines vivent dans le désert de Wadi Natroun, là où vécut saint Macaire.", "translation": "La tradition n''a jamais été interrompue depuis le IVe siècle."}, "id": "eg.l30.e13", "pool": "lesson", "lessonId": "eg.l30", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l30.e14', 'eg', 'eg.l30', 'eg.g30.peres_du_desert', array['eg.g30.peres_du_desert','eg.v.vie_cenobitique']::text[], 'free_answer', 'lesson', 'Comment appelle-t-on la vie des moines qui vivent ensemble en communauté ?', array['La vie cénobitique','cénobitique','vie cénobitique','cenobitique']::text[], 'La vie cénobitique est la vie en communauté. Elle a été organisée par saint Pacôme.', 2, '{"unitIds": ["eg.g30.peres_du_desert", "eg.v.vie_cenobitique"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Comment appelle-t-on la vie des moines qui vivent ensemble en communauté ?", "promptLanguage": "fr", "answer": "La vie cénobitique", "acceptedAnswers": ["La vie cénobitique", "cénobitique", "vie cénobitique", "cenobitique"], "explanation": "La vie cénobitique est la vie en communauté. Elle a été organisée par saint Pacôme.", "tip": "Cénobite = communauté.", "extraExample": {"text": "Le monastère de saint Antoine, près de la mer Rouge, est l''un des plus anciens monastères du monde.", "translation": "Il garde le souvenir du père des moines."}, "id": "eg.l30.e14", "pool": "lesson", "lessonId": "eg.l30", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l30.e15', 'eg', 'eg.l30', 'eg.g30.peres_du_desert', array['eg.g30.peres_du_desert','eg.v.jean_cassien']::text[], 'free_answer', 'lesson', 'Quel moine fait connaître la littérature monastique égyptienne à l''Occident ?', array['Jean Cassien','Cassien']::text[], 'Jean Cassien relaie en Occident la sagesse des Pères du désert, avant les traductions latines.', 3, '{"unitIds": ["eg.g30.peres_du_desert", "eg.v.jean_cassien"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Quel moine fait connaître la littérature monastique égyptienne à l''Occident ?", "promptLanguage": "fr", "answer": "Jean Cassien", "acceptedAnswers": ["Jean Cassien", "Cassien"], "explanation": "Jean Cassien relaie en Occident la sagesse des Pères du désert, avant les traductions latines.", "tip": "Cassien = pont vers l''Occident.", "extraExample": {"text": "Saint Benoît (VIe siècle) a rédigé sa règle de 73 chapitres pour le Mont-Cassin.", "translation": "La vie communautaire d''Égypte a inspiré les moines d''Occident."}, "id": "eg.l30.e15", "pool": "lesson", "lessonId": "eg.l30", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
