insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l31.e09', 'eg', 'eg.l31', 'eg.g31.concile_de_constantinople', array['eg.g31.concile_de_constantinople','eg.v.macedonius']::text[], 'mcq', 'lesson', 'Que soutient Macédonius à propos du Saint-Esprit ?', array['Le Saint-Esprit a été créé']::text[], 'Macédonius nie la divinité de l''Esprit Saint, comme Arius celle du Fils. Le concile affirme l''Esprit Seigneur et vivifiant.', 2, '{"unitIds": ["eg.g31.concile_de_constantinople", "eg.v.macedonius"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que soutient Macédonius à propos du Saint-Esprit ?", "promptLanguage": "fr", "options": ["Le Saint-Esprit a été créé", "Le Saint-Esprit est le Père", "Le Saint-Esprit n''existe pas", "Le Saint-Esprit est un ange"], "answer": "Le Saint-Esprit a été créé", "acceptedAnswers": ["Le Saint-Esprit a été créé"], "explanation": "Macédonius nie la divinité de l''Esprit Saint, comme Arius celle du Fils. Le concile affirme l''Esprit Seigneur et vivifiant.", "tip": "Arius touche le Fils, Macédonius l''Esprit.", "extraExample": {"text": "En 381, Constantinople n''a que cinquante ans d''existence.", "translation": "Une ville toute neuve accueille déjà un concile œcuménique."}, "id": "eg.l31.e09", "pool": "lesson", "lessonId": "eg.l31", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l31.e10', 'eg', 'eg.l31', 'eg.g31.concile_de_constantinople', array['eg.g31.concile_de_constantinople','eg.v.credo_de_nicee_constantinople']::text[], 'fill_blank', 'lesson', 'Les pères complètent le credo à partir de « Je crois en l''___ ».', array['Esprit Saint']::text[], 'Nicée s''arrêtait à « son règne n''aura pas de fin ». Constantinople ajoute toute la suite sur l''Esprit Saint.', 2, '{"unitIds": ["eg.g31.concile_de_constantinople", "eg.v.credo_de_nicee_constantinople"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Les pères complètent le credo à partir de « Je crois en l''___ ».", "promptLanguage": "fr", "options": ["Esprit Saint", "Église catholique", "Fils unique", "Père tout-puissant"], "answer": "Esprit Saint", "acceptedAnswers": ["Esprit Saint"], "explanation": "Nicée s''arrêtait à « son règne n''aura pas de fin ». Constantinople ajoute toute la suite sur l''Esprit Saint.", "tip": "Constantinople complète sur l''Esprit.", "extraExample": {"text": "Le Credo que tu récites à la messe est celui de Nicée complété à Constantinople.", "translation": "Les 318 pères de Nicée et les 150 de Constantinople sont donc présents dans ta prière."}, "id": "eg.l31.e10", "pool": "lesson", "lessonId": "eg.l31", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l31.e11', 'eg', 'eg.l31', 'eg.g31.concile_de_constantinople', array['eg.g31.concile_de_constantinople','eg.v.concile_de_constantinople']::text[], 'free_answer', 'lesson', 'Combien de canons le concile de Constantinople établit-il ?', array['7','sept','7 canons','sept canons']::text[], 'Constantinople établit sept canons, dont celui sur le rang de Constantinople.', 3, '{"unitIds": ["eg.g31.concile_de_constantinople", "eg.v.concile_de_constantinople"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Combien de canons le concile de Constantinople établit-il ?", "promptLanguage": "fr", "answer": "7", "acceptedAnswers": ["7", "sept", "7 canons", "sept canons"], "explanation": "Constantinople établit sept canons, dont celui sur le rang de Constantinople.", "tip": "7 canons.", "extraExample": {"text": "Grégoire de Nazianze disait : ce que le Christ n''a pas pris, il ne l''a pas guéri.", "translation": "Si le Christ n''avait pas d''âme humaine, notre âme ne serait pas sauvée."}, "id": "eg.l31.e11", "pool": "lesson", "lessonId": "eg.l31", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l31.e12', 'eg', 'eg.l31', 'eg.g31.concile_de_constantinople', array['eg.g31.concile_de_constantinople','eg.v.concile_de_constantinople']::text[], 'mcq', 'lesson', 'Quel canon de Constantinople le siège d''Alexandrie n''a-t-il pas accepté ?', array['Constantinople est le deuxième siège après celui de Rome']::text[], 'Alexandrie ne reconnaît pas ce rang : elle occupait la deuxième place depuis Nicée, et ne veut pas qu''un siège gagne en rang parce que la ville est capitale.', 3, '{"unitIds": ["eg.g31.concile_de_constantinople", "eg.v.concile_de_constantinople"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quel canon de Constantinople le siège d''Alexandrie n''a-t-il pas accepté ?", "promptLanguage": "fr", "options": ["Constantinople est le deuxième siège après celui de Rome", "Les évêques doivent se marier", "Le credo est supprimé", "Alexandrie perd son pape"], "answer": "Constantinople est le deuxième siège après celui de Rome", "acceptedAnswers": ["Constantinople est le deuxième siège après celui de Rome"], "explanation": "Alexandrie ne reconnaît pas ce rang : elle occupait la deuxième place depuis Nicée, et ne veut pas qu''un siège gagne en rang parce que la ville est capitale.", "tip": "Alexandrie refuse la « nouvelle Rome ».", "extraExample": {"text": "En 381, Constantinople n''a que cinquante ans d''existence.", "translation": "Une ville toute neuve accueille déjà un concile œcuménique."}, "id": "eg.l31.e12", "pool": "lesson", "lessonId": "eg.l31", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.que