insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l32.e10', 'eg', 'eg.l32', 'eg.g28.concile_de_nicee', array['eg.g28.concile_de_nicee','eg.v.homoousios','eg.v.concile_de_nicee','eg.v.homoousios']::text[], 'mcq', 'lesson', 'Que définit le concile de Nicée à propos du Fils ?', array['Il a la même substance que le Père']::text[], 'Nicée affirme que le Fils est de même substance que le Père. Les autres formules sont des positions ariennes ou semi-ariennes.', 2, '{"unitIds": ["eg.g28.concile_de_nicee", "eg.v.homoousios", "eg.v.concile_de_nicee", "eg.v.homoousios"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que définit le concile de Nicée à propos du Fils ?", "promptLanguage": "fr", "options": ["Il a la même substance que le Père", "Il a une substance créée", "Il a une substance similaire à celle du Père", "Il est inférieur au Père"], "answer": "Il a la même substance que le Père", "acceptedAnswers": ["Il a la même substance que le Père"], "explanation": "Nicée affirme que le Fils est de même substance que le Père. Les autres formules sont des positions ariennes ou semi-ariennes.", "tip": "Nicée = homoousios.", "extraExample": {"text": "Basile, Grégoire et Cyrille : trois noms de liturgies que l''on entend dans l''Église copte.", "translation": "Ces saints ne sont pas seulement dans les livres : leurs prières sont dans ta messe."}, "id": "eg.l32.e10", "pool": "lesson", "lessonId": "eg.l32", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.diffic