insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l32.e17', 'eg', 'eg.l32', 'eg.g32.bilan_du_siecle', array['eg.g32.bilan_du_siecle','eg.v.saint_ambroise_de_milan']::text[], 'fill_blank', 'lesson', 'Saint Ambroise est évêque de ___.', array['Milan']::text[], 'Ambroise est évêque de Milan, en Occident.', 2, '{"unitIds": ["eg.g32.bilan_du_siecle", "eg.v.saint_ambroise_de_milan"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Saint Ambroise est évêque de ___.", "promptLanguage": "fr", "options": ["Milan", "Hippone", "Antioche", "Nazianze"], "answer": "Milan", "acceptedAnswers": ["Milan"], "explanation": "Ambroise est évêque de Milan, en Occident.", "tip": "Ambroise-Milan.", "extraExample": {"text": "Augustin devient chrétien grâce à la prédication d''Ambroise à Milan.", "translation": "Un évêque convaincant peut changer la vie d''un des plus grands penseurs chrétiens."}, "id": "eg.l32.e17", "pool": "lesson", "lessonId": "eg.l32", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
