insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l35.e17', 'eg', 'eg.l35', 'eg.g35.cyrille', array['eg.g35.cyrille','eg.v.pilier_de_la_foi']::text[], 'free_answer', 'lesson', 'Quel surnom porte Cyrille dans l''Église copte ?', array['le Pilier de la foi','Pilier de la foi']::text[], 'On l''appelle le Pilier de la foi.', 2, '{"id": "eg.l35.e17", "unitIds": ["eg.g35.cyrille", "eg.v.pilier_de_la_foi"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Quel surnom porte Cyrille dans l''Église copte ?", "promptLanguage": "fr", "answer": "le Pilier de la foi", "acceptedAnswers": ["le Pilier de la foi", "Pilier de la foi"], "explanation": "On l''appelle le Pilier de la foi.", "tip": "Pilier = Cyrille.", "extraExample": {"text": "Il a soutenu la foi.", "translation": "Contre Nestorius."}, "pool": "lesson", "lessonId": "eg.l35", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
