insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l35.e19', 'eg', 'eg.l35', 'eg.g35.cyrille', array['eg.g35.cyrille','eg.v.formule_de_cyrille']::text[], 'free_answer', 'lesson', 'Complète la formule de Cyrille : « une seule nature du Verbe ... »', array['incarné','Verbe incarné','Dieu le Verbe incarné']::text[], 'La formule de Cyrille est « une seule nature du Verbe incarné ».', 3, '{"id": "eg.l35.e19", "unitIds": ["eg.g35.cyrille", "eg.v.formule_de_cyrille"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Complète la formule de Cyrille : « une seule nature du Verbe ... »", "promptLanguage": "fr", "answer": "incarné", "acceptedAnswers": ["incarné", "Verbe incarné", "Dieu le Verbe incarné"], "explanation": "La formule de Cyrille est « une seule nature du Verbe incarné ».", "tip": "Incarné = fait chair.", "extraExample": {"text": "Le Verbe devient chair.", "translation": "Incarnation."}, "pool": "lesson", "lessonId": "eg.l35", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l36.e01', 'eg', 'eg.l36', 'eg.g36.ephese_431', array['eg.g36.ephese_431','eg.v.concile_ephese_431','eg.v.ephese']::text[], 'mcq', 'lesson', 'En quelle année se tient le concile d''Éphèse ?', array['431']::text[], 'Éphèse est le troisième concile œcuménique, en 431.', 1, '{"id": "eg.l36.e01", "unitIds": ["eg.g36.ephese_431", "eg.v.concile_ephese_431", "eg.v.ephese"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "En quelle année se tient le concile d''Éphèse ?", "promptLanguage": "fr", "options": ["431", "325", "381", "451"], "answer": "431", "acceptedAnswers": ["431"], "explanation": "Éphèse est le troisième concile œcuménique, en 431.", "tip": "325, 381, 431.", "extraExample": {"text": "Chalcédoine suit en 451.", "translation": "Vingt ans plus tard."}, "pool": "lesson", "lessonId": "eg.l36", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l36.e02', 'eg', 'eg.l36', 'eg.g36.ephese_431', array['eg.g36.ephese_431','eg.v.theodose_ii']::text[], 'mcq', 'lesson', 'Quel empereur convoque le concile d''Éphèse ?', array['Théodose II']::text[], 'Théodose II, petit-fils de Théodose Ier, réunit les évêques à Éphèse. Marcien conviendra Chalcédoine.', 1, '{"id": "eg.l36.e02", "unitIds": ["eg.g36.ephese_431", "eg.v.theodose_ii"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel empereur convoque le concile d''Éphèse ?", "promptLanguage": "fr", "options": ["Théodose II", "Constantin", "Marcien", "Zénon"], "answer": "Théodose II", "acceptedAnswers": ["Théodose II"], "explanation": "Théodose II, petit-fils de Théodose Ier, réunit les évêques à Éphèse. Marcien conviendra Chalcédoine.", "tip": "Théodose II : Éphèse ; Marcien : Chalcédoine.", "extraExample": {"text": "Il convoquera aussi Éphèse II en 449.", "translation": "Deux Éphèse sous un même empereur."}, "pool": "lesson", "lessonId": "eg.l36", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l36.e03', 'eg', 'eg.l36', 'eg.g36.ephese_431', array['eg.g36.ephese_431','eg.v.cyrille_d_alexandrie']::text[], 'mcq', 'lesson', 'Qui préside le concile d''Éphèse ?', array['Cyrille d''Alexandrie']::text[], 'Cyrille préside, avec l''appui de Rome.', 1, '{"id": "eg.l36.e03", "unitIds": ["eg.g36.ephese_431", "eg.v.cyrille_d_alexandrie"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Qui préside le concile d''Éphèse ?", "promptLanguage": "fr", "options": ["Cyrille d''Alexandrie", "Nestorius", "Jean d''Antioche", "Flavien"], "answer": "Cyrille d''Alexandrie", "acceptedAnswers": ["Cyrille d''Alexandrie"], "explanation": "Cyrille préside, avec l''appui de Rome.", "tip": "Cyrille = Éphèse.", "extraExample": {"text": "Alexandrie est chef de file.", "translation": "Comme à Nicée."}, "pool": "lesson", "lessonId": "eg.l36", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l36.e04', 'eg', 'eg.l36', 'eg.g36.ephese_431', array['eg.g36.ephese_431','eg.v.nestorius']::text[], 'mcq', 'lesson', 'Pourquoi Nestorius est-il condamné sans être entendu au concile ?', array['Il refuse de comparaître']::text[], 'Nestorius ne vient pas devant les évêques qui le jugent.', 2, '{"id": "eg.l36.e04", "unitIds": ["eg.g36.ephese_431", "eg.v.nestorius"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi Nestorius est-il condamné sans être entendu au concile ?", "promptLanguage": "fr", "options": ["Il refuse de comparaître", "Il est déjà mort", "Il est empereur", "Il n''a pas été invité"], "answer": "Il refuse de comparaître", "acceptedAnswers": ["Il refuse de comparaître"], "explanation": "Nestorius ne vient pas devant les évêques qui le jugent.", "tip": "Il refuse, ils jugent.", "extraExample": {"text": "Il est donc condamné.", "translation": "Et déposé."}, "pool": "lesson", "lessonId": "eg.l36", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
