insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l36.e10', 'eg', 'eg.l36', 'eg.g34.nestorius', array['eg.g34.nestorius','eg.v.nestorianisme']::text[], 'mcq', 'lesson', 'Quelle doctrine est condamnée à Éphèse en 431 ?', array['Le nestorianisme']::text[], 'Rappel : le nestorianisme sépare le Verbe et l''homme Jésus.', 2, '{"id": "eg.l36.e10", "unitIds": ["eg.g34.nestorius", "eg.v.nestorianisme"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle doctrine est condamnée à Éphèse en 431 ?", "promptLanguage": "fr", "options": ["Le nestorianisme", "L''arianisme", "Le monophysisme", "Le catholicisme"], "answer": "Le nestorianisme", "acceptedAnswers": ["Le nestorianisme"], "explanation": "Rappel : le nestorianisme sépare le Verbe et l''homme Jésus.", "tip": "Éphèse = nestorianisme.", "extraExample": {"text": "Nicée = arianisme.", "translation": "Deux conciles, deux erreurs."}, "pool": "lesson", "lessonId": "eg.l36", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
