insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l37.e02', 'eg', 'eg.l37', 'eg.g37.apres_ephese', array['eg.g37.apres_ephese','eg.v.formule_d_union']::text[], 'mcq', 'lesson', 'Qu''accepte Jean d''Antioche dans la formule d''union ?', array['la déposition de Nestorius et le titre Théotokos']::text[], 'Jean cède sur Nestorius et sur Théotokos, Cyrille cède sur le vocabulaire.', 2, '{"id": "eg.l37.e02", "unitIds": ["eg.g37.apres_ephese", "eg.v.formule_d_union"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qu''accepte Jean d''Antioche dans la formule d''union ?", "promptLanguage": "fr", "options": ["la déposition de Nestorius et le titre Théotokos", "les douze anathèmes", "la formule du Tome", "le canon 28"], "answer": "la déposition de Nestorius et le titre Théotokos", "acceptedAnswers": ["la déposition de Nestorius et le titre Théotokos"], "explanation": "Jean cède sur Nestorius et sur Théotokos, Cyrille cède sur le vocabulaire.", "tip": "Chacun fait un pas.", "extraExample": {"text": "Cyrille adopte un vocabulaire plus nuancé.", "translation": "Pour la paix."}, "pool": "lesson", "lessonId": "eg.l37", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l37.e03', 'eg', 'eg.l37', 'eg.g37.apres_ephese', array['eg.g37.apres_ephese','eg.v.formule_d_union']::text[], 'mcq', 'lesson', 'Pourquoi la paix de 433 reste-t-elle fragile ?', array['La question « une ou deux natures ? » reste ouverte']::text[], 'Le compromis ne tranche pas la question des natures.', 2, '{"id": "eg.l37.e03", "unitIds": ["eg.g37.apres_ephese", "eg.v.formule_d_union"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi la paix de 433 reste-t-elle fragile ?", "promptLanguage": "fr", "options": ["La question « une ou deux natures ? » reste ouverte", "Cyrille est exilé", "Éphèse est annulé", "Rome refuse"], "answer": "La question « une ou deux natures ? » reste ouverte", "acceptedAnswers": ["La question « une ou deux natures ? » reste ouverte"], "explanation": "Le compromis ne tranche pas la question des natures.", "tip": "Compromis ≠ solution.", "extraExample": {"text": "Eutychès et Chalcédoine reviendront dessus.", "translation": "Quinze ans plus tard."}, "pool": "lesson", "lessonId": "eg.l37", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l37.e04', 'eg', 'eg.l37', 'eg.g37.apres_ephese', array['eg.g37.apres_ephese','eg.v.perse']::text[], 'mcq', 'lesson', 'Où partent beaucoup de partisans de Nestorius ?', array['En Perse']::text[], 'Ils quittent l''Empire romain pour le royaume voisin à l''est.', 1, '{"id": "eg.l37.e04", "unitIds": ["eg.g37.apres_ephese", "eg.v.perse"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Où partent beaucoup de partisans de Nestorius ?", "promptLanguage": "fr", "options": ["En Perse", "À Rome", "À Alexandrie", "En Éthiopie"], "answer": "En Perse", "acceptedAnswers": ["En Perse"], "explanation": "Ils quittent l''Empire romain pour le royaume voisin à l''est.", "tip": "Perse = hors de l''Empire.", "extraExample": {"text": "Là naît l''Église de l''Orient.", "translation": "Elle existe encore."}, "pool": "lesson", "lessonId": "eg.l37", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l37.e05', 'eg', 'eg.l37', 'eg.g37.apres_ephese', array['eg.g37.apres_ephese','eg.v.eglise_de_l_orient']::text[], 'mcq', 'lesson', 'Quel nom porte l''Église née en Perse chez les partisans de Nestorius ?', array['l''Église de l''Orient']::text[], 'Elle adopte la théologie nestorienne et ne reconnaît pas Éphèse.', 2, '{"id": "eg.l37.e05", "unitIds": ["eg.g37.apres_ephese", "eg.v.eglise_de_l_orient"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel nom porte l''Église née en Perse chez les partisans de Nestorius ?", "promptLanguage": "fr", "options": ["l''Église de l''Orient", "l''Église copte", "l''Église melkite", "l''Église arménienne"], "answer": "l''Église de l''Orient", "acceptedAnswers": ["l''Église de l''Orient"], "explanation": "Elle adopte la théologie nestorienne et ne reconnaît pas Éphèse.", "tip": "Nestorius → Perse → Église de l''Orient.", "extraExample": {"text": "Ce n''est pas l''Église copte.", "translation": "Ni une Église sœur."}, "pool": "lesson", "lessonId": "eg.l37", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
