insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l37.e16', 'eg', 'eg.l37', 'eg.g37.apres_ephese', array['eg.g37.apres_ephese','eg.v.eglise_de_l_orient']::text[], 'match', 'lesson', 'Lieux, Églises et personnages', '{}'::text[], 'Chaque élément a son lieu et son rôle.', 2, '{"id": "eg.l37.e16", "unitIds": ["eg.g37.apres_ephese", "eg.v.eglise_de_l_orient"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Lieux, Églises et personnages", "promptLanguage": "fr", "pairs": [{"left": "l''Église de l''Orient", "right": "née en Perse"}, {"left": "Flavien", "right": "patriarche de Constantinople"}, {"left": "Dioscore", "right": "25e pape d''Alexandrie"}, {"left": "la Perse", "right": "royaume voisin de l''Empire"}], "answer": "l''Église de l''Orient = née en Perse ; Flavien = patriarche de Constantinople ; Dioscore = 25e pape d''Alexandrie ; la Perse = royaume voisin de l''Empire", "acceptedAnswers": [], "explanation": "Chaque élément a son lieu et son rôle.", "tip": "Chaque nom a son siège.", "extraExample": {"text": "Personnages et lieux.", "translation": "La suite arrive."}, "pool": "lesson", "lessonId": "eg.l37", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
