insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l38.e01', 'eg', 'eg.l38', 'eg.g38.eutyches', array['eg.g38.eutyches','eg.v.eutyches']::text[], 'mcq', 'lesson', 'Qui est Eutychès ?', array['archimandrite d''un monastère près de Constantinople']::text[], 'Il dirige un monastère et jouit d''une grande autorité.', 1, '{"id": "eg.l38.e01", "unitIds": ["eg.g38.eutyches", "eg.v.eutyches"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Qui est Eutychès ?", "promptLanguage": "fr", "options": ["archimandrite d''un monastère près de Constantinople", "évêque d''Antioche", "empereur d''Orient", "diacre d''Alexandrie"], "answer": "archimandrite d''un monastère près de Constantinople", "acceptedAnswers": ["archimandrite d''un monastère près de Constantinople"], "explanation": "Il dirige un monastère et jouit d''une grande autorité.", "tip": "Eutychès = moine, pas évêque.", "extraExample": {"text": "Un archimandrite est un chef de monastère.", "translation": "Il est donc respecté."}, "pool": "lesson", "lessonId": "eg.l38", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
