insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l38.e03', 'eg', 'eg.l38', 'eg.g38.eutyches', array['eg.g38.eutyches','eg.v.monophysisme']::text[], 'mcq', 'lesson', 'Que croit Eutychès sur la nature du Christ ?', array['Jésus n''a qu''une seule nature, la divine']::text[], 'Pour lui, après l''union il n''y a plus que la nature divine.', 2, '{"id": "eg.l38.e03", "unitIds": ["eg.g38.eutyches", "eg.v.monophysisme"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que croit Eutychès sur la nature du Christ ?", "promptLanguage": "fr", "options": ["Jésus n''a qu''une seule nature, la divine", "Jésus a deux personnes", "Jésus n''est qu''un homme", "Jésus n''est pas né"], "answer": "Jésus n''a qu''une seule nature, la divine", "acceptedAnswers": ["Jésus n''a qu''une seule nature, la divine"], "explanation": "Pour lui, après l''union il n''y a plus que la nature divine.", "tip": "Mono = un.", "extraExample": {"text": "Cette erreur s''appelle le monophysisme.", "translation": "Du grec mono et physis."}, "pool": "lesson", "lessonId": "eg.l38", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l38.e04', 'eg', 'eg.l38', 'eg.g38.eutyches', array['eg.g38.eutyches','eg.v.humanite_absorbee']::text[], 'mcq', 'lesson', 'Quelle image Eutychès utilise-t-il pour l''humanité du Christ ?', array['une goutte de miel dans la mer']::text[], 'Elle se mélange à l''eau de mer et disparaît.', 2, '{"id": "eg.l38.e04", "unitIds": ["eg.g38.eutyches", "eg.v.humanite_absorbee"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle image Eutychès utilise-t-il pour l''humanité du Christ ?", "promptLanguage": "fr", "options": ["une goutte de miel dans la mer", "une flamme dans une lampe", "un grain de blé", "un pilier dans un temple"], "answer": "une goutte de miel dans la mer", "acceptedAnswers": ["une goutte de miel dans la mer"], "explanation": "Elle se mélange à l''eau de mer et disparaît.", "tip": "Miel = humanité ; mer = divinité.", "extraExample": {"text": "Cette image est fausse pour l''Église copte.", "translation": "Elle supprime l''humanité."}, "pool": "lesson", "lessonId": "eg.l38", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l38.e05', 'eg', 'eg.l38', 'eg.g38.eutyches', array['eg.g38.eutyches','eg.v.eutyches']::text[], 'mcq', 'lesson', 'Quelle erreur est l''inverse de celle de Nestorius ?', array['mélanger les natures']::text[], 'Nestorius sépare le Verbe et l''homme Jésus ; Eutychès mélange tout.', 2, '{"id": "eg.l38.e05", "unitIds": ["eg.g38.eutyches", "eg.v.eutyches"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle erreur est l''inverse de celle de Nestorius ?", "promptLanguage": "fr", "options": ["mélanger les natures", "séparer les natures", "nier la divinité du Christ", "nier la Trinité"], "answer": "mélanger les natures", "acceptedAnswers": ["mélanger les natures"], "explanation": "Nestorius sépare le Verbe et l''homme Jésus ; Eutychès mélange tout.", "tip": "Séparer ≠ mélanger.", "extraExample": {"text": "Les deux erreurs sont opposées.", "translation": "Cyrille tient les deux bouts."}, "errorPatterns": [{"equals": "séparer les natures", "category": "word_confusion", "feedback": "C''est l''erreur de Nestorius, pas d''Eutychès."}], "pool": "lesson", "lessonId": "eg.l38", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l38.e06', 'eg', 'eg.l38', 'eg.g38.eutyches', array['eg.g38.eutyches','eg.v.humanite_absorbee']::text[], 'mcq', 'lesson', 'Pourquoi l''idée d''une humanité absorbée est-elle grave ?', array['Jésus ne serait plus vraiment homme comme nous']::text[], 'Si l''humanité disparaît, le Christ ne partage plus notre condition et ne nous sauve plus.', 3, '{"id": "eg.l38.e06", "unitIds": ["eg.g38.eutyches", "eg.v.humanite_absorbee"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi l''idée d''une humanité absorbée est-elle grave ?", "promptLanguage": "fr", "options": ["Jésus ne serait plus vraiment homme comme nous", "Marie ne serait plus sa mère", "L''empereur perdrait son pouvoir", "Le baptême serait inutile"], "answer": "Jésus ne serait plus vraiment homme comme nous", "acceptedAnswers": ["Jésus ne serait plus vraiment homme comme nous"], "explanation": "Si l''humanité disparaît, le Christ ne partage plus notre condition et ne nous sauve plus.", "tip": "Pas d''humanité, pas de salut.", "extraExample": {"text": "Cyrille garde l''humanité pleine.", "translation": "Complètement homme."}, "pool": "lesson", "lessonId": "eg.l38", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l38.e07', 'eg', 'eg.l38', 'eg.g38.eutyches', array['eg.g38.eutyches','eg.v.synode_de_constantinople_448']::text[], 'mcq', 'lesson', 'Qui préside le synode de Constantinople de 448 ?', array['Flavien']::text[], 'Flavien est le patriarche de Constantinople.', 1, '{"id": "eg.l38.e07", "unitIds": ["eg.g38.eutyches", "eg.v.synode_de_constantinople_448"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Qui préside le synode de Constantinople de 448 ?", "promptLanguage": "fr", "options": ["Flavien", "Dioscore", "Cyrille", "Léon Ier"], "answer": "Flavien", "acceptedAnswers": ["Flavien"], "explanation": "Flavien est le patriarche de Constantinople.", "tip": "Flavien, nouvelle Rome.", "extraExample": {"text": "Il condamne Eutychès.", "translation": "Il l''excommunie."}, "pool": "lesson", "lessonId": "eg.l38", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l38.e08', 'eg', 'eg.l38', 'eg.g38.eutyches', array['eg.g38.eutyches','eg.v.synode_de_constantinople_448']::text[], 'mcq', 'lesson', 'Que fait Eutychès après sa condamnation ?', array['fait appel à l''empereur Théodose II']::text[], 'Frustré, il s''adresse à l''empereur et aux autres sièges, surtout Alexandrie.', 2, '{"id": "eg.l38.e08", "unitIds": ["eg.g38.eutyches", "eg.v.synode_de_constantinople_448"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que fait Eutychès après sa condamnation ?", "promptLanguage": "fr", "options": ["fait appel à l''empereur Théodose II", "part en Perse", "se soumet", "devient pape"], "answer": "fait appel à l''empereur Théodose II", "acceptedAnswers": ["fait appel à l''empereur Théodose II"], "explanation": "Frustré, il s''adresse à l''empereur et aux autres sièges, surtout Alexandrie.", "tip": "Appel à l''empereur.", "extraExample": {"text": "Théodose II fait confiance à Alexandrie.", "translation": "Il convoque un concile."}, "pool": "lesson", "lessonId": "eg.l38", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l38.e09', 'eg', 'eg.l38', 'eg.g38.eutyches', array['eg.g38.eutyches','eg.v.synode_de_constantinople_448']::text[], 'mcq', 'lesson', 'Où et quand l''empereur convoque-t-il le nouveau concile ?', array['À Éphèse, le 1er août 449']::text[], 'Théodose II convoque un concile à Éphèse pour le 1er août 449.', 2, '{"id": "eg.l38.e09", "unitIds": ["eg.g38.eutyches", "eg.v.synode_de_constantinople_448"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Où et quand l''empereur convoque-t-il le nouveau concile ?", "promptLanguage": "fr", "options": ["À Éphèse, le 1er août 449", "À Nicée, en 325", "À Chalcédoine, en 451", "À Antioche, en 433"], "answer": "À Éphèse, le 1er août 449", "acceptedAnswers": ["À Éphèse, le 1er août 449"], "explanation": "Théodose II convoque un concile à Éphèse pour le 1er août 449.", "tip": "449 = Éphèse II.", "extraExample": {"text": "C''est le second concile d''Éphèse.", "translation": "Dioscore le préside."}, "pool": "lesson", "lessonId": "eg.l38", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
