insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l38.e16', 'eg', 'eg.l38', 'eg.g38.eutyches', array['eg.g38.eutyches','eg.v.eutyches']::text[], 'match', 'lesson', 'Qui défend ou combat quoi ?', '{}'::text[], 'Chacun a une position : séparer, mélanger, unir, juger.', 2, '{"id": "eg.l38.e16", "unitIds": ["eg.g38.eutyches", "eg.v.eutyches"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Qui défend ou combat quoi ?", "promptLanguage": "fr", "pairs": [{"left": "Nestorius", "right": "sépare le Verbe et l''homme Jésus"}, {"left": "Eutychès", "right": "l''humanité absorbée par la divinité"}, {"left": "Cyrille", "right": "un seul Christ, Dieu et homme"}, {"left": "Flavien", "right": "condamne Eutychès en 448"}], "answer": "Nestorius = sépare le Verbe et l''homme Jésus ; Eutychès = l''humanité absorbée par la divinité ; Cyrille = un seul Christ, Dieu et homme ; Flavien = condamne Eutychès en 448", "acceptedAnswers": [], "explanation": "Chacun a une position : séparer, mélanger, unir, juger.", "tip": "Sépare, mélange, unit, juge.", "extraExample": {"text": "Quatre rôles.", "translation": "Quatre positions."}, "pool": "lesson", "lessonId": "eg.l38", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l38.e17', 'eg', 'eg.l38', 'eg.g38.eutyches', array['eg.g38.eutyches','eg.v.monophysisme']::text[], 'match', 'lesson', 'Du vocabulaire', '{}'::text[], 'Quatre termes clés de la leçon.', 2, '{"id": "eg.l38.e17", "unitIds": ["eg.g38.eutyches", "eg.v.monophysisme"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Du vocabulaire", "promptLanguage": "fr", "pairs": [{"left": "monophysisme", "right": "une seule nature, la divine"}, {"left": "archimandrite", "right": "chef de monastère"}, {"left": "synode de 448", "right": "condamne Eutychès"}, {"left": "goutte de miel", "right": "l''humanité absorbée"}], "answer": "monophysisme = une seule nature, la divine ; archimandrite = chef de monastère ; synode de 448 = condamne Eutychès ; goutte de miel = l''humanité absorbée", "acceptedAnswers": [], "explanation": "Quatre termes clés de la leçon.", "tip": "Un mot, une idée.", "extraExample": {"text": "Termes à retenir.", "translation": "Pour la suite."}, "pool": "lesson", "lessonId": "eg.l38", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
