insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l40.e03', 'eg', 'eg.l40', 'eg.g40.chalcedoine', array['eg.g40.chalcedoine','eg.v.chalcedoine']::text[], 'mcq', 'lesson', 'Où se trouve Chalcédoine ?', array['en face de Constantinople']::text[], 'Chalcédoine est une ville d''Asie Mineure sur le Bosphore.', 1, '{"id": "eg.l40.e03", "unitIds": ["eg.g40.chalcedoine", "eg.v.chalcedoine"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Où se trouve Chalcédoine ?", "promptLanguage": "fr", "options": ["en face de Constantinople", "en Égypte", "en Perse", "à Rome"], "answer": "en face de Constantinople", "acceptedAnswers": ["en face de Constantinople"], "explanation": "Chalcédoine est une ville d''Asie Mineure sur le Bosphore.", "tip": "En face de la capitale.", "extraExample": {"text": "Près de l''empereur.", "translation": "Facile à surveiller."}, "pool": "lesson", "lessonId": "eg.l40", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l40.e04', 'eg', 'eg.l40', 'eg.g40.chalcedoine', array['eg.g40.chalcedoine','eg.v.tome_de_leon']::text[], 'mcq', 'lesson', 'Quel texte est lu puis ratifié à Chalcédoine ?', array['le Tome de Léon']::text[], 'Il n''avait pas été lu à Éphèse II ; cette fois il est ratifié.', 1, '{"id": "eg.l40.e04", "unitIds": ["eg.g40.chalcedoine", "eg.v.tome_de_leon"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel texte est lu puis ratifié à Chalcédoine ?", "promptLanguage": "fr", "options": ["le Tome de Léon", "le credo de Nicée", "les douze anathèmes", "la formule d''union"], "answer": "le Tome de Léon", "acceptedAnswers": ["le Tome de Léon"], "explanation": "Il n''avait pas été lu à Éphèse II ; cette fois il est ratifié.", "tip": "Tome lu en 451.", "extraExample": {"text": "Il parle de deux natures.", "translation": "Cyrille parlait d''une."}, "pool": "lesson", "lessonId": "eg.l40", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l40.e05', 'eg', 'eg.l40', 'eg.g40.chalcedoine', array['eg.g40.chalcedoine','eg.v.definition_de_chalcedoine']::text[], 'mcq', 'lesson', 'Que définit le concile de Chalcédoine ?', array['un seul Christ reconnu en deux natures']::text[], 'La définition distingue les deux natures après l''union.', 2, '{"id": "eg.l40.e05", "unitIds": ["eg.g40.chalcedoine", "eg.v.definition_de_chalcedoine"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que définit le concile de Chalcédoine ?", "promptLanguage": "fr", "options": ["un seul Christ reconnu en deux natures", "une seule nature divine", "trois personnes", "deux Christs"], "answer": "un seul Christ reconnu en deux natures", "acceptedAnswers": ["un seul Christ reconnu en deux natures"], "explanation": "La définition distingue les deux natures après l''union.", "tip": "Un Christ, deux natures.", "extraExample": {"text": "C''est le point de rupture.", "translation": "Avec l''Église copte."}, "pool": "lesson", "lessonId": "eg.l40", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l40.e06', 'eg', 'eg.l40', 'eg.g40.chalcedoine', array['eg.g40.chalcedoine','eg.v.deux_natures']::text[], 'mcq', 'lesson', 'Quelle formule de Chalcédoine l''Église copte ne reprend-elle pas ?', array['en deux natures']::text[], 'L''Église copte confesse « une seule nature du Verbe incarné ».', 2, '{"id": "eg.l40.e06", "unitIds": ["eg.g40.chalcedoine", "eg.v.deux_natures"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle formule de Chalcédoine l''Église copte ne reprend-elle pas ?", "promptLanguage": "fr", "options": ["en deux natures", "un seul Christ", "vrai Dieu", "vrai homme"], "answer": "en deux natures", "acceptedAnswers": ["en deux natures"], "explanation": "L''Église copte confesse « une seule nature du Verbe incarné ».", "tip": "Deux natures ≠ une nature du Verbe.", "extraExample": {"text": "Elle confesse aussi un Christ Dieu et homme.", "translation": "Le désaccord est sur les mots."}, "pool": "lesson", "lessonId": "eg.l40", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l40.e07', 'eg', 'eg.l40', 'eg.g40.chalcedoine', array['eg.g40.chalcedoine','eg.v.concile_chalcedoine']::text[], 'mcq', 'lesson', 'Que subit Dioscore à Chalcédoine ?', array['condamné pour sa conduite à Éphèse II et exilé']::text[], 'Il est condamné pour sa conduite à Éphèse II et exilé.', 2, '{"id": "eg.l40.e07", "unitIds": ["eg.g40.chalcedoine", "eg.v.concile_chalcedoine"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que subit Dioscore à Chalcédoine ?", "promptLanguage": "fr", "options": ["condamné pour sa conduite à Éphèse II et exilé", "élu pape", "canonisé", "réhabilité"], "answer": "condamné pour sa conduite à Éphèse II et exilé", "acceptedAnswers": ["condamné pour sa conduite à Éphèse II et exilé"], "explanation": "Il est condamné pour sa conduite à Éphèse II et exilé.", "tip": "Dioscore condamné.", "extraExample": {"text": "Il refuse de signer.", "translation": "Selon la tradition copte."}, "pool": "lesson", "lessonId": "eg.l40", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
