insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l40.e16', 'eg', 'eg.l40', 'eg.g40.chalcedoine', array['eg.g40.chalcedoine','eg.v.concile_chalcedoine']::text[], 'match', 'lesson', 'Trois conciles, trois décisions', '{}'::text[], 'Chaque concile a son enjeu.', 2, '{"id": "eg.l40.e16", "unitIds": ["eg.g40.chalcedoine", "eg.v.concile_chalcedoine"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Trois conciles, trois décisions", "promptLanguage": "fr", "pairs": [{"left": "Éphèse (431)", "right": "Marie Théotokos"}, {"left": "Éphèse II (449)", "right": "Flavien est déposé"}, {"left": "Chalcédoine (451)", "right": "un seul Christ en deux natures"}], "answer": "Éphèse (431) = Marie Théotokos ; Éphèse II (449) = Flavien est déposé ; Chalcédoine (451) = un seul Christ en deux natures", "acceptedAnswers": [], "explanation": "Chaque concile a son enjeu.", "tip": "431, 449, 451.", "extraExample": {"text": "Le Ve siècle en trois dates.", "translation": "Une ligne de crête."}, "pool": "lesson", "lessonId": "eg.l40", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
