insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l41.e03', 'eg', 'eg.l41', 'eg.g41.dioscore', array['eg.g41.dioscore','eg.v.accusations_contre_dioscore']::text[], 'mcq', 'lesson', 'Quelle est la première accusation contre Dioscore ?', array['avoir accepté l''hérésie d''Eutychès']::text[], 'On lui reproche d''avoir fait siennes les idées d''Eutychès.', 2, '{"id": "eg.l41.e03", "unitIds": ["eg.g41.dioscore", "eg.v.accusations_contre_dioscore"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle est la première accusation contre Dioscore ?", "promptLanguage": "fr", "options": ["avoir accepté l''hérésie d''Eutychès", "avoir exilé Cyrille", "avoir ajouté un canon", "avoir ordonné Nestorius"], "answer": "avoir accepté l''hérésie d''Eutychès", "acceptedAnswers": ["avoir accepté l''hérésie d''Eutychès"], "explanation": "On lui reproche d''avoir fait siennes les idées d''Eutychès.", "tip": "Eutychès, Flavien, Tome.", "extraExample": {"text": "La tradition copte conteste cette accusation.", "translation": "Il enseigne que le Christ est UN."}, "pool": "lesson", "lessonId": "eg.l41", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l41.e04', 'eg', 'eg.l41', 'eg.g41.dioscore', array['eg.g41.dioscore','eg.v.accusations_contre_dioscore']::text[], 'mcq', 'lesson', 'Que répond la tradition copte à l''accusation d''avoir adopté l''erreur d''Eutychès ?', array['Dioscore enseigne que le Christ est UN']::text[], 'Dioscore suit Cyrille : un seul Christ, Dieu et homme.', 3, '{"id": "eg.l41.e04", "unitIds": ["eg.g41.dioscore", "eg.v.accusations_contre_dioscore"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Que répond la tradition copte à l''accusation d''avoir adopté l''erreur d''Eutychès ?", "promptLanguage": "fr", "options": ["Dioscore enseigne que le Christ est UN", "Dioscore enseigne que le Christ n''a qu''une nature divine", "Dioscore n''a jamais rencontré Eutychès", "Dioscore a changé le credo"], "answer": "Dioscore enseigne que le Christ est UN", "acceptedAnswers": ["Dioscore enseigne que le Christ est UN"], "explanation": "Dioscore suit Cyrille : un seul Christ, Dieu et homme.", "tip": "UN, pas absorbé.", "extraExample": {"text": "Eutychès disait l''humanité absorbée.", "translation": "Pas Dioscore."}, "pool": "lesson", "lessonId": "eg.l41", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l41.e05', 'eg', 'eg.l41', 'eg.g41.dioscore', array['eg.g41.dioscore','eg.v.accusations_contre_dioscore']::text[], 'mcq', 'lesson', 'Pourquoi Dioscore a-t-il déposé Flavien, selon la tradition copte ?', array['Flavien avait enfreint Nicée et Éphèse I']::text[], 'Il avait défini le mode de la double nature, ce que Nicée et Éphèse I n''avaient pas fait.', 3, '{"id": "eg.l41.e05", "unitIds": ["eg.g41.dioscore", "eg.v.accusations_contre_dioscore"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi Dioscore a-t-il déposé Flavien, selon la tradition copte ?", "promptLanguage": "fr", "options": ["Flavien avait enfreint Nicée et Éphèse I", "Flavien avait refusé de venir", "Flavien était hérétique", "Flavien était empereur"], "answer": "Flavien avait enfreint Nicée et Éphèse I", "acceptedAnswers": ["Flavien avait enfreint Nicée et Éphèse I"], "explanation": "Il avait défini le mode de la double nature, ce que Nicée et Éphèse I n''avaient pas fait.", "tip": "Nicée et Éphèse I, c''est la règle.", "extraExample": {"text": "Le credo ne bouge pas.", "translation": "Éphèse l''a interdit."}, "pool": "lesson", "lessonId": "eg.l41", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l41.e06', 'eg', 'eg.l41', 'eg.g41.dioscore', array['eg.g41.dioscore','eg.v.concile_chalcedoine']::text[], 'mcq', 'lesson', 'Pour quelles raisons Dioscore est-il déposé, selon les actes de Chalcédoine ?', array['pour ses fautes de conduite et pour avoir refusé de comparaître, non pour une hérésie']::text[], 'Le concile lui-même ne le juge pas hérétique.', 3, '{"id": "eg.l41.e06", "unitIds": ["eg.g41.dioscore", "eg.v.concile_chalcedoine"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Pour quelles raisons Dioscore est-il déposé, selon les actes de Chalcédoine ?", "promptLanguage": "fr", "options": ["pour ses fautes de conduite et pour avoir refusé de comparaître, non pour une hérésie", "pour hérésie monophysite", "pour avoir condamné Nestorius", "pour avoir signé la définition"], "answer": "pour ses fautes de conduite et pour avoir refusé de comparaître, non pour une hérésie", "acceptedAnswers": ["pour ses fautes de conduite et pour avoir refusé de comparaître, non pour une hérésie"], "explanation": "Le concile lui-même ne le juge pas hérétique.", "tip": "Conduite, pas dogme.", "extraExample": {"text": "L''Église copte le rappelle.", "translation": "Détail clé."}, "pool": "lesson", "lessonId": "eg.l41", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l41.e07', 'eg', 'eg.l41', 'eg.g41.dioscore', array['eg.g41.dioscore','eg.v.gangra']::text[], 'mcq', 'lesson', 'Où Dioscore est-il exilé ?', array['À Gangra']::text[], 'Une ville d''Asie Mineure, loin d''Alexandrie.', 1, '{"id": "eg.l41.e07", "unitIds": ["eg.g41.dioscore", "eg.v.gangra"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Où Dioscore est-il exilé ?", "promptLanguage": "fr", "options": ["À Gangra", "À Rome", "En Perse", "À Éphèse"], "answer": "À Gangra", "acceptedAnswers": ["À Gangra"], "explanation": "Une ville d''Asie Mineure, loin d''Alexandrie.", "tip": "Gangra = exil.", "extraExample": {"text": "Il y meurt en 454.", "translation": "Après trois ans."}, "pool": "lesson", "lessonId": "eg.l41", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l41.e08', 'eg', 'eg.l41', 'eg.g41.dioscore', array['eg.g41.dioscore','eg.v.gangra']::text[], 'mcq', 'lesson', 'En quelle année meurt Dioscore ?', array['454']::text[], 'Il meurt en exil, trois ans après Chalcédoine.', 1, '{"id": "eg.l41.e08", "unitIds": ["eg.g41.dioscore", "eg.v.gangra"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "En quelle année meurt Dioscore ?", "promptLanguage": "fr", "options": ["454", "451", "444", "461"], "answer": "454", "acceptedAnswers": ["454"], "explanation": "Il meurt en exil, trois ans après Chalcédoine.", "tip": "444 pape ; 454 mort.", "extraExample": {"text": "Dix ans de pontificat.", "translation": "444-454."}, "pool": "lesson", "lessonId": "eg.l41", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l41.e09', 'eg', 'eg.l41', 'eg.g41.dioscore', array['eg.g41.dioscore','eg.v.confesseur']::text[], 'mcq', 'lesson', 'Qu''est-ce qu''un confesseur de la foi ?', array['celui qui souffre pour sa foi sans mourir martyr']::text[], 'L''Église copte vénère Dioscore comme confesseur.', 2, '{"id": "eg.l41.e09", "unitIds": ["eg.g41.dioscore", "eg.v.confesseur"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qu''est-ce qu''un confesseur de la foi ?", "promptLanguage": "fr", "options": ["celui qui souffre pour sa foi sans mourir martyr", "celui qui écoute les confessions", "un martyr", "un évêque"], "answer": "celui qui souffre pour sa foi sans mourir martyr", "acceptedAnswers": ["celui qui souffre pour sa foi sans mourir martyr"], "explanation": "L''Église copte vénère Dioscore comme confesseur.", "tip": "Confesseur ≠ martyr.", "extraExample": {"text": "Il a souffert l''exil.", "translation": "Il n''est pas mort de persécution."}, "pool": "lesson", "lessonId": "eg.l41", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
