insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l42.e04', 'eg', 'eg.l42', 'eg.g42.miaphysisme', array['eg.g42.miaphysisme','eg.v.miaphysisme']::text[], 'mcq', 'lesson', 'Qui défend le monophysisme ?', array['Eutychès']::text[], 'Pour lui, l''humanité est absorbée par la divinité.', 1, '{"id": "eg.l42.e04", "unitIds": ["eg.g42.miaphysisme", "eg.v.miaphysisme"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Qui défend le monophysisme ?", "promptLanguage": "fr", "options": ["Eutychès", "Cyrille", "Nestorius", "Léon"], "answer": "Eutychès", "acceptedAnswers": ["Eutychès"], "explanation": "Pour lui, l''humanité est absorbée par la divinité.", "tip": "Mono = Eutychès.", "extraExample": {"text": "L''Église copte le condamne.", "translation": "Elle est miaphysite."}, "pool": "lesson", "lessonId": "eg.l42", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l42.e05', 'eg', 'eg.l42', 'eg.g42.miaphysisme', array['eg.g42.miaphysisme','eg.v.dyophysisme']::text[], 'mcq', 'lesson', 'Quelle position a été définie à Chalcédoine ?', array['le dyophysisme']::text[], 'Deux natures, chacune gardant son caractère.', 2, '{"id": "eg.l42.e05", "unitIds": ["eg.g42.miaphysisme", "eg.v.dyophysisme"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle position a été définie à Chalcédoine ?", "promptLanguage": "fr", "options": ["le dyophysisme", "le miaphysisme", "le monophysisme", "l''arianisme"], "answer": "le dyophysisme", "acceptedAnswers": ["le dyophysisme"], "explanation": "Deux natures, chacune gardant son caractère.", "tip": "Dyo = Chalcédoine.", "extraExample": {"text": "Rome et Constantinople la suivent.", "translation": "Les Églises chalcédoniennes."}, "pool": "lesson", "lessonId": "eg.l42", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l42.e06', 'eg', 'eg.l42', 'eg.g42.miaphysisme', array['eg.g42.miaphysisme','eg.v.miaphysisme']::text[], 'mcq', 'lesson', 'Quelle position confesse l''Église copte ?', array['le miaphysisme']::text[], 'Une seule nature du Verbe incarné, ni mélangée ni divisée.', 1, '{"id": "eg.l42.e06", "unitIds": ["eg.g42.miaphysisme", "eg.v.miaphysisme"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle position confesse l''Église copte ?", "promptLanguage": "fr", "options": ["le miaphysisme", "le monophysisme", "le dyophysisme", "le nestorianisme"], "answer": "le miaphysisme", "acceptedAnswers": ["le miaphysisme"], "explanation": "Une seule nature du Verbe incarné, ni mélangée ni divisée.", "tip": "Mia = Cyrille.", "extraExample": {"text": "Elle est parfois dite monophysite à tort.", "translation": "C''est faux."}, "errorPatterns": [{"equals": "le monophysisme", "category": "word_confusion", "feedback": "C''est la position d''Eutychès, que l''Église copte condamne."}], "pool": "lesson", "lessonId": "eg.l42", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l42.e07', 'eg', 'eg.l42', 'eg.g42.miaphysisme', array['eg.g42.miaphysisme','eg.v.sans_melange_ni_division']::text[], 'mcq', 'lesson', 'Dans le miaphysisme, le divin et l''humain sont…', array['ni mélangés ni divisés']::text[], 'On ne confond rien, on ne sépare rien.', 2, '{"id": "eg.l42.e07", "unitIds": ["eg.g42.miaphysisme", "eg.v.sans_melange_ni_division"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Dans le miaphysisme, le divin et l''humain sont…", "promptLanguage": "fr", "options": ["ni mélangés ni divisés", "mélangés", "séparés", "absorbés l''un par l''autre"], "answer": "ni mélangés ni divisés", "acceptedAnswers": ["ni mélangés ni divisés"], "explanation": "On ne confond rien, on ne sépare rien.", "tip": "Ni mélange, ni division.", "extraExample": {"text": "Chalcédoine dit aussi « sans confusion ».", "translation": "Les mots varient."}, "errorPatterns": [{"equals": "mélangés", "category": "word_confusion", "feedback": "Le mélange est l''erreur d''Eutychès."}, {"equals": "séparés", "category": "word_confusion", "feedback": "La séparation est l''erreur de Nestorius."}], "pool": "lesson", "lessonId": "eg.l42", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l42.e08', 'eg', 'eg.l42', 'eg.g42.miaphysisme', array['eg.g42.miaphysisme','eg.v.miaphysisme']::text[], 'mcq', 'lesson', 'Que dit l''Église copte, contrairement à Eutychès ?', array['l''humanité est complète, elle n''est ni absorbée ni séparée du divin']::text[], 'Même vocabulaire (« une nature »), sens opposé.', 3, '{"id": "eg.l42.e08", "unitIds": ["eg.g42.miaphysisme", "eg.v.miaphysisme"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Que dit l''Église copte, contrairement à Eutychès ?", "promptLanguage": "fr", "options": ["l''humanité est complète, elle n''est ni absorbée ni séparée du divin", "l''humanité n''existe plus", "la divinité est absorbée", "il n''y a qu''un homme"], "answer": "l''humanité est complète, elle n''est ni absorbée ni séparée du divin", "acceptedAnswers": ["l''humanité est complète, elle n''est ni absorbée ni séparée du divin"], "explanation": "Même vocabulaire (« une nature »), sens opposé.", "tip": "Absorbée ≠ complète.", "extraExample": {"text": "C''est la nuance de la leçon.", "translation": "Capitale."}, "pool": "lesson", "lessonId": "eg.l42", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
