insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l42.e16', 'eg', 'eg.l42', 'eg.g42.miaphysisme', array['eg.g42.miaphysisme','eg.v.physis']::text[], 'match', 'lesson', 'Un petit dictionnaire grec', '{}'::text[], 'Quatre mots grecs pour comprendre trois positions.', 1, '{"id": "eg.l42.e16", "unitIds": ["eg.g42.miaphysisme", "eg.v.physis"], "type": "match", "difficulty": 1, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Un petit dictionnaire grec", "promptLanguage": "fr", "pairs": [{"left": "physis", "right": "nature"}, {"left": "mono", "right": "un seul"}, {"left": "dyo", "right": "deux"}, {"left": "mia", "right": "une seule, unie"}], "answer": "physis = nature ; mono = un seul ; dyo = deux ; mia = une seule, unie", "acceptedAnswers": [], "explanation": "Quatre mots grecs pour comprendre trois positions.", "tip": "Nature, seul, deux, une.", "extraExample": {"text": "Tu peux les assembler.", "translation": "Mono + physis, etc."}, "pool": "lesson", "lessonId": "eg.l42", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
