insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l43.e16', 'eg', 'eg.l43', 'eg.g43.schisme_et_suites', array['eg.g43.schisme_et_suites','eg.v.henotikon']::text[], 'match', 'lesson', 'Qui fait quoi ?', '{}'::text[], 'Quatre acteurs de la suite du schisme.', 2, '{"id": "eg.l43.e16", "unitIds": ["eg.g43.schisme_et_suites", "eg.v.henotikon"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Qui fait quoi ?", "promptLanguage": "fr", "pairs": [{"left": "Zénon", "right": "publie l''Hénotikon (482)"}, {"left": "Justinien", "right": "nomme un patriarche chalcédonien (538)"}, {"left": "Macaire d''Edkou", "right": "martyr des persécutions"}, {"left": "les melkites", "right": "fidèles à l''empereur"}], "answer": "Zénon = publie l''Hénotikon (482) ; Justinien = nomme un patriarche chalcédonien (538) ; Macaire d''Edkou = martyr des persécutions ; les melkites = fidèles à l''empereur", "acceptedAnswers": [], "explanation": "Quatre acteurs de la suite du schisme.", "tip": "Zénon, Justinien, Macaire, melkites.", "extraExample": {"text": "Chacun a son rôle.", "translation": "Et sa date."}, "pool": "lesson", "lessonId": "eg.l43", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l43.e17', 'eg', 'eg.l43', 'eg.g43.schisme_et_suites', array['eg.g43.schisme_et_suites','eg.v.non_chalcedoniens']::text[], 'match', 'lesson', 'Deux familles', '{}'::text[], 'Deux familles, deux comptes de conciles.', 2, '{"id": "eg.l43.e17", "unitIds": ["eg.g43.schisme_et_suites", "eg.v.non_chalcedoniens"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Deux familles", "promptLanguage": "fr", "pairs": [{"left": "Églises non-chalcédoniennes", "right": "Alexandrie et Antioche"}, {"left": "Églises chalcédoniennes", "right": "Rome et Constantinople"}, {"left": "non-chalcédoniennes", "right": "trois conciles"}, {"left": "chalcédoniennes", "right": "sept conciles"}], "answer": "Églises non-chalcédoniennes = Alexandrie et Antioche ; Églises chalcédoniennes = Rome et Constantinople ; non-chalcédoniennes = trois conciles ; chalcédoniennes = sept conciles", "acceptedAnswers": [], "explanation": "Deux familles, deux comptes de conciles.", "tip": "Trois ou sept.", "extraExample": {"text": "Chalcédoine sépare.", "translation": "Depuis 451."}, "pool": "lesson", "lessonId": "eg.l43", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
