insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l44.e01', 'eg', 'eg.l44', 'eg.g44.deux_familles', array['eg.g44.deux_familles','eg.v.eglises_soeurs']::text[], 'mcq', 'lesson', 'Combien d''Églises sœurs l''Église copte compte-t-elle, elle comprise ?', array['six']::text[], 'Copte, syriaque, éthiopienne, indienne, érythréenne, arménienne.', 1, '{"id": "eg.l44.e01", "unitIds": ["eg.g44.deux_familles", "eg.v.eglises_soeurs"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Combien d''Églises sœurs l''Église copte compte-t-elle, elle comprise ?", "promptLanguage": "fr", "options": ["six", "trois", "sept", "douze"], "answer": "six", "acceptedAnswers": ["six"], "explanation": "Copte, syriaque, éthiopienne, indienne, érythréenne, arménienne.", "tip": "Six Églises sœurs.", "extraExample": {"text": "Elles sont en intercommunion.", "translation": "Toutes non-chalcédoniennes."}, "pool": "lesson", "lessonId": "eg.l44", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l44.e02', 'eg', 'eg.l44', 'eg.g44.deux_familles', array['eg.g44.deux_familles','eg.v.eglises_soeurs']::text[], 'mcq', 'lesson', 'Laquelle de ces Églises n''est pas une Église sœur de l''Église copte ?', array['l''Église de l''Orient']::text[], 'Rappel : l''Église de l''Orient, née en Perse, est liée à Nestorius.', 3, '{"id": "eg.l44.e02", "unitIds": ["eg.g44.deux_familles", "eg.v.eglises_soeurs"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Laquelle de ces Églises n''est pas une Église sœur de l''Église copte ?", "promptLanguage": "fr", "options": ["l''Église de l''Orient", "l''Église arménienne", "l''Église éthiopienne", "l''Église syriaque"], "answer": "l''Église de l''Orient", "acceptedAnswers": ["l''Église de l''Orient"], "explanation": "Rappel : l''Église de l''Orient, née en Perse, est liée à Nestorius.", "tip": "Perse ≠ sœurs.", "extraExample": {"text": "Elle ne reconnaît pas Éphèse.", "translation": "Autre histoire."}, "pool": "lesson", "lessonId": "eg.l44", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
