insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l44.e21', 'eg', 'eg.l44', 'eg.g44.deux_familles', array['eg.g44.deux_familles','eg.v.christologie']::text[], 'free_answer', 'lesson', 'Comment appelle-t-on l''enseignement sur qui est le Christ et sur ses natures ?', array['christologie','la christologie']::text[], 'La christologie.', 2, '{"id": "eg.l44.e21", "unitIds": ["eg.g44.deux_familles", "eg.v.christologie"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Comment appelle-t-on l''enseignement sur qui est le Christ et sur ses natures ?", "promptLanguage": "fr", "answer": "christologie", "acceptedAnswers": ["christologie", "la christologie"], "explanation": "La christologie.", "tip": "Christologie.", "extraExample": {"text": "Miaphysite chez les coptes.", "translation": "Dyophysite chez les chalcédoniens."}, "pool": "lesson", "lessonId": "eg.l44", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l45.e01', 'eg', 'eg.l45', 'eg.g45.logique_des_conciles', array['eg.g45.logique_des_conciles','eg.v.synode']::text[], 'mcq', 'lesson', 'Comment appelle-t-on une assemblée d''évêques d''une seule région ?', array['un synode']::text[], 'Un synode est un concile local. Un concile œcuménique réunit les évêques de toute l''Église (carte 2).', 1, '{"unitIds": ["eg.g45.logique_des_conciles", "eg.v.synode"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Comment appelle-t-on une assemblée d''évêques d''une seule région ?", "options": ["un synode", "un concile œcuménique", "un canon", "un anathème"], "answer": "un synode", "acceptedAnswers": ["un synode"], "explanation": "Un synode est un concile local. Un concile œcuménique réunit les évêques de toute l''Église (carte 2).", "tip": "Synode = local.", "extraExample": {"text": "Le synode d''Antioche (269).", "translation": "Il juge Paul de Samosate."}, "errorPatterns": [{"equals": "un concile œcuménique", "category": "word_confusion", "feedback": "Œcuménique veut dire « de toute la terre habitée » : ce n''est pas une assemblée d''une seule région."}], "id": "eg.l45.e01", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l45", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l45.e02', 'eg', 'eg.l45', 'eg.g45.logique_des_conciles', array['eg.g45.logique_des_conciles']::text[], 'mcq', 'lesson', 'Depuis Constantin, qui convoque les grands conciles ?', array['l''empereur']::text[], 'Constantin, Théodose Ier, Théodose II, Marcien : à chaque fois, c''est l''empereur qui convoque (carte 3).', 1, '{"unitIds": ["eg.g45.logique_des_conciles"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Depuis Constantin, qui convoque les grands conciles ?", "options": ["l''empereur", "les moines du désert", "un simple prêtre", "le peuple"], "answer": "l''empereur", "acceptedAnswers": ["l''empereur"], "explanation": "Constantin, Théodose Ier, Théodose II, Marcien : à chaque fois, c''est l''empereur qui convoque (carte 3).", "tip": "Convoquer = l''empereur ; définir la foi = les évêques.", "extraExample": {"text": "Constantin convoque Nicée.", "translation": "En 325."}, "id": "eg.l45.e02", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l45", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l45.e03', 'eg', 'eg.l45', 'eg.g45.logique_des_conciles', array['eg.g45.logique_des_conciles']::text[], 'mcq', 'lesson', 'Dans un concile, qui définit la foi ?', array['les évêques']::text[], 'L''empereur convoque et veut la paix, mais ce sont les évêques qui définissent la foi (carte 3).', 2, '{"unitIds": ["eg.g45.logique_des_conciles"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Dans un concile, qui définit la foi ?", "options": ["les évêques", "l''empereur seul", "les généraux", "les juges de l''empire"], "answer": "les évêques", "acceptedAnswers": ["les évêques"], "explanation": "L''empereur convoque et veut la paix, mais ce sont les évêques qui définissent la foi (carte 3).", "tip": "L''empereur convoque, les évêques décident.", "extraExample": {"text": "À Nicée, les évêques rédigent le credo.", "translation": "Constantin les écoute."}, "errorPatterns": [{"equals": "l''empereur seul", "category": "word_confusion", "feedback": "L''empereur convoque, mais il ne définit pas la foi : c''est le rôle des évêques."}], "id": "eg.l45.e03", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l45", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l45.e04', 'eg', 'eg.l45', 'eg.g45.logique_des_conciles', array['eg.g45.logique_des_conciles','eg.v.anathemes']::text[], 'mcq', 'lesson', 'Qu''est-ce qu''un anathème ?', array['une condamnation solennelle de l''erreur']::text[], 'L''anathème condamne solennellement l''erreur. Les règles de discipline, elles, s''appellent des canons (carte 4).', 2, '{"unitIds": ["eg.g45.logique_des_conciles", "eg.v.anathemes"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qu''est-ce qu''un anathème ?", "options": ["une condamnation solennelle de l''erreur", "une règle de discipline", "une prière de la messe", "le nom d''un concile"], "answer": "une condamnation solennelle de l''erreur", "acceptedAnswers": ["une condamnation solennelle de l''erreur"], "explanation": "L''anathème condamne solennellement l''erreur. Les règles de discipline, elles, s''appellent des canons (carte 4).", "tip": "Anathème = condamnation ; canon = règle.", "extraExample": {"text": "Nicée joint des anathèmes à son credo.", "translation": "Ils condamnent Arius."}, "errorPatterns": [{"equals": "une règle de discipline", "category": "word_confusion", "feedback": "Une règle de discipline est un canon. L''anathème condamne une erreur."}], "id": "eg.l45.e04", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l45", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l45.e05', 'eg', 'eg.l45', 'eg.g45.logique_des_conciles', array['eg.g45.logique_des_conciles','eg.v.canon_ecclesiastique']::text[], 'mcq', 'lesson', 'À quoi servent les canons d''un concile ?', array['des règles pour la vie de l''Église']::text[], 'Les canons règlent la vie de l''Église (rangs, discipline) ; la foi, elle, est dite par la formule de foi (carte 4).', 2, '{"unitIds": ["eg.g45.logique_des_conciles", "eg.v.canon_ecclesiastique"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "À quoi servent les canons d''un concile ?", "options": ["des règles pour la vie de l''Église", "à écrire le credo", "à condamner un hérétique", "à fixer le calendrier des fêtes de l''empereur"], "answer": "des règles pour la vie de l''Église", "acceptedAnswers": ["des règles pour la vie de l''Église"], "explanation": "Les canons règlent la vie de l''Église (rangs, discipline) ; la foi, elle, est dite par la formule de foi (carte 4).", "tip": "Canon = règle.", "extraExample": {"text": "Le canon 3 de 381 règle les rangs.", "translation": "Il ne parle pas de la foi."}, "id": "eg.l45.e05", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l45", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l45.e06', 'eg', 'eg.l45', 'eg.g45.logique_des_conciles', array['eg.g45.logique_des_conciles']::text[], 'mcq', 'lesson', 'Combien de conciles œcuméniques l''Église copte reconnaît-elle ?', array['trois']::text[], 'Nicée, Constantinople et Éphèse : trois conciles (carte 6). Sept est le nombre des Églises chalcédoniennes.', 1, '{"unitIds": ["eg.g45.logique_des_conciles"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Combien de conciles œcuméniques l''Église copte reconnaît-elle ?", "options": ["trois", "quatre", "sept", "douze"], "answer": "trois", "acceptedAnswers": ["trois"], "explanation": "Nicée, Constantinople et Éphèse : trois conciles (carte 6). Sept est le nombre des Églises chalcédoniennes.", "tip": "Trois chez nous, sept chez les chalcédoniens.", "extraExample": {"text": "325, 381, 431.", "translation": "Environ cinquante ans d''écart chaque fois."}, "errorPatterns": [{"equals": "sept", "category": "word_confusion", "feedback": "Sept est le nombre de conciles reconnus par les Églises chalcédoniennes."}], "id": "eg.l45.e06", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l45", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l45.e07', 'eg', 'eg.l45', 'eg.g45.logique_des_conciles', array['eg.g45.logique_des_conciles']::text[], 'mcq', 'lesson', 'Lequel de ces conciles l''Église copte ne reconnaît-elle pas ?', array['Chalcédoine (451)']::text[], 'Chalcédoine définit « deux natures » : l''Église copte ne le reçoit pas (carte 7).', 2, '{"unitIds": ["eg.g45.logique_des_conciles"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Lequel de ces conciles l''Église copte ne reconnaît-elle pas ?", "options": ["Chalcédoine (451)", "Nicée (325)", "Constantinople (381)", "Éphèse (431)"], "answer": "Chalcédoine (451)", "acceptedAnswers": ["Chalcédoine (451)"], "explanation": "Chalcédoine définit « deux natures » : l''Église copte ne le reçoit pas (carte 7).", "tip": "Les trois reconnus s''arrêtent à 431.", "extraExample": {"text": "Les trois conciles copte : 325, 381, 431.", "translation": "Rien après."}, "id": "eg.l45.e07", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l45", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l45.e08', 'eg', 'eg.l45', 'eg.g45.logique_des_conciles', array['eg.g45.logique_des_conciles','eg.v.reception_d_un_concile']::text[], 'mcq', 'lesson', 'Qu''appelle-t-on la « réception » d''un concile ?', array['l''acceptation par l''ensemble de l''Église']::text[], 'Un concile devient vraiment œcuménique quand toute l''Église l''accepte (carte 5).', 3, '{"unitIds": ["eg.g45.logique_des_conciles", "eg.v.reception_d_un_concile"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Qu''appelle-t-on la « réception » d''un concile ?", "options": ["l''acceptation par l''ensemble de l''Église", "la réunion des évêques dans la ville", "le repas offert par l''empereur", "la lecture du credo à la messe"], "answer": "l''acceptation par l''ensemble de l''Église", "acceptedAnswers": ["l''acceptation par l''ensemble de l''Église"], "explanation": "Un concile devient vraiment œcuménique quand toute l''Église l''accepte (carte 5).", "tip": "Réception = acceptation.", "extraExample": {"text": "Nicée est reçu partout.", "translation": "Chalcédoine ne l''est pas par Alexandrie."}, "id": "eg.l45.e08", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l45", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l45.e09', 'eg', 'eg.l45', 'eg.g45.logique_des_conciles', array['eg.g45.logique_des_conciles','eg.v.orthodoxie']::text[], 'mcq', 'lesson', 'Que veut dire « orthodoxie » ?', array['la foi droite']::text[], 'Orthodoxie vient du grec : « droite foi ». Les trois conciles fixent l''orthodoxie (carte 6).', 2, '{"unitIds": ["eg.g45.logique_des_conciles", "eg.v.orthodoxie"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que veut dire « orthodoxie » ?", "options": ["la foi droite", "la foi nouvelle", "la foi cachée", "la foi des empereurs"], "answer": "la foi droite", "acceptedAnswers": ["la foi droite"], "explanation": "Orthodoxie vient du grec : « droite foi ». Les trois conciles fixent l''orthodoxie (carte 6).", "tip": "Ortho = droit.", "extraExample": {"text": "L''hérésie s''écarte de la foi droite.", "translation": "L''orthodoxie la garde."}, "id": "eg.l45.e09", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l45", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l45.e10', 'eg', 'eg.l45', 'eg.v.theodose_ii', array['eg.v.theodose_ii','eg.g45.logique_des_conciles']::text[], 'mcq', 'lesson', 'Qui a convoqué le concile d''Éphèse de 431 ?', array['Théodose II']::text[], 'En 431, Théodose II, petit-fils de Théodose Ier, convoque Éphèse (carte 3).', 2, '{"unitIds": ["eg.v.theodose_ii", "eg.g45.logique_des_conciles"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui a convoqué le concile d''Éphèse de 431 ?", "options": ["Théodose II", "Constantin", "Théodose Ier", "Marcien"], "answer": "Théodose II", "acceptedAnswers": ["Théodose II"], "explanation": "En 431, Théodose II, petit-fils de Théodose Ier, convoque Éphèse (carte 3).", "tip": "Les deux Théodose : 381 puis 431.", "extraExample": {"text": "Théodose Ier convoque Constantinople.", "translation": "En 381."}, "id": "eg.l45.e10", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l45", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l45.e11', 'eg', 'eg.l45', 'eg.g45.logique_des_conciles', array['eg.g45.logique_des_conciles']::text[], 'mcq', 'lesson', 'Quel est l''enchaînement habituel ?', array['une erreur, un concile, une formule de foi']::text[], 'Les conciles répondent à des erreurs par une formule de foi (carte 8).', 3, '{"unitIds": ["eg.g45.logique_des_conciles"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quel est l''enchaînement habituel ?", "options": ["une erreur, un concile, une formule de foi", "un concile, une erreur, un canon", "une formule de foi, une erreur, un exil", "un empereur, un exil, un concile"], "answer": "une erreur, un concile, une formule de foi", "acceptedAnswers": ["une erreur, un concile, une formule de foi"], "explanation": "Les conciles répondent à des erreurs par une formule de foi (carte 8).", "tip": "Erreur, concile, formule.", "extraExample": {"text": "Arius, Nicée, homoousios.", "translation": "Le schéma se répète."}, "id": "eg.l45.e11", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l45", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l45.e12', 'eg', 'eg.l45', 'eg.v.concile_de_jerusalem', array['eg.v.concile_de_jerusalem','eg.g45.logique_des_conciles']::text[], 'fill_blank', 'lesson', 'Le premier concile de l''histoire chrétienne a lieu à ___, vers l''an 49.', array['Jérusalem']::text[], 'Le concile de Jérusalem, vers 49, sert de modèle à tous les autres (carte 1).', 1, '{"unitIds": ["eg.v.concile_de_jerusalem", "eg.g45.logique_des_conciles"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Le premier concile de l''histoire chrétienne a lieu à ___, vers l''an 49.", "options": ["Jérusalem", "Nicée", "Éphèse"], "answer": "Jérusalem", "acceptedAnswers": ["Jérusalem"], "explanation": "Le concile de Jérusalem, vers 49, sert de modèle à tous les autres (carte 1).", "tip": "Le premier concile, c''est Jérusalem.", "extraExample": {"text": "Les apôtres et les anciens s''y réunissent.", "translation": "Ils décident ensemble."}, "id": "eg.l45.e12", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l45", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l45.e13', 'eg', 'eg.l45', 'eg.g45.logique_des_conciles', array['eg.g45.logique_des_conciles','eg.v.concile_oecumenique']::text[], 'fill_blank', 'lesson', 'Un concile est dit ___ quand il réunit les évêques de toute l''Église.', array['œcuménique','oecuménique','oecumenique']::text[], 'Œcuménique : « de toute la terre habitée » (carte 2).', 1, '{"unitIds": ["eg.g45.logique_des_conciles", "eg.v.concile_oecumenique"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Un concile est dit ___ quand il réunit les évêques de toute l''Église.", "options": ["œcuménique", "local", "secret"], "answer": "œcuménique", "acceptedAnswers": ["œcuménique", "oecuménique", "oecumenique"], "explanation": "Œcuménique : « de toute la terre habitée » (carte 2).", "tip": "Œcuménique = universel.", "extraExample": {"text": "Nicée est œcuménique.", "translation": "Antioche 269 ne l''est pas."}, "id": "eg.l45.e13", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l45", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l45.e14', 'eg', 'eg.l45', 'eg.g45.logique_des_conciles', array['eg.g45.logique_des_conciles','eg.v.synode']::text[], 'fill_blank', 'lesson', 'Un synode est un concile ___.', array['local']::text[], 'Un synode réunit les évêques d''une région : c''est un concile local (carte 2).', 2, '{"unitIds": ["eg.g45.logique_des_conciles", "eg.v.synode"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Un synode est un concile ___.", "options": ["local", "œcuménique", "impérial"], "answer": "local", "acceptedAnswers": ["local"], "explanation": "Un synode réunit les évêques d''une région : c''est un concile local (carte 2).", "tip": "Synode = local.", "extraExample": {"text": "Constantinople 448 est un synode.", "translation": "Il condamne Eutychès."}, "id": "eg.l45.e14", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l45", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l45.e15', 'eg', 'eg.l45', 'eg.g45.logique_des_conciles', array['eg.g45.logique_des_conciles','eg.v.symbole_de_foi']::text[], 'fill_blank', 'lesson', 'Le credo s''appelle aussi le ___ de foi.', array['symbole']::text[], 'Le credo est la formule de foi, appelée aussi symbole de foi (carte 4).', 2, '{"unitIds": ["eg.g45.logique_des_conciles", "eg.v.symbole_de_foi"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Le credo s''appelle aussi le ___ de foi.", "options": ["symbole", "canon", "synode"], "answer": "symbole", "acceptedAnswers": ["symbole"], "explanation": "Le credo est la formule de foi, appelée aussi symbole de foi (carte 4).", "tip": "Symbole de foi = credo.", "extraExample": {"text": "Le symbole de foi résume la foi.", "translation": "On le récite à la messe."}, "id": "eg.l45.e15", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l45", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l45.e16', 'eg', 'eg.l45', 'eg.g45.logique_des_conciles', array['eg.g45.logique_des_conciles']::text[], 'match', 'lesson', 'Qui convoque quel concile ?', '{}'::text[], 'Chaque concile a son empereur (carte 3).', 2, '{"unitIds": ["eg.g45.logique_des_conciles"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Qui convoque quel concile ?", "pairs": [{"left": "Nicée (325)", "right": "Constantin"}, {"left": "Constantinople (381)", "right": "Théodose Ier"}, {"left": "Éphèse (431)", "right": "Théodose II"}, {"left": "Chalcédoine (451)", "right": "Marcien"}], "answer": "Nicée (325) = Constantin ; Constantinople (381) = Théodose Ier ; Éphèse (431) = Théodose II ; Chalcédoine (451) = Marcien", "acceptedAnswers": [], "explanation": "Chaque concile a son empereur (carte 3).", "tip": "Constantin, deux Théodose, Marcien.", "id": "eg.l45.e16", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l45", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l45.e17', 'eg', 'eg.l45', 'eg.g45.logique_des_conciles', array['eg.g45.logique_des_conciles']::text[], 'match', 'lesson', 'Ce que produit un concile', '{}'::text[], 'Formule de foi, anathèmes, canons : trois produits différents (carte 4).', 2, '{"unitIds": ["eg.g45.logique_des_conciles"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Ce que produit un concile", "pairs": [{"left": "un anathème", "right": "une condamnation solennelle de l''erreur"}, {"left": "un canon", "right": "des règles pour la vie de l''Église"}, {"left": "un credo", "right": "une formule de foi"}, {"left": "un synode", "right": "un concile local"}], "answer": "un anathème = une condamnation solennelle de l''erreur ; un canon = des règles pour la vie de l''Église ; un credo = une formule de foi ; un synode = un concile local", "acceptedAnswers": [], "explanation": "Formule de foi, anathèmes, canons : trois produits différents (carte 4).", "tip": "Foi, condamnation, règle.", "id": "eg.l45.e17", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l45", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l45.e18', 'eg', 'eg.l45', 'eg.g45.logique_des_conciles', array['eg.g45.logique_des_conciles']::text[], 'reorder', 'lesson', 'Phrase-repère : le concile œcuménique.', array['Un concile œcuménique réunit les évêques de toute l''Église']::text[], 'Œcuménique veut dire « de toute la terre habitée » (carte 2).', 2, '{"unitIds": ["eg.g45.logique_des_conciles"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "prompt": "Phrase-repère : le concile œcuménique.", "tokens": ["l''Église", "de", "Un", "toute", "évêques", "réunit", "œcuménique", "les", "concile"], "answer": "Un concile œcuménique réunit les évêques de toute l''Église", "acceptedAnswers": ["Un concile œcuménique réunit les évêques de toute l''Église"], "explanation": "Œcuménique veut dire « de toute la terre habitée » (carte 2).", "tip": "Œcuménique = toute l''Église.", "extraExample": {"text": "Un synode réunit les évêques d''une région.", "translation": "C''est la différence."}, "id": "eg.l45.e18", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l45", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l45.e19', 'eg', 'eg.l45', 'eg.g45.logique_des_conciles', array['eg.g45.logique_des_conciles','eg.v.reception_d_un_concile']::text[], 'free_answer', 'lesson', 'Comment appelle-t-on l''acceptation d''un concile par toute l''Église ?', array['la réception','réception','reception','la reception']::text[], 'C''est la réception : un concile n''est œcuménique que s''il est reçu par l''ensemble de l''Église (carte 5).', 3, '{"unitIds": ["eg.g45.logique_des_conciles", "eg.v.reception_d_un_concile"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Comment appelle-t-on l''acceptation d''un concile par toute l''Église ?", "answer": "la réception", "acceptedAnswers": ["la réception", "réception", "reception", "la reception"], "explanation": "C''est la réception : un concile n''est œcuménique que s''il est reçu par l''ensemble de l''Église (carte 5).", "tip": "Réception = acceptation.", "extraExample": {"text": "Chalcédoine n''est pas reçu par les coptes.", "translation": "Nicée l''est."}, "id": "eg.l45.e19", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l45", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l45.e20', 'eg', 'eg.l45', 'eg.v.concile_de_nicee', array['eg.v.concile_de_nicee','eg.g45.logique_des_conciles']::text[], 'free_answer', 'lesson', 'Quel empereur a convoqué le concile de Nicée ?', array['Constantin','l''empereur Constantin']::text[], 'Constantin convoque Nicée en 325, pour rétablir l''unité de l''empire (carte 3).', 1, '{"unitIds": ["eg.v.concile_de_nicee", "eg.g45.logique_des_conciles"], "type": "free_answer", "difficulty": 1, "instruction": "Écris ta réponse.", "prompt": "Quel empereur a convoqué le concile de Nicée ?", "answer": "Constantin", "acceptedAnswers": ["Constantin", "l''empereur Constantin"], "explanation": "Constantin convoque Nicée en 325, pour rétablir l''unité de l''empire (carte 3).", "tip": "Nicée = Constantin.", "extraExample": {"text": "Il convoque Nicée en 325.", "translation": "Il veut un empire uni."}, "id": "eg.l45.e20", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l45", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
