insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e01', 'eg', 'eg.l53', 'eg.g53.familles_eglises', array['eg.g53.familles_eglises','eg.v.eglises_orthodoxes_orientales','eg.v.eglise_orthodoxe_chalcedonienne']::text[], 'match', 'lesson', 'Chaque famille et son exemple', '{}'::text[], 'Quatre familles : les orthodoxes orientales (dont la nôtre), les chalcédoniennes, les catholiques et les protestants.', 1, '{"unitIds": ["eg.g53.familles_eglises", "eg.v.eglises_orthodoxes_orientales", "eg.v.eglise_orthodoxe_chalcedonienne"], "type": "match", "difficulty": 1, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Chaque famille et son exemple", "promptLanguage": "fr", "pairs": [{"left": "Églises orthodoxes orientales", "right": "copte, syriaque, arménienne, éthiopienne"}, {"left": "Église orthodoxe chalcédonienne", "right": "grecque, russe, serbe, roumaine"}, {"left": "Église catholique", "right": "dirigée par le pape à Rome"}, {"left": "Protestantisme", "right": "né de la Réforme au XVIe siècle"}], "answer": "Églises orthodoxes orientales = copte, syriaque, arménienne, éthiopienne ; Église orthodoxe chalcédonienne = grecque, russe, serbe, roumaine ; Église catholique = dirigée par le pape à Rome ; Protestantisme = né de la Réforme au XVIe siècle", "acceptedAnswers": [], "explanation": "Quatre familles : les orthodoxes orientales (dont la nôtre), les chalcédoniennes, les catholiques et les protestants.", "tip": "Orientales = sans Chalcédoine ; chalcédoniennes = avec.", "id": "eg.l53.e01", "pool": "lesson", "lessonId": "eg.l53", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e02', 'eg', 'eg.l53', 'eg.g53.familles_eglises', array['eg.g53.familles_eglises']::text[], 'mcq', 'lesson', 'Combien y a-t-il de grandes familles de chrétiens ?', array['Quatre']::text[], 'On distingue les Églises orthodoxes orientales, les orthodoxes chalcédoniens, les catholiques et les protestants.', 1, '{"unitIds": ["eg.g53.familles_eglises"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Combien y a-t-il de grandes familles de chrétiens ?", "promptLanguage": "fr", "options": ["Quatre", "Deux", "Six", "Douze"], "answer": "Quatre", "acceptedAnswers": ["Quatre"], "explanation": "On distingue les Églises orthodoxes orientales, les orthodoxes chalcédoniens, les catholiques et les protestants.", "tip": "Quatre familles, trois questions.", "extraExample": {"text": "Les Églises ont de nombreuses divisions.", "translation": "Mais ces quatre familles servent de repères."}, "id": "eg.l53.e02", "pool": "lesson", "lessonId": "eg.l53", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e03', 'eg', 'eg.l53', 'eg.g53.familles_eglises', array['eg.g53.familles_eglises','eg.v.eglises_orthodoxes_orientales']::text[], 'mcq', 'lesson', 'À quelle famille appartient l''Église copte orthodoxe ?', array['Les Églises orthodoxes orientales']::text[], 'Comme les Églises arménienne, syriaque, éthiopienne et malankare, l''Église copte n''a pas reçu Chalcédoine.', 1, '{"unitIds": ["eg.g53.familles_eglises", "eg.v.eglises_orthodoxes_orientales"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "À quelle famille appartient l''Église copte orthodoxe ?", "promptLanguage": "fr", "options": ["Les Églises orthodoxes orientales", "L''Église orthodoxe chalcédonienne", "Le protestantisme", "L''Église catholique"], "answer": "Les Églises orthodoxes orientales", "acceptedAnswers": ["Les Églises orthodoxes orientales"], "explanation": "Comme les Églises arménienne, syriaque, éthiopienne et malankare, l''Église copte n''a pas reçu Chalcédoine.", "tip": "Orientale ne veut pas dire grecque.", "extraExample": {"text": "Un orthodoxe grec n''est pas un orthodoxe oriental.", "translation": "Les grecs reçoivent Chalcédoine."}, "errorPatterns": [{"equals": "L''Église orthodoxe chalcédonienne", "category": "word_confusion", "feedback": "Les orthodoxes grecs ou russes reçoivent Chalcédoine ; nous, non."}], "id": "eg.l53.e03", "pool": "lesson", "lessonId": "eg.l53", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e04', 'eg', 'eg.l53', 'eg.g53.familles_eglises', array['eg.g53.familles_eglises','eg.v.eglises_orthodoxes_orientales']::text[], 'mcq', 'lesson', 'Quel concile les Églises orthodoxes orientales n''ont-elles pas reçu ?', array['Chalcédoine (451)']::text[], 'Elles gardent les trois premiers conciles (Nicée, Constantinople, Éphèse) mais refusent Chalcédoine en 451.', 2, '{"unitIds": ["eg.g53.familles_eglises", "eg.v.eglises_orthodoxes_orientales"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel concile les Églises orthodoxes orientales n''ont-elles pas reçu ?", "promptLanguage": "fr", "options": ["Chalcédoine (451)", "Nicée (325)", "Constantinople (381)", "Éphèse (431)"], "answer": "Chalcédoine (451)", "acceptedAnswers": ["Chalcédoine (451)"], "explanation": "Elles gardent les trois premiers conciles (Nicée, Constantinople, Éphèse) mais refusent Chalcédoine en 451.", "tip": "Trois conciles reçus, Chalcédoine refusé.", "extraExample": {"text": "Nicée, Constantinople et Éphèse sont reçus par tous.", "translation": "Seul Chalcédoine divise."}, "errorPatterns": [{"equals": "Éphèse (431)", "category": "word_confusion", "feedback": "Éphèse (431) est reçu par les orthodoxes orientaux, qui lui doivent le titre de Mère de Dieu."}], "id": "eg.l53.e04", "pool": "lesson", "lessonId": "eg.l53", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e05', 'eg', 'eg.l53', 'eg.v.eglise_malankare', array['eg.v.eglise_malankare','eg.g53.familles_eglises']::text[], 'mcq', 'lesson', 'Quelle Église orthodoxe orientale rattache ses origines à l''apôtre Thomas ?', array['L''Église malankare']::text[], 'Les chrétiens du Kerala, en Inde, disent descendre de ceux que Thomas a évangélisés.', 2, '{"unitIds": ["eg.v.eglise_malankare", "eg.g53.familles_eglises"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle Église orthodoxe orientale rattache ses origines à l''apôtre Thomas ?", "promptLanguage": "fr", "options": ["L''Église malankare", "L''Église arménienne", "L''Église tewahedo", "L''Église syriaque"], "answer": "L''Église malankare", "acceptedAnswers": ["L''Église malankare"], "explanation": "Les chrétiens du Kerala, en Inde, disent descendre de ceux que Thomas a évangélisés.", "tip": "Thomas va en Inde, comme Marc va à Alexandrie.", "extraExample": {"text": "Thomas est l''apôtre de l''Inde.", "translation": "Marc est l''apôtre de l''Égypte."}, "id": "eg.l53.e05", "pool": "lesson", "lessonId": "eg.l53", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e06', 'eg', 'eg.l53', 'eg.v.eglise_armenienne_apostolique', array['eg.v.eglise_armenienne_apostolique','eg.g53.familles_eglises']::text[], 'mcq', 'lesson', 'Quel royaume est le premier à adopter le christianisme comme religion d''État vers 301 ?', array['L''Arménie']::text[], 'Saint Grégoire l''Illuminateur convertit le roi d''Arménie vers 301, avant que Constantin ne protège les chrétiens.', 2, '{"unitIds": ["eg.v.eglise_armenienne_apostolique", "eg.g53.familles_eglises"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel royaume est le premier à adopter le christianisme comme religion d''État vers 301 ?", "promptLanguage": "fr", "options": ["L''Arménie", "L''Éthiopie", "L''Égypte", "L''Empire romain"], "answer": "L''Arménie", "acceptedAnswers": ["L''Arménie"], "explanation": "Saint Grégoire l''Illuminateur convertit le roi d''Arménie vers 301, avant que Constantin ne protège les chrétiens.", "tip": "Arménie : 301.", "extraExample": {"text": "Rome ne devient officiellement chrétienne qu''avec Théodose, en 380.", "translation": "L''Arménie l''a précédée."}, "errorPatterns": [{"equals": "L''Empire romain", "category": "word_confusion", "feedback": "L''Arménie devance Rome : son roi se convertit vers 301."}], "id": "eg.l53.e06", "pool": "lesson", "lessonId": "eg.l53", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e07', 'eg', 'eg.l53', 'eg.v.eglise_tewahedo', array['eg.v.eglise_tewahedo','eg.g53.familles_eglises']::text[], 'fill_blank', 'lesson', 'Jusqu''en 1959, l''abouna d''Éthiopie était envoyé depuis ___.', array['Alexandrie']::text[], 'L''Église éthiopienne dépendait de l''Église copte : le premier évêque, Frumence, fut consacré par saint Athanase.', 2, '{"unitIds": ["eg.v.eglise_tewahedo", "eg.g53.familles_eglises"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Jusqu''en 1959, l''abouna d''Éthiopie était envoyé depuis ___.", "promptLanguage": "fr", "options": ["Alexandrie", "Rome", "Antioche", "Constantinople"], "answer": "Alexandrie", "acceptedAnswers": ["Alexandrie"], "explanation": "L''Église éthiopienne dépendait de l''Église copte : le premier évêque, Frumence, fut consacré par saint Athanase.", "tip": "Éthiopie = fille d''Alexandrie.", "extraExample": {"text": "L''Église éthiopienne a eu son propre patriarche à partir de 1959.", "translation": "Le pape copte a alors consacré le premier patriarche éthiopien."}, "id": "eg.l53.e07", "pool": "lesson", "lessonId": "eg.l53", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e08', 'eg', 'eg.l53', 'eg.g53.familles_eglises', array['eg.g53.familles_eglises','eg.v.eglise_catholique']::text[], 'mcq', 'lesson', 'Qui est le chef de l''Église catholique ?', array['Le pape, évêque de Rome']::text[], 'Les catholiques reconnaissent le pape comme chef. C''est le point central qui les distingue des orthodoxes.', 1, '{"unitIds": ["eg.g53.familles_eglises", "eg.v.eglise_catholique"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Qui est le chef de l''Église catholique ?", "promptLanguage": "fr", "options": ["Le pape, évêque de Rome", "Le patriarche de Constantinople", "Le pape d''Alexandrie", "Le roi d''Angleterre"], "answer": "Le pape, évêque de Rome", "acceptedAnswers": ["Le pape, évêque de Rome"], "explanation": "Les catholiques reconnaissent le pape comme chef. C''est le point central qui les distingue des orthodoxes.", "tip": "Catholique = en communion avec le pape.", "extraExample": {"text": "Notre pape est évêque d''Alexandrie.", "translation": "Le pape de Rome est celui des catholiques."}, "errorPatterns": [{"equals": "Le pape d''Alexandrie", "category": "word_confusion", "feedback": "Le pape d''Alexandrie est le chef de l''Église copte orthodoxe."}], "id": "eg.l53.e08", "pool": "lesson", "lessonId": "eg.l53", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e09', 'eg', 'eg.l53', 'eg.v.eglise_catholique', array['eg.v.eglise_catholique','eg.g53.familles_eglises']::text[], 'mcq', 'lesson', 'Que signifie « Église catholique copte » ?', array['Elle garde la liturgie copte mais reconnaît le pape']::text[], 'Elle garde la liturgie copte mais reconnaît le pape. Elle est distincte de l''Église copte orthodoxe.', 3, '{"unitIds": ["eg.v.eglise_catholique", "eg.g53.familles_eglises"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Que signifie « Église catholique copte » ?", "promptLanguage": "fr", "options": ["Elle garde la liturgie copte mais reconnaît le pape", "Une autre appellation de l''Église copte orthodoxe", "Une Église protestante d''Égypte", "L''Église des Coptes de Rome"], "answer": "Elle garde la liturgie copte mais reconnaît le pape", "acceptedAnswers": ["Elle garde la liturgie copte mais reconnaît le pape"], "explanation": "Elle garde la liturgie copte mais reconnaît le pape. Elle est distincte de l''Église copte orthodoxe.", "tip": "Copte par le rite, catholique par la communion.", "extraExample": {"text": "L''Église catholique compte 23 Églises orientales.", "translation": "La copte est l''une d''elles."}, "errorPatterns": [{"equals": "Une autre appellation de l''Église copte orthodoxe", "category": "word_confusion", "feedback": "Non : ce sont deux Églises différentes, l''une reconnaît le pape, l''autre pas."}], "id": "eg.l53.e09", "pool": "lesson", "lessonId": "eg.l53", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e10', 'eg', 'eg.l53', 'eg.g53.familles_eglises', array['eg.g53.familles_eglises','eg.v.eglise_orthodoxe_chalcedonienne']::text[], 'fill_blank', 'lesson', 'Les orthodoxes chalcédoniens reçoivent ___ conciles.', array['sept']::text[], 'Ils reçoivent sept conciles, dont Chalcédoine. Nous en gardons trois.', 2, '{"unitIds": ["eg.g53.familles_eglises", "eg.v.eglise_orthodoxe_chalcedonienne"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Les orthodoxes chalcédoniens reçoivent ___ conciles.", "promptLanguage": "fr", "options": ["sept", "trois", "neuf", "quinze"], "answer": "sept", "acceptedAnswers": ["sept"], "explanation": "Ils reçoivent sept conciles, dont Chalcédoine. Nous en gardons trois.", "tip": "7 contre 3.", "extraExample": {"text": "Le septième concile est Nicée II.", "translation": "Il porte sur les icônes."}, "id": "eg.l53.e10", "pool": "lesson", "lessonId": "eg.l53", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e11', 'eg', 'eg.l53', 'eg.v.protestantisme', array['eg.v.protestantisme','eg.g53.familles_eglises']::text[], 'free_answer', 'lesson', 'De quel grand mouvement du XVIe siècle les protestants sont-ils nés ?', array['la Réforme','Réforme']::text[], 'La Réforme commence en 1517 avec Luther. Elle donne naissance aux Églises protestantes.', 2, '{"unitIds": ["eg.v.protestantisme", "eg.g53.familles_eglises"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "De quel grand mouvement du XVIe siècle les protestants sont-ils nés ?", "promptLanguage": "fr", "hint": "Elle commence en 1517.", "answer": "la Réforme", "acceptedAnswers": ["la Réforme", "Réforme"], "explanation": "La Réforme commence en 1517 avec Luther. Elle donne naissance aux Églises protestantes.", "tip": "Protestant = fils de la Réforme.", "extraExample": {"text": "Luther affiche ses 95 thèses en 1517.", "translation": "C''est la date de départ."}, "id": "eg.l53.e11", "pool": "lesson", "lessonId": "eg.l53", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e12', 'eg', 'eg.l53', 'eg.v.eglise_tewahedo', array['eg.v.eglise_tewahedo','eg.g53.familles_eglises']::text[], 'free_answer', 'lesson', 'Quel mot, qui veut dire « rendu un », désigne les Églises d''Éthiopie et d''Érythrée ?', array['tewahedo','Église tewahedo']::text[], 'Tewahedo exprime l''union du divin et de l''humain en Christ, c''est-à-dire la foi miaphysite.', 3, '{"unitIds": ["eg.v.eglise_tewahedo", "eg.g53.familles_eglises"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Quel mot, qui veut dire « rendu un », désigne les Églises d''Éthiopie et d''Érythrée ?", "promptLanguage": "fr", "hint": "Pense à « rendu un ».", "answer": "tewahedo", "acceptedAnswers": ["tewahedo", "Église tewahedo"], "explanation": "Tewahedo exprime l''union du divin et de l''humain en Christ, c''est-à-dire la foi miaphysite.", "tip": "Tewahedo = rendu un.", "extraExample": {"text": "L''Église éthiopienne se dit « tewahedo ».", "translation": "L''Église érythréenne aussi."}, "id": "eg.l53.e12", "pool": "lesson", "lessonId": "eg.l53", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e13', 'eg', 'eg.l53', 'eg.g53.familles_eglises', array['eg.g53.familles_eglises']::text[], 'reorder', 'lesson', 'Phrase-repère : notre famille d''Églises.', array['Les Églises orthodoxes orientales n''ont pas reçu Chalcédoine']::text[], 'Les Églises orthodoxes orientales n''ont pas reçu Chalcédoine, mais gardent Nicée, Constantinople et Éphèse.', 2, '{"unitIds": ["eg.g53.familles_eglises"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former la phrase.", "prompt": "Phrase-repère : notre famille d''Églises.", "promptLanguage": "fr", "tokens": ["orthodoxes", "reçu", "Les", "Chalcédoine", "pas", "Églises", "n''ont", "orientales"], "answer": "Les Églises orthodoxes orientales n''ont pas reçu Chalcédoine", "acceptedAnswers": ["Les Églises orthodoxes orientales n''ont pas reçu Chalcédoine"], "explanation": "Les Églises orthodoxes orientales n''ont pas reçu Chalcédoine, mais gardent Nicée, Constantinople et Éphèse.", "tip": "Orientales = sans Chalcédoine.", "extraExample": {"text": "Les orthodoxes chalcédoniens reçoivent Chalcédoine.", "translation": "La différence est dans le nom."}, "id": "eg.l53.e13", "pool": "lesson", "lessonId": "eg.l53", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e14', 'eg', 'eg.l53', 'eg.g53.familles_eglises', array['eg.g53.familles_eglises']::text[], 'mcq', 'lesson', 'Quelle question sépare surtout les protestants de toutes les autres familles ?', array['La Bible seule suffit-elle ?']::text[], 'Les protestants s''appuient sur la Bible seule ; les autres ajoutent la Tradition.', 3, '{"unitIds": ["eg.g53.familles_eglises"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle question sépare surtout les protestants de toutes les autres familles ?", "promptLanguage": "fr", "options": ["La Bible seule suffit-elle ?", "Reçoit-on Chalcédoine ?", "Parle-t-on grec ?", "Prie-t-on en copte ?"], "answer": "La Bible seule suffit-elle ?", "acceptedAnswers": ["La Bible seule suffit-elle ?"], "explanation": "Les protestants s''appuient sur la Bible seule ; les autres ajoutent la Tradition.", "tip": "Bible seule = signature protestante.", "extraExample": {"text": "Les orthodoxes disent : Écriture et Tradition.", "translation": "Les catholiques aussi."}, "id": "eg.l53.e14", "pool": "lesson", "lessonId": "eg.l53", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e15', 'eg', 'eg.l53', 'eg.g53.familles_eglises', array['eg.g53.familles_eglises','eg.v.eglise_syriaque_orthodoxe','eg.v.eglise_tewahedo','eg.v.eglise_malankare']::text[], 'match', 'lesson', 'Chaque Église et son pays', '{}'::text[], 'Ces quatre Églises sont orthodoxes orientales, comme la nôtre.', 2, '{"unitIds": ["eg.g53.familles_eglises", "eg.v.eglise_syriaque_orthodoxe", "eg.v.eglise_tewahedo", "eg.v.eglise_malankare"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Chaque Église et son pays", "promptLanguage": "fr", "pairs": [{"left": "Église syriaque orthodoxe", "right": "patriarcat d''Antioche"}, {"left": "Église arménienne apostolique", "right": "Arménie"}, {"left": "Église tewahedo", "right": "Éthiopie et Érythrée"}, {"left": "Église malankare", "right": "Kerala, en Inde"}], "answer": "Église syriaque orthodoxe = patriarcat d''Antioche ; Église arménienne apostolique = Arménie ; Église tewahedo = Éthiopie et Érythrée ; Église malankare = Kerala, en Inde", "acceptedAnswers": [], "explanation": "Ces quatre Églises sont orthodoxes orientales, comme la nôtre.", "tip": "Antioche, Arménie, Éthiopie, Kerala.", "id": "eg.l53.e15", "pool": "lesson", "lessonId": "eg.l53", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e16', 'eg', 'eg.l53', 'eg.g53.familles_eglises', array['eg.g53.familles_eglises','eg.v.eglise_catholique']::text[], 'mcq', 'lesson', 'Quelle est la plus grande famille chrétienne ?', array['L''Église catholique']::text[], 'L''Église catholique compte environ 1,4 milliard de fidèles.', 2, '{"unitIds": ["eg.g53.familles_eglises", "eg.v.eglise_catholique"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle est la plus grande famille chrétienne ?", "promptLanguage": "fr", "options": ["L''Église catholique", "Les orthodoxes orientaux", "Les orthodoxes chalcédoniens", "Les anglicans"], "answer": "L''Église catholique", "acceptedAnswers": ["L''Église catholique"], "explanation": "L''Église catholique compte environ 1,4 milliard de fidèles.", "tip": "Un chrétien sur deux est catholique ou presque.", "extraExample": {"text": "Les orthodoxes chalcédoniens dépassent 200 millions.", "translation": "Ils sont loin derrière."}, "id": "eg.l53.e16", "pool": "lesson", "lessonId": "eg.l53", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e17', 'eg', 'eg.l53', 'eg.g53.familles_eglises', array['eg.g53.familles_eglises','eg.v.eglise_armenienne_apostolique']::text[], 'fill_blank', 'lesson', 'L''Église arménienne est dite « ___ » car elle remonte aux apôtres.', array['apostolique']::text[], 'Elle fait remonter ses origines aux apôtres Thaddée et Barthélemy.', 3, '{"unitIds": ["eg.g53.familles_eglises", "eg.v.eglise_armenienne_apostolique"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète la phrase.", "prompt": "L''Église arménienne est dite « ___ » car elle remonte aux apôtres.", "promptLanguage": "fr", "options": ["apostolique", "évangélique", "byzantine"], "answer": "apostolique", "acceptedAnswers": ["apostolique"], "explanation": "Elle fait remonter ses origines aux apôtres Thaddée et Barthélemy.", "tip": "Apostolique = qui remonte aux apôtres.", "extraExample": {"text": "Notre Église aussi est apostolique.", "translation": "Elle remonte à saint Marc."}, "id": "eg.l53.e17", "pool": "lesson", "lessonId": "eg.l53", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e18', 'eg', 'eg.l53', 'eg.v.eglise_malankare', array['eg.v.eglise_malankare','eg.g53.familles_eglises']::text[], 'free_answer', 'lesson', 'Dans quel pays se trouve l''Église malankare ?', array['l''Inde','Inde','Inde (Kerala)','au Kerala','Kerala']::text[], 'L''Église malankare est celle du Kerala, dans le sud-ouest de l''Inde.', 2, '{"unitIds": ["eg.v.eglise_malankare", "eg.g53.familles_eglises"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Dans quel pays se trouve l''Église malankare ?", "promptLanguage": "fr", "hint": "Elle remonte à l''apôtre Thomas.", "answer": "l''Inde", "acceptedAnswers": ["l''Inde", "Inde", "Inde (Kerala)", "au Kerala", "Kerala"], "explanation": "L''Église malankare est celle du Kerala, dans le sud-ouest de l''Inde.", "tip": "Malankare = Inde.", "extraExample": {"text": "Le Kerala est au sud-ouest de l''Inde.", "translation": "Thomas y serait venu."}, "id": "eg.l53.e18", "pool": "lesson", "lessonId": "eg.l53", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e19', 'eg', 'eg.l53', 'eg.g53.familles_eglises', array['eg.g53.familles_eglises']::text[], 'mcq', 'lesson', 'Un orthodoxe grec est :', array['Un orthodoxe chalcédonien']::text[], 'Les orthodoxes grecs, russes, serbes… reçoivent Chalcédoine : on les appelle chalcédoniens.', 3, '{"unitIds": ["eg.g53.familles_eglises"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Un orthodoxe grec est :", "promptLanguage": "fr", "options": ["Un orthodoxe chalcédonien", "Un orthodoxe oriental", "Un protestant", "Un catholique copte"], "answer": "Un orthodoxe chalcédonien", "acceptedAnswers": ["Un orthodoxe chalcédonien"], "explanation": "Les orthodoxes grecs, russes, serbes… reçoivent Chalcédoine : on les appelle chalcédoniens.", "tip": "Grec, russe, serbe = chalcédoniens.", "extraExample": {"text": "Le patriarche de Constantinople est de cette famille.", "translation": "Il reçoit sept conciles."}, "errorPatterns": [{"equals": "Un orthodoxe oriental", "category": "word_confusion", "feedback": "Nous sommes les orthodoxes orientaux ; les Grecs sont chalcédoniens."}], "id": "eg.l53.e19", "pool": "lesson", "lessonId": "eg.l53", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e20', 'eg', 'eg.l53', 'eg.v.saint_marc', array['eg.v.saint_marc','eg.g53.familles_eglises']::text[], 'mcq', 'lesson', 'Révision — Quel apôtre a fondé l''Église d''Alexandrie ?', array['Saint Marc']::text[], 'Saint Marc a fondé l''Église d''Alexandrie, dont notre pape est le successeur.', 1, '{"unitIds": ["eg.v.saint_marc", "eg.g53.familles_eglises"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Révision — Quel apôtre a fondé l''Église d''Alexandrie ?", "promptLanguage": "fr", "options": ["Saint Marc", "Saint Pierre", "Saint Thomas", "Saint Paul"], "answer": "Saint Marc", "acceptedAnswers": ["Saint Marc"], "explanation": "Saint Marc a fondé l''Église d''Alexandrie, dont notre pape est le successeur.", "tip": "Marc : Alexandrie.", "extraExample": {"text": "Thomas est l''apôtre de l''Inde.", "translation": "Pierre est l''apôtre de Rome."}, "errorPatterns": [{"equals": "Saint Thomas", "category": "word_confusion", "feedback": "Thomas est lié à l''Inde, donc à l''Église malankare."}], "id": "eg.l53.e20", "pool": "lesson", "lessonId": "eg.l53", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e21', 'eg', 'eg.l53', 'eg.v.concile_de_nicee', array['eg.v.concile_de_nicee','eg.g53.familles_eglises']::text[], 'mcq', 'lesson', 'Révision — En quelle année se tient le concile de Nicée ?', array['325']::text[], 'Le premier concile œcuménique se tient à Nicée en 325. Il est reçu par toutes les familles d''Églises.', 2, '{"unitIds": ["eg.v.concile_de_nicee", "eg.g53.familles_eglises"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Révision — En quelle année se tient le concile de Nicée ?", "promptLanguage": "fr", "options": ["325", "381", "431", "451"], "answer": "325", "acceptedAnswers": ["325"], "explanation": "Le premier concile œcuménique se tient à Nicée en 325. Il est reçu par toutes les familles d''Églises.", "tip": "Nicée : 325.", "extraExample": {"text": "Constantinople vient en 381.", "translation": "Éphèse en 431."}, "errorPatterns": [{"equals": "451", "category": "word_confusion", "feedback": "451 est Chalcédoine, que nous n''avons pas reçu."}], "id": "eg.l53.e21", "pool": "lesson", "lessonId": "eg.l53", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e22', 'eg', 'eg.l53', 'eg.v.arius', array['eg.v.arius','eg.g53.familles_eglises']::text[], 'free_answer', 'lesson', 'Révision — Quel prêtre d''Alexandrie niait que le Fils soit Dieu, au début du IVe siècle ?', array['Arius']::text[], 'Arius, prêtre d''Alexandrie, est condamné à Nicée.', 2, '{"unitIds": ["eg.v.arius", "eg.g53.familles_eglises"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Révision — Quel prêtre d''Alexandrie niait que le Fils soit Dieu, au début du IVe siècle ?", "promptLanguage": "fr", "hint": "Son nom commence par A.", "answer": "Arius", "acceptedAnswers": ["Arius"], "explanation": "Arius, prêtre d''Alexandrie, est condamné à Nicée.", "tip": "Arius : le Fils créé.", "extraExample": {"text": "Les témoins de Jéhovah reprennent une idée voisine.", "translation": "Nicée l''a condamnée."}, "id": "eg.l53.e22", "pool": "lesson", "lessonId": "eg.l53", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l54.e01', 'eg', 'eg.l54', 'eg.g54.chalcedoine_orthodoxes', array['eg.g54.chalcedoine_orthodoxes']::text[], 'match', 'lesson', 'Qui a fait quoi à Chalcédoine ?', '{}'::text[], 'Marcien réunit le concile, qui reçoit la lettre de Léon, dépose Dioscore et condamne Eutychès.', 1, '{"unitIds": ["eg.g54.chalcedoine_orthodoxes"], "type": "match", "difficulty": 1, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Qui a fait quoi à Chalcédoine ?", "promptLanguage": "fr", "pairs": [{"left": "Marcien", "right": "l''empereur qui réunit le concile"}, {"left": "Léon", "right": "évêque de Rome, auteur du Tome"}, {"left": "Dioscore", "right": "patriarche d''Alexandrie déposé"}, {"left": "Eutychès", "right": "condamné par le concile"}], "answer": "Marcien = l''empereur qui réunit le concile ; Léon = évêque de Rome, auteur du Tome ; Dioscore = patriarche d''Alexandrie déposé ; Eutychès = condamné par le concile", "acceptedAnswers": [], "explanation": "Marcien réunit le concile, qui reçoit la lettre de Léon, dépose Dioscore et condamne Eutychès.", "tip": "Quatre noms de 451.", "id": "eg.l54.e01", "pool": "lesson", "lessonId": "eg.l54", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l54.e02', 'eg', 'eg.l54', 'eg.g54.chalcedoine_orthodoxes', array['eg.g54.chalcedoine_orthodoxes']::text[], 'mcq', 'lesson', 'En quelle année se tient le concile de Chalcédoine ?', array['451']::text[], 'Chalcédoine se tient en 451, vingt ans après Éphèse (431).', 1, '{"unitIds": ["eg.g54.chalcedoine_orthodoxes"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "En quelle année se tient le concile de Chalcédoine ?", "promptLanguage": "fr", "options": ["451", "325", "431", "381"], "answer": "451", "acceptedAnswers": ["451"], "explanation": "Chalcédoine se tient en 451, vingt ans après Éphèse (431).", "tip": "451 : Chalcédoine ; 431 : Éphèse.", "extraExample": {"text": "Nicée est en 325, Constantinople en 381.", "translation": "Chalcédoine est le quatrième concile."}, "errorPatterns": [{"equals": "431", "category": "word_confusion", "feedback": "431 est l''année d''Éphèse."}, {"equals": "325", "category": "word_confusion", "feedback": "325 est l''année de Nicée."}], "id": "eg.l54.e02", "pool": "lesson", "lessonId": "eg.l54", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l54.e03', 'eg', 'eg.l54', 'eg.g54.chalcedoine_orthodoxes', array['eg.g54.chalcedoine_orthodoxes','eg.v.deux_natures']::text[], 'mcq', 'lesson', 'Quelle formule est celle du concile de Chalcédoine ?', array['Un seul Christ reconnu en deux natures']::text[], 'La formule de Chalcédoine confesse un Christ reconnu en deux natures, divine et humaine, sans confusion ni séparation.', 2, '{"unitIds": ["eg.g54.chalcedoine_orthodoxes", "eg.v.deux_natures"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle formule est celle du concile de Chalcédoine ?", "promptLanguage": "fr", "options": ["Un seul Christ reconnu en deux natures", "Une seule nature du Verbe incarné", "Le Christ n''a qu''une apparence humaine", "Le Christ est deux personnes"], "answer": "Un seul Christ reconnu en deux natures", "acceptedAnswers": ["Un seul Christ reconnu en deux natures"], "explanation": "La formule de Chalcédoine confesse un Christ reconnu en deux natures, divine et humaine, sans confusion ni séparation.", "tip": "Chalcédoine : deux natures.", "extraExample": {"text": "Nestorius parlait de deux personnes.", "translation": "Chalcédoine le rejette aussi."}, "errorPatterns": [{"equals": "Une seule nature du Verbe incarné", "category": "word_confusion", "feedback": "C''est la formule de saint Cyrille, que garde l''Église copte."}], "id": "eg.l54.e03", "pool": "lesson", "lessonId": "eg.l54", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l54.e04', 'eg', 'eg.l54', 'eg.g54.chalcedoine_orthodoxes', array['eg.g54.chalcedoine_orthodoxes']::text[], 'mcq', 'lesson', 'Quelle formule de saint Cyrille garde l''Église copte ?', array['Une seule nature du Verbe incarné']::text[], 'Cyrille parle d''une seule nature du Verbe incarné : divinité et humanité unies sans mélange.', 2, '{"unitIds": ["eg.g54.chalcedoine_orthodoxes"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle formule de saint Cyrille garde l''Église copte ?", "promptLanguage": "fr", "options": ["Une seule nature du Verbe incarné", "Un seul Christ reconnu en deux natures", "Le Fils est inférieur au Père", "Deux Christs unis par amour"], "answer": "Une seule nature du Verbe incarné", "acceptedAnswers": ["Une seule nature du Verbe incarné"], "explanation": "Cyrille parle d''une seule nature du Verbe incarné : divinité et humanité unies sans mélange.", "tip": "Cyrille : une seule nature.", "extraExample": {"text": "Cyrille est patriarche d''Alexandrie de 412 à 444.", "translation": "Il combat Nestorius à Éphèse."}, "errorPatterns": [{"equals": "Le Fils est inférieur au Père", "category": "word_confusion", "feedback": "C''est la thèse d''Arius, condamnée à Nicée."}], "id": "eg.l54.e04", "pool": "lesson", "lessonId": "eg.l54", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l54.e05', 'eg', 'eg.l54', 'eg.g54.chalcedoine_orthodoxes', array['eg.g54.chalcedoine_orthodoxes']::text[], 'fill_blank', 'lesson', 'L''Église copte est miaphysite : « mia » veut dire ___.', array['une']::text[], 'Miaphysite vient du grec mia (une) et physis (nature).', 2, '{"unitIds": ["eg.g54.chalcedoine_orthodoxes"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "L''Église copte est miaphysite : « mia » veut dire ___.", "promptLanguage": "fr", "options": ["une", "deux", "trois", "nature"], "answer": "une", "acceptedAnswers": ["une"], "explanation": "Miaphysite vient du grec mia (une) et physis (nature).", "tip": "Mia = une.", "extraExample": {"text": "Monophysite vient aussi de « une nature ».", "translation": "Mais le sens d''Eutychès est condamné."}, "id": "eg.l54.e05", "pool": "lesson", "lessonId": "eg.l54", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l54.e06', 'eg', 'eg.l54', 'eg.g54.chalcedoine_orthodoxes', array['eg.g54.chalcedoine_orthodoxes','eg.v.deux_natures']::text[], 'mcq', 'lesson', 'Pourquoi l''Église d''Alexandrie a-t-elle refusé « en deux natures » ?', array['Elle craignait de diviser le Christ']::text[], 'Dire « en deux natures » après l''union semblait séparer Dieu et l''homme en deux personnes. Alexandrie préfère « de deux natures ».', 3, '{"unitIds": ["eg.g54.chalcedoine_orthodoxes", "eg.v.deux_natures"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi l''Église d''Alexandrie a-t-elle refusé « en deux natures » ?", "promptLanguage": "fr", "options": ["Elle craignait de diviser le Christ", "Elle niait que le Christ soit homme", "Elle refusait les icônes", "Elle voulait un pape à Alexandrie"], "answer": "Elle craignait de diviser le Christ", "acceptedAnswers": ["Elle craignait de diviser le Christ"], "explanation": "Dire « en deux natures » après l''union semblait séparer Dieu et l''homme en deux personnes. Alexandrie préfère « de deux natures ».", "tip": "Alexandrie veut défendre l''unité du Christ.", "extraExample": {"text": "L''Église copte confesse la pleine humanité du Christ.", "translation": "Elle condamne Eutychès."}, "errorPatterns": [{"equals": "Elle niait que le Christ soit homme", "category": "word_confusion", "feedback": "Au contraire : l''Église copte confesse le Christ vrai homme et condamne Eutychès."}], "id": "eg.l54.e06", "pool": "lesson", "lessonId": "eg.l54", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l54.e07', 'eg', 'eg.l54', 'eg.g54.chalcedoine_orthodoxes', array['eg.g54.chalcedoine_orthodoxes']::text[], 'mcq', 'lesson', 'Que reproche-t-on au monophysisme d''Eutychès ?', array['Il absorbait l''humanité du Christ dans sa divinité']::text[], 'Eutychès disait que l''humanité disparaît dans la divinité. L''Église copte le condamne aussi : le Christ est vraiment homme.', 2, '{"unitIds": ["eg.g54.chalcedoine_orthodoxes"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que reproche-t-on au monophysisme d''Eutychès ?", "promptLanguage": "fr", "options": ["Il absorbait l''humanité du Christ dans sa divinité", "Il divisait le Christ en deux personnes", "Il niait la Trinité", "Il refusait l''Ancien Testament"], "answer": "Il absorbait l''humanité du Christ dans sa divinité", "acceptedAnswers": ["Il absorbait l''humanité du Christ dans sa divinité"], "explanation": "Eutychès disait que l''humanité disparaît dans la divinité. L''Église copte le condamne aussi : le Christ est vraiment homme.", "tip": "Eutychès mélange ; Nestorius divise.", "extraExample": {"text": "Miaphysite n''est pas monophysite.", "translation": "La différence est capitale."}, "errorPatterns": [{"equals": "Il divisait le Christ en deux personnes", "category": "word_confusion", "feedback": "C''est le reproche fait à Nestorius."}], "id": "eg.l54.e07", "pool": "lesson", "lessonId": "eg.l54", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l54.e08', 'eg', 'eg.l54', 'eg.v.tome_de_leon', array['eg.v.tome_de_leon','eg.g54.chalcedoine_orthodoxes']::text[], 'mcq', 'lesson', 'Le Tome de Léon, qu''est-ce que c''était ?', array['Une lettre du pape de Rome']::text[], 'Léon, évêque de Rome, y expose deux natures dans le Christ. Chalcédoine la reçoit ; Alexandrie la refuse.', 2, '{"unitIds": ["eg.v.tome_de_leon", "eg.g54.chalcedoine_orthodoxes"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Le Tome de Léon, qu''est-ce que c''était ?", "promptLanguage": "fr", "options": ["Une lettre du pape de Rome", "Un livre de saint Athanase", "Une règle de saint Pacôme", "Un canon de Nicée"], "answer": "Une lettre du pape de Rome", "acceptedAnswers": ["Une lettre du pape de Rome"], "explanation": "Léon, évêque de Rome, y expose deux natures dans le Christ. Chalcédoine la reçoit ; Alexandrie la refuse.", "tip": "Tome de Léon = lettre de Rome.", "extraExample": {"text": "Le mot « tome » signifie ici un texte long.", "translation": "C''est une lettre à Flavien."}, "id": "eg.l54.e08", "pool": "lesson", "lessonId": "eg.l54", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l54.e09', 'eg', 'eg.l54', 'eg.g54.chalcedoine_orthodoxes', array['eg.g54.chalcedoine_orthodoxes']::text[], 'free_answer', 'lesson', 'Quel patriarche d''Alexandrie a été déposé à Chalcédoine ?', array['Dioscore','saint Dioscore','Dioscore d''Alexandrie','Dioscore Ier']::text[], 'Dioscore est déposé en 451, exilé à Gangra et meurt en 454. L''Église copte le vénère comme confesseur.', 3, '{"unitIds": ["eg.g54.chalcedoine_orthodoxes"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Quel patriarche d''Alexandrie a été déposé à Chalcédoine ?", "promptLanguage": "fr", "hint": "Il succède à Cyrille.", "answer": "Dioscore", "acceptedAnswers": ["Dioscore", "saint Dioscore", "Dioscore d''Alexandrie", "Dioscore Ier"], "explanation": "Dioscore est déposé en 451, exilé à Gangra et meurt en 454. L''Église copte le vénère comme confesseur.", "tip": "Dioscore = confesseur de la foi.", "extraExample": {"text": "Dioscore succède à saint Cyrille en 444.", "translation": "Il fut patriarche dix ans."}, "id": "eg.l54.e09", "pool": "lesson", "lessonId": "eg.l54", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l54.e10', 'eg', 'eg.l54', 'eg.g54.chalcedoine_orthodoxes', array['eg.g54.chalcedoine_orthodoxes','eg.v.melkites']::text[], 'free_answer', 'lesson', 'Comment les Égyptiens appellent-ils les chrétiens du parti de l''empereur, restés chalcédoniens ?', array['melkites','les melkites','melkite']::text[], 'Melkite vient du mot « roi » : le patriarche de l''empereur.', 3, '{"unitIds": ["eg.g54.chalcedoine_orthodoxes", "eg.v.melkites"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Comment les Égyptiens appellent-ils les chrétiens du parti de l''empereur, restés chalcédoniens ?", "promptLanguage": "fr", "hint": "Le mot veut dire « roi ».", "answer": "melkites", "acceptedAnswers": ["melkites", "les melkites", "melkite"], "explanation": "Melkite vient du mot « roi » : le patriarche de l''empereur.", "tip": "Melkite = royal.", "extraExample": {"text": "Le patriarche grec d''Alexandrie descend des melkites.", "translation": "Il n''est pas notre pape."}, "id": "eg.l54.e10", "pool": "lesson", "lessonId": "eg.l54", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l54.e11', 'eg', 'eg.l54', 'eg.g54.chalcedoine_orthodoxes', array['eg.g54.chalcedoine_orthodoxes','eg.v.sept_conciles']::text[], 'mcq', 'lesson', 'Combien de conciles les orthodoxes chalcédoniens reçoivent-ils ?', array['Sept']::text[], 'Ils vont jusqu''à Nicée II, en 787. Nous en gardons trois.', 2, '{"unitIds": ["eg.g54.chalcedoine_orthodoxes", "eg.v.sept_conciles"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Combien de conciles les orthodoxes chalcédoniens reçoivent-ils ?", "promptLanguage": "fr", "options": ["Sept", "Trois", "Quatre", "Neuf"], "answer": "Sept", "acceptedAnswers": ["Sept"], "explanation": "Ils vont jusqu''à Nicée II, en 787. Nous en gardons trois.", "tip": "7 contre 3.", "extraExample": {"text": "Nicée II traite des icônes.", "translation": "Il est reçu par les chalcédoniens."}, "errorPatterns": [{"equals": "Trois", "category": "word_confusion", "feedback": "Trois est le nombre des conciles reçus par les orthodoxes orientaux."}], "id": "eg.l54.e11", "pool": "lesson", "lessonId": "eg.l54", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l54.e12', 'eg', 'eg.l54', 'eg.g54.chalcedoine_orthodoxes', array['eg.g54.chalcedoine_orthodoxes','eg.v.trois_conciles']::text[], 'fill_blank', 'lesson', 'Les orthodoxes orientaux reçoivent Nicée, Constantinople et ___.', array['Éphèse']::text[], 'Éphèse (431) proclame Marie Mère de Dieu et condamne Nestorius.', 2, '{"unitIds": ["eg.g54.chalcedoine_orthodoxes", "eg.v.trois_conciles"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Les orthodoxes orientaux reçoivent Nicée, Constantinople et ___.", "promptLanguage": "fr", "options": ["Éphèse", "Chalcédoine", "Latran", "Nicée II"], "answer": "Éphèse", "acceptedAnswers": ["Éphèse"], "explanation": "Éphèse (431) proclame Marie Mère de Dieu et condamne Nestorius.", "tip": "Nicée, Constantinople, Éphèse.", "extraExample": {"text": "Éphèse précède Chalcédoine de vingt ans.", "translation": "Il est reçu par tous les orthodoxes."}, "id": "eg.l54.e12", "pool": "lesson", "lessonId": "eg.l54", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l54.e13', 'eg', 'eg.l54', 'eg.v.patriarcat_grec_d_alexandrie', array['eg.v.patriarcat_grec_d_alexandrie','eg.g54.chalcedoine_orthodoxes']::text[], 'mcq', 'lesson', 'Qui sont les deux patriarches d''Alexandrie depuis 451 ?', array['L''un copte, l''autre grec']::text[], 'L''empereur a imposé un patriarche chalcédonien ; les Égyptiens ont gardé Dioscore. Les deux lignes existent encore.', 3, '{"unitIds": ["eg.v.patriarcat_grec_d_alexandrie", "eg.g54.chalcedoine_orthodoxes"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Qui sont les deux patriarches d''Alexandrie depuis 451 ?", "promptLanguage": "fr", "options": ["L''un copte, l''autre grec", "L''un copte, l''autre catholique", "L''un grec, l''autre russe", "L''un syriaque, l''autre arménien"], "answer": "L''un copte, l''autre grec", "acceptedAnswers": ["L''un copte, l''autre grec"], "explanation": "L''empereur a imposé un patriarche chalcédonien ; les Égyptiens ont gardé Dioscore. Les deux lignes existent encore.", "tip": "Deux lignes, copte et grecque.", "extraExample": {"text": "Le patriarche grec est en communion avec Constantinople.", "translation": "Notre pape est en communion avec les Églises orientales."}, "id": "eg.l54.e13", "pool": "lesson", "lessonId": "eg.l54", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l54.e14', 'eg', 'eg.l54', 'eg.v.dialogue_chambesy', array['eg.v.dialogue_chambesy','eg.g54.chalcedoine_orthodoxes']::text[], 'fill_blank', 'lesson', 'En 1989 puis 1990, des théologiens ont constaté à Wadi Natroun et à Chambésy que les deux familles ont la même ___.', array['foi']::text[], 'Les commissions mixtes ont déclaré que les deux familles confessent la même foi dans le Christ.', 3, '{"unitIds": ["eg.v.dialogue_chambesy", "eg.g54.chalcedoine_orthodoxes"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète la phrase.", "prompt": "En 1989 puis 1990, des théologiens ont constaté à Wadi Natroun et à Chambésy que les deux familles ont la même ___.", "promptLanguage": "fr", "options": ["foi", "liturgie", "langue", "date de Pâques"], "answer": "foi", "acceptedAnswers": ["foi"], "explanation": "Les commissions mixtes ont déclaré que les deux familles confessent la même foi dans le Christ.", "tip": "Même foi, mots différents.", "extraExample": {"text": "Il reste à régler la réception des conciles.", "translation": "Le chemin est encore long."}, "id": "eg.l54.e14", "pool": "lesson", "lessonId": "eg.l54", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l54.e15', 'eg', 'eg.l54', 'eg.g54.chalcedoine_orthodoxes', array['eg.g54.chalcedoine_orthodoxes']::text[], 'reorder', 'lesson', 'Phrase-repère : la formule de saint Cyrille.', array['Une seule nature du Verbe incarné']::text[], 'La formule de saint Cyrille est « une seule nature du Verbe incarné ».', 2, '{"unitIds": ["eg.g54.chalcedoine_orthodoxes"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former la phrase.", "prompt": "Phrase-repère : la formule de saint Cyrille.", "promptLanguage": "fr", "tokens": ["nature", "seule", "incarné", "du", "Verbe", "Une"], "answer": "Une seule nature du Verbe incarné", "acceptedAnswers": ["Une seule nature du Verbe incarné"], "explanation": "La formule de saint Cyrille est « une seule nature du Verbe incarné ».", "tip": "Une seule nature, sans mélange.", "extraExample": {"text": "La formule se dit « miaphysite ».", "translation": "Mia veut dire une."}, "id": "eg.l54.e15", "pool": "lesson", "lessonId": "eg.l54", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l54.e16', 'eg', 'eg.l54', 'eg.g53.familles_eglises', array['eg.g53.familles_eglises','eg.v.eglises_orthodoxes_orientales']::text[], 'mcq', 'lesson', 'Révision — Quel concile les Églises orthodoxes orientales n''ont-elles pas reçu ?', array['Chalcédoine']::text[], 'Les Églises orthodoxes orientales gardent les trois premiers conciles et refusent Chalcédoine.', 2, '{"unitIds": ["eg.g53.familles_eglises", "eg.v.eglises_orthodoxes_orientales"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Révision — Quel concile les Églises orthodoxes orientales n''ont-elles pas reçu ?", "promptLanguage": "fr", "options": ["Chalcédoine", "Nicée", "Constantinople", "Éphèse"], "answer": "Chalcédoine", "acceptedAnswers": ["Chalcédoine"], "explanation": "Les Églises orthodoxes orientales gardent les trois premiers conciles et refusent Chalcédoine.", "tip": "Orientales = sans Chalcédoine.", "extraExample": {"text": "Le refus date de 451.", "translation": "Il dure depuis plus de 1500 ans."}, "id": "eg.l54.e16", "pool": "lesson", "lessonId": "eg.l54", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l54.e17', 'eg', 'eg.l54', 'eg.g53.familles_eglises', array['eg.g53.familles_eglises','eg.v.eglise_orthodoxe_chalcedonienne']::text[], 'mcq', 'lesson', 'Révision — Un orthodoxe grec est :', array['Un orthodoxe chalcédonien']::text[], 'Les orthodoxes grecs, russes ou serbes reçoivent Chalcédoine : ils sont chalcédoniens.', 2, '{"unitIds": ["eg.g53.familles_eglises", "eg.v.eglise_orthodoxe_chalcedonienne"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Révision — Un orthodoxe grec est :", "promptLanguage": "fr", "options": ["Un orthodoxe chalcédonien", "Un orthodoxe oriental", "Un protestant", "Un catholique"], "answer": "Un orthodoxe chalcédonien", "acceptedAnswers": ["Un orthodoxe chalcédonien"], "explanation": "Les orthodoxes grecs, russes ou serbes reçoivent Chalcédoine : ils sont chalcédoniens.", "tip": "Grec, russe, serbe = chalcédoniens.", "extraExample": {"text": "Le patriarche de Constantinople en est le premier en honneur.", "translation": "Il n''a pas le pouvoir d''un pape."}, "id": "eg.l54.e17", "pool": "lesson", "lessonId": "eg.l54", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l54.e18', 'eg', 'eg.l54', 'eg.g53.familles_eglises', array['eg.g53.familles_eglises','eg.v.eglise_tewahedo','eg.v.eglise_malankare']::text[], 'match', 'lesson', 'Révision — Les sœurs de l''Église copte', '{}'::text[], 'Ces quatre Églises sont orthodoxes orientales, comme l''Église copte.', 2, '{"unitIds": ["eg.g53.familles_eglises", "eg.v.eglise_tewahedo", "eg.v.eglise_malankare"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Révision — Les sœurs de l''Église copte", "promptLanguage": "fr", "pairs": [{"left": "Église syriaque orthodoxe", "right": "Antioche"}, {"left": "Église arménienne apostolique", "right": "Arménie"}, {"left": "Église tewahedo", "right": "Éthiopie et Érythrée"}, {"left": "Église malankare", "right": "Kerala, en Inde"}], "answer": "Église syriaque orthodoxe = Antioche ; Église arménienne apostolique = Arménie ; Église tewahedo = Éthiopie et Érythrée ; Église malankare = Kerala, en Inde", "acceptedAnswers": [], "explanation": "Ces quatre Églises sont orthodoxes orientales, comme l''Église copte.", "tip": "Antioche, Arménie, Éthiopie, Kerala.", "id": "eg.l54.e18", "pool": "lesson", "lessonId": "eg.l54", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l54.e19', 'eg', 'eg.l54', 'eg.g53.familles_eglises', array['eg.g53.familles_eglises','eg.v.eglise_catholique']::text[], 'free_answer', 'lesson', 'Révision — Quel est le chef de l''Église catholique ?', array['le pape','pape','le pape de Rome']::text[], 'Les catholiques reconnaissent le pape, évêque de Rome, comme chef.', 2, '{"unitIds": ["eg.g53.familles_eglises", "eg.v.eglise_catholique"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Révision — Quel est le chef de l''Église catholique ?", "promptLanguage": "fr", "hint": "Il est évêque de Rome.", "answer": "le pape", "acceptedAnswers": ["le pape", "pape", "le pape de Rome"], "explanation": "Les catholiques reconnaissent le pape, évêque de Rome, comme chef.", "tip": "Catholique = en communion avec le pape.", "extraExample": {"text": "L''Église catholique copte reconnaît aussi le pape.", "translation": "Elle garde la liturgie copte."}, "id": "eg.l54.e19", "pool": "lesson", "lessonId": "eg.l54", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l55.e01', 'eg', 'eg.l55', 'eg.g55.papaute_filioque', array['eg.g55.papaute_filioque','eg.v.primaute_du_pape','eg.v.infaillibilite_pontificale','eg.v.filioque']::text[], 'match', 'lesson', 'Les mots-clés de la papauté', '{}'::text[], 'Primauté, infaillibilité et Filioque sont les trois points catholiques ; 1054 est la rupture qui en résulte.', 1, '{"unitIds": ["eg.g55.papaute_filioque", "eg.v.primaute_du_pape", "eg.v.infaillibilite_pontificale", "eg.v.filioque"], "type": "match", "difficulty": 1, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Les mots-clés de la papauté", "promptLanguage": "fr", "pairs": [{"left": "primauté du pape", "right": "autorité sur toute l''Église, selon les catholiques"}, {"left": "infaillibilité pontificale", "right": "le pape ne se trompe pas quand il enseigne ex cathedra"}, {"left": "Filioque", "right": "« et du Fils » ajouté au Credo"}, {"left": "schisme de 1054", "right": "rupture entre Rome et Constantinople"}], "answer": "primauté du pape = autorité sur toute l''Église, selon les catholiques ; infaillibilité pontificale = le pape ne se trompe pas quand il enseigne ex cathedra ; Filioque = « et du Fils » ajouté au Credo ; schisme de 1054 = rupture entre Rome et Constantinople", "acceptedAnswers": [], "explanation": "Primauté, infaillibilité et Filioque sont les trois points catholiques ; 1054 est la rupture qui en résulte.", "tip": "Primauté, infaillibilité, Filioque, 1054.", "id": "eg.l55.e01", "pool": "lesson", "lessonId": "eg.l55", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded