insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l55.e02', 'eg', 'eg.l55', 'eg.g55.papaute_filioque', array['eg.g55.papaute_filioque','eg.v.pape']::text[], 'mcq', 'lesson', 'Pour les catholiques, qui est le pape ?', array['Le successeur de saint Pierre']::text[], 'Les catholiques voient dans le pape le successeur de Pierre et le chef visible de l''Église.', 1, '{"unitIds": ["eg.g55.papaute_filioque", "eg.v.pape"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Pour les catholiques, qui est le pape ?", "promptLanguage": "fr", "options": ["Le successeur de saint Pierre", "Le successeur de saint Marc", "Un évêque comme les autres", "Le patriarche de Constantinople"], "answer": "Le successeur de saint Pierre", "acceptedAnswers": ["Le successeur de saint Pierre"], "explanation": "Les catholiques voient dans le pape le successeur de Pierre et le chef visible de l''Église.", "tip": "Pierre → pape de Rome ; Marc → pape d''Alexandrie.", "extraExample": {"text": "Notre pape est successeur de saint Marc.", "translation": "Le pape de Rome est celui de Pierre."}, "errorPatterns": [{"equals": "Le successeur de saint Marc", "category": "word_confusion", "feedback": "Saint Marc est le fondateur de l''Église d''Alexandrie : il est à l''origine de notre pape."}], "id": "eg.l55.e02", "pool": "lesson", "lessonId": "eg.l55", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l55.e03', 'eg', 'eg.l55', 'eg.g55.papaute_filioque', array['eg.g55.papaute_filioque','eg.v.vatican_i']::text[], 'mcq', 'lesson', 'En quelle année Vatican I définit-il l''infaillibilité du pape ?', array['1870']::text[], 'Le 18 juillet 1870, Vatican I définit la primauté et l''infaillibilité du pape.', 2, '{"unitIds": ["eg.g55.papaute_filioque", "eg.v.vatican_i"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "En quelle année Vatican I définit-il l''infaillibilité du pape ?", "promptLanguage": "fr", "options": ["1870", "1054", "1517", "1965"], "answer": "1870", "acceptedAnswers": ["1870"], "explanation": "Le 18 juillet 1870, Vatican I définit la primauté et l''infaillibilité du pape.", "tip": "1870 : infaillibilité.", "extraExample": {"text": "1054 : schisme. 1517 : Réforme. 1965 : levée des excommunications.", "translation": "Quatre dates à ne pas confondre."}, "errorPatterns": [{"equals": "1054", "category": "word_confusion", "feedback": "1054 est la date du schisme entre Rome et Constantinople."}, {"equals": "1965", "category": "word_confusion", "feedback": "1965 est la levée des excommunications de 1054."}], "id": "eg.l55.e03", "pool": "lesson", "lessonId": "eg.l55", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l55.e04', 'eg', 'eg.l55', 'eg.g55.papaute_filioque', array['eg.g55.papaute_filioque','eg.v.ex_cathedra']::text[], 'mcq', 'lesson', 'Quand le pape est-il infaillible selon les catholiques ?', array['Quand il enseigne ex cathedra sur la foi et la morale']::text[], 'Seul l''enseignement solennel sur la foi et la morale est infaillible, ce qui est rare.', 2, '{"unitIds": ["eg.g55.papaute_filioque", "eg.v.ex_cathedra"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quand le pape est-il infaillible selon les catholiques ?", "promptLanguage": "fr", "options": ["Quand il enseigne ex cathedra sur la foi et la morale", "Dans toutes ses paroles", "Quand il voyage", "Quand il parle en public"], "answer": "Quand il enseigne ex cathedra sur la foi et la morale", "acceptedAnswers": ["Quand il enseigne ex cathedra sur la foi et la morale"], "explanation": "Seul l''enseignement solennel sur la foi et la morale est infaillible, ce qui est rare.", "tip": "Ex cathedra = solennel.", "extraExample": {"text": "Un discours n''est pas ex cathedra.", "translation": "Ni une interview."}, "errorPatterns": [{"equals": "Dans toutes ses paroles", "category": "word_confusion", "feedback": "Non : seulement dans l''enseignement solennel sur la foi et la morale."}], "id": "eg.l55.e04", "pool": "lesson", "lessonId": "eg.l55", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l55.e05', 'eg', 'eg.l55', 'eg.g55.papaute_filioque', array['eg.g55.papaute_filioque']::text[], 'mcq', 'lesson', 'Pour l''Église copte, comment se règlent les grandes questions de foi ?', array['En concile']::text[], 'Comme à Jérusalem (Actes 15), les évêques réunis en concile décident ensemble, guidés par l''Esprit Saint.', 2, '{"unitIds": ["eg.g55.papaute_filioque"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Pour l''Église copte, comment se règlent les grandes questions de foi ?", "promptLanguage": "fr", "options": ["En concile", "Par le pape seul", "Par chaque fidèle", "Par le patriarche de Constantinople"], "answer": "En concile", "acceptedAnswers": ["En concile"], "explanation": "Comme à Jérusalem (Actes 15), les évêques réunis en concile décident ensemble, guidés par l''Esprit Saint.", "tip": "Concile = décision commune.", "extraExample": {"text": "Nicée a réuni plus de 300 évêques.", "translation": "Ils ont fixé le Credo."}, "errorPatterns": [{"equals": "Par le pape seul", "category": "word_confusion", "feedback": "Même notre pape ne décide pas seul : il agit avec le Saint-Synode."}], "id": "eg.l55.e05", "pool": "lesson", "lessonId": "eg.l55", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l55.e06', 'eg', 'eg.l55', 'eg.v.pape', array['eg.v.pape','eg.g55.papaute_filioque']::text[], 'fill_blank', 'lesson', 'Le mot « pape » veut dire « ___ ».', array['père']::text[], 'Pape vient de pappas, « père ». Alexandrie l''utilisait dès le IIIe siècle.', 1, '{"unitIds": ["eg.v.pape", "eg.g55.papaute_filioque"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Le mot « pape » veut dire « ___ ».", "promptLanguage": "fr", "options": ["père", "roi", "juge", "pasteur"], "answer": "père", "acceptedAnswers": ["père"], "explanation": "Pape vient de pappas, « père ». Alexandrie l''utilisait dès le IIIe siècle.", "tip": "Pape = père.", "extraExample": {"text": "Abouna (notre père) a le même sens.", "translation": "Le mot est le même en arabe."}, "id": "eg.l55.e06", "pool": "lesson", "lessonId": "eg.l55", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l55.e07', 'eg', 'eg.l55', 'eg.g55.papaute_filioque', array['eg.g55.papaute_filioque','eg.v.filioque']::text[], 'mcq', 'lesson', 'Que dit le Credo de 381 de l''Esprit Saint ?', array['L''Esprit Saint procède du Père']::text[], 'Le Credo de Nicée-Constantinople dit que l''Esprit procède du Père, d''après Jean 15, 26.', 2, '{"unitIds": ["eg.g55.papaute_filioque", "eg.v.filioque"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que dit le Credo de 381 de l''Esprit Saint ?", "promptLanguage": "fr", "options": ["L''Esprit Saint procède du Père", "L''Esprit Saint procède du Père et du Fils", "L''Esprit Saint est créé par le Fils", "L''Esprit Saint est une force"], "answer": "L''Esprit Saint procède du Père", "acceptedAnswers": ["L''Esprit Saint procède du Père"], "explanation": "Le Credo de Nicée-Constantinople dit que l''Esprit procède du Père, d''après Jean 15, 26.", "tip": "Credo de 381 : du Père.", "extraExample": {"text": "Le Credo copte garde cette formule.", "translation": "Rome a ajouté « et du Fils »."}, "errorPatterns": [{"equals": "L''Esprit Saint procède du Père et du Fils", "category": "word_confusion", "feedback": "C''est la version avec le Filioque, ajoutée en Occident."}], "id": "eg.l55.e07", "pool": "lesson", "lessonId": "eg.l55", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l55.e08', 'eg', 'eg.l55', 'eg.g55.papaute_filioque', array['eg.g55.papaute_filioque','eg.v.filioque']::text[], 'free_answer', 'lesson', 'Quel mot latin désigne l''ajout « et du Fils » au Credo ?', array['Filioque','le Filioque']::text[], 'Filioque veut dire « et du Fils » en latin.', 2, '{"unitIds": ["eg.g55.papaute_filioque", "eg.v.filioque"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Quel mot latin désigne l''ajout « et du Fils » au Credo ?", "promptLanguage": "fr", "hint": "Il commence par F.", "answer": "Filioque", "acceptedAnswers": ["Filioque", "le Filioque"], "explanation": "Filioque veut dire « et du Fils » en latin.", "tip": "Filio-que : « et du Fils ».", "extraExample": {"text": "L''ajout est apparu en Espagne en 589.", "translation": "Rome l''adopte en 1014."}, "id": "eg.l55.e08", "pool": "lesson", "lessonId": "eg.l55", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l55.e09', 'eg', 'eg.l55', 'eg.g55.papaute_filioque', array['eg.g55.papaute_filioque','eg.v.filioque']::text[], 'fill_blank', 'lesson', 'Le Filioque est d''abord apparu en ___ à Tolède en 589.', array['Espagne','l''Espagne']::text[], 'Tolède, en Espagne, adopte l''ajout en 589 ; Rome l''accepte en 1014.', 3, '{"unitIds": ["eg.g55.papaute_filioque", "eg.v.filioque"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète la phrase.", "prompt": "Le Filioque est d''abord apparu en ___ à Tolède en 589.", "promptLanguage": "fr", "options": ["Espagne", "Égypte", "Grèce", "Syrie"], "answer": "Espagne", "acceptedAnswers": ["Espagne", "l''Espagne"], "explanation": "Tolède, en Espagne, adopte l''ajout en 589 ; Rome l''accepte en 1014.", "tip": "Tolède = Espagne.", "extraExample": {"text": "Les Francs l''ont ensuite répandu.", "translation": "Rome l''a accepté tard."}, "id": "eg.l55.e09", "pool": "lesson", "lessonId": "eg.l55", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l55.e10', 'eg', 'eg.l55', 'eg.g55.papaute_filioque', array['eg.g55.papaute_filioque','eg.v.filioque']::text[], 'mcq', 'lesson', 'Quel est le problème de méthode du Filioque ?', array['On ne modifie pas le Credo sans concile']::text[], 'Le Credo de 381 a été fixé par un concile œcuménique. Ajouter un mot sans concile est jugé illégitime.', 3, '{"unitIds": ["eg.g55.papaute_filioque", "eg.v.filioque"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quel est le problème de méthode du Filioque ?", "promptLanguage": "fr", "options": ["On ne modifie pas le Credo sans concile", "Il manque dans la Bible", "Il est écrit en latin", "Il date de Nicée"], "answer": "On ne modifie pas le Credo sans concile", "acceptedAnswers": ["On ne modifie pas le Credo sans concile"], "explanation": "Le Credo de 381 a été fixé par un concile œcuménique. Ajouter un mot sans concile est jugé illégitime.", "tip": "Un texte de concile ne se retouche pas seul.", "extraExample": {"text": "Le même principe vaut pour l''Écriture.", "translation": "On n''ajoute rien."}, "errorPatterns": [{"equals": "Il manque dans la Bible", "category": "word_confusion", "feedback": "Ce n''est pas la question de méthode : c''est l''ajout sans concile."}], "id": "eg.l55.e10", "pool": "lesson", "lessonId": "eg.l55", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l55.e11', 'eg', 'eg.l55', 'eg.g55.papaute_filioque', array['eg.g55.papaute_filioque','eg.v.filioque']::text[], 'mcq', 'lesson', 'Que veulent exprimer les catholiques par le Filioque ?', array['Que l''Esprit est aussi l''Esprit du Fils']::text[], 'Ils veulent dire que l''Esprit est aussi l''Esprit du Fils. On voit donc deux soucis légitimes.', 3, '{"unitIds": ["eg.g55.papaute_filioque", "eg.v.filioque"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Que veulent exprimer les catholiques par le Filioque ?", "promptLanguage": "fr", "options": ["Que l''Esprit est aussi l''Esprit du Fils", "Que le Fils est inférieur", "Que l''Esprit est une force", "Que le Père n''a pas de source"], "answer": "Que l''Esprit est aussi l''Esprit du Fils", "acceptedAnswers": ["Que l''Esprit est aussi l''Esprit du Fils"], "explanation": "Ils veulent dire que l''Esprit est aussi l''Esprit du Fils. On voit donc deux soucis légitimes.", "tip": "Comprendre avant de juger.", "extraExample": {"text": "Jésus dit qu''il enverra l''Esprit.", "translation": "C''est le point de départ du raisonnement latin."}, "id": "eg.l55.e11", "pool": "lesson", "lessonId": "eg.l55", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l55.e12', 'eg', 'eg.l55', 'eg.g55.papaute_filioque', array['eg.g55.papaute_filioque','eg.v.schisme_de_1054']::text[], 'fill_blank', 'lesson', 'Rome et Constantinople se séparent en ___.', array['1054']::text[], 'Le 16 juillet 1054 : excommunications croisées entre Rome et Constantinople.', 1, '{"unitIds": ["eg.g55.papaute_filioque", "eg.v.schisme_de_1054"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Rome et Constantinople se séparent en ___.", "promptLanguage": "fr", "options": ["1054", "451", "1870", "1517"], "answer": "1054", "acceptedAnswers": ["1054"], "explanation": "Le 16 juillet 1054 : excommunications croisées entre Rome et Constantinople.", "tip": "1054 : orthodoxes et catholiques.", "extraExample": {"text": "451 : Chalcédoine.", "translation": "1517 : la Réforme."}, "id": "eg.l55.e12", "pool": "lesson", "lessonId": "eg.l55", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l55.e13', 'eg', 'eg.l55', 'eg.g55.papaute_filioque', array['eg.g55.papaute_filioque','eg.v.schisme_de_1054']::text[], 'free_answer', 'lesson', 'Quelle grande ville est le siège du patriarche opposé au pape en 1054 ?', array['Constantinople','Byzance']::text[], 'En 1054, le légat du pape excommunie le patriarche de Constantinople à Sainte-Sophie.', 2, '{"unitIds": ["eg.g55.papaute_filioque", "eg.v.schisme_de_1054"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Quelle grande ville est le siège du patriarche opposé au pape en 1054 ?", "promptLanguage": "fr", "hint": "Elle s''appelle aujourd''hui Istanbul.", "answer": "Constantinople", "acceptedAnswers": ["Constantinople", "Byzance"], "explanation": "En 1054, le légat du pape excommunie le patriarche de Constantinople à Sainte-Sophie.", "tip": "1054 : Rome contre Constantinople.", "extraExample": {"text": "Constantinople est aujourd''hui Istanbul.", "translation": "Sainte-Sophie en était la grande église."}, "id": "eg.l55.e13", "pool": "lesson", "lessonId": "eg.l55", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l55.e14', 'eg', 'eg.l55', 'eg.g55.papaute_filioque', array['eg.g55.papaute_filioque','eg.v.schisme_de_1054']::text[], 'mcq', 'lesson', 'Qui lève les excommunications de 1054 en 1965 ?', array['Paul VI et Athénagoras']::text[], 'En 1965, Paul VI et Athénagoras lèvent les excommunications. La communion n''est pas rétablie pour autant.', 3, '{"unitIds": ["eg.g55.papaute_filioque", "eg.v.schisme_de_1054"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Qui lève les excommunications de 1054 en 1965 ?", "promptLanguage": "fr", "options": ["Paul VI et Athénagoras", "Pie IX et Photios", "François et Tawadros II", "Léon et Dioscore"], "answer": "Paul VI et Athénagoras", "acceptedAnswers": ["Paul VI et Athénagoras"], "explanation": "En 1965, Paul VI et Athénagoras lèvent les excommunications. La communion n''est pas rétablie pour autant.", "tip": "1965 : levée, pas réunion.", "extraExample": {"text": "François et Tawadros II sont de 2017.", "translation": "Ce sont d''autres rencontres."}, "errorPatterns": [{"equals": "François et Tawadros II", "category": "word_confusion", "feedback": "Ils ont signé en 2017 la reconnaissance du baptême entre Coptes et catholiques."}], "id": "eg.l55.e14", "pool": "lesson", "lessonId": "eg.l55", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l55.e15', 'eg', 'eg.l55', 'eg.g55.papaute_filioque', array['eg.g55.papaute_filioque']::text[], 'reorder', 'lesson', 'Phrase-repère : le Credo copte.', array['Le Credo copte dit que l''Esprit procède du Père']::text[], 'Le Credo copte garde le texte de 381 : l''Esprit procède du Père.', 2, '{"unitIds": ["eg.g55.papaute_filioque"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former la phrase.", "prompt": "Phrase-repère : le Credo copte.", "promptLanguage": "fr", "tokens": ["procède", "copte", "Le", "l''Esprit", "que", "dit", "Père", "du", "Credo"], "answer": "Le Credo copte dit que l''Esprit procède du Père", "acceptedAnswers": ["Le Credo copte dit que l''Esprit procède du Père"], "explanation": "Le Credo copte garde le texte de 381 : l''Esprit procède du Père.", "tip": "Texte de 381, sans ajout.", "extraExample": {"text": "Le Credo de 381 date du concile de Constantinople.", "translation": "Il complète celui de Nicée."}, "id": "eg.l55.e15", "pool": "lesson", "lessonId": "eg.l55", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l55.e16', 'eg', 'eg.l55', 'eg.g55.papaute_filioque', array['eg.g55.papaute_filioque']::text[], 'match', 'lesson', 'Quelle date pour quel événement ?', '{}'::text[], '381, 1014, 1054 et 1870 sont les quatre repères de la lecture orthodoxe de l''histoire de Rome.', 2, '{"unitIds": ["eg.g55.papaute_filioque"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Quelle date pour quel événement ?", "promptLanguage": "fr", "pairs": [{"left": "381", "right": "Credo de Nicée-Constantinople"}, {"left": "1014", "right": "Rome adopte le Filioque"}, {"left": "1054", "right": "schisme de Rome et Constantinople"}, {"left": "1870", "right": "Vatican I définit l''infaillibilité"}], "answer": "381 = Credo de Nicée-Constantinople ; 1014 = Rome adopte le Filioque ; 1054 = schisme de Rome et Constantinople ; 1870 = Vatican I définit l''infaillibilité", "acceptedAnswers": [], "explanation": "381, 1014, 1054 et 1870 sont les quatre repères de la lecture orthodoxe de l''histoire de Rome.", "tip": "381 → 1014 → 1054 → 1870.", "id": "eg.l55.e16", "pool": "lesson", "lessonId": "eg.l55", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l55.e17', 'eg', 'eg.l55', 'eg.g55.papaute_filioque', array['eg.g55.papaute_filioque']::text[], 'mcq', 'lesson', 'Comment confessent-ils le Christ, Chenouda III et Paul VI, en 1973 ?', array['Parfait Dieu et parfait homme']::text[], 'La déclaration commune de 1973 confesse un seul Christ, parfait Dieu et parfait homme, ce qui rapproche les deux Églises.', 2, '{"unitIds": ["eg.g55.papaute_filioque"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Comment confessent-ils le Christ, Chenouda III et Paul VI, en 1973 ?", "promptLanguage": "fr", "options": ["Parfait Dieu et parfait homme", "Le Filioque", "L''infaillibilité du pape", "Le purgatoire"], "answer": "Parfait Dieu et parfait homme", "acceptedAnswers": ["Parfait Dieu et parfait homme"], "explanation": "La déclaration commune de 1973 confesse un seul Christ, parfait Dieu et parfait homme, ce qui rapproche les deux Églises.", "tip": "1973 : même Christ.", "extraExample": {"text": "Ils reconnaissent aussi l''erreur des anciennes querelles de mots.", "translation": "Le dialogue vient de là."}, "id": "eg.l55.e17", "pool": "lesson", "lessonId": "eg.l55", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l55.e18', 'eg', 'eg.l55', 'eg.g55.papaute_filioque', array['eg.g55.papaute_filioque']::text[], 'fill_blank', 'lesson', 'En 2017, François et Tawadros II reconnaissent mutuellement le ___.', array['baptême']::text[], 'Les deux Églises reconnaissent la validité du baptême de l''autre : un pas vers l''unité.', 2, '{"unitIds": ["eg.g55.papaute_filioque"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "En 2017, François et Tawadros II reconnaissent mutuellement le ___.", "promptLanguage": "fr", "options": ["baptême", "mariage", "sacerdoce", "Credo"], "answer": "baptême", "acceptedAnswers": ["baptême"], "explanation": "Les deux Églises reconnaissent la validité du baptême de l''autre : un pas vers l''unité.", "tip": "2017 : baptême.", "extraExample": {"text": "Avant cela, chaque Église examinait le baptême de l''autre.", "translation": "L''accord simplifie la vie des couples mixtes."}, "id": "eg.l55.e18", "pool": "lesson", "lessonId": "eg.l55", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l55.e19', 'eg', 'eg.l55', 'eg.g54.chalcedoine_orthodoxes', array['eg.g54.chalcedoine_orthodoxes','eg.v.deux_natures']::text[], 'mcq', 'lesson', 'Révision — Quelle formule de saint Cyrille garde l''Église copte ?', array['Une seule nature du Verbe incarné']::text[], 'La formule de saint Cyrille est « une seule nature du Verbe incarné ».', 2, '{"unitIds": ["eg.g54.chalcedoine_orthodoxes", "eg.v.deux_natures"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Révision — Quelle formule de saint Cyrille garde l''Église copte ?", "promptLanguage": "fr", "options": ["Une seule nature du Verbe incarné", "Un seul Christ reconnu en deux natures", "Le Fils est créé", "Marie n''est pas Mère de Dieu"], "answer": "Une seule nature du Verbe incarné", "acceptedAnswers": ["Une seule nature du Verbe incarné"], "explanation": "La formule de saint Cyrille est « une seule nature du Verbe incarné ».", "tip": "Cyrille : une seule nature.", "extraExample": {"text": "Chalcédoine dit « en deux natures ».", "translation": "Les deux formules veulent confesser le même Christ."}, "id": "eg.l55.e19", "pool": "lesson", "lessonId": "eg.l55", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l55.e20', 'eg', 'eg.l55', 'eg.g54.chalcedoine_orthodoxes', array['eg.g54.chalcedoine_orthodoxes','eg.v.sept_conciles']::text[], 'mcq', 'lesson', 'Révision — Combien de conciles les orthodoxes chalcédoniens reçoivent-ils ?', array['Sept']::text[], 'Les chalcédoniens reçoivent sept conciles. Nous en gardons trois.', 2, '{"unitIds": ["eg.g54.chalcedoine_orthodoxes", "eg.v.sept_conciles"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Révision — Combien de conciles les orthodoxes chalcédoniens reçoivent-ils ?", "promptLanguage": "fr", "options": ["Sept", "Trois", "Quatre", "Douze"], "answer": "Sept", "acceptedAnswers": ["Sept"], "explanation": "Les chalcédoniens reçoivent sept conciles. Nous en gardons trois.", "tip": "7 contre 3.", "extraExample": {"text": "Le septième est Nicée II, en 787.", "translation": "Il défend les icônes."}, "id": "eg.l55.e20", "pool": "lesson", "lessonId": "eg.l55", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l55.e21', 'eg', 'eg.l55', 'eg.g53.familles_eglises', array['eg.g53.familles_eglises','eg.v.eglise_catholique']::text[], 'mcq', 'lesson', 'Révision — Qu''est-ce que l''Église catholique copte ?', array['Elle garde la liturgie copte mais reconnaît le pape']::text[], 'L''Église catholique copte est distincte de l''Église copte orthodoxe : même liturgie, mais communion avec le pape.', 3, '{"unitIds": ["eg.g53.familles_eglises", "eg.v.eglise_catholique"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Révision — Qu''est-ce que l''Église catholique copte ?", "promptLanguage": "fr", "options": ["Elle garde la liturgie copte mais reconnaît le pape", "Elle est la même que l''Église copte orthodoxe", "Elle est une Église protestante", "Elle ne reconnaît pas le pape"], "answer": "Elle garde la liturgie copte mais reconnaît le pape", "acceptedAnswers": ["Elle garde la liturgie copte mais reconnaît le pape"], "explanation": "L''Église catholique copte est distincte de l''Église copte orthodoxe : même liturgie, mais communion avec le pape.", "tip": "Copte de rite, catholique de communion.", "extraExample": {"text": "Il y a 23 Églises catholiques orientales.", "translation": "La copte est l''une d''elles."}, "id": "eg.l55.e21", "pool": "lesson", "lessonId": "eg.l55", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l56.e01', 'eg', 'eg.l56', 'eg.g56.dogmes_usages_catholiques', array['eg.g56.dogmes_usages_catholiques']::text[], 'match', 'lesson', 'Chaque notion et son sens', '{}'::text[], 'Ces quatre notions sont au cœur du désaccord avec les catholiques.', 1, '{"unitIds": ["eg.g56.dogmes_usages_catholiques"], "type": "match", "difficulty": 1, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Chaque notion et son sens", "promptLanguage": "fr", "pairs": [{"left": "purgatoire", "right": "purification après la mort"}, {"left": "Immaculée Conception", "right": "Marie conçue sans péché originel"}, {"left": "azymes", "right": "pain sans levain"}, {"left": "pain levé", "right": "pain de l''offrande copte"}], "answer": "purgatoire = purification après la mort ; Immaculée Conception = Marie conçue sans péché originel ; azymes = pain sans levain ; pain levé = pain de l''offrande copte", "acceptedAnswers": [], "explanation": "Ces quatre notions sont au cœur du désaccord avec les catholiques.", "tip": "Quatre mots : purgatoire, Immaculée Conception, azymes, pain levé.", "id": "eg.l56.e01", "pool": "lesson", "lessonId": "eg.l56", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l56.e02', 'eg', 'eg.l56', 'eg.g56.dogmes_usages_catholiques', array['eg.g56.dogmes_usages_catholiques','eg.v.purgatoire']::text[], 'mcq', 'lesson', 'Qu''est-ce que le purgatoire pour les catholiques ?', array['Une purification après la mort avant le ciel']::text[], 'Le purgatoire est un état de purification provisoire pour ceux qui meurent en grâce.', 1, '{"unitIds": ["eg.g56.dogmes_usages_catholiques", "eg.v.purgatoire"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Qu''est-ce que le purgatoire pour les catholiques ?", "promptLanguage": "fr", "options": ["Une purification après la mort avant le ciel", "Un enfer éternel", "Un séjour sur la terre", "Un sacrement"], "answer": "Une purification après la mort avant le ciel", "acceptedAnswers": ["Une purification après la mort avant le ciel"], "explanation": "Le purgatoire est un état de purification provisoire pour ceux qui meurent en grâce.", "tip": "Purgatoire = purifier avant le ciel.", "extraExample": {"text": "Il est toujours un chemin vers le ciel.", "translation": "Ce n''est pas un enfer."}, "errorPatterns": [{"equals": "Un enfer éternel", "category": "word_confusion", "feedback": "Pour les catholiques, il n''est pas éternel : il conduit au ciel."}], "id": "eg.l56.e02", "pool": "lesson", "lessonId": "eg.l56", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l56.e03', 'eg', 'eg.l56', 'eg.g56.dogmes_usages_catholiques', array['eg.g56.dogmes_usages_catholiques','eg.v.prieres_pour_les_defunts']::text[], 'mcq', 'lesson', 'Que fait l''Église copte pour les défunts ?', array['Elle prie pour les défunts']::text[], 'L''Église copte prie pour les défunts aux 3e, 7e et 40e jours, sans enseigner le purgatoire.', 2, '{"unitIds": ["eg.g56.dogmes_usages_catholiques", "eg.v.prieres_pour_les_defunts"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que fait l''Église copte pour les défunts ?", "promptLanguage": "fr", "options": ["Elle prie pour les défunts", "Elle les oublie", "Elle enseigne un purgatoire", "Elle ne parle pas de la mort"], "answer": "Elle prie pour les défunts", "acceptedAnswers": ["Elle prie pour les défunts"], "explanation": "L''Église copte prie pour les défunts aux 3e, 7e et 40e jours, sans enseigner le purgatoire.", "tip": "Prier, oui ; purgatoire, non.", "extraExample": {"text": "Les messes pour les défunts sont courantes.", "translation": "Elles montrent l''unité de l''Église."}, "errorPatterns": [{"equals": "Elle enseigne un purgatoire", "category": "word_confusion", "feedback": "L''Église copte n''enseigne pas le purgatoire catholique."}], "id": "eg.l56.e03", "pool": "lesson", "lessonId": "eg.l56", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l56.e04', 'eg', 'eg.l56', 'eg.g56.dogmes_usages_catholiques', array['eg.g56.dogmes_usages_catholiques','eg.v.purgatoire']::text[], 'mcq', 'lesson', 'Qui juge les défunts selon l''Église copte ?', array['Dieu seul juge']::text[], 'Nous prions pour les défunts et laissons le jugement à Dieu seul.', 2, '{"unitIds": ["eg.g56.dogmes_usages_catholiques", "eg.v.purgatoire"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui juge les défunts selon l''Église copte ?", "promptLanguage": "fr", "options": ["Dieu seul juge", "Le pape", "L''évêque", "La famille"], "answer": "Dieu seul juge", "acceptedAnswers": ["Dieu seul juge"], "explanation": "Nous prions pour les défunts et laissons le jugement à Dieu seul.", "tip": "Dieu seul juge.", "extraExample": {"text": "Le jugement dernier aura lieu au retour du Christ.", "translation": "Nous n''en décrivons pas le détail."}, "errorPatterns": [{"equals": "Le pape", "category": "word_confusion", "feedback": "Même un pape ne juge pas les défunts."}], "id": "eg.l56.e04", "pool": "lesson", "lessonId": "eg.l56", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l56.e05', 'eg', 'eg.l56', 'eg.g56.dogmes_usages_catholiques', array['eg.g56.dogmes_usages_catholiques','eg.v.purgatoire']::text[], 'fill_blank', 'lesson', 'Le purgatoire est précisé au concile de ___ en 1274.', array['Lyon II','Lyon']::text[], 'Lyon II, en 1274, précise la doctrine du purgatoire.', 2, '{"unitIds": ["eg.g56.dogmes_usages_catholiques", "eg.v.purgatoire"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Le purgatoire est précisé au concile de ___ en 1274.", "promptLanguage": "fr", "options": ["Lyon II", "Nicée", "Éphèse", "Trente"], "answer": "Lyon II", "acceptedAnswers": ["Lyon II", "Lyon"], "explanation": "Lyon II, en 1274, précise la doctrine du purgatoire.", "tip": "1274 : Lyon II.", "extraExample": {"text": "Trente reprend l''enseignement au XVIe siècle.", "translation": "Mais c''est Lyon II qui le précise."}, "id": "eg.l56.e05", "pool": "lesson", "lessonId": "eg.l56", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l56.e06', 'eg', 'eg.l56', 'eg.g56.dogmes_usages_catholiques', array['eg.g56.dogmes_usages_catholiques','eg.v.immaculee_conception']::text[], 'mcq', 'lesson', 'En quelle année l''Immaculée Conception est-elle définie ?', array['1854']::text[], 'Le 8 décembre 1854, Pie IX proclame le dogme.', 2, '{"unitIds": ["eg.g56.dogmes_usages_catholiques", "eg.v.immaculee_conception"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "En quelle année l''Immaculée Conception est-elle définie ?", "promptLanguage": "fr", "options": ["1854", "1870", "1054", "1950"], "answer": "1854", "acceptedAnswers": ["1854"], "explanation": "Le 8 décembre 1854, Pie IX proclame le dogme.", "tip": "1854 : Marie.", "extraExample": {"text": "1870 : infaillibilité.", "translation": "1950 : Assomption."}, "errorPatterns": [{"equals": "1870", "category": "word_confusion", "feedback": "1870 est la date de l''infaillibilité du pape."}, {"equals": "1950", "category": "word_confusion", "feedback": "1950 est l''Assomption de Marie."}], "id": "eg.l56.e06", "pool": "lesson", "lessonId": "eg.l56", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l56.e07', 'eg', 'eg.l56', 'eg.g56.dogmes_usages_catholiques', array['eg.g56.dogmes_usages_catholiques','eg.v.immaculee_conception']::text[], 'fill_blank', 'lesson', 'L''Immaculée Conception est définie par le pape ___ en 1854.', array['Pie IX']::text[], 'Pie IX proclame le dogme en 1854 ; le même pape convoque Vatican I.', 2, '{"unitIds": ["eg.g56.dogmes_usages_catholiques", "eg.v.immaculee_conception"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "L''Immaculée Conception est définie par le pape ___ en 1854.", "promptLanguage": "fr", "options": ["Pie IX", "Léon", "Jean-Paul II", "Grégoire"], "answer": "Pie IX", "acceptedAnswers": ["Pie IX"], "explanation": "Pie IX proclame le dogme en 1854 ; le même pape convoque Vatican I.", "tip": "Pie IX : 1854, puis 1870.", "extraExample": {"text": "Il convoque aussi Vatican I.", "translation": "Deux dogmes sous un même pape."}, "id": "eg.l56.e07", "pool": "lesson", "lessonId": "eg.l56", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l56.e08', 'eg', 'eg.l56', 'eg.g56.dogmes_usages_catholiques', array['eg.g56.dogmes_usages_catholiques','eg.v.immaculee_conception']::text[], 'mcq', 'lesson', 'Que signifie l''Immaculée Conception ?', array['Marie a été conçue sans péché originel']::text[], 'Elle concerne la conception de Marie. La naissance virginale concerne Jésus.', 2, '{"unitIds": ["eg.g56.dogmes_usages_catholiques", "eg.v.immaculee_conception"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que signifie l''Immaculée Conception ?", "promptLanguage": "fr", "options": ["Marie a été conçue sans péché originel", "Jésus est né d''une vierge", "Marie est montée au ciel", "Jésus n''a pas de père"], "answer": "Marie a été conçue sans péché originel", "acceptedAnswers": ["Marie a été conçue sans péché originel"], "explanation": "Elle concerne la conception de Marie. La naissance virginale concerne Jésus.", "tip": "Immaculée = Marie.", "extraExample": {"text": "L''Assomption est un autre dogme.", "translation": "Elle est définie en 1950."}, "errorPatterns": [{"equals": "Jésus est né d''une vierge", "category": "word_confusion", "feedback": "C''est la naissance virginale, différente de l''Immaculée Conception."}, {"equals": "Marie est montée au ciel", "category": "word_confusion", "feedback": "C''est l''Assomption, un autre dogme."}], "id": "eg.l56.e08", "pool": "lesson", "lessonId": "eg.l56", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l56.e09', 'eg', 'eg.l56', 'eg.g56.dogmes_usages_catholiques', array['eg.g56.dogmes_usages_catholiques','eg.v.peche_originel']::text[], 'free_answer', 'lesson', 'Comment appelle-t-on la faute d''Adam transmise à tout homme, selon saint Augustin ?', array['péché originel','le péché originel','peche originel']::text[], 'Pour Augustin, le péché originel se transmet à la naissance. Les orthodoxes y voient plutôt un héritage de mortalité.', 2, '{"unitIds": ["eg.g56.dogmes_usages_catholiques", "eg.v.peche_originel"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Comment appelle-t-on la faute d''Adam transmise à tout homme, selon saint Augustin ?", "promptLanguage": "fr", "hint": "Deux mots, le deuxième commence par o.", "answer": "péché originel", "acceptedAnswers": ["péché originel", "le péché originel", "peche originel"], "explanation": "Pour Augustin, le péché originel se transmet à la naissance. Les orthodoxes y voient plutôt un héritage de mortalité.", "tip": "Originel : dès l''origine.", "extraExample": {"text": "Le baptême en guérit les conséquences.", "translation": "Il ne s''agit pas de culpabilité héritée pour les orthodoxes."}, "id": "eg.l56.e09", "pool": "lesson", "lessonId": "eg.l56", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l56.e10', 'eg', 'eg.l56', 'eg.g56.dogmes_usages_catholiques', array['eg.g56.dogmes_usages_catholiques']::text[], 'mcq', 'lesson', 'Quel verset montre que Marie reconnaît avoir un Sauveur ?', array['« Mon esprit se réjouit en Dieu, mon Sauveur »']::text[], 'Luc 1, 47 : Marie loue Dieu comme son Sauveur. C''est pourquoi nous croyons que Marie a besoin d''un Sauveur, comme tous.', 3, '{"unitIds": ["eg.g56.dogmes_usages_catholiques"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quel verset montre que Marie reconnaît avoir un Sauveur ?", "promptLanguage": "fr", "options": ["« Mon esprit se réjouit en Dieu, mon Sauveur »", "« Tu es Pierre »", "« Que ta volonté soit faite »", "« Au commencement était le Verbe »"], "answer": "« Mon esprit se réjouit en Dieu, mon Sauveur »", "acceptedAnswers": ["« Mon esprit se réjouit en Dieu, mon Sauveur »"], "explanation": "Luc 1, 47 : Marie loue Dieu comme son Sauveur. C''est pourquoi nous croyons que Marie a besoin d''un Sauveur, comme tous.", "tip": "Marie a un Sauveur.", "extraExample": {"text": "Elle le dit dans le Magnificat.", "translation": "Nous le chantons dans la liturgie."}, "errorPatterns": [{"equals": "« Tu es Pierre »", "category": "word_confusion", "feedback": "C''est la parole de Jésus à Pierre (Matthieu 16, 18)."}], "id": "eg.l56.e10", "pool": "lesson", "lessonId": "eg.l56", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l56.e11', 'eg', 'eg.l56', 'eg.g56.dogmes_usages_catholiques', array['eg.g56.dogmes_usages_catholiques','eg.v.azymes']::text[], 'mcq', 'lesson', 'Quel pain les catholiques latins utilisent-ils pour l''Eucharistie ?', array['Du pain azyme, sans levain']::text[], 'L''hostie latine est un pain azyme : sans levain, mince et ronde.', 1, '{"unitIds": ["eg.g56.dogmes_usages_catholiques", "eg.v.azymes"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel pain les catholiques latins utilisent-ils pour l''Eucharistie ?", "promptLanguage": "fr", "options": ["Du pain azyme, sans levain", "Du pain levé", "Du pain d''orge", "Du pain de maïs"], "answer": "Du pain azyme, sans levain", "acceptedAnswers": ["Du pain azyme, sans levain"], "explanation": "L''hostie latine est un pain azyme : sans levain, mince et ronde.", "tip": "Azyme = a-zymê : sans levain.", "extraExample": {"text": "Les Arméniens utilisent aussi des azymes.", "translation": "Ils sont pourtant orthodoxes orientaux."}, "errorPatterns": [{"equals": "Du pain levé", "category": "word_confusion", "feedback": "Le pain levé est celui de l''Église copte."}], "id": "eg.l56.e11", "pool": "lesson", "lessonId": "eg.l56", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l56.e12', 'eg', 'eg.l56', 'eg.g56.dogmes_usages_catholiques', array['eg.g56.dogmes_usages_catholiques','eg.v.pain_leve']::text[], 'fill_blank', 'lesson', 'L''Église copte utilise un pain ___ pour l''Eucharistie.', array['levé','pain levé']::text[], 'Notre pain est levé, comme celui des orthodoxes grecs.', 1, '{"unitIds": ["eg.g56.dogmes_usages_catholiques", "eg.v.pain_leve"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "L''Église copte utilise un pain ___ pour l''Eucharistie.", "promptLanguage": "fr", "options": ["levé", "azyme", "sec"], "answer": "levé", "acceptedAnswers": ["levé", "pain levé"], "explanation": "Notre pain est levé, comme celui des orthodoxes grecs.", "tip": "Pain levé = pain vivant.", "extraExample": {"text": "L''offrande est estampillée d''une croix.", "translation": "On l''appelle qorban."}, "id": "eg.l56.e12", "pool": "lesson", "lessonId": "eg.l56", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l56.e13', 'eg', 'eg.l56', 'eg.g56.dogmes_usages_catholiques', array['eg.g56.dogmes_usages_catholiques','eg.v.pain_leve']::text[], 'mcq', 'lesson', 'Que symbolise le pain levé pour l''Église copte ?', array['Il est vivant : il évoque la Résurrection']::text[], 'Le pain levé est vivant. Il évoque la Résurrection. L''Église d''Orient l''utilise depuis les origines.', 3, '{"unitIds": ["eg.g56.dogmes_usages_catholiques", "eg.v.pain_leve"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Que symbolise le pain levé pour l''Église copte ?", "promptLanguage": "fr", "options": ["Il est vivant : il évoque la Résurrection", "Il est pauvre", "Il est réservé aux fêtes", "Il vient d''Égypte ancienne"], "answer": "Il est vivant : il évoque la Résurrection", "acceptedAnswers": ["Il est vivant : il évoque la Résurrection"], "explanation": "Le pain levé est vivant. Il évoque la Résurrection. L''Église d''Orient l''utilise depuis les origines.", "tip": "Levé : vivant.", "extraExample": {"text": "Le levain fait monter la pâte.", "translation": "La Résurrection fait monter l''homme à la vie."}, "id": "eg.l56.e13", "pool": "lesson", "lessonId": "eg.l56", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l56.e14', 'eg', 'eg.l56', 'eg.g56.dogmes_usages_catholiques', array['eg.g56.dogmes_usages_catholiques','eg.v.celibat_des_pretres']::text[], 'mcq', 'lesson', 'Dans l''Église latine, les prêtres sont en général :', array['Célibataires']::text[], 'La règle du célibat est affermie au XIIe siècle dans l''Église latine.', 2, '{"unitIds": ["eg.g56.dogmes_usages_catholiques", "eg.v.celibat_des_pretres"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Dans l''Église latine, les prêtres sont en général :", "promptLanguage": "fr", "options": ["Célibataires", "Mariés", "Veufs", "Moines"], "answer": "Célibataires", "acceptedAnswers": ["Célibataires"], "explanation": "La règle du célibat est affermie au XIIe siècle dans l''Église latine.", "tip": "Latin : célibat.", "extraExample": {"text": "Certaines Églises catholiques orientales ordonnent des hommes mariés.", "translation": "Le célibat n''est pas un dogme."}, "errorPatterns": [{"equals": "Mariés", "category": "word_confusion", "feedback": "C''est le cas chez les Coptes, pas la règle générale latine."}], "id": "eg.l56.e14", "pool": "lesson", "lessonId": "eg.l56", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l56.e15', 'eg', 'eg.l56', 'eg.g56.dogmes_usages_catholiques', array['eg.g56.dogmes_usages_catholiques','eg.v.celibat_des_pretres']::text[], 'mcq', 'lesson', 'Quand un homme marié peut-il devenir prêtre dans l''Église copte ?', array['S''il est marié avant l''ordination']::text[], 'Un homme marié avant l''ordination peut devenir prêtre. Il ne se marie pas après.', 2, '{"unitIds": ["eg.g56.dogmes_usages_catholiques", "eg.v.celibat_des_pretres"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quand un homme marié peut-il devenir prêtre dans l''Église copte ?", "promptLanguage": "fr", "options": ["S''il est marié avant l''ordination", "Jamais", "Seulement après avoir divorcé", "Seulement s''il se marie après"], "answer": "S''il est marié avant l''ordination", "acceptedAnswers": ["S''il est marié avant l''ordination"], "explanation": "Un homme marié avant l''ordination peut devenir prêtre. Il ne se marie pas après.", "tip": "Marié avant, jamais après.", "extraExample": {"text": "Saint Pierre était marié.", "translation": "Sa belle-mère est guérie en Matthieu 8, 14."}, "errorPatterns": [{"equals": "Jamais", "category": "word_confusion", "feedback": "Chez les Coptes, la tradition ancienne autorise l''ordination d''hommes mariés."}], "id": "eg.l56.e15", "pool": "lesson", "lessonId": "eg.l56", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l56.e16', 'eg', 'eg.l56', 'eg.g56.dogmes_usages_catholiques', array['eg.g56.dogmes_usages_catholiques','eg.v.celibat_des_pretres']::text[], 'free_answer', 'lesson', 'Parmi qui les évêques coptes sont-ils choisis ?', array['les moines','des moines','moines','parmi les moines']::text[], 'Les évêques sont choisis parmi les moines, donc célibataires.', 2, '{"unitIds": ["eg.g56.dogmes_usages_catholiques", "eg.v.celibat_des_pretres"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Parmi qui les évêques coptes sont-ils choisis ?", "promptLanguage": "fr", "hint": "Ils vivent dans les monastères.", "answer": "les moines", "acceptedAnswers": ["les moines", "des moines", "moines", "parmi les moines"], "explanation": "Les évêques sont choisis parmi les moines, donc célibataires.", "tip": "Évêque = moine.", "extraExample": {"text": "Le pape est choisi parmi eux.", "translation": "Le monastère forme les évêques."}, "id": "eg.l56.e16", "pool": "lesson", "lessonId": "eg.l56", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l56.e17', 'eg', 'eg.l56', 'eg.g56.dogmes_usages_catholiques', array['eg.g56.dogmes_usages_catholiques']::text[], 'reorder', 'lesson', 'Phrase-repère : les défunts.', array['L''Église copte prie pour les défunts']::text[], 'L''Église copte prie pour les défunts et laisse le jugement à Dieu seul.', 2, '{"unitIds": ["eg.g56.dogmes_usages_catholiques"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former la phrase.", "prompt": "Phrase-repère : les défunts.", "promptLanguage": "fr", "tokens": ["prie", "défunts", "les", "L''Église", "copte", "pour"], "answer": "L''Église copte prie pour les défunts", "acceptedAnswers": ["L''Église copte prie pour les défunts"], "explanation": "L''Église copte prie pour les défunts et laisse le jugement à Dieu seul.", "tip": "Prier, c''est aimer.", "extraExample": {"text": "Les prières ont lieu aux 3e, 7e et 40e jours.", "translation": "La mémoire est annuelle."}, "id": "eg.l56.e17", "pool": "lesson", "lessonId": "eg.l56", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l56.e18', 'eg', 'eg.l56', 'eg.g56.dogmes_usages_catholiques', array['eg.g56.dogmes_usages_catholiques']::text[], 'mcq', 'lesson', 'Combien de sacrements les Coptes et les catholiques ont-ils en commun ?', array['Sept']::text[], 'Les Coptes et les catholiques ont les mêmes sept sacrements. Les protestants en gardent généralement deux.', 2, '{"unitIds": ["eg.g56.dogmes_usages_catholiques"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Combien de sacrements les Coptes et les catholiques ont-ils en commun ?", "promptLanguage": "fr", "options": ["Sept", "Deux", "Trois", "Douze"], "answer": "Sept", "acceptedAnswers": ["Sept"], "explanation": "Les Coptes et les catholiques ont les mêmes sept sacrements. Les protestants en gardent généralement deux.", "tip": "Sept en commun.", "extraExample": {"text": "Les orthodoxes grecs en ont aussi sept.", "translation": "Le nombre est le même."}, "id": "eg.l56.e18", "pool": "lesson", "lessonId": "eg.l56", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l56.e19', 'eg', 'eg.l56', 'eg.g55.papaute_filioque', array['eg.g55.papaute_filioque','eg.g56.dogmes_usages_catholiques']::text[], 'match', 'lesson', 'Révision — Les dates catholiques', '{}'::text[], 'Quatre dates jalonnent la divergence avec Rome.', 2, '{"unitIds": ["eg.g55.papaute_filioque", "eg.g56.dogmes_usages_catholiques"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Révision — Les dates catholiques", "promptLanguage": "fr", "pairs": [{"left": "1054", "right": "schisme de Rome et Constantinople"}, {"left": "1274", "right": "Lyon II précise le purgatoire"}, {"left": "1854", "right": "Immaculée Conception"}, {"left": "1870", "right": "infaillibilité du pape"}], "answer": "1054 = schisme de Rome et Constantinople ; 1274 = Lyon II précise le purgatoire ; 1854 = Immaculée Conception ; 1870 = infaillibilité du pape", "acceptedAnswers": [], "explanation": "Quatre dates jalonnent la divergence avec Rome.", "tip": "1054, 1274, 1854, 1870.", "id": "eg.l56.e19", "pool": "lesson", "lessonId": "eg.l56", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l56.e20', 'eg', 'eg.l56', 'eg.g55.papaute_filioque', array['eg.g55.papaute_filioque','eg.v.filioque']::text[], 'free_answer', 'lesson', 'Révision — Comment s''appelle l''ajout latin « et du Fils » au Credo de 381 ?', array['Filioque','le Filioque']::text[], 'Filioque veut dire « et du Fils » en latin.', 2, '{"unitIds": ["eg.g55.papaute_filioque", "eg.v.filioque"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Révision — Comment s''appelle l''ajout latin « et du Fils » au Credo de 381 ?", "promptLanguage": "fr", "hint": "Il commence par F.", "answer": "Filioque", "acceptedAnswers": ["Filioque", "le Filioque"], "explanation": "Filioque veut dire « et du Fils » en latin.", "tip": "Filioque = et du Fils.", "extraExample": {"text": "Le Credo copte n''a pas cet ajout.", "translation": "Il dit : l''Esprit procède du Père."}, "id": "eg.l56.e20", "pool": "lesson", "lessonId": "eg.l56", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
