insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l57.e01', 'eg', 'eg.l57', 'eg.g57.reforme_protestante', array['eg.g57.reforme_protestante','eg.v.sola_scriptura','eg.v.sola_fide','eg.v.sainte_tradition']::text[], 'match', 'lesson', 'Les mots-clés de la Réforme', '{}'::text[], 'Sola scriptura et sola fide sont les deux principes protestants ; la Sainte Tradition est ce que nous gardons en plus.', 1, '{"unitIds": ["eg.g57.reforme_protestante", "eg.v.sola_scriptura", "eg.v.sola_fide", "eg.v.sainte_tradition"], "type": "match", "difficulty": 1, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Les mots-clés de la Réforme", "promptLanguage": "fr", "pairs": [{"left": "sola scriptura", "right": "l''Écriture seule"}, {"left": "sola fide", "right": "le salut par la foi seule"}, {"left": "la Réforme", "right": "mouvement né en 1517"}, {"left": "Sainte Tradition", "right": "enseignement des apôtres transmis dans l''Église"}], "answer": "sola scriptura = l''Écriture seule ; sola fide = le salut par la foi seule ; la Réforme = mouvement né en 1517 ; Sainte Tradition = enseignement des apôtres transmis dans l''Église", "acceptedAnswers": [], "explanation": "Sola scriptura et sola fide sont les deux principes protestants ; la Sainte Tradition est ce que nous gardons en plus.", "tip": "Latin : seule.", "id": "eg.l57.e01", "pool": "lesson", "lessonId": "eg.l57", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = exclude